INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('39e97a64-94b4-5c9f-99c3-a6f5bac18b57','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='METAFOR' AND il IS NOT DISTINCT FROM 'KOCAELİ' LIMIT 1),'48c33d56-bcf0-5452-921b-66f6ad6df33b'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-01-06',NULL,'İzaydaş taşeronu firma, 7 tane loderleri var. Patlayan lastiklerini kontrol için gittim, sevis yönlerdim yerinde tamir yaptık. Ertesi gün başk bir lasikleri patladı yine yerinde tamir aracaı yönlendirdim. Yeni lastik almalarını tavsiy etim fakat ihale 4. ayda yenielenmeden alım yapmaacaklarını söylediler. Adnan abi diğer firmalarına TBR de satyıro.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('1a651289-27f6-5870-a70b-9e59f5f2a4b2','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='KALYON İNŞAAT' AND il IS NOT DISTINCT FROM 'KOCAELİ' LIMIT 1),'e8cac308-d4e2-5cf6-ab2e-60589cc06f97'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-01-06',NULL,'Rahmi tek fiyat üzerinden gitmek istiyor, daha önce burası ile Yıldıray Yenişehir ile Murat Yener ilgilendiğinden fiyatlama farklılıkları olmuş. Yeni fiyatlar için teklifi sunmamız durumunda genel ihaleye çıkıp herkesten fiyat alıp değerlendirip Ekrem beye sunacaklarını bununda 20 günden önce bitmeyecek bir iş olduğunu söylediler. Buradaki işlerinin 2 yıl daha devam edeceğini söylediler, şantiye hareketli durumdaydı. Yeni lastik konusunda Sailun için verdiğimiz fiyatı içeri onaylattıklarını fakat bizim sonra fiyatı yanlış verdiğimizi söylememiz üzere içeride zor duruma düştüklerini bu sebeple yeni lastikte şuan Sailunu değerlendirmek istemediklerini söylediler. Buradaki yetkili bizim ilk kontaklarımızdan Rahmi Turgut zamanla Sailun konusunda gerekli ilgiyi toplayacağım','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('9a44499f-2b14-5c8e-8cc4-bbca136a4d8d','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='KALYON İNŞAAT' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'b64acf8f-6845-54d7-9f93-2aaacd974067'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-01-07',NULL,'Miraç beyin yerine gelen makine müdürü Serkan bey ile görüştüm. Bizden memnun olmadığını söyledi, sadece lastik alıp gidiyorsunuz bana bugüne kadar hiçbir konuda geri bildirimde bulunmadınız, daha önce gelen arkadaşlara da bunu söyledim hallederiz deyip gittiler dedi. Ben lastik kökenliyim lastikten anlarım dedi. Bende aksine bizim burada test ürünlerimizin olduğunu ve ölçmek için geldiğimizde takılış bilgisi yok, araç yok vb gerekçeler ile bilgi alamadığımızı söyledim. O gibi durumlarda bana gelin ben ne gerekiyorsa yaparım dedi. Burada ölçüm yapıp almadığınız her lastik önce bana sonra size zarar dedi. Kendisinin Petlas geçmişi olduğunu söyledi, Yahya beyin bizden danışman olduğunu söyledim, çok etkilendi, kendisi ile çalışmış argede. Ayrıca eski firması Limaktan çok ortak tanıdığımız çıktı. Serkan bey yeni konusuna şuanda sizinle girmiyorum ama kaplama işi sizde gelin ölçün zorla söktürün alın dedi. En az 2 yıllık daha iş varmış. 31 loder, 76 damperli kamyon, 43 beton mikseri ve 24 servis kamyonu ile ciddi bir makine parkı var. Ben en kısa sürede bizzat kendimin tüm iş makineleri başta olmak üzere kontrollere başlayacağımızı söyledim. Bizimde çalışma tarzımızın bu şekilde olduğunu söyledim. Sen şimdi yeni yıl zam diye geldin muhtemelen ama sana tavsiyem diğer firmaların zammını bekle şubat sonuna kadar buraya devam et dedi. Yine de zamlı fiyatları atarsan ihaleye çıkacağız herkesten fiyat alacağız dedi. Bende maliyetlerin eski fiyatlara imkan vermediğini söyledim fakat tavsiyesini yineledi.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('2bb7ac35-6880-596a-89d0-a1395c9b3213','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='BERGİZ İNŞAAT' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'38d87106-68e1-5fa5-b76e-2b6d1b051cc6'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-01-13','Kenan Yalçınkaya','doğancılı - Orhaneli arasında barajın üzerinden yol yapıyorlar. Burada 2 loderleri var. Tüm talepleri için ankara merkez Mehmet Efe bey yetkili. Tüm işi Tatkodan alıp Metkay firmasına vermişler. Ankara programıma aldım.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
