INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('b4687d2f-2cc1-5093-96af-2796d3ccbca3','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ÜNALDI MADEN' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'d5103b93-0438-5a22-b2e1-d5298e35db53'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-01-13','Kenan Yalçınkaya','İbrahim şef ile görüştüm, eski Şetat maden sahasında erkay madenin taşeronu firma. 4 loderleri var firma merkezi Kütahya tavşanlı orada firma sahibi ilgileniyor. Programıma aldım.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('4be541b8-9139-5015-a0cc-ba1dcb8a0263','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ERKAY MADEN' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'bb02b48d-b869-523f-b6bf-145ec0769be3'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-01-13','Kenan Yalçınkaya','Şetat maden sahasını devralmışlar. Krom ocağı, Ramazan bey ile görüştüm satınalmadan. 5 loder 1 greyder var. Civardaki BG madende onlara ait ama kapalı şuan. Kaplama ve yokohama konuştuk. Takip edeceğiz.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
