INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('8f225ecc-6fc1-5592-b875-aadf05d425da','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ALİZE BETON' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'1efe809d-d571-5647-be6a-9b11a6529d68'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-01-13','Kenan Yalçınkaya','Yetkili Cuma bey yoktu. 1 loderlerivar. Şükriyede beton santrali.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('ff312e70-33c4-5d5d-989b-00caf5ece592','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='NC YAPI' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'e8564a03-9a8b-5a18-9fef-7154ca52df78'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-01-14','Kenan Yalçınkaya','İznik bilecik arası genişletme işi almışlar. Daha makineler yeni iniyordu yetkili kimse yoktu. Ankara merkezli firma programıma aldım.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('785bce20-8872-5b7e-8c31-7925c3bfc93e','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='KALYON İNŞAAT' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'b64acf8f-6845-54d7-9f93-2aaacd974067'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-01-14','Kenan Yalçınkaya','Kenan ve Talha ile ölçüme gittik. Serkan bey önce hurdalığı incelememizi istedi, hurdalık incelerken hurdacı geldi lastikleri almaya bizde aralarından 8-10 tane olur seçmiştik hurdacı onları almazsam hiç almam diye olay çıkardı. Serkan beyi aradım, sen seç olanı almazsa almasınlar dedi. kendi lastikçileri hepsi hurda onlar anlamıyor diye bize çıkıştı. Serkan beye konuyu anlattaım bu gibi durumlar olabildiğini bizim hurdalığı incelemeden lasitk göndermemelerini söyledim. çok teşekkür etti böyle olacak bundan sonra dedi Serkan beyi tanıyor gibiydim hep Eren NTF den mühendismiş o da beni tanıdı sonra Bülen Çamı aradık beraber. bize bakışı ve güveni daha iyi bir zemine oturdu. gün boyu ölçüm yaptık ve sonucu sunduk. 120 hurda lastik inceledik.18 lastik kurtardık.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('78c7eb14-1e32-5d7a-a120-f2c5a60a83e9','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='HAYRİ ÖĞELMAN MADENCİLİK' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'515126e5-921f-5cae-b0f5-54efb6406e81'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-01-15','Kenan Yalçınkaya','CVK firması eskiden yoğun çalıştığımız lokasyon, İlhan bey ile görüştüm beni hatırladı, sen gittikten sonra biz sizle sorun yaşadık ve çalışamadık dedi. Aynı odada mühendisleri Ziya bey vardı firma adımızı duyunca aman sizin yüzünüzden neler çektim ben dedi. Rekor arıza sırasında 2 kez sırt atmış kaplamalar ve o makine çalışamadığı için taşerona eksrta ödeme yapmak zorunda kalmışlar merkeze bizi şikayet etmişler merkezleri Doğangüye vermiş o lastikleri sorunsuz çalışmış. ben bunu tazmin edebileceğimzi söyledim yanaşmadılar, Yokohama ve eski günler sohbeti sonrası yumaşadılar senin gelmen hatrına 2 lastik daha vereceğim sana gel haftya al onlarda çalışmazsa daha bize gelme dedi Ziya bey. fiyat içinde teklfini at ama benim dediğim fiyattan olacak dedi bende tamam dedim. İlhan bey CVK nın yeni altın maden projesinden bahsetti sarısu balıkesirde bana oranın bilgilerini verdi. bir kaç ziyaret sonrası yine çalışmayı esk formuna döndürmeyi hedefliyorum. 7 loder var bu tesiste. Tatko ve subaşı çok aktif yeni lasttik veriyor. BKT test lastiğ vermiş yeraltı loderine 20 adet yer altı loderi var ama ebatları micehelin tekelinde malesef.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('839df509-e6aa-5701-b6f7-ccbcf11bb05d','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='KORAT MADEN' AND il IS NOT DISTINCT FROM 'BALIKESİR' LIMIT 1),'6e3a1d8f-aacb-525c-91ea-d2591b1b62dc'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-01-15','Kenan Yalçınkaya','Şantiye yolu çok kötüydü dereden geçerken aracaın karter muhafazası kırıldı. Fatih bey görüştük. Krom ocağı eski bir ocak, çok önceden EMF üzerinden çalışmıştık. Ocak kapalıymış yeni açmışlar. 2 loderleri var. Tatko ile çalışıyorlar. Yokohama ve kaplama görüştük.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('5b8fd0f5-a5f7-5345-9d91-d25fa3a6caa7','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='CVK ALTIN MADENİ' AND il IS NOT DISTINCT FROM 'BALIKESİR' LIMIT 1),'6acb15a1-3eb0-57ea-85ac-ddbff8329d30'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-01-16','Kenan Yalçınkaya','Satınalma Mehmet Doğan bey ile görüştük, CVK madenin Altın madeni şuanda kurulum aşamasında aslında 2 yıldır burada ve kurulum aşamasındaymış şu aralar hızlandırmışlar içeride yoğun bir inşaat çalışması var. Çok büyük saha ve açık işletme olacakmış. CVK yozgatta da altın maden ruhsatı almış. şuanda bu tesiste 2 loder var onlarda inşaat işlerinde çalışıyor. Mehmet bey ile sıkı iletişim içinde olacağız. ayrıca haftaya holding merkez satınalmalarını da ziyaret edeceğim.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('a525d63c-ca68-50bf-b62b-c87a2c113170','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='KARMAK' AND il IS NOT DISTINCT FROM 'BALIKESİR' LIMIT 1),'d1cee061-b886-5f7f-8220-fdd3140d7448'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-01-16','Kenan Yalçınkaya','Esan kurşun madeninin 15 yıllık taşeronu daha önce bir kere test kaplaması yapmıştık. 26 loderleri var. Mühendisleri Hakan bey ile görüştük. Tatko ile devam ediyorlar. Silik kaplama konusunu sordular açıkladım çok akıllarına yattı 2-4 lastik silik kaplama için satınalma sizden fiyat alacak dediler. Yokohama bezli yeraltı ürünlerinden bahsettim ilgilerini çekti. Tatko burada çok agresif TBR kaplama yıllık 1.000 adet potansiyelleri var Atlı düzenli haftalık kaplama için araç çıkarıyor.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('fa2d7df3-9ce5-5668-81ee-270348d8cc64','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='IŞIL MADEN' AND il IS NOT DISTINCT FROM 'BALIKESİR' LIMIT 1),'5e599c1a-6c6d-5daa-aaf2-b537d8bb8876'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-01-16','Kenan Yalçınkaya','Kütük mermerin firması, Recep bey ile görüştük, ocak kapalı nisan gibi açacaklar. Bülent Kristalden Yokahama almışlar fakat sökme-takmada sorun yaşatmış firma. 3 loder 4 belden kırmalı var. Sezona takip edeceğiz.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('3569814f-7104-5bb8-9544-858b7c5b8b8f','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='TOMAY GÜREL' AND il IS NOT DISTINCT FROM 'BALIKESİR' LIMIT 1),'252fccf4-5371-501c-9188-dea10831558b'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-01-16','Kenan Yalçınkaya','Tomay Gürel ile görüştük. Marmara adası göçük sebebi ile neredeyse durmuş durumda. BKT ile devam ediyorum, siz benim müşterime kasıtlı girdiniz dedi, sorduğumda verdiği firma ile Ispartada aktif çalıştığımızı söyledim. Orada çalışabilirsini adada yeri varsa çalışamayacaktınız firmayı ben öğrettim size dedi, bende firmayı iyi bildiğimi ve diğer tüm lokasyonlarında zaten eskiden beri çalıştığımızı bizim asla kasıtlı olarak müşterisine gitmeyeceğimizi söyledim. Ceat beko loder getiriyorum sanada vereyim dedi olabilir dedim. fiyat verdi inceleyeceğim. ödemeyi söyledim hemen yapalım bu ay içinde diye not aldı.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('3fcb2001-6daf-5575-af04-8bc82beef837','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ÇAMSAN' AND il IS NOT DISTINCT FROM 'SAKARYA' LIMIT 1),'42b03df1-58e5-5f97-b641-9773a0c4dfae'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-01-17',NULL,'Satınalma ve teknik müdürlük daveti üzerine gittim. Bizden aldıklarını düşündükleri Contilerin arıza şikayeti vardı kontrol ettiğimde bizden alınmadığını gördük, lastiğide hurdaya atmışlar, bir daha bizden almasanız bile garanti süreci için atmayın takip edelim dedim. sızdırmazlık kolonlarının iç subaplarında kısa olmasından hava sorunu yaşadıklarını söylediler, numune alıp hemen doğru ölçüde tedarik ettik, çok memnun kaldılar. 11.00-20 kullanan ekskavatörlerinin 10.00-20 düşürme konusundan teknik kitaptan yük ve diğer değerleri kontrol edip karar verdik. aldıkları michelin xzm lerin çok pahalı olması ve ömrünü kesilmeler ile tamamlayamamasından dolayı havalı Tiron önerdim, kesinlikle deneyelim dediler 16 adet için fiyat vereceğiz. Maxam test lastiğimiz dönüyor. kaplama için 5 loderi takip edeiyoruz. Continental dolgu lastikler için euro bazında sabit fiyat verip onlar için alacakları ebatları stok tutabileceğimizi söyledim.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('7be46ef8-25a7-5e12-b701-73243268ca28','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='CVK MERKEZ' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'1d4dd521-cc21-50d8-9613-2aff4f3e5e04'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-01-21',NULL,'Merkez satınalma ile görüştüm, kardeşim Kenanın eski mesai arkadaşı Emrah burada satınalma şefi olarak işe başlamış o ve amiri ile görüştüm. Amiri bizi tanıyor ve kırgın arıza konusuna sahip çıkmamamız ve hiç ziyaret etmememizden şikayetçiydi, ayrıca çok kişi değişiminden kontak kim bilemedik dedi. ben artık kendimin ilgileneceğini söyledim ve geriye dönük ne yapmamız gerekiyorsa yapacağımızı söyledim, bu yaklaşımımızdan çok mutlu olduklarını söylediler.  Yokohama konusu ilgilerini çekti. Çanakkalede yeni bir altın madeni açıyorlarmış, şirket altına fokuslanmış borsaya açılma sonrası. sıkı takip ediyorum en kısa sürede yeniden kazanacağız. fakat doğangü ve tatko çok sıkı ilişkiler içerisinde.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('4d7e7480-eb87-547c-a79f-a9a234953f6a','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='HP MERMER' AND il IS NOT DISTINCT FROM 'KASTAMONU' LIMIT 1),'851ba703-2e4d-5ecc-9490-f83d88e916bc'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-01-22','ŞEREF BEKTAŞ','Eray bey ile tanıştım, bölgeyi ilk açtığımda ben portföye katmıştım bu firmayı, 3 loderleri var. Maxam montajında Ahmet arkadaşımız topuğa zarar vermiş tazmin etmişiz. Alımlara ankara merkezlerinden Kenan bey bakıyor. Ocak kış sebebi ile çalışmıyordu. artık ben ilgileneceğimi söyledim.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('3722e719-a395-54d3-8136-128b24adbe5e','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='GARTUN MADEN' AND il IS NOT DISTINCT FROM 'KASTAMONU' LIMIT 1),'80794c75-9255-59c4-be7f-2b5531f37fc8'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-01-22','ŞEREF BEKTAŞ','5 Loderleri var, bölgedeki tek açık ocak. Sıkı tatko müşterisi yeni lastik konusuna direkt patronları karar veriyor. Ben satınalma Ebru hanım ve formenleri Fahri bey ile tanıştım. Daha önceden bezli yokohama almışlar ve arıza yapmış. Ebru hanım o ring bulamıyormuş ben hemen tedarik edip kargo yaptırdım ilk faturayı kestik yıllar sonra. Ebru hanım yeni için söz veremem ama kaplamada mutlaka sizi deneyeceğim dedi. artık ben ilgileneceğimi söyledim.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('a8960cbd-ef97-5ba4-ade4-fd7e0719fa8c','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='MCD MERMER' AND il IS NOT DISTINCT FROM 'KASTAMONU' LIMIT 1),'a0362b31-13bf-5888-8d6b-3f681c4ca2bd'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-01-22','ŞEREF BEKTAŞ','3 loder ve 1 kamyon var. Ocak kış sebebi ile kapalı. En son bizden Maxamı almış, Murat Gülenç bana mal satamıyorum çok kızıyorlar demiş bunun üzerine ihtiyacım olmamasına rağmen aldım dedi firma müdürü. Yokohama anlattım, artık ben ilgileneceğim dedim.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('f272edc2-f1d2-5109-9c27-e6b47023973f','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='IŞIL MADEN' AND il IS NOT DISTINCT FROM 'KASTAMONU' LIMIT 1),'57725ae8-fcb1-5477-a6d1-19c8c090ec83'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-01-22','ŞEREF BEKTAŞ','Kaplamalarda yoğun arıza olan firma halen bize kırgınlıkları var. Kütük mermer firması. Ocak komple kapalıydı. Recep bey ile takip ediyoruz.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('36239b7c-8053-5ad6-a874-3ea3994497de','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='EFEDAĞ MERMER' AND il IS NOT DISTINCT FROM 'KASTAMONU' LIMIT 1),'4a1566d3-b34a-589d-b880-f295f3aade40'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-01-22','ŞEREF BEKTAŞ','Bu bölgeyi açtığımda ilk çalıştığımız firmaydı, mühendisleri beni hatrıladı. Ocak kış sebebi ile kapalı. Burası Efendioğlu, Kasmer, Aydağ firmalarının ortak firması diğer firmalarda alımı bura üzerinden yapıyor. 4 loder ve 2 kamyonları var. Artık ben takip edeceğim bilgisini verdim. yokohama sunumu yaptım.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('e41a12cc-c3f9-5ceb-97a3-fc1f643e6dd8','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='AS ONUR MERMER' AND il IS NOT DISTINCT FROM 'KASTAMONU' LIMIT 1),'2111bf6e-d311-5092-aad6-d560b941d4d9'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-01-22','ŞEREF BEKTAŞ','Uzaktan akrabam olan Birol abi ile görüştüm, yeni açtıları fabrikadaydı. Kış sebebi ile ocakları kapalı. Fabrikada yatan 1 loder ve 2 kamyonu kontrol ettik, 2 adet lastik ihtiyaçları vardı fiyat verdik. Birol abi ocağa geçip orayı da kontrol etmemizi istedi. Yokohama sunumu yaptım, A40 kamyonlarında OE yokohama vardı.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('28ad808e-f345-5b4e-8e76-e362e3e8ebc9','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='KASTAMONU ENTEGRE' AND il IS NOT DISTINCT FROM 'KASTAMONU' LIMIT 1),'d8e9cc29-2e6b-5deb-a428-d7e339895064'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-01-23','ŞEREF BEKTAŞ','merkezden Levent beyi aradım beni Sinan beye yönlendirdi, Levent beyde dün buradaymış denk gelemedik. Sinan bey ile randevulaştık tesise gittik 1 saat odasında bekledik fakat acil toplanstısı sebebi ile yüz yüze görüşemedik ayrıldık. Bizi akşam aradı ve çok özür diledi, keşke 3 gün önce gelseydiniz 26.5 vardı tamire sizi bilmediğim için ankaraya gönderdim dedi. beni özellikle yine beklediğini söyledi.2-3 hafta sonra için sözleştik. buranın eski mühendisi kronospan firmasına geçmiş burası ile yanı sektörde firma, aradım fakat açmadı zaten pehlivanların damadı olduğu için bizi çok sevmiyordu.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('36cf6412-ba81-5bb4-aa12-884436d17e53','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='SERVO İŞ MAKİNELERİ' AND il IS NOT DISTINCT FROM 'KASTAMONU' LIMIT 1),'80697715-a1d7-58fe-94d2-740973a29cba'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-01-23','ŞEREF BEKTAŞ','Bölgeyi ilk açtığımızda çok paslaşmıştık, Hüseyin bey işleri büyütmüş, o zamanda makineleri akasya madende kiralık çalışıyordu, şimdi 6 loderi var kiralık. 1 tanesi kaplama için fiuyat verdik. Diğer 5 loderi madende kontrol etmemizi istedi. 2 saatlik yola gidip tüm makineleri ölçüp talebi bildirdik. MAxam L5 teklif ettim fakat Cüneyt zamanı maxam arızaya sahip çıkmadınız asla almam dedi. ölçümde BKT L5 lasitkleri gördük, Yokohama sunumu yaptık. kırgınlığı zamanla gidince L5 için bize iyi bir nokta olacak. artık ben ilgileceğimi söyledim.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('a978ad93-aaed-5824-b992-f1426155e58b','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='HASPINAR İNŞAAT' AND il IS NOT DISTINCT FROM 'KASTAMONU' LIMIT 1),'fa9b922f-9272-571e-9462-cabc26048e9b'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-01-23','ŞEREF BEKTAŞ','Taşköprü - Boyabat arası yol yapıyorlar. 1 loder ve 1 greyder var. Tatko ile çalışıyorlar. Alımlara Ömür bey bakıyor yerinde yoktu telefonda görüştük masasına kart bıraktık ve katalog.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('e37124d1-7615-5747-92d3-d746c3c702ba','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='AS ONUR MERMER' AND il IS NOT DISTINCT FROM 'KASTAMONU' LIMIT 1),'2111bf6e-d311-5092-aad6-d560b941d4d9'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-01-22','ŞEREF BEKTAŞ','Ocak kapalıydı makineleri yatarken ölçtük, kaplama için olanları not aldık ve firmaya bildirdik. 3 loder 1 kamyonda bu ocakta var.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('7045a158-30b0-5037-a8df-418b91dd18ab','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='MUTAŞ MADEN' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'ba748c07-7c1f-5096-b497-96b5a15a9991'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-01-27',NULL,'Satınalamdan yetkili Ece hanım ile tanışmaya ve zamlı fiyatları görüşmeye gittim, burada sabit fiyattan kaplama için çalışılıyordu. 1 Şubatta geçilmesi gereken fiyatları öncesinde sunumuştum, zam öncesi 6 lastik verdiler bunları eski fiyatlarından yapacağız. Ece hanım teklifi değerlendirdiklerini söyledi. Ocağı da ziyaret edeceğimzi söyledim, biraz beklememi teknik departmanda ciddi bir değişiklik olacağını yakın zamanda bu bitince yeni kadro ile tanışmamı istedi. Tokatta krom ocağı açıyorlarmış, Alanya ve Tavşanlıda da krom işine girmeye başlamışlar. tüm potansiyellerini yakından takip ediyorum.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('5e0d9c34-63ca-56b8-b2a4-9da3da60e8b2','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='YILMAZLAR MADENCİLİK' AND il IS NOT DISTINCT FROM 'BALIKESİR' LIMIT 1),'da449dbc-1b5b-54a9-b4ec-2bb2fa9b54bb'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-01-27',NULL,'Fatih Yılmaz ile görüştüm, 5 adet 29.5R25 kaplamaya aldı, bunlar arıza yapmazsa artık hepsi sende iyi takip edelim dedi. Ziyaretine gelen lastikçiler muhtemelen bursa bayileri bizim artık lastik işini bıraktığımızı söylemişler, bende aksine yine ben seninleyim biraz organizasyon yapımız değişti onlar bunu magazinsel ele almışlar dedim. 29.5R25 L5 alımı söz konusudu biz Yokohama için 285.000TL+KDV verdik fakat subaşı GY RL5K için 240.000TL+KDV vermiş. L4 için Yokohama 188.000TL+KDV fiyat verdik Subaşı 170.000TL Goodyear GP4D fiyatı vermiş. Kemal bu farklar ile işi sana veremem kusura bakma dedi. bende yine bir bakıp döneceğim dedim zaten alımı da kaplamaların duruma göre biraz ertelerim belki dedi. 8 loderi var. TBR için Sailun sunumu yaptım çok sıcak bakmadı.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('ebd97374-a8a1-526c-8e80-4260c2ea35b9','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='TARHAN MADENCİLİK' AND il IS NOT DISTINCT FROM 'BALIKESİR' LIMIT 1),'a6410dd2-3fe5-51ee-854e-76e4eb902a60'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-01-27',NULL,'Makine müdürü Ali  bey görüştüm 4 loderleri var.  TKİ taşeronu olarak devam ediyorlar. 29.5R25 L4 fiyatı verdim. Takip edeceğim.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('03e84075-cf99-56a0-bb82-5148dfa00e4c','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='GÖNLÜGÜR OTOMOTİV' AND il IS NOT DISTINCT FROM 'İZMİR' LIMIT 1),'a56466d3-ef1f-52e6-8264-1aa6f5d854b9'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-01-29',NULL,'Gökhan gönlügür ile görüştük. 900.000 bakiyemiz var vade geçimi vardı, Gökhan çok özür dileyerek hemen 500.000TL yi kart çekti kalanı için haftay bitirme sözü verdi. İrfan Gönce Ankara Özcanlar Süleyman ile gelmiş artık buraya vereceksin diye baskı kurmuş. 11. aydan beri bize sadeve 1 tamir vermişler o süreden beri kimseye vermiyoruz madende sorun var diyorlamış, banada aynı şeyi söyledi fakat sonra İrfan bey zorladı mecbur verdim Özcanlara dedi. ama yine hepsini vermedim madende sipariş onay sorunu var bekletiyorum dedi. bence o süreçten beri yani 11. aydan beri Özcanlara veriyor aktif. Artık oraya vermeyeceğim ödeme de ters düştük mal inmeden para istedi özcanlar zaten işçilikte sıkınte elime koz geçti bunu öne sürüp brisaya onlara vermeyeceğim yine size vereceğim dedi. eksiden maden çok Yokohama satıyordum dedi desenleri ismi ile söyledi, bunları sana ebat ve desen olarak atacağım 2-4 vereceğim madene Yokohama dedi. Daha önce Yokohama satmak üzere Işıl hanım ziyaret etmiş ve fiyat vereceğimizi söylemiş. ben elimizden geldiğince yardımcı olacağımızı söyledim. kaplama konusunu takip edeceğim. Mustafa Kırbaşoğlu ile iyi dost o da Doğangüye geçti şimdi o da bana baskı yapacak dedi.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('27f5027b-9784-5822-ab91-89cc354cd553','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ORBİTAL LASTİK' AND il IS NOT DISTINCT FROM 'İZMİR' LIMIT 1),'f722f9dc-31bb-5668-b33d-2a2d487ccc5f'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-01-29','ŞEREF BEKTAŞ','Metin ve Ziyanın ziyaretindeki tavırlarından çok rahatsız olduğunu söyledi. Madenin kaplama fiyatlarındaki artışa itiraz edip %5 daha indirime ihtiyacı olduğunu söyledi. En fazla %2,5 yapabileceğimizi maliyet konuşmaları sonrası açıkladık. Madene sunacak güncel fiyatları.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('a9866d62-833b-595c-a797-26621e478e1b','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='DENİZLİ OTO LASTİK' AND il IS NOT DISTINCT FROM 'DENİZLİ' LIMIT 1),'836fb19c-8399-5e9c-87c2-b38db1f88287'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-01-30','ŞEREF BEKTAŞ','Ali Ulu ile görüştük, Doğangü ile devam ediyor, Mustafanın orada başladığını duymamış. Genel sohbet ettik. Brisa OTR kurması için ciddi baskı yapıyormuş ama ben yapmak istemiyorum istediğim her yere kaplatabiliyorum dedi ama onlar buraya birisi ile tesis kuracak bence dedi, burayı boş bırakmayacaklar dedi. genel işlerin azlığını söyledi. ben yeniden buralardayım haberleşiriz dedim.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('9a35e3f5-465c-5530-903a-150e6e7e13cc','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='KUĞ LASTİK' AND il IS NOT DISTINCT FROM 'DENİZLİ' LIMIT 1),'fb4d6ced-253c-5e23-8e85-89a70b73f590'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-01-30','ŞEREF BEKTAŞ','Serhat bey ile görüştük, iade konusu söyledi, sonuçta malı isteyerek aldım biz iade almak zorunda değildik sende sattığın malı tahsil edemeyince iade almak istemiyorsun dedim. İlave destek istedi maliyetlerimize göre en iyi fiyatlarımızı sunduğumuzu söyledim. eğer ticarete devam edeceksek kalan bakiyenin sıfırklanması sonrası 1.000.000TL DBS açmadan iş yapamayacağımızı söyledim. DBS yi ayarlayacağını söyledi. Takip  edeceğiz.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('09bef7ac-e41c-5b2f-8ba8-02fa89770b63','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='TEKMAR MERMER' AND il IS NOT DISTINCT FROM 'MUĞLA' LIMIT 1),'864667e3-944c-5849-b0ba-0990a8c056b7'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-01-30','ŞEREF BEKTAŞ','Kamuran ile görüştük, ödeme konusunu 120 güne sabitlemişler, Yokohama 4 adet 29.5R25 denemeleri için almalarını söyledim, satınalmadan talep edeceğini söyledi. Karkaslar çok eski olduğu için kaplamay lastik çıkmıyor senden sonra da kaplatmıyorum dedi. kaplama içinde düzgün olanları alalım dedim. Satınalma üzerinden talepleri takip edeceğiz. 14 loder ve 6 kamyon var burada tek vardiyaya düşmüşler işler zayıf oldukça.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('80828efa-7e77-5335-857b-27fa35e6863b','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ÇOBANLAR MERMER' AND il IS NOT DISTINCT FROM 'MUĞLA' LIMIT 1),'7ebca720-372b-541c-b656-7807d702631d'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-01-31','ŞEREF BEKTAŞ','Harun Çoban ile görüştük, normalde artık tedarikçi görüşmesi yapmadığını fakat beni özellikle kabul ettiğini dinleme istediğini söyledi. Son durumu güncelledim not aldı her şeyi. Tatko ile aktif devam ettiğini 3.500 saaati kaplamada geçemediğini söyledi. bize 4 lastik vereceğini bunu Tatko fiyatından yapıp performansı takip edeceklerini söyledi. Yokohama içinde satınalmaya bilgi vereceğini bana anlatıklarınızın hepsini mühendisleri Feridun ve satınalma Meral hanıma anlatmamızı istedi.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('8331cfde-70ef-50f2-9d53-3b1dd18bd0a6','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ÖZALTIN İNŞAAT' AND il IS NOT DISTINCT FROM 'ANKARA' LIMIT 1),'d4358e8a-e1e1-54ce-99be-6ed81bf4c855'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-02-04',NULL,'Nenetahun merkezlerinde Satınalma yetkilileri Erkan Yıldırım ile görüştüm. Mersinde yol projeleri devam ediyor, Aydında Baraj işleri var. Fakat asıl yoğun işleri Romanyada yol yapıyorlar, Romanya için alımı o taraftan yapıyoruz dediler. Türkiyedeki projeler ödenek geldikçe devam ediyor çok yavaş devam ediyormuş. Mersin için bize arada kaplama ifyatı soruyorlar. 2-3 ayda bir ziyaret edip talepleri kaçırmayacağım. Yokohama sunumu yaptım ilgilerini çekti. yine kardeşler ulaşım ile çalışmaya devam ediyorlar.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('e2d46673-9c12-5087-9a66-8a6a770cf08b','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ÖZALTIN İNŞAAT' AND il IS NOT DISTINCT FROM 'ANKARA' LIMIT 1),'d4358e8a-e1e1-54ce-99be-6ed81bf4c855'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-02-04',NULL,'Ilısu barajından eksi kontağımız makine müdürleri Necati Özkan ve Satınalma Yetkilileri Bekir bey ile görüştüm. Mersin, İzmir bergama, muğla ve Sivas Gürün de baraj ileri var. Tüm şantiyeleri ödenek sıkıntısı sebebiyle kapatmışlar. Kardeşler ulaşım ve diğer brisa bayileri ile ticaretleri devam ediyor. Yokohma sunumu yaptım. işler açıldığında değerlendireceğiz dediler. 2 ay sonra yine yoklayacağım.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('71f229fc-c302-5baa-97bb-bc8f8af0b62f','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='GÖÇAY İNŞAAT' AND il IS NOT DISTINCT FROM 'ANKARA' LIMIT 1),'79bdbffa-a80b-5f14-878e-1dead97925ce'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-02-04',NULL,'Ali Brücü ile telefonda görüştüm, Müteahhitlik kısmından artık çıkmışlar, ellerinde hiç proje yok. İzmir otoyol işletme ve otel işlerini bakıyorlar.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('4704dc99-651d-53f4-b45f-eb0b71e92861','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='TBR LASTİK' AND il IS NOT DISTINCT FROM 'ANKARA' LIMIT 1),'5ed18bc6-5f04-5a05-add8-af3ad977959b'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-02-04',NULL,'Üzeyir abi ile görüştüm, iş makinesinde tüm konularda benimle iletişime geçmelerini istedim. Kaplamalarda akoya vermiyorlar fakat yakın dönemde AKD fırat orbit kurunca gelmiş onlara vermeye başlamışlar. Sizin fiyatlar çok yüksek hiç uymadı bize dedi. hedef fiyat istedim bana hedef fiyat verecekler çalışıp döneceğim. Maxam işimnde Derlasın bizden ucuz olduğunu oradan devam ettiklerini söylediler, hatta bir ara stok 60 adet oldu dedi, bende stok alınca paranın maliyetini hesaplarlar ise bizden anlık 4-8 almalarının daha ucuza gelceğini söyledim. doğru söylüyorsun biz hiç öyle bakmadık dedi. yeni işine oğlum Onur bakıyor ben ona ileteceğim dedi. kaplamada vermeye başla bize bende tamirleri sana vereyim, emanet için karkas alayım senden karşılıklı gidelim dedim. Uğur hep bize satmaya geldi sen böyle yanaşıyorsun ben elimden geleni yapacağım dedi. genel sohbet ettik.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('897b358c-2fad-5bca-b754-10b78de6e3d8','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='SEZA İNŞAAT' AND il IS NOT DISTINCT FROM 'ANKARA' LIMIT 1),'b7ec08e6-4631-523f-bcb4-fb268351a59b'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-02-05',NULL,'Eski kontağımız Hacı abi ve Emre bey ile ostimde görüştüm. Uzun süredir bu firma ile iletişimimiz yoktu. Konya Seydişehir, Konya Çevreyolu, Manisa Akhisar ve Kastamonu yol projeleri var. Bunların hepsi ödenek sebebiyle düşük tempoda çalışıyor. Elazığ Çimento fabrikası aktif devam ediyor. Ayrıca elazığda da yol projeleri var. Hacı abi iş makinesi taleplerinde yine bizle çalışmaya başlayacağını söyledi. Grup firmalarından Açılım ve Açık inşaat tarafında işler kötü olduğu için proje almıyorlarmış. Aylık olarak Hacı abiyi yoklayacağım, Bridgestone alımları devam ediyor ama OTR için bana başlayağımıza dair söz verdi.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('66e3e037-3ddc-5aa7-bdd0-5bf141e6da48','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='KÖSEOĞLU GRUP' AND il IS NOT DISTINCT FROM 'ANKARA' LIMIT 1),'53a655e5-4e0e-50d7-a648-d9aa467d96fe'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-02-05',NULL,'Türkiyenin en büyük maden ihracatı yapan krom madeni Accacia madenin ana taşeronu. Ayrıca Sivas divriği, Erzurum İspir ve Sivas kangalda maden işletiyorlar. Toplamda 30 lastikli yükleyicileri var, Atlı otomotivden Bridgestone alımları yoğun. Satınalma yetkilisi Tuncay bey ile Ostimde görüştüm. İş makinesi kaplamada bize denemeye lastik verecekler sonrasında yeni lastik kısmında bizi deneyecekler. 17.5R25 14.00R24 ve 26.5R25 için kaplama fiyatlarımızı atacağım. TBR konusunda tamamen Petlas alımına dönmüşler. 26.5R25 Yokohama L5 fiyatı verdik, Bridgestone ile kıyaslayacakalar. ben oradayken atlıdan Bartu aradı adam benim onu tanımadığımı düşünürek rahat konuştu,çok samimiydiler. Bartu hiç fiyat vermeden zam gelecek sana 2 palet jant yoluyorum dedi adam sorun yok gönder gelsin dedi. Kaplama ile başlamak üzere aylık takip edeceğim.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('103c4f1b-c099-519d-b639-05312524bcdf','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='BAHAR MADENCİLİK' AND il IS NOT DISTINCT FROM 'ANKARA' LIMIT 1),'a75442c9-b0ca-50bc-bef3-e4a58bc196a8'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-02-05',NULL,'Satınalma yetkilisi Ahmet bey ile Ostimde görüştüm. Fatsa ve Sivasta aktif altın madeni işletiyorlar. Bergama ve Niğdede aldıkları altın maden ruhsatları var buraları da yakın zamanda açacakar. Özcanlar lastik ile çok aktif ve tek tedarikçi olarak çalışıyorlar. İstanbulda cenderede kırma eleme tesisleri var bize buradan talep gelirse deneme için kaplama verecekler bize. Toplamda 20 loderlei var. Aylık takip edeceğim istanbul ile kaplamada başlamak hedefim. Yokohama ilgilerini çekti.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('47bf4c15-ad81-559a-8b9d-75cd73fddbf1','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='BAYBURT GRUP' AND il IS NOT DISTINCT FROM 'ANKARA' LIMIT 1),'06fb320a-a960-5765-9444-47611a6cf8f0'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-02-05',NULL,'Satınalma müdürleri Erkan bey ile Ostimde görüştüm. Yurduseven bayisi ile aktif çalııyorlar, eskiden Kardeşler Ulaşım üzerinde iş makinesi kaplamalarını biz yapıyorduk dedim bizi oradan hatırladılar. Bir çok şantiyemiz var fakat şuan en aktif Alaşehir ve uşak tren hattı dediler. Rasim aldığı kaplamaları 2 ayda geri teslim edemediği için patronları tepki göstermiş ve bize iş vermemelerini söylemiş. Erkan bey kaplamada mutlaka bize tekrar deneme için lastik vereceklerini ve patronlarını yumuşatacağını söyledi. 200 adet loderleri olduğunu söyledi. Erkan bey ile freknasım tuttu aylık takip edeceğim hızlıca kaplamada yol alacağımıza inaniyorum.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('1da341f0-2436-5575-b08c-e070f43f6b70','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='GALEN MAKİNE' AND il IS NOT DISTINCT FROM 'ANKARA' LIMIT 1),'abbfc2e5-c38d-5e10-8bc8-c1675f1779b5'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-02-05',NULL,'Komatsu iş makinelerinin Ankaradaki en büyük servisi. Marubeni merkezden tanıdığım Serdar beyin referansı ile gttiim. Firma sahibi Servet bey ile görüştüm. Buradaki işlerine talip olduk, talep durumunda iletişime geçecekler. Her gittiğimde uğrayıp takip edeceğim, aylık 2-4 kaplama potansiyeli var. arada yeni de alıyorlar.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('b5a02a8a-f0b1-5a67-bfec-5d1549c7fb37','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='TURAN BEKİŞOĞLU MERMER' AND il IS NOT DISTINCT FROM 'ANKARA' LIMIT 1),'399317cf-b783-5f34-bc18-03f2c47b49be'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-02-05',NULL,'Saray merkez fabrikalarında Kerim bey ile görüştüm. Mermer firmalarının işleri çok kötü fakat bu firma amerika pazarına mal sattığı için işleri çok iyi. 11 loder ve 5 kaya kamyonları var. Sivrihisar ve iççehisarda ocakları var. Daha önce çok aktif çalışmadık. Makine ve ekipmanları yenilemişler lastik talepleri yakında olmayacaktır. Ocaklarını ziyaret edip ekipmanları kontrol edeceğiz. Talep halinde iletişime geçecekler. Ocaktan çıkacak talebi takip edip buradan almaya çalışacağım.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('e55ee433-f778-50de-9209-7ec0881ab321','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='GÜRBAĞ İNŞAAT' AND il IS NOT DISTINCT FROM 'ANKARA' LIMIT 1),'48f03ad3-c3ec-520a-9bbd-68ea76d1180a'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-02-06',NULL,'Satınalma yetkilileri İrfan bey ile görüştük. Diyarbakır şehir hastanesi, Adana İmamoğlu sulama kanalı, Ankara su hattı, Antaya sulama kanalı projeleri aktif. 8 loderleri var. Anakara şantiyelerinde 3 adet 23.5R25 lastik tespit ettik kaplanabilir. Ayrıca Diyarbakırda lastikler var gidip bakın onlarıda inceleyin dediler. Fiyat teklifi verip takip edeceğiz. İrfan bey mehmet Özden ile akraba ama Tatko ile çalışmıyor.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('e39306cd-b947-590c-bfea-c1a7b864db8e','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='AGE İNŞAAT' AND il IS NOT DISTINCT FROM 'ANKARA' LIMIT 1),'3d28f645-02ab-559f-a371-fbb338c162e4'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-02-06',NULL,'Teknik müdürleri Eyüp bey ile görüştük, Eyüp bey ile Adana baraj şantiyelerinden çalıştığımız eski dönemden tanışıyoruz. Şuanda Konya sulama kanalı, Sinop gölet, Antalya gölet işleri var bunlar bitmek üzere yeni yıla ihale kovalıyoruz elimizde iş kalmadı dedi. Bridgestone ve Goodeyar almaya devam ediyorlar. Bizden Uğur arkadaşımız en son greyder lastiği almış kaplamaya onları 2 yada geri teslim edemeyince sorun yaşamışlar. O günden beri sizden gelip giden yoktu dedi. 12 lodeleri ve 2 kaya kamyonları var. Kaya kamyonları müşterimiz HP mermerde Kastamonuda kiralık çalışıyor. Ömer yılmazdan aldığı MAxam lar çalışmamış. Yokohama konusuna sıcak baktılar. 2 ayda bir takip edeceğim.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('1736b6a5-ad18-5ace-92d6-cb73591903b9','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='KLV İNŞAAT' AND il IS NOT DISTINCT FROM 'ANKARA' LIMIT 1),'1fe55a6f-fc7c-54e1-9434-c406409d0fcf'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-02-06',NULL,'Satınalma yetkilisi Gamze hanım ile görüştüm, Gamze hanım yeni lastik kısmına Talip bey kaplama kısmına bakıyormuş. Talip beyde katıldı görüşmeye. Kıbrıs yol, Ordu yol ve gölet,Elazığ ve malatyada toki, Adanada yol ve Kazakistanda yol işleri var. Yılbaşında gelseydiniz keşke toplu Maxam aldık sizden de sorardık dediler. Lastikleri ZQ çalışanı Rahmanın şahsi firması CHN globalden almışlar. Sizden fiyat almadık çok kişi değişti kimi arayacağımızı bilemedik Saldıray, Uğur, Rasim vardı bizde karıştı dediler. Ben artık tek nokta benimle iletişim kurmaların söyledim. Kaplama için baskı yaptım, yeni aldıklarınız taktıkça çıkanları alalım dedim. Takip edip kaplamaları alacağım. Talip bey ile frekansımız tuttu aylık takip edeceğim.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('85d71662-86b8-541f-9b5d-c9c05d99b6f4','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='TBR LASTİK' AND il IS NOT DISTINCT FROM 'ANKARA' LIMIT 1),'5ed18bc6-5f04-5a05-add8-af3ad977959b'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-02-06',NULL,'Onur aradı 20 adetlik bir Maxam talep sordu yakın olduğum için yanlarına gittim. Fiyatları verdim verdiğim fiyatlara göre hemen yanımda fiyat verdi müşteriye. 23.5R25 Maxam L3 fiyatımız Çaplayanın onlara verdiğ VJT ile aynıydı ama zamsız eski mal yenisini alamayız bu paraya dedi. Çağlayan bunlara %25 iskonto yapıyormuş OTR de fix ama stokta özel çalışıyor VJT için maliyet verdiği fiyat. Kaplamalar için hedef fiyat beklediğimi söyledim. Sailun konusunda sizi randevu alıp ziyatet etmek istediklerini söylediler. Kaplamaları alabilemek ilk hedefim.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('f7de34f1-7aa4-58fc-9104-ca1d3bc79d83','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='GÖKSUTAŞ MERMER' AND il IS NOT DISTINCT FROM 'BİLECİK' LIMIT 1),'c27d7571-c0fd-5318-a1b3-c150286216c5'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-02-10',NULL,'Firma sahiplerinden Ömer bey ile görüştüm, beni hatırladı. Söğüt ve Dudakta 2 ocakları var. 2 loder ve 2 kamyonları çalışıyor. Fiyatları Alev hanım üzerinden topluyorlar beni tanıştıdı. Şuan işler yavaş olduğu için ocakları kış şartından kapatmışlar. fuara doğru açacaklarmış. Cariyi kontrol ettiğimde en son 2022 yılınca çalışmışız o günden bugüne hiç hareket olmamış, düzenl ziyaret de olmamış. takip ile geri kazanacağız.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('8118dbdc-e91e-5925-88a4-db594158a064','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='GÜLMER MADENCİLİK' AND il IS NOT DISTINCT FROM 'BİLECİK' LIMIT 1),'87e35df1-c6cd-58b1-849b-d49870791823'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-02-10',NULL,'Organize sanayiyi tararken loderi görüp girdim, 17.5R25 kullanan bir loder var. Big baglere yükleme yapıyorlar, lastikler aşınmıştı. Tesis müdürü Yasemin hanıma bilgi verdim, Muahmmed bey ilgileniyormuş yoktu bilgi vereceğini söyledi. Firma ayrıca Bergamada da aynı tesisi açacaklarmış orayada hizmet verebileceğimizi söyledim.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('037dca84-9e95-584d-a96d-3c95c8493e44','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='SAFİ ÇİMENTO' AND il IS NOT DISTINCT FROM 'BİLECİK' LIMIT 1),'e206332d-abb2-5df9-94d1-db2a45398c66'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-02-10',NULL,'Çimento fabrikalarında lojistik biriminden Mehmet bey ile görüştüm, filodan sorumlu mühendis kendisi. 2 loderleri burada 1 loderleri organize sanayi tesislerinde var. Biz ve solaksubaşını bildiklerini talep olunca ikimizede soracağını söyledi. Biz ile çalıştığını söyledi fakat cariyi kontrol ettiğimde hareket göremedim, takip edeceğim.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('fd27397d-3924-573c-9094-772f5f157ebb','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='TURGUT ÖZEN' AND il IS NOT DISTINCT FROM 'BİLECİK' LIMIT 1),'6a71ea54-0d2d-57c4-b923-b1e06db844ec'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-02-10',NULL,'Formenleri Şenol usta ile görüştüm, 2 adet 35/65R33 ve 2 adet 29.5R25 ve 2 adet belden kırmalı kamyonları var. Bizden aldıkları Maxamlar zincirde koparak iz yapıp aşınmış garanti talebine olumsuz olarak dönmüşüz fakat kontrol ettiğimde bizden resmi bir arıza kaydı talebi açılmamış gözüküyor sanırım Murat Yener bakıp cevap vermiş. ben inceleyip taleplerini takip edeceğimi söyledim. makine müsait olmadığı için inceleyemedik. bir öğlen arası için program yapıp resimleyip resmi kayıt açacağım bende durumu anlamaya çalışacağım. işleri yavaşlamış kaya kamyonlarını yatırıyorlar ama ocak aktif devam ediyor.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('ce7faa90-23f5-5be7-a8d0-55fca2f1e4b3','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='NATURA MERMER' AND il IS NOT DISTINCT FROM 'BİLECİK' LIMIT 1),'b5a0e608-3511-5287-ab0b-7b60e9dd2934'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-02-10',NULL,'Satınalmadan mühendis Uğur bey ile görüştüm, 3 loder ve 3 kamyonları var, ocak aktif çalışıyor. Özcanlar ile ilişkileri vardı en son aktif benim bildiğim. Eski kontağım kimse yoktu. 16:00 vardiye bitimi olduğu için çok verimli bir görüşme olmadı. Sonrası için detaylı görüşmek üzere sözleştik. Cariyi kontrol ettiğimde hiç hareketimiz olmamış','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('20dc9e06-c9c1-5005-8685-d01981a3e0ca','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='KARTAL MERMER' AND il IS NOT DISTINCT FROM 'BİLECİK' LIMIT 1),'515b7572-782b-56ad-aca8-86bacb53ce79'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-02-10',NULL,'Mühendisleri Nazım bey ile görüştüm, 2 loder ve 1 kamyonları var. Tatko ile aktif çalışıyorlar, bizden en son Beytullah ile kontakları olmuş, o dönemde satışımız olmuştu. 26.5R25 talepleri vardı fiyat verdim.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('ce377e38-4484-5e4e-9901-7f5963ffc1d7','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='FEDERAL MERMER' AND il IS NOT DISTINCT FROM 'BİLECİK' LIMIT 1),'5aef9238-6308-5cb6-9856-94a5aacf7cc9'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-02-11',NULL,'Mühendisler Selçuk bey ile görüştüm beni hatırladı. Makineleri yatıyordu, stoktan satuş yapıyorlar. Petlas alıma dönmüşler 6.000 saate petlaslar halen çalışıyor dedi. Baktım lastiklere fakat çamurdan inceleyemedim. Kaplanacak lastik var ama işler yavaş diye bekletiyorum dedi. Cariyi kontrol ettim en son 2023 yılında hareketimiz olmuş.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('ff679cdb-d336-537b-a5b8-ad3bb2d3c87c','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='TMG DOĞALTAŞ' AND il IS NOT DISTINCT FROM 'BİLECİK' LIMIT 1),'bc8dd035-d956-56af-9cd2-bc8363babbfb'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-02-11',NULL,'Mühendisleri Mustafa bey ile görüştüm, 3 loderleri var, bizden sanırım Furkan uğramış en son onu tarif etti. Yokohama alıp kullanmışlar memnunlar şauanda da çalışıyor lastikler. Cariyi kontrol ettiğimde hiç hareket yoktu.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('508e1be8-02f4-54ec-a142-1f2c1dedcfbe','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='VEZİR MERMER' AND il IS NOT DISTINCT FROM 'BİLECİK' LIMIT 1),'c9214911-f906-584a-8959-8b444d81aba7'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-02-11',NULL,'Mühendisleri Sümeyye hanım ile görüştüm, 2 loderleri var. Tatko ile çalışıyorlar. İşleri yavaş ama ocak çalışıyor. Cariyi kontrol ettiğimde hiç hareket yoktu. Önceden çalışmıştık.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('f510799b-1aa1-5780-bb83-c6f47a18cd2c','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='LİNDA MERMER' AND il IS NOT DISTINCT FROM 'BİLECİK' LIMIT 1),'6ea60056-9e2b-5c8a-aea1-8fecd74e2f0c'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-02-11',NULL,'Mühendisleri Kerem bey ile görüştüm. 2 loderleri var. Petlas ile çalışıyorlar. İşler yavaş hafif tempo çalıyorlar. Caride hareketleri yoktu.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('a9133e25-764b-5dd3-803d-fb052c158118','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ATALAY MADEN' AND il IS NOT DISTINCT FROM 'BİLECİK' LIMIT 1),'2f81dc2a-8ec8-5295-a723-d00606fc9cdb'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-02-11',NULL,'Adoçim sahası tabelası görüp girdim. Lastikli makine yoktu, sahayı taşeron olarak Atalay maden işletiyor, firma Bursa çimentonunda taşeronu. Firma merkezi Çorumda, Tokat Artovada adoçimde 5 loderleri çalışıyor. Süleyman takip edecek.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('40b58485-926f-51a1-952e-7bec673fd45d','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='SAYIN A.Ş' AND il IS NOT DISTINCT FROM 'BİLECİK' LIMIT 1),'7c84b599-5b59-5976-8ae6-8d9df1463cda'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-02-11',NULL,'Daha önceden çalışışyorduk firmayı tanıyorum Afyon merkezli grup firması. Mermer ocaklarını ziyaret ettim yine merkezde Aşkın bey ilgileniyor satınalma ile. Burada 2 loder ve 2 kaya kamyonları var. En son 2023 yılında çalışmışız Şeref abi takip ediyor bende takip edeceğim. Aşkın beyi aradım ziyaret edeceğim.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('fc76232c-432d-5ae9-a741-88013c9f3e1b','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='VEDAT BALTAOĞLU' AND il IS NOT DISTINCT FROM 'BİLECİK' LIMIT 1),'663750df-5235-5dec-8cd6-9bdd30fede68'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-02-11',NULL,'Vedat bey ile tanıştım, Hüseyin 23.5R25 için fiyat vermiş, Vedat bey ile loderi inceledik, yeni talebini tespit ettik. Bridgestone almak istiyorum dedi yanımda Albayrak Salihi aradı 23.5R25 VJT için 96.500TL KDV dahil vadeli fiyat verdi, fiyatı kendim duydum. Yokohama fiyatımız 124.500TL fakat rakip fiyatı gerçek olamayacak kadar ucuz ben yanlış fiyat verdiklerine inanmak istiyorum. verilen fiyat listeden tam 35 iskonto yani maliyetleri. Maxam ms302 satış fiyatımız kampanyalı 94.250TL.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('d2b5708b-699d-5dfc-93d9-298d51a75a0c','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='VEZİRHAN ÇİMENTO' AND il IS NOT DISTINCT FROM 'BİLECİK' LIMIT 1),'f2dfbde2-50c7-54f3-94ce-ddfacaaea3a6'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-02-11',NULL,'Satınalmadan Ercan bey ile görüştüm, 5 tesis ve 1 fabrika var. Toplamda 8 loderleri var. Loderler ile Bilim makine adında kendi firmalarında patronları İhsan bey Bursada bakıyormuş. Kenan programına aldı. Ödeme konusunda elleri briaz ağırmış ona göre takip edeceğiz. Cari kontrol ettiğimde hareketimiz yok.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('8dc6cd69-d079-5bea-b591-262d0659e9d9','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='CACİMLER' AND il IS NOT DISTINCT FROM 'BİLECİK' LIMIT 1),'aa393685-0551-5698-bb2f-e7a16dd1de35'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-02-11',NULL,'Vezirhan çimentonun taşeronu sadece burada 5 loderleri var, ben firmayı Çanakkale Akçansa taşeronluğundan tanıyorum oradayken atlının iyi müşterisiyledi. Adana Oyak çimento, Mersin, Afyon çimsa ve izmir çimentaş içinde loderleri varmış. Mersinde Gökhan bey ilgileniyormuş. Şeref abi o taraflardaydı yönlendirdim hemen ama şehir dışındaymış görüşemedik. ben ve Şeref abi takip edeceğiz.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('ccd1d69b-bd1b-585b-9690-7b1bc396cbc2','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='PRODEM MERMER' AND il IS NOT DISTINCT FROM 'BİLECİK' LIMIT 1),'4fc66b0c-e2b8-51c7-95d2-997acb32cf49'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-02-12',NULL,'Dün uğradığımda görüşmemişlerdi benimle, bugün Serkan şef ile görüştüm. En son size kaplattık dedi baktığımda en son hareket 2022 yılında. İşleri yavaş ama ocak çalışıyor. 2 loderleri var. Takip edeceğim.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('f0a205d2-73f4-5576-91d5-e389a00de6d1','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='DEVREK MERMER' AND il IS NOT DISTINCT FROM 'BİLECİK' LIMIT 1),'133a6f52-f4e1-5142-9f14-8c8656e0583c'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-02-12',NULL,'Firma sahiplerinden Mustafa Tabak ile görüştüm beni hatırladı. Buradaki ocak kapalı sadece fabrikaları açık, kastamonu ve karabük ocakları aktif. 5 loder ve 2 kaya kamyonları var. Alımları Devrekte Ural bey yapıyormuş. Geçen ay 4 loder lastiği almışlar ne alındığını bilmiyor. Devrekte takip edeceğim.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('6be10c16-5983-5497-8f34-0dc7fa4247a3','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='İÇTAŞ' AND il IS NOT DISTINCT FROM 'BİLECİK' LIMIT 1),'c90ed45b-bb57-57d1-8246-2a1755bc181b'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-02-12',NULL,'Hızlı tren şantiyesini ziyaret ettim, Hayrullah formen eskişehire gitmiş görüşemedik.6 loderleri var burada. Trelleborg L5 almışlar 7 adet depoalarındaydı. Buradan takibe başlayacağım.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('0d5c1f16-5b2b-5fed-bd96-06fe533b180b','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='GÖKYAR MERMER' AND il IS NOT DISTINCT FROM 'BİLECİK' LIMIT 1),'b6013855-562f-5a1c-9a91-bf4c75cefb3e'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-02-12',NULL,'Osman bey istanbuldaymış kardeşi Fatih ile görüştüm, işler oldukça yavaş dedi. Sivrihisar kar nedeniyle kapalı, söğütte krıcı çalışıyor sadece betonculara agrega veriyoruz dedi. Ocağa geçtim sonrasında, mğhendisleri Onur ile tanıştım, makineleri kotnrol ettik beraber, bir lastikte 30 psi gördük, bir çoğunda acil tamir edilmesi gereken kesikler ve ovakent kaplamalarında arızalar, Onur bey birden bana birşey demeden gitti, arakasından seslendim dönüp bakmadı. işim biitnce yanına gittim, Fatih beyde gelmişti kibarca durumu özetledim oda çok umursamadı. bir şey olursa haber veririz dediler. Tamamen Ovakent e dönmüşler sanırım Onur bey kanalı ile dönmüler ben sorunları gösterince bana soğuk yaptı. burada asıl muhatap Osman  bey onunla görüşüp tekrar kazanmaya çalışacağım. en son geçen ay ben 2 adet 29.5R25 Maxam verdim, ondan önceki ilk hareket 2022 yılında çok emek vermiştik kabetmemiz beni üzdü.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('86dd6fcc-f900-5ab7-bc03-cbedeb9eeed2','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ŞİLE MADEN' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'080c3745-36e5-5786-a9d9-61b33c072824'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-02-13','ADNAN KARAKAYA','Kış sebebiyle kamyonları merkeze çekmişler, burada 2 loder var biriside burdaydı kontrol ettik. Fatih bey bizi patrona götürdü, firmanın eskişehirdeki koçkaya hafriyat taş ocağında 7 loderleri varmış, bizim oraya kaplama yaptığımızı söyledi fakat carilerde bulamadım, brisa bayisi Özkan oto üzerinden yapmışız muhtemelen. 13R22.5 600D Petrolastan 14.000TL KDV dahil vadeli almışlar. Eşkişehiri takip edeceğim.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('1dd29f5a-afeb-5258-837d-9efd84255869','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ÇEKLİKTAŞ KUM' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'a441d5ae-ea2c-5dca-9f15-483d3c0d1ef2'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-02-13','ADNAN KARAKAYA','Mühendisleri Tarık bey ile görüştüm, test kaplaması yaptığımız makine arıza yapmış serviste yatıyormuş. Yine çıkacak ilk talep için bize haber vermesin bizimde satınalma Hülya hanım üzerinde  takip edeceğimizi söyledim.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('f500006a-d856-5afb-a1e8-865ea8c00498','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='KUMSAN' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'c377dfc6-00f0-5852-b882-fdd7b38a21e4'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-02-13','ADNAN KARAKAYA','Loderin bir tanesin kontrol ettik. Batık vardı çıkarttık derine geçmemiş, Kerem bey ile görüşemedik bilgi verip ayrıldık.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('75e10078-8961-5f9a-81f6-0e606666e4ba','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='DAŞDAN MADEN' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'351831ac-513b-57b0-ac63-d7017871426a'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-02-13','ADNAN KARAKAYA','Fırat Daşdan ile görüştük, tüm makine parkı yatıyordu, işler iyi değil dedi, taşeron çalıştırıyor kendi makinelerini kullanmıyor. Biraz da sezondan yatıyorlar. Takip ediyorum.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('0059d46a-cc31-5a81-a969-9600b02724c0','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='KALYON İNŞAAT' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'3db272f1-ce77-5e36-a7eb-46e6066acc14'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-02-13',NULL,'Bursa şantiyesinin çekini almak için merkezlerine gittim, tahsilat yapıldı.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('e4866e54-6b12-5d41-9321-9ce187f20409','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='DİMİN MADENCİLİK' AND il IS NOT DISTINCT FROM 'BİNGÖL' LIMIT 1),'1ad38d62-3ba4-51dd-867f-5a345a50dc67'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-02-18','SÜLEYMAN KILIÇ','Satınalmadan Muhammed bey ile randevumuz vardı fakat kendisi elazığdaymış, satınalmadan Merve hanım ve Mehmet bey ile görüştük. En son verdiğimiz 29.5R25 Yokohama teklifimizi çok yüksel bulmuşlar. Net rakam etik olmadığı için söyleyemeyiz fakat Micheline yakındı fiyatınız, Bridgestone Goodyear ile iyi bir fark vardı arada dediler. Michelin en yakın rakibinden %50 daha fazla ömürü yazılı garanti ettiği için tercih ettik dediler. 8 adet alım yapmışlar. Yılmazlar VLTS için 11.000 saat garanti vermiş, bizm hiç VLTS de 7.000 saat üzerini bu sahada görmedik. işi almak için ciddi saat garantileri verilmiş. Teknik müdürleri Nurullah bey ile de tanıştık. bu yıl için kaplama ihalesini Tatkoya verdiklerini 90 lastik dolmadan başka yere lastik veremeyeceğini söyledi. 2-4 lastik deneme için hazır olduğumuzu söyledim. bizim kaplama arızları olduğunda sürekli iade faturalaşmasından merkezdeki müdürleri çok rahatsız olmuş ve bizimle çok çalışmak istemediğini söylemiş. Yokohama için bu yıl yeni alım talepleri olduğunda fiyatımız en uygun olursa deneme yapabileceklerini söyledi. kaplama için Yılmazlar ve Tatko ciddi kapışmışlar, bedelsiz bir sökme takma makinesi hibe edilmiş, Yılmazların bu bölgeye bakan ve madenin olduğu köylü olan satışcısı Tatkoya geçmiş geçerkende firmayıda almış Yılmazlardan. Ankara merkezide ziyeret edeceğim. Süleyman kademeden ben satınalma tarafından takip edip 2 yokohama ve 4 kaplama verip seneyeki alıma kadar arayı düzelteceğiz.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('7b88ee4c-f76c-593f-a84c-66555a08ebcd','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='DİMER MERMER' AND il IS NOT DISTINCT FROM 'DİYARBAKIR' LIMIT 1),'03c5990c-3066-5e2b-b258-df3d9f27abe9'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-02-18','SÜLEYMAN KILIÇ','Dimer merkez fabrika ve kademeyi ziyaret ettik. Fırat usta ile görüştük. Dimer ile aynı grup olmasına rağmen Dimer ile çalışıyoruz burada Süleymanın kademe ile benim merkezde patronun yeğeni mesut bey ile ilişkimiz iyi durumda. 2 loderi kontrol ettik ve kaplama için alınacak lastikleri bildirdik. merkeze fiyat verip kaplamaları alacağız.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('13ac625e-76ec-537d-825a-768c82833dc6','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='DİMER MERMER' AND il IS NOT DISTINCT FROM 'DİYARBAKIR' LIMIT 1),'03c5990c-3066-5e2b-b258-df3d9f27abe9'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-02-18','SÜLEYMAN KILIÇ','Mesut bey ile merkez ofiste görüştük. Uzun süredir görüşememiştik, kaplama için tespit ettiğimiz lastikleri almamızı söyledi, fiyatıda atın bakarım ben dedi. Yokohama için mutlaka bu yıl 2 lastik alıp deneyeceğini söyledi. Deneme için 4 lastik Çağlayana vermişler fakat hepsinde arıza olunca artık vermeyeceğim dedi. tüm ocakları kış sebebi ile yavaş. Diyarbakır kulp ve adıyaman aktif. 10 loder ve 4 kaya kamyonları var. arızadan kalan 2 lastiği olduğunu bunu Murat Yener in ters tavırları yüzünden çözemediklerini söyledi. ben lastikleri inceletip bilgi vereceğimizi söyledim. lastikler bitsin öyle bakarız şeklinde bilgi verildiğini bunu kabul etmediğini söyledi.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('d2b31806-c53c-5db8-8291-6126e4f4c929','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ETİ KROM' AND il IS NOT DISTINCT FROM 'ELAZIĞ' LIMIT 1),'fac55ed9-11a4-52ba-9bad-f952d07169c0'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-02-19','SÜLEYMAN KILIÇ','Satınalamadan eski kontağım Ünal bey müdür yardımcısı olmuş, bize tüm satınalma ile bir toplantı organize etti. firma patronların ayrılması sonrası fabrika ve KEF ocak bölgesi olarak 2 ye ayrılmış her yerin satınalması ve teknik müdürlüğü ayrı. Ünal müdür yarıdmcısı, TOgay bey müdür, Coşkun ve Mustafa bey ise satınalam uzmanı, hepsi ile genel bir sohbet ettik. Kaplama için bu yıl yeni ihale olmak üzere buna katılacağız. ayrıca teknik müdürleri Selahaddin beyi de kademe ofisinde ziyaret ettik. masasında Solak subaşı katalopu vardı. Yokohamayı bilmediğini satınalam ucuz olursa alıp dener ancak dedi. kaplama içinde sizi biliyorum fiyat satınalmadan geçerse benim için sorun yok dedi.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('4f90f75d-7b90-5021-ab83-c7290f379c34','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ETİ KROM' AND il IS NOT DISTINCT FROM 'ELAZIĞ' LIMIT 1),'fac55ed9-11a4-52ba-9bad-f952d07169c0'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-02-19','SÜLEYMAN KILIÇ','Ünal bize ocak tarafında da toplantılar ayarladı. Ocak satınalma uzmanı Kutsal ve müdürü Haşim bey ile görüştük. En veridğimiz 26.5R25 Yokohama teklifimizde fiyatta farkın olduğu için Bridgestone ile devam ettiklerini ve çok memnun olduklarını söyledi. kaplama içinde henüz Tatko ile ihale devam ettiği için teknik müdür Talat beyin takibinde olduğunu  söyledi. Talat bey ile görüştük, Bridgestone çok memnun ve değiştirme eğiliminde değil, kaplama içinde henüz tatkoya verilen adetler ihaleyi doldurmadı ama dolunca sizde yeni ihaleye katılın dedi. Yokohama için deneme amaçlı az miktarda fiyat eğer satınalmadan geçerse alırım dedi. biraz daha takip etmemiz gerekecek.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('51cf6f6d-d24c-5313-a134-671febb9efbb','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ALACAKAYA MERMER' AND il IS NOT DISTINCT FROM 'ELAZIĞ' LIMIT 1),'2eb08171-6927-5779-a477-92f5a47d6314'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-02-19','SÜLEYMAN KILIÇ','Satınalmadan Ersin bey ile görüştük. Verdiğimiz tekliflerin hep çok yukarıda kaldığını söyledi, zaten teknik onayıda Bayram bey veriyor son karar yine onda dedi. Yıllardır Bayram beyi aşamıyoruz burada. Bayram beyin ofisine geçtik bize çok sıcak davrandı eski hırçınlığı yoktu. ilk çıkacak kaplamalardan 4 adet alın deneyelim hemen takip edip Karamandan alın dedi ben size hedef fiyat vereceğim dedi. Yokohama Bülent kristal mağdurlarından olduğu için çok yorum yapmadı, talep olursa konuşalım dedi. 40 adet lastikli makineleri var. 15 yıldır aralıksız tatko ile çalışıyorlar.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('c0c14965-a40a-53a8-bc3b-7c100ef4a795','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='AKDAĞ MERMER' AND il IS NOT DISTINCT FROM 'ELAZIĞ' LIMIT 1),'f55d5980-e93e-55e4-b77e-cb614006b218'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-02-19','SÜLEYMAN KILIÇ','5 loder ve 3 kaya kamyonları var. Elazığ ve Tunceli ocakları açık. Satınalma ile görüştük. Bridgestone çok memnunuz yokohama düşünmeyiz dediler. Kaplamada en son biz yapmıştık yine talep olunca takip edelim dediler.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('e62293cc-6fdf-54e4-a41c-ab0fac9644e8','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='BURÇ MERMER' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'03841b24-f9c7-591f-9113-41afa038bda9'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-02-25','Kenan Yalçınkaya','Şeref abi firma sahibi Cem  bey ile Burdurda bir müşterisinde denk gelmiş, Cem beyde Bursa ocaklarına gidip lastikleri kontrol etmemizi istemiş. Ocağı geçen ay da ziyaret etmiştik kapalıyıdı, yetkili ile görüştük ocak kapalı kimse yok siz gidin lastiklere bakın dedi. Hatta Tatko da bakmaya gelecek sizinle aynı zamanda dedi. Ocak yolu karlı ve kötüydü, Tatko satış çalışanı Serkan Corolla aracı ile şantiyeye çıkamamıştı geri dönmeye çalışıyordu. Biz onu geçip biz ocağa çıktık, ocak uzun süredir kapalı yeniden açmak istiyolar. bu ocağa ben daha önce lastik satmıştım. ekipmanları kontrol edip Cem beye bilgi verdik, Tatkodan da fiyat alıp bize döneceğini söyledi. Şeref abi sonrasında görüşüp Maxam vermiş ve kaplamaları almak üzere anlaşmış.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('ce2fcaf3-ddc7-5108-b5e6-2d679a91d65a','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='JEOPARK' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'df6b9425-125d-5c2e-92df-b65702146cb1'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-02-25','Kenan Yalçınkaya','Ali Kemal abi ile görüştük, ocak kapalı stoktan sevkiyat yapıyorlar. Sezon başında lastik alabilriz dedi, 29.5R25 fiyat verdik.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('3c37b95e-78fa-56ad-828d-bcc62ea2562f','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ERKAY MADEN' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'bb02b48d-b869-523f-b6bf-145ec0769be3'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-02-25','Kenan Yalçınkaya','İkinci ziyaretimizi yaptık, Ramazan bey bizi tanıdı, feren basmışlar krom fiyatı düştüğü için kendi ferro krom firmaları olan BG Ferro kroma çalışıyorlarmış. Orayada Ramazan bey bakıyormuş. Loderin lastikleri kaplanabilir seviyedeydi fakat işler açılmadan bir şey yapmayacağız dedi.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('162ee8cc-6440-5d7b-ac01-c65b874fe623','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ORAK AŞ' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'667ce6f4-5894-5a31-82c6-429891eccc45'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-02-25','Kenan Yalçınkaya','Yol şantiyelerini daha önce ziyaretimizde merkeze yönlendirmişlerde Ankaraya ben Anrakada aradığımda merkez bakmıyor şantiyeye gidin dediler. Fuat bey ile görüştük, burada 1 loder var ve yeni alım yapmışlar şantiye 10 yıldır kurulu ödenek oldukça iş yapıyoruz dedi.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('b1b7dd3e-9516-5ee1-b9a1-57d306fe13c2','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='SEL MADEN' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'c6956321-e211-5258-9b8c-edb39a1becd9'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-02-25','Kenan Yalçınkaya','Şükriyedeki ocağı ziyaret ettik, firma afyon merkezli, 2 loderleri var. Firma sahibi ben afyondan çalışıyorum buralardan almam bişey diye soğuk yaptı bize, içeri davet etmedi. Takip edeceğiz.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('df34dc08-9bd6-5e01-96f8-53a5b30a5ae2','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='KUZEY YILDIZI MERMER' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'fcbd9c45-35a4-569f-b633-e6b695067258'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-02-26','Kenan Yalçınkaya','Ocak kapalıydı makineleri kotnrol ettik. 35/65R33 kaplama için görüşüyoruz. Tüm makineleri ölçütük ve yetkiliye bilgi verdik.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('eb511ab3-32a4-50fd-9fbe-5d61296e4e4b','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='HAYRİ ÖĞELMAN MADENCİLİK' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'515126e5-921f-5cae-b0f5-54efb6406e81'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-02-25','Kenan Yalçınkaya','İlhan bey yine telefonlarıma bakmadı, merkezi aradım kaplamarı çok fark var diye başka yere verdik dediler. Bir önceki ziyaretimde de İlhan bey benimle görüşmemişti. Merkez üzerinde takip edeceğim.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('abd9c370-dcfd-510b-8763-baee9382852a','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ORHUN METAL' AND il IS NOT DISTINCT FROM 'BALIKESİR' LIMIT 1),'814a1c4f-27f6-5cfe-9761-c65ce1880b90'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-02-25','Kenan Yalçınkaya','Daha önceden Uğur Yıldız aktif çalışıyordu, şantiye şefi Hamza bey ile görüştük, loderin lastikleri kaplama zamanı gelmişti ve tamirlik 26.5R25 vardı. İnceledik bilgi verdik. TBR kaplamaları markasız bir yere yaptırıyorlar 3.500TL KDV dahil dedi. Biz tüm talepler için fiyat verdik. 5 loderleri var.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('da0ff474-e3a4-555c-b60c-a10d5c0a1d29','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='KASTAMONU ENTEGRE' AND il IS NOT DISTINCT FROM 'BALIKESİR' LIMIT 1),'8dafea2a-6526-5842-8b99-5ae39a41332c'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-02-26','Kenan Yalçınkaya','Mühendisleri Yasin bey ve satınalmacıları Özen bey ile görüştük. 9 loderleri var. 8 adet 23.5R25 kaplama için hazır lastik var. Onlara fiyat teklifi verdik. Artık her tesis kendi satınalmasını kurmuş her tesisi geziyorum. Her tesiste ortalama 8 loder var.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('457efa9b-5dab-56f7-be0c-042c96da9dfc','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='KARMAK' AND il IS NOT DISTINCT FROM 'BALIKESİR' LIMIT 1),'d1cee061-b886-5f7f-8220-fdd3140d7448'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-02-26','Kenan Yalçınkaya','Mühendisleri Hakan bey ve Satınalma Kenan bey ile görüştük. Tatko zammı sonrası başka yere kaplama vermişler fakat arızalar gelince yine Tatkoya dönmüşler. TBR için haftalık 200 lastik veriyoruz bize özel fiyat verin dediler. Avon+ 20 adet performans takip  için fiyat verdim. 26 loder var kaplamalar için teklifimizi verdim. vadeleri biraz uzun ve çok uzun süredir tatko ile çalışıyorlar. BKT alıyorlar Maxam anlattım.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
