INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('56c809c4-e233-5331-a1a1-e8fc592de760','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ÇAN 2 TERMİK' AND il IS NOT DISTINCT FROM 'ÇANAKKALE' LIMIT 1),'227e2e0b-34d9-5b06-8d99-a4b100fe61e5'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-02-26','Kenan Yalçınkaya','ODAŞ içerisinde özel firma , satıalma Melih bey ile görüştük. Kaç loderleri var bilmiyor ama BKT falan aldık dedi. Alımlarda sizede sorarım dedi. Takip edeceğiz.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('7f84c7ca-8a50-523b-ab9c-06beda1b97d6','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='DİMAKS BETON' AND il IS NOT DISTINCT FROM 'ADANA' LIMIT 1),'f684d5f2-a013-5909-a866-8306be04d1b7'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-03-04','SÜLEYMAN KILIÇ','Bülent Çam burada başladı beni davet etmişti. Bülent abi yoktu. Firma beton santrali, taş ocağı ve asfalt işi yapıyor. 5 loder ve 100 üzerinden damperli kamyonları var. Ana merkezlerindeki loderi ölçük, sonrasında yakın lokasyondaki loderi ölçtük. Yumurtalık tarafına geçip oradaki 2 loderi de ölçtük. 8 kaplama tespit ettik bize vereceklerini söylediler. tekip ediyorum.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('60232006-83d8-5e1a-9379-f4ff14cfbbbe','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='DİMAKS BETON' AND il IS NOT DISTINCT FROM 'ADANA' LIMIT 1),'f684d5f2-a013-5909-a866-8306be04d1b7'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-03-04','SÜLEYMAN KILIÇ','2 Loderi ölçtük, 6 lastik acil kaplanmalı, yetkliye bilgi verdik resimleri paylaştık.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('ddc2ea1c-fbec-58c3-8cf5-4987ca88305b','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='POLYAK KÖMÜR' AND il IS NOT DISTINCT FROM 'ADANA' LIMIT 1),'ec8fee73-5bb1-5200-98bb-07fdae393447'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-03-04','SÜLEYMAN KILIÇ','3 loderleri var, geçen hafta en son kaplananları teslim ettik. Loderli ölçtük 2 adet yeni lastiğe ihtiyaçarı var, teklifimizi verdik. Firmanın Afyon ve Konya da mermer ocağı, balıkesirde ve tekirdağda kömür ocağı var. Balıkesir hariç diğer lokasyonları ile de çalışıyoruz. her tesis alımı ayrıca yapıyor.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('0621ec7e-ade4-5d2a-9780-5ecb5f81f0c2','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='YCS BOZDOĞAN' AND il IS NOT DISTINCT FROM 'ADANA' LIMIT 1),'052e6d73-1e00-5a1f-ad67-3b0579b0f903'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-03-04','SÜLEYMAN KILIÇ','2 loderi var, taş ocağı işletiyorlar, firma sahibi eski GY bayisi olduğu için otr lastiği biliyorç özellikle L5 fiyatı sordu. Kaplama içinde fiyat verdik. Şuan talepleri yok. Takip edeceğiz.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('bb301d8e-1aa3-5fee-98e9-77e0099da120','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ÖZTRANS' AND il IS NOT DISTINCT FROM 'OSMANİYE' LIMIT 1),'541d474b-bc6e-527b-9c26-c41b1bd5ecc0'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-03-05','SÜLEYMAN KILIÇ','Satınalma müdürleri Emrah bey ile görüştük, bizden memnun olmadığını kaplamalarımızın 6 ay bile gitmediğini söyledi. Ayrıca lastiklerde olan çatlamalar yüzünden ana işveren İsdemir ile sorun yaşadıklarını söyledi. Tüm kaplamaların bizde takılış formlarının olduğunu bizdeki verilere göre 6 aydan uzun çalıştıklarını söyledik. emrah bey çok önyargılıydı müsade istedik tüm makineleri kontrol edip bilgi vermek için. HAtaya makinelere geçtik','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('58bd8958-24f1-5ac9-aa9b-d7f62c5079f1','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ÖZTRANS' AND il IS NOT DISTINCT FROM 'HATAY' LIMIT 1),'ab152e3d-c916-5deb-88f9-3437ddece542'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-03-05','SÜLEYMAN KILIÇ','İsdemir sahasında Öztrans 5 loderi ölçtük, orkap hamurlar 5000-6000 saat arası 10-11 ay çalışmış bitmiş bazıları devam ediyor. Hamur sertliğinden yanakta ciddi çatlamalar olmuş bunlar ana gövdeye de işlemeye başlamış bu sebeple isdemir lastikleri zorla söktürüp tamire göndermiş. formenleri lasitklerimizin az çalıştığını söylüyordu ölçümleri onunla yaptık, ben aslında çatlamalardan şikayetçişydim diye konuyu çevirdi.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('72d7c368-cb95-5b9d-a6ce-cbfeb1162156','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='İSDEMİR' AND il IS NOT DISTINCT FROM 'HATAY' LIMIT 1),'12f899db-b04e-5193-b1dd-6e3c9f1e2b2b'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-03-05','SÜLEYMAN KILIÇ','Eski kontağım Mustafa Ertük beye ulaştım, çok yoğun olduğu için saha içine girmeme rağmen telefonla görüştük. Portal üzerinden talepleri değerlendireceğiz','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('2e2efa4d-ea1a-5566-b15e-ef93622e5a47','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ASSAN PORT' AND il IS NOT DISTINCT FROM 'HATAY' LIMIT 1),'c222e772-0173-5f29-a7e9-2cd9c34a877a'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-03-06','SÜLEYMAN KILIÇ','Mühendisleri Şafak bey ile görüştük, 8 adet Tiron teklfimizin üzerine baskı içinde gittim, en son verdiğimiz makineyi ölçtük 2.960 saatte %60 diş derinliğinden rotasyon olursa 8.000 saat verilen garantiyi yakalar gibi. Yokohama konusuna çok sevindiler, gelince fiyat vermemizi istediler. 8 adet alımı sonuçlandırmadıklarını söylediler. 14 adet dolu konteyner taşıyıcıları var.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('38823511-65d5-5b61-a5c7-d3d623b261a0','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ÖZTRANS' AND il IS NOT DISTINCT FROM 'OSMANİYE' LIMIT 1),'541d474b-bc6e-527b-9c26-c41b1bd5ecc0'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-03-06','SÜLEYMAN KILIÇ','Emrah beye ölçümü sunmaya gittik, kaplamaların yeni lastiğe yakın çalıştığını belgeleri ile sunduk, ayrıca düşük havaları resim ve videoları ile gösterdik. Buna rağmen ben sizin kaplamanıza iyi diyemem dedi. Bende daha nasıl bir beklentiniz var yeni lastiği yakalamışız dedim. bana kademeden çalışmadığı bilgisi geldi siz geldiniz aksini söylüyorsunuz ben değerlendireceğim dedi. Solak subaşından 12 adet 26.5R25 RL-5K yı 200.000TL dahilden alım yapmışlar 4 adedi takılmıştı. Emrah bey kademeden gelen kirli bilgiden kaynaklı bozuldu, sanırım konuyu hazmedince kaplamaları almaya devam edeceğiz.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('5373a2e8-51c8-5201-8263-0e62a93fdbb8','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='SARGIN İNŞAAT' AND il IS NOT DISTINCT FROM 'HATAY' LIMIT 1),'95f16eee-8c36-5290-b663-462cae906578'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-03-06','SÜLEYMAN KILIÇ','Toplu konutlar ile Beleni bağlayan tüneli yapıyorlar. 2 loderleri var. Proje müdürleri ile tanıştık, ankara merkez bülent bey yönlendirdi. 1 yıllık işleri var.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('858216f8-9d00-5519-a7ef-6bd0310fd147','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='İNTEKAR İNŞAAT' AND il IS NOT DISTINCT FROM 'HATAY' LIMIT 1),'31d15e20-ef81-5137-95ca-1f2ee22b53eb'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-03-06','SÜLEYMAN KILIÇ','Belen ile Kırıkhan arası tünel işini yapıyorlar 7 yıllık bir proje 13 loder aktif çalışıyor. Serdar bey satınalmaya bakıyor bizi tanıyor daha önce çalışmıştık. Burası için fiyat alacak. Ayrıca ankara merkezde patronlarını ziyaret edeceğin final karar verici patronları.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('e4322747-cba5-569b-ba01-131048436bc9','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ASLAR BETON' AND il IS NOT DISTINCT FROM 'HATAY' LIMIT 1),'bb081f4f-a65b-5f8b-b7a0-d07267c5d4e0'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-03-06','SÜLEYMAN KILIÇ','ılısu barajından mühendis Ahmet abi burada baş mühendis olmuş o davet etti. 10 loderleri var Kavi ve Petlas ile çalışıyorlar. Beton santrali, taş ocağı ve kuars ocakları var. Kavi 23.5R25 40mm 34.000TL fiyatı paylaştılar bizim fiyatımız 40.000TL. Takip edeceğiz.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('f7cb4be3-2657-5d30-9d20-4aed33e37e4d','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='DENAS BETON' AND il IS NOT DISTINCT FROM 'HATAY' LIMIT 1),'b8a367cc-2881-574b-9799-bf5e24185185'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-03-06','SÜLEYMAN KILIÇ','taş ocağı ve baton santral işleri var, 10 loderleri var toplamda burada 2 loder var. Hatay merkezde Ali Emre beye yönlendirldiler diğer makineler için. Buranın yetkilisi ile görüştük.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('e2171877-d38f-5d16-941e-20b63e87e169','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='KASTAMONU ENTEGRE' AND il IS NOT DISTINCT FROM 'ADANA' LIMIT 1),'a2c30799-1ef3-5440-a876-5ffd38cdd756'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-03-07','SÜLEYMAN KILIÇ','Mühendisleri Muhammed bey ile tanıştım, Tarsus fabrikaları kapanması sonrası loder sayıları 14 olmuş. Bir kısmı arızadan yatıyordu. En son kaplama işini tatko almış. Artık kaplamalara tesis satınalmacıları karar vediği için tüm tesisleri gezyorum fakat buradaki satınalmacı işten ayrılmış şuan görüşebileceğim kimse yoktu. Muhammed bey tüm makineleri kontrol edip bir rapor çıkarmamızı duruma göre kaplama ve tamire lastik vereceğini söyledi. İSG izin olmadığı için kontrol yapamadık, Süleyman haftaya kontrol edecek.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('d63445c3-9849-5d13-b662-4107427acd42','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='DİMAKS BETON' AND il IS NOT DISTINCT FROM 'ADANA' LIMIT 1),'f684d5f2-a013-5909-a866-8306be04d1b7'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-03-07','SÜLEYMAN KILIÇ','Bülent Çam ile görüştüm, tespit ettiğim tüm kaplamaları almam için onay verdi, ilk etapda 2 şer 23.5R25 ve 26.5R25 alacağız, sonrasında diş derinliklerini kayıt altına aldığımız lasitkleri zamanla alacağız. Firma toki işine de girmye başlamış makine parkı artacakmış.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('b0a8c9f0-123b-59d9-b220-b42fe77ba7d5','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='NUROL İNŞAAT' AND il IS NOT DISTINCT FROM 'ANKARA' LIMIT 1),'8b58d03e-afca-5b26-86a7-b54dd6133e75'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-03-10',NULL,'Satınalma müdürü Emin Algül bey ile görütüm, eskiden ılısu barajında çalışığımız dönemden beni tanıyor. Türkiye içinde inşaat anlamında işleri kalmamış, Cezayir ve Ukraynada işleri varmış. Lastikleri o tarafa genelde fiyat oralarda daha ucuz olduğu için oralardan alıyorlarmış. Brisa ve Goodyear filo bayiliği almışlar direkt alım yapıyorlarmış. Çanakkaledeki Tümad altın madeninin sahipleri aynı zamanda fakat orada iş makieleri yok tüm parkur Köseoğluna ait. Emin bey taleplerde yine fiyat soracak bize.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('334daaaa-b964-5586-a816-3ae4f3aa7a9f','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ÇETİN İŞLETMELERİ' AND il IS NOT DISTINCT FROM 'ANKARA' LIMIT 1),'5ef5043b-63c3-58e3-a319-0abcf83aa22d'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-03-10',NULL,'Satınalmadan Caner bey ve müdürleri Tekin bey ile tanıştım. Caner bey ile genel görüştük, 103 adet lastikleri iş makineleri var. Genelde michelin alıyoruz dediler. Kaplama zaman zaman tercih ediyorlarmış fakat kiminle çalıştıkları bilgisini vermediler. kaç şantiyeleri olduğu bilgisinide paylaşmadılar. şantiyleri ziyaret etme talebimize edin isterseniz ama bizde her şey buradan biter asla şantiyeden alım olmaz, tüm makineler buraya gelir burada bakımı olur ve geri gider dediler. kaplama ve yokohama ilgilerini biraz çekti. alımlarda fiyat soracaklarını söylediler.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('d08fc97d-4954-5be1-a499-a52e536116b3','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='MARUBENİ DAĞITIM' AND il IS NOT DISTINCT FROM 'ANKARA' LIMIT 1),'edb81818-6069-5363-8b9b-9dc1e2ad98d5'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-03-11',NULL,'Komatsu Ankara merkeze Serda abinin 2.el makinesinin lastiklerine bakmak için gittim. Kaplama talebi vardı lastikleri kontrol ettim diş derinlikleri olduğu için 4 adet 29.5R25 lastiği tamire almayı önerdim. Serdar bey onayı verdi lastikeri yakında olan aracımız söküp almak üzere program yaptık.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('e5241731-d97a-5ebe-ae1e-e625499bb14b','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='BERGİZ İNŞAAT' AND il IS NOT DISTINCT FROM 'ANKARA' LIMIT 1),'b59039b6-539a-5787-b8aa-60bf2e3ce275'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-03-11',NULL,'Satınalmadan Serkar bey ile merkezlerinde görüştük. Ağırlıklı yol müteahhtiliği yapan bir firma. Daha önceleri Kardeşler ulaşım üzerinden kaplama yapmııştık. Yine aktif olarak kardeşler ulaşım ve goodyear ile çalışıyorlar. Şuanda tüm şantiyeleri kapatmışlar bayram sonrası açacaklar. kaplama ve yokohama için fiyat alacaklar. Serkar bey makine parkur bilgisini paylaşmadı.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('4237beaa-e551-5119-ba15-4c64ed264d13','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='TEK İMAJ İNŞAAT' AND il IS NOT DISTINCT FROM 'ANKARA' LIMIT 1),'6da4998c-46f6-58e3-9c17-74f932490cfc'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-03-11',NULL,'Satınalma müdürleri Nejdet bey ile görüştüm beni hatırladı. Şuanda yurt içinde sadece antayada boru hattı işleri var orada da lastikli makine yok. Diğer tüm makineler yurtdışı şantiylerinde, buralarada TBR lastik Üzeyirden karkaslı kaplanmış alıyorlarmış. taleplerde artık bizden de fiyat alacak.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('52bf82e3-9484-5241-b7a2-0019199384f6','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ÇİFTAY İNŞAAT' AND il IS NOT DISTINCT FROM 'ANKARA' LIMIT 1),'c929611c-4936-5bcd-93e5-31fe4772c7ad'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-03-12',NULL,'Satınalma müdürleri Selahattin bey ile görüştüm, 3 gündür randevu için olumsuz dünüyordu sabah için gel dedi fakat gittiğimde Tatko ile görüşüyordu. Doğangü ile yeni lastik ve kaplamada sabit fiyat ile sözlşemeyi yenilediklerini söyledi. Kaplama için sadece istanbul çöp tesisini yapıyorsunuz ama trakyada traçim içinde de makinemiz gidin bakın ona da konuşalım dedi. Yokohama yu Bülent Kiristalden almış, bezli lastiği radyal diye satmış ayrıca taktıkları hafta lastik batık almış hurda olmuş bülent kristal sahip çıkmamış. Yokohama deneme düşünmem bu sebeple dedi. ancak bana bedelsiz verirseniz 2 yıl kullanırım çalışır ise fatura edersiniz o şekide denerim dedi. Bridgestone da buraya böyle girdi bedelsiz lastik verdi dedi. stoğumuzda olan uygun ürünleri teklif edebileceğimizi söyledim, hemen ilgisini çekti. 18.00R25 maxamları söyledim fiyatını istedi.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('9feb77f6-39cc-5dc5-9b3d-b652ab43b5b0','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='KÖSEOĞLU GRUP' AND il IS NOT DISTINCT FROM 'ANKARA' LIMIT 1),'53a655e5-4e0e-50d7-a648-d9aa467d96fe'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-03-12',NULL,'Tuncay bey ile 3. gün görüşebildim o da telefonda Ostim içinde. Patronları Ako ile tüm kaplama işleri için pazarlık ediyormuş, bizim fiyatıda karşılaştırma tablolarına eklemişler. Bu haftalarda bir karar vereceklermiş. Fakat bundan bağımsız deneme için bize kaplama vereceğini söyledi. yeni konusunda da fiyat sormasını istedim, soracağını söyledi.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('a476ceee-4811-524e-80ec-d2d42cca6d6b','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='AGE İNŞAAT' AND il IS NOT DISTINCT FROM 'ANKARA' LIMIT 1),'3d28f645-02ab-559f-a371-fbb338c162e4'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-03-12',NULL,'29.5R25 yeni teklifimiz Tatkoya göre yukarıda kalmıştı, 29.5R25 4 adet 55mm kastamonuda bizim müşterimiz HP mermerde kiralık olan makine için fiyat verdik, 55.000TL+KDV Tatko 45.000TL+KDV den işi aldı. Lastikleri almaya gidince HP mermere de aynı fiyatı verdi, muhtemelen HP mermerde Tatkoya verecek çıkacak takip ettiğimiz lastikleri. Eyüp bey fiyat sorduğunu fakat çok yukarıda kaldığımızı söyledi.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('f5bee6d3-600c-5692-ac52-a8a9467f5061','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='VEGA HERACO' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'33c036fa-f484-5f28-b6cf-a3b8fde16331'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-03-13','ADNAN KARAKAYA','Çiftay merkezin yönlendirmesi üzere yeni yetkilileri Umut beyi ziyaret ettik. Merkezin performans bilgisi istedini bunun için bize lastiklerin sökülş bilgileri gerektiğini söyledik. Kendisi iliç altına madeninden gelmiş bu konuyu orada takip ediyordum onun için sorun yok gerekli bilgileri sağlayacağım dedi. 2 loder aktif çalışıyor.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('74c6e2a2-3166-59b7-aa21-c48e87e2b31f','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='İLK YAPI' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'1246e7f7-5f32-51e0-8ed9-9885d39920e8'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-03-13','ADNAN KARAKAYA','Geçe yıl uğramıştım eski Ergen madeni devralmışlardı, tesisi aktife almışlar, şefleri Engin ile görüştük, 2 loder çalışıyor. Grubun diğer lokasyonları için bizi merkese yönlendirdi. Hatip bey ile görüştük merkezden bizi portföye dahil etti. taş ocakları ve yurt dışı altın maden ortaklıkları var.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('4579dc40-7c6c-58a7-a73f-391f584d0ce0','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='SÖRHAZ' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'d14ab8fa-796c-5ff0-8e95-ffdc418ba211'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-03-13','ADNAN KARAKAYA','Eski Sörmaş firması bileci tesisini MAŞ firmasına satınca isim değiştirmiş. 2 loderleri var burada, kontrol ettik ve kaplama tespit ettik. Ahmet şef bizden teklif  istedi. Tatko ile çalışıyor karşılaştıracak.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('7478c492-28ea-569b-959f-4c0313bd8cbc','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='DEMİRKOÇ' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'97787b54-e7a6-5f2e-a31e-6c3e281183a6'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-03-13','ADNAN KARAKAYA','Firma sahibi Zafer bey ile görüştük, Saliun alacağını söyledi ,güncel fiyatları verdik 100 adede kadar alabileceğini söyledi. Önden 4 adet lastikleri görmek için hemen istedi. Loderlerin durumu iyi.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('92585a5c-ab97-5aae-a701-919612823915','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='MAGNESİT AŞ' AND il IS NOT DISTINCT FROM 'ESKİŞEHİR' LIMIT 1),'4e7ac0c1-df75-5039-b113-d66aa8e2c188'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-03-18',NULL,'Kademe sorumlusu İshak abi ile görüştüm, eskiden beni tanıyor. En son dönemde kaplama arızalarımız ve sonrasından bizim iade ettiğimiz lastikleri başka yerin kaplayıp lastiklerin çalışması sonraı artık bizimle çalışmak istemediğini söyledi. Yeni lastik kısmında Selen hanımın ilgilendiğini onunla görüşmemi söyledi. bize kırgınlığı var zamanla tekrar ilişkimizi düzeltmeye çalışacağım.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('55125297-c568-5f2d-a5ac-d8a60fc60d84','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='GÖKYAR MERMER' AND il IS NOT DISTINCT FROM 'BİLECİK' LIMIT 1),'b6013855-562f-5a1c-9a91-bf4c75cefb3e'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-03-18',NULL,'Osman bey ile uzun zamandır görüşememiştik, onu ziyaret ettim, işleri yavaş. Beraber tesisteki forkliftleri kontrol ettik, değişimi için hbaer verecekler. Sonrasında ocağa geçtim ve makineleri kontrol ettim, değişmesi gerekenleri bildirdim.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('2b55dc76-834b-52e8-a5d1-037226802cb5','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ASSAN PORT' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'706a0958-9bbe-5787-b010-b252a5f86f01'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-03-26',NULL,'18.00-25 talepleri sonrası merkezlerinden Şule hanımı ziyaret ettim. Tatkonun bizim fiyatın altına BKT verdiğini öğrendim. Şule hanım limanın sadece 18.00-25 alımına bakıyormuş diğer tüm lastiklere kibar holding merkezde Yağız Sefa bey bakıyormuş bana onun iletişim bilgilerini de verdi.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('b1422a8f-7338-5903-8139-a4ba4a7d6880','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='BOĞAZİÇİ BETON' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'11951ff9-4ab1-549e-98e2-a44939d38e1a'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-04-08',NULL,'Satınalmadan Arif ve Erdem beyler ile görüştüm. Kaplanacak olan 23.5R25 ler için fiyat verdim, fiyatımızın iyi olduğunu bize mutlaka döneceklerini söylediler. Fakat geri dönüş sağlamadılar.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('b983dd6d-8923-594b-90c7-cbb6474f5e51','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='MAKYOL' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'b540e6cd-c913-58ae-b0fb-d76d24b37afc'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-04-08',NULL,'Müjdat bey ile görüştüm, Antalya ve Akyazı açılıyor taleplerimiz olacak dedi. Ben 2 tarafında kaplamasına talip olduğumuzu söyledim. Ayrıca Romanyadan da OTR kaplama alabileceğimizi söyledim. Ben gideceğim bir göreyim olabilir mantıklı dedi. 325/95R24 ler için koşul fiyatlarımızı verdim fakat Koplas GY fiyatının daha düşük olduğunu söyledi. bana hededf fiyat verdi o fiyata düştüm geri dönüş sağlayacak. yakındaki talepleri takip ediyorum.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('ae62192f-dac1-5946-a173-2986715ee247','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='AKDAĞLAR GRUP' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'7ca7b93d-066b-5fcf-b913-e45da6d1fb4a'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-04-08',NULL,'Satınalma müdürü İsmail bey ile görüştüm, daha önce ziyaretlerimiz olmuştu fakat sonuç alamamıştı, İsmail bey lastikleri direkt patron alır ben hiç lastik almadım dedi. Kaplama da yıllık sözleşmeli Laskap ile o bitmeden kimseye lastik veremeyiz dedi.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('27e9929a-32e9-5fcd-9d72-c1524535b073','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='AKBAY' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'9c87bdcb-e0e2-5fa1-96f2-c52a122507ed'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-04-08',NULL,'Satınalma müdürleri Savaş bey ile görüştüm. Sonrasında buradaki loderleri ölçtüm ve ihtiyaçları mail attım. Savaş bey tüm lokasyonları kontrol edip raporlamamı istedi.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('f480d9d4-a74f-5888-ad7f-9746acf08c50','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='TRAKYA CAM' AND il IS NOT DISTINCT FROM 'KIRKLARELİ' LIMIT 1),'f11bfb8b-79ae-597a-8f81-54acba69d043'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-04-09',NULL,'Bakım mühendisleri Osman bey ile görüştüm, loderi kontrol ettik L5 almak istiyordu, L4 alıp 2 tanede kaplama ile kurtarabileceğimizi söyledim. İhale talebini Yokohama olarak açacak.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('a5ceb6e8-2356-5b44-9155-2a0269b8ef47','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='AKBAY' AND il IS NOT DISTINCT FROM 'KIRKLARELİ' LIMIT 1),'1785717c-c110-5ecc-9674-ff5230bcae6a'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-04-09',NULL,'Akbayın Bulgaristan sınırındaki tesisini ziyaret ettim, loderleri ve depolarını kontrol ettim. 2 kaplama ve 1 tamir tespit ettim, 1 ay sonrası için planlama yapıp lastikleri alacağız.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
