INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('67cd40b4-45ee-58b7-b974-22d3f52113e6','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='SERVO İŞ MAKİNELERİ' AND il IS NOT DISTINCT FROM 'KASTAMONU' LIMIT 1),'80697715-a1d7-58fe-94d2-740973a29cba'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-04-14','ŞEREF BEKTAŞ','Hüseyin Çoban ile mermer fuarında denk geldiğimizde biz Pazartesi için daavet etmişti, merkez ofisine gittk, satacağı makinelerin lastiklerini aktarıp çıkanları kaplama ve tamire almamız için çağırdı. Sonrasında hep berarber hanönü ilçesine Acacia madencilik sahasına makinelere gittik, kontrolleri yaptık. 3 tamie ayrıdık, bunları alıp teslim edince yerine çıkanları kaplamaya alacağız. ayrıca yeni aldığı makine teslim olunca önlerine L5 vereceğiz.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('d50e8b7e-b579-52c6-a868-2fde50236524','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='TUGUT ÖZEN MERMER' AND il IS NOT DISTINCT FROM 'BİLECİK' LIMIT 1),'f1a81e61-9ee8-59c4-86c1-1afc54d98189'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-04-15','TAMER AYYILDIZ','Öğle saati tüm makineler yatarken planlama yapmıştık. Takılı olan 29.5R25 Maxamları kontrol ettik, zincirin yolduğu yerler ile ilgili firmanın şikayeti vardı takip edelim bir sorun olursa arkadasındayız denildi. 35/65R33 kullanan makine ve lastiklerini özellikle incediler. yeni 4 yıldızlı lastiklerimizin bu sahalarda iyi performans sergileyeceğini söylediler.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('10e026a8-5765-50a4-bf24-6bc5a5590e56','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='GÖKYAR MERMER' AND il IS NOT DISTINCT FROM 'BİLECİK' LIMIT 1),'b6013855-562f-5a1c-9a91-bf4c75cefb3e'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-04-15','TAMER AYYILDIZ','Takılı olan 29.5R25 Maxamlar incelediler, jantın verdiği hasarın sebebinin karkasın esnek olmasından kanaklandığını yeni 4 yıldız lastiklerinde bunu iyileştirdiklerini söylediler. 35/65R33 kullanan makine incelendi. L5 mermer için zincirli kullanıyor bu makine bizim lastiğide verebilrsiniz bu şekilde sorun olmaz denildi. stoktaki L5 leri mermere 35/65R33 için teklif edeceğim.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('92429427-3d82-5976-863f-8028e1b16676','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='KARMERSAN' AND il IS NOT DISTINCT FROM 'ISPARTA' LIMIT 1),'6e3df711-f8eb-54e0-9335-7789a8c3972a'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-04-16','TAMER AYYILDIZ','Tamer bey burada uyaroğlunun sattığı 35/65R33 maxam lastiği kontrol için gelmemizi istedi, makineyi bulduk ve lastiği inceledik, topuk hasarları için yeni 4 yıldız lastikte bu sorunları görmeyeceğimizi söylediler. Diğer 29.5R25 lastikleri de kontrol ettik.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('58dab19f-9911-5244-87ce-8e456c14ae8d','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='BEJ MERMER' AND il IS NOT DISTINCT FROM 'ISPARTA' LIMIT 1),'b6566c70-8262-57b5-bd54-3078f2760461'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-04-16','TAMER AYYILDIZ','35/65R33 kullanan makine ve diğer makinelerdeki lasitkleri inceledik. Burada aktif dönen maxam yok satılanlar takılmadı. Burada 4 yıldız BS 35/65R33 OE lastiği detaylı incelediler.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('03ee06b8-5a98-5b29-8c7c-fb0ba6eb2c46','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='AYTAŞ AKIN MERMER' AND il IS NOT DISTINCT FROM 'BURDUR' LIMIT 1),'53bd955f-1865-55a8-b546-b061b090491f'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-04-17','TAMER AYYILDIZ','Takılı olan 29.5R25 maxamları inceledik. Yeni aldıkları elektrikli suny kamyonun 16.00R25 lastiklerini inceledik, bu ürün hazırda bizde üretimi MS306+ olarak var ve iyi çalışır dediler. O sırada Suny markasının türkiye müdürü kamyonu başka müşteriye göstermek için gelmişti tanıştık ve bu lastiklerden almak istediğini söyledi. 60 adet kamyon sattık dedi. lastikler için fiyat gelince suny müdürü ile görüşeceğim. 2 adet 29.5r25 maxam ms406 alımı yaptı firma','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('2e538a49-1220-5af8-8201-c2f9329754e4','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='MAKOMAR MERMER' AND il IS NOT DISTINCT FROM 'BURDUR' LIMIT 1),'82134797-30ed-54ab-9140-ce68c3c3bc5b'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-04-17','TAMER AYYILDIZ','Takılı olan maxamları inceledik burda yaklaşık 16 tane takılı maxam var, 35/65R33 makineyi inceledik, firma 4 adet 29.5R25 maxam alımı yaptı.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('b38e90bb-dacc-5027-8eb6-d14f70709bc7','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='AKBAY' AND il IS NOT DISTINCT FROM 'SAKARYA' LIMIT 1),'7853b190-84a8-5581-9fe4-4f23f96260fa'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-04-21',NULL,'Formenleri Cafer bey ile görüştüm. Cafer bey tüm şantiyeler üzerinde etkili eski personelleri. Tüm makineleri kontrol ettim ve bilgi verdim. Bu tesista yarıca tbr kaplamada yapıyoruz. tbr yeni hariç tüm taleplerini bizden karşılıyorlar.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('50a7d2fe-7643-51b0-9ee5-399a69eb07a1','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='GÖKSUTAŞ MERMER' AND il IS NOT DISTINCT FROM 'BİLECİK' LIMIT 1),'c27d7571-c0fd-5318-a1b3-c150286216c5'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-04-25',NULL,'Ömer bey ocaktaydı telefonlaştık. Ben merkezden satınalmadan Alev hanım ile görüştüm, henüz talep yok ocağı yeni açıyorlar. Fuara katılım sağlamamışlardı. İşleri genel olarak yavaş.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('6189d316-5fa0-5bcf-a90d-085e9741ada0','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='SAFİ ÇİMENTO' AND il IS NOT DISTINCT FROM 'BİLECİK' LIMIT 1),'e206332d-abb2-5df9-94d1-db2a45398c66'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-04-25',NULL,'Mehmet bey görüşme talebimi kabul etmedi, kaplama taleplerini atilla bilgioplu üzerinden bize yönlendiriyor. Atilla ya gelen talebi bize iletmedi dahi bu sefer.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('82870fe7-aeb7-587e-8a0c-4ed0ddb58b95','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='FEDERAL MERMER' AND il IS NOT DISTINCT FROM 'BİLECİK' LIMIT 1),'5aef9238-6308-5cb6-9856-94a5aacf7cc9'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-04-25',NULL,'Selçuk şef ile görüştüm, fuara katılmadılar, işleri yavaş ocakta stoktan olan satışları var. Makineler yatıyor. Kaplamaya çıkacak lastikleri var onları takip ediyorum.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('cb5c0844-3e74-5061-bd49-c7f11ce999ce','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='TMG DOĞALTAŞ' AND il IS NOT DISTINCT FROM 'BİLECİK' LIMIT 1),'bc8dd035-d956-56af-9cd2-bc8363babbfb'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-04-25',NULL,'Ocağı kapatmışlar kimse yoktu, Mustafa beyi aradım bilecikteyim ama ocağı bayram sonrası açmadk. Talep yok olunca açacağız dedi.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('5ca7befe-2bdd-552c-889b-6aaa960fd3d8','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='VEZİR MERMER' AND il IS NOT DISTINCT FROM 'BİLECİK' LIMIT 1),'c9214911-f906-584a-8959-8b444d81aba7'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-04-25',NULL,'Sümeyye hanım ile görüştüm, fuara katılmadılar, işleri yavaş. Ocak rolantide çalışıyor. Takip ediyorum.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('7f09c9d9-728e-56bb-9645-6c587d98d078','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='LİNDA MERMER' AND il IS NOT DISTINCT FROM 'BİLECİK' LIMIT 1),'6ea60056-9e2b-5c8a-aea1-8fecd74e2f0c'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-04-25',NULL,'Mühendisleri Kerem ile görüştüm. Fuara katılmadılar. Tek makine ile yavaş çalışıyorlar.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('11b48d84-f78c-5a8c-8051-646519bb5950','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ÇALIŞKAN MADEN' AND il IS NOT DISTINCT FROM 'TEKİRDAĞ' LIMIT 1),'89b6d9e1-d861-550c-a3e2-9b484a774f8b'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-04-28',NULL,'Formenleri Ünal bey ile görüştüm. Kapladığımız 2 lastiği takacağız çıkanlar çöp durumda 2 adet yeni yedek ihtiyaçları olacak. Kaya bey ben gelmeden çıkmış ve Vizeye geçmiş peşinden gittim.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('0bfc697a-37c4-5e27-87e3-0537e91c13a6','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ÇALIŞKAN MADEN' AND il IS NOT DISTINCT FROM 'KIRKLARELİ' LIMIT 1),'4e8729e0-240e-5bb4-ace6-4861fc0d67d7'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-04-28',NULL,'Formenleri İlker bey ile görüştüm, 2 adet 26.5R25 lastiği tamir için aldık. Kaya bey ile görüştüm çorlu da hiç yedekleri kalmadığı için yokohama L5 leri önerdim. Fiyat pazarlığı yaptık. Ben onları alacağım ama çeki ayarlayayım sen birkaç hafta sonra gel bakalım o işe dedi.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('ac19a584-bd69-5d20-9cc4-4017cdd4fa18','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='TRAKTAŞ MADEN' AND il IS NOT DISTINCT FROM 'KIRKLARELİ' LIMIT 1),'5ea9cdec-118a-5751-b578-2bf291b5bd2a'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-04-28',NULL,'Onur bey ile görüştüm, kapladığımız 26.5R25 leri kontrol ederken açılma tespit ettik, araç yakındaydı hemen önden söküp arkaya aldık. Haftaya emanet ile garantiye alacağız. Diğer makinenin lastiklerini takip ediyorum sezon sonuna kaplamaya alacağız.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('6b75e1d7-6350-51ec-8dc6-7ea5393e4390','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='AKÇANSA' AND il IS NOT DISTINCT FROM 'KIRKLARELİ' LIMIT 1),'a51822a6-ed73-5cc2-9609-4cbad5720cbe'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-04-28',NULL,'Semih bey yerinde yoktu ben makineleri kontrol ettim kaplama tespit ettim telefonda bilgi verdim. Bende bir bakayım dedi. Bir kaç hafta sonra gidince takip edip aldıracağım.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('8280c541-c741-58f8-af3d-4835827bcd35','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='CAMİŞ MADENCİLİK' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'e10c047d-553c-5dd9-84cf-32c7f7af968e'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-04-29',NULL,'Camiş madencilik grununun istanbul merkez satınalmasını ziyaret ettim. Eski kontaklarım artık yoklar. Bilecik tesisi sorumlusu Hakan bey ve Mersin tesis sorumlusu Burçin hanım ile tanıştım. Cennet hanım ile maalesef görüşemedim. Camişde eski kontağım Günayın yönlendirmesi ile tekrar hepsi ile iletişime geçtim ve kaplama, yeni lastik vermeye başladık. Bilecik ve MErsin tesislerinin mühendisleri ile ilişkileri geliştirmem gerekiyor, diğer tesislerdeki arkadaşlar ile iletişimimiz iyi ve lastikleri alıyoruz.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('db444099-4aa8-5ec2-a5b9-f40915d218db','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='GRANİTAŞ' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'57ec2d3c-a9d0-5a38-91bd-85ee64ceee91'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-04-29',NULL,'Merkez satınalmadan Tansel abi ile görüştüm, yakın zamanda eskişehir ve karamandaki lastikleri kaplamıştık. Rota lastik Aksem ile görüşüyorum o her işimi çözüyor sizinle sadece kaplamada devam edelim. Yeni lastiklte Yokohamdan yaşadığım sorunları hala unutmadım asla almam dedi.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('645fbbcb-6672-5b6a-9b86-a04bc602af61','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='MARUBENİ DAĞITIM' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'2f2a5b8b-2c9a-562e-9f00-aeee24b4e6d6'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-04-29',NULL,'Serdar abi ile yeni taşındıkları yerlerinde görüştüm henüz yerleşiyorlalardı. Michelinden gelen bana ara ara iş paslayan İbrahim Topuz Hankook tarafına tbr satışa geçmiş. Genel görüştük, talepleri karşılıyoruz.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('1c2c6d53-8468-5fb9-8407-cb51c1dcf767','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ÖZKUM MADENCİLİK' AND il IS NOT DISTINCT FROM 'TEKİRDAĞ' LIMIT 1),'a52a0861-365e-57c7-9036-9b6a7ff03872'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-04-30',NULL,'Vadesi geçen ödememizi tahsil ettim. Kaplamalarımızı kontrol ettim çalışıyor. Yakın zamanda bir talep gözükmüyor. Takip ediyoruz','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('cdcd29de-eb72-5329-80a4-28132ceb6f70','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='BATI KUM' AND il IS NOT DISTINCT FROM 'TEKİRDAĞ' LIMIT 1),'dbb3d9f7-27ad-56d1-9e0e-7e197a8a9036'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-04-30',NULL,'Emrah bey ile görüştüm, işleri halen çok durgun makinenin lastikleri kötü ama yaptırmıyorlar. Takip ediyorum.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('7f14a075-6da8-524a-9a2a-4feb816142ea','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ŞENBAL KUM' AND il IS NOT DISTINCT FROM 'TEKİRDAĞ' LIMIT 1),'811b67cb-17c0-56e4-9569-1ce23798b870'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-04-30',NULL,'Erhan bey ile tanıştım, 3 loder var yeni açmışlar lastik ihtiyaçları olacak durumları iyi değil. Kiralık makineyi iade edince bize haber verecek.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
