INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('6f6bf3d4-9c54-538a-9046-79ebe4f5e270','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ALACAKAYA MERMER' AND il IS NOT DISTINCT FROM 'ESKİŞEHİR' LIMIT 1),'e6166edc-6258-5b46-a20e-9e284b770c46'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-05-06',NULL,'Bayram beyin Süleymana gidip ocağa bakın sürekli hava kaçıran lastik var demesi üzerine gittim. 35/65R33 kullanan loder için 4 lastiğe köpük testi yaptım 2 tanesinde  o ringden gelen kaçağı buldum. Kaya kamyonunda  2 yeni 2 kaplama tespit ettim. Süleyman Bayram beye bilgi verdi, yeni ve kaplamaların onayını almaya çalışıyor.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('78204e8c-542b-587d-861a-ead4f7329879','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='TURAN BEKİŞOĞLU' AND il IS NOT DISTINCT FROM 'ESKİŞEHİR' LIMIT 1),'7fb16da7-9b6b-5cc3-afa9-4aefdf4470e4'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-05-06',NULL,'Ankara merkezlerinnden Kerim bey ocağa da uğramamı istemişti, şefleri Kamil bey ile tanıştım. Hizmetlerimizi anlattım, tüm alımları Kerim bey üzerinde yaptığını bu aralar ucuz marka Petlas eğiliminde olduklarını söyledi. Yine ankara üsti takip edeceğim.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('169f95ad-a1aa-59e1-bf28-4a0ca44876e8','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ŞAHMERSAN MERMER' AND il IS NOT DISTINCT FROM 'ESKİŞEHİR' LIMIT 1),'b0a9ee35-fa40-5a37-aa18-427b3737c937'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-05-06',NULL,'3 loder ve 1 kamyonları var, tüm talepleri Ankara ivedik merkezden patronları karşılıyor. Ankarada takip edeceğim.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('c2628976-1ea8-5c71-8c78-a50c2b3b0c1f','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ATIŞKAN ALÇI' AND il IS NOT DISTINCT FROM 'ESKİŞEHİR' LIMIT 1),'8f80781e-8afe-5b08-93fc-327732dd6975'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-05-07',NULL,'Eskişehir çıkışında büyük bir fabrika satınalmadan Emine hanım ile görüştüm hizmetlerimizi mail atmamı istedi. Taleplerde iletişime geçecek.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('6d4ae749-fc62-5927-bc35-a3cd9b802d41','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='BİEN SERAMİK' AND il IS NOT DISTINCT FROM 'ESKİŞEHİR' LIMIT 1),'8c2fb52c-788e-53c6-872f-296102927cb6'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-05-07',NULL,'4. görüşme çalışmamda güvenlik Uğur beyin malini verdi. Telefonda bana mail atsın öyle görüşelim dedi.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('649190bd-f13d-546a-8d27-afdb78b20764','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='CAMİŞ MADENCİLİK' AND il IS NOT DISTINCT FROM 'BİLECİK' LIMIT 1),'775a0021-11a8-5108-9c10-25fa8d6dbc2b'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-05-07',NULL,'mühendisleri Can ve Berkay bey ile tanıştım. Geçen ay kaplama hizmeti vermiştik fakat yenileri petlas istemişlerdi. Yokohama sunumu yaptım bir sonraki talepte isteyecekler. Tüm loderleri ölçtük ve kontrol ettik, sekman kilidi olmayan o ringlerden kaçıran lastikleri tepsit ettik. verimli oldu, kaplama da devam edeceğiz yeni de yokohama olarak vereceğiz.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('81bdf103-c7b9-5232-b6a5-7fa79ccd6ebb','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='İÇTAŞ İNŞAAT' AND il IS NOT DISTINCT FROM 'BİLECİK' LIMIT 1),'d9698d82-bb18-550d-ac5c-8dcf645dc788'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-05-07',NULL,'4. denememde Harullah formeni yakaladım, kendimizi anlattım, 6 ay kaldı burada işimiz keşke önceden gelseydiniz dedi. Beni satınalmaya yönlendirdi. Özkan bey ile tanıştım, kaydımızı yaptı her alımda fiyat soracaklar.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('fd5c52aa-8812-511c-9c12-fb43c771b609','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='BURÇ MERMER' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'03841b24-f9c7-591f-9113-41afa038bda9'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-05-08',NULL,'ölçüm yaptım sonucunu şeflerine ve firma sahibi cem beye bildirdim. Tamire alınacak lastik var. Cem bey bilgi verecek. Kaplama ve yenilerimizi takmıştık onların durumları iyi.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('bf70b2fe-befc-54c4-9192-0d837c89b8e0','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ALTINSOY MERMER' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'48279c3d-5b5c-5a90-843d-3ad62cc13b5b'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-05-08',NULL,'Erenler ocağında ölçüm yaptım 2 kaplama ve 2 yeni ihtiyaçları var. Şefe ve firma sahibi Nurullah Altınsoya bilgi verdim. Nurullah bey alımları ağırdan alıyor.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('a948c7c3-6aaf-50f7-a539-f2ded6353220','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='JEOPARK MERMER' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'e4eaca6e-d4fa-5d18-affc-82d8e954d2a4'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-05-08',NULL,'Öğle saati tüm makineleri ölçtüm, turgayda kapladığımız 35/65R33 leri takıyordu. 1 tane tamir tespit ettik takip edip alacağız. Bu sezon daha kaplamaya lastikleri çıkmaz, loderlere sattığımız yenileri takınca çıkanları kamyonlara kaplayıp takacağız.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('c8362e8f-8c67-5c64-baa8-f5ebe0cbfd66','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ERENLER MERMER' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'179f5ac5-09a9-5dc8-b6db-d87c3c4f6426'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-05-08',NULL,'Maxamların takıldığı makine arızadan yatıyordu. Diğer loderde 1 kaplama tespit ettim. Firma sahibi Osman abiye arayıp bilgi verdim, yedeğimde var diğer makineyi kaldırayım 2 kaplamayı al dedi. Takip edeceğim.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('75fc5d33-d439-5cbb-a4d7-ccacfd75d1bf','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='AY KARDEŞLER MERMER' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'d3279ad0-3084-5c9a-9031-bdb9e3da728c'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-05-08',NULL,'Uzun süredir kapalı olan ocağı yeniden açmışlar, kamyonda 4 kaplama tespit ettim şefe bilgi verdim. Ama iş patron Nedim beyde bitiyor Kestelde olduğu için görüşemedim.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('f7847847-6b08-5fac-a10e-3231dcce6a4f','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='AYDINOĞLU MADEN' AND il IS NOT DISTINCT FROM 'SİLİVRİ' LIMIT 1),'a0366191-834d-566d-b44f-2184d0c2a655'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-07-07',NULL,'Firma sahibi Ömer bey ile görüştüm.  Kum ocağı işletiyorlar, 3 hafta önce uğradığımda firma aktif çalışıyordu fakat bu ziyaretimde tüm tesis çalışmıyordu. Günde 2-3 kamyon çıkış olduğu için tesisi durdurmuşlar stoktan satıyorlarmış. Makineler yatarken hepsini kontrol ettim lastik durumları gayet iyi. Tatko ile çalışıyorlar.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('9ea0ac8c-b1fd-5ce0-9359-6330d839088f','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='DİDO MADEN' AND il IS NOT DISTINCT FROM 'SİLİVRİ' LIMIT 1),'49f4257d-6692-5326-82e9-1b336a591000'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-07-07',NULL,'Formenleri Nail şef ile görüştüm. Bölgenin en büyüğü Mert kum ile ortak tesis. Tatkonun aktif müşterisi. 2 loderleri var. Şuan talepleri yok.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('dd850037-5d11-58e7-8a4f-bbf7ab88f799','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='MERT KUM' AND il IS NOT DISTINCT FROM 'SİLİVRİ' LIMIT 1),'8297b4cc-8328-5dbb-a208-d6e0c6e85e58'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-07-07',NULL,'bölgenin en büyüğü 2  farklı lokasyonları var ikisininde ziyaret ettim. Belden kırmalı kanyonda kullanyorlar. 2 hafta önce 26.5R25 45mm için fiyat vermiştik, Tatko bizim fiyatın biraz altına 55mm olarak 8 lastiği almış, 4 tanesini kaplamış teslim etmiş. formenleri Yasin usta ve firma sahibi ile görüştüm. uzun yıllardır tatko ile çalıştklarını ancak ucuz olmamız durumunda denemeye lastik verebileceklerini söyledir.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('521cb156-59b3-5856-aaa4-4c8b7fc25ff0','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ÖZKUM MADENCİLİK' AND il IS NOT DISTINCT FROM 'SİLİVRİ' LIMIT 1),'85a2c67b-afd5-532b-bd8f-00109a56584c'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-07-07',NULL,'Formenleri Ahmet usta ile görüştüm, yıllardır aktif müşterimiz. Şuan yedeklerine kadar kapladık bir ihtyaçları yok. Zaten işleri de yok stoğa üretime çalışıyorlar.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('c077da28-526a-57b1-baee-2dde7fdbdae6','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='SAFİR KUM' AND il IS NOT DISTINCT FROM 'SİLİVRİ' LIMIT 1),'91298cf6-acd7-53b0-ad75-8d3e0b9d2382'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-07-07',NULL,'İşlerin yavaşlığından çoğu araçları yatıyor. Kotnrol ettiğim çalışan loderin kaplamaları için şefleri Abdullah formene bilgi verdim. Değerlendirecek. Tatko ile çalışıyorlar aktif olarak.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('622376ca-76f0-5a73-b2d7-a0b49fea9612','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='BEYKUM' AND il IS NOT DISTINCT FROM 'SİLİVRİ' LIMIT 1),'02d37f1a-3250-5f3a-a15e-8d422bcd7e42'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-07-07',NULL,'Civardaki diğer büyük kum işletmesi, mühendisleri ile eski ortak tanıdıklarımız çıktı, o da yeni başlamış burada. Çok aktif olarak tatko ile çalışıyoruz dedi. Hatta m mehmet bey ayrılmadan çokca yeni satmış buraya stoğum şişik dedi. Takip edeceğim.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('aa07798e-1eb5-5978-98f2-cd11cdead28e','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='PAKSOY BETON' AND il IS NOT DISTINCT FROM 'BÜYÜKÇEKMECE' LIMIT 1),'6ba454a6-09f2-56c1-aecf-298c9839bb3d'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-07-10',NULL,'Betonsanın çekmece tesisini işletiyorlar 1 lodeleri var. Nurhan bey ile görüştüm, çok ilgilenmedi, randevusuz geldim diye sitem etti. takip edeceğim.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('cb31d63f-9ff2-5ce2-a5d3-ad2371673e3d','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ADM BETON' AND il IS NOT DISTINCT FROM 'SİLİVRİ' LIMIT 1),'ce840b7b-2da9-5a8c-a4e5-0f712ed403b6'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-07-10',NULL,'Necmettim formen ile görüştüm, tahsilat için çekimizi aldım. Danamandıraki ocağa geçip ölçüm yaptım, 2 kaplama tespit ettim, fiyar verdik, kaplama için alacağız.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
