INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('204bf84f-0828-54f3-83f7-54fa98cc99d8','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='KENT BETON' AND il IS NOT DISTINCT FROM 'ADAPAZARI' LIMIT 1),'eac2d26c-f008-5613-966c-4fbfe85b32e1'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-07-16',NULL,'Satınalmalarından Fatih bey ile görüştük, 1 lodeleri var. Çıkmış 4 lastiğini inceledik, bunlardan 2 adet kaplanabilecek olan var dedik. Loderin altındakiler kaplama olmaz. Fiyatı verdik. Değerlendirecek.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('a3ee551d-0639-5533-8706-e6575f3e2d70','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='AKÇANSA' AND il IS NOT DISTINCT FROM 'BÜYÜKÇEKMECE' LIMIT 1),'50e50a23-9809-5f62-8cd0-20217c38c0e7'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-07-18',NULL,'Tüm tesislerin ekipmanlarından sorumlu mühendis Cahit bey ile görüştüm, eskiden tüm tesislere tek noktadan verdiğimiz hizmeti yine vermek istediğimizi söyledim. Sıcak baktı konuya,  bana tüm tesislerin listesini ve iletişim bilgilerini verdi. Tesisleri ziyaret edip kendisine bilgi mailleri atmamı istedi. tüm tesisleri hızlıca ziyaret edip kaplamaları için devrede olacağım.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('81b41a9b-6c9c-51b7-af8b-1e1abe8bc44c','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='AKÇANSA' AND il IS NOT DISTINCT FROM 'ESENKENT' LIMIT 1),'4d5c2b63-4b52-59ce-b5cf-98fe67cd4b8b'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-07-18',NULL,'Bugün aracımızda burada daha önce kapladığımız lastikleri takmak için geldi. Çıkan 4 23.5 lastiği bedelsiz olarak emanet kullanmak için tesis müdürünün bilgisinde aldık. Buradaki ortak tesis makinesinin kaplamaya ihtiyacı var, onu resimledim Cahit beye bildireceğim, makine bu tesise ait değil.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('aef7281a-abd2-5d01-9d47-e632cc3a519b','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='AKÇANSA' AND il IS NOT DISTINCT FROM 'BAŞAKŞEHİR' LIMIT 1),'979bac71-d2eb-501b-bac9-f39c589466bf'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-07-18',NULL,'Kanal istanbul için yapılan ilk büyük köprünün inşaat işinin beton kısmı akçansada, ana yüklenici rönesans. Rıdvan bey ile görüştüm, burada yeni makine var fakat 2 lastiği yakın zamanda kaplama olması gerekiyor. Rıdvan bey teklif istedi mail olarak attım.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('0c7a183f-0e60-5b0c-8ebf-5139a163a663','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='AKÇANSA' AND il IS NOT DISTINCT FROM 'YARIMBURGAZ' LIMIT 1),'b46db83c-bf18-5402-a4b5-b364f7485530'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-07-18',NULL,'Bu tesis ile de Rıdvan bey ilgileniyor, halkalı metro şantiyesinin beton işini Akçansa almış. 4 adet çıkmış 23.5 lastiği hursa sahasında inceledim 2 adedine kaplanır oanyı verdim. Atlı gelip incelemiş hepsine olmaz demiş. Takip ediyorum.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('002b73c1-a549-58ea-9e42-f598bb40eef5','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ADM BETON' AND il IS NOT DISTINCT FROM 'SİLİVRİ' LIMIT 1),'ce840b7b-2da9-5a8c-a4e5-0f712ed403b6'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-07-18',NULL,'Necmettin formen ile görüşüp kaplamaların onayını aldım.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('fe4b0e43-3403-5752-8642-f962fa1ff498','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ADM BETON' AND il IS NOT DISTINCT FROM 'SİLİVRİ' LIMIT 1),'ce840b7b-2da9-5a8c-a4e5-0f712ed403b6'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-07-18',NULL,'Selçuk bey ile görüştüm, bu tesisteki makine yerel bir taşerondan kiralıkmış, bizim bilgilerimizi ihtiyaç halinde onlara iletecek.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('7d8934cd-b566-536c-af24-43a08dbaaf18','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa','8b1ab4be-de03-4a62-a51b-249550f385e3'::uuid,'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-07-21','YILDIRAY BİLEN','Tatkonun lastikçisi emekli olmuş, Tatko yerine birini verene kadar biriken işler ile ilgili bizden destek istediler. Yusuf beyi ziyaret ettik, 1 adet 27.00R49 değişimi yaptık. Yusuf beye bu süreçte ekibimiz müsait olduğu günlerde denk gelirse ve fiyatlarımıza onay verirlerse hizmet verebileceğimizi söyledik. çıkan tamir ve kaplamalardan bize vermek istediğini söyledi, fiyat istedi fiyat verdik. takip ediyoruz.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('a329fc1f-e536-5c2d-b1b0-3930eb987781','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='HEREKE MICIR' AND il IS NOT DISTINCT FROM 'HEREKE' LIMIT 1),'5be3a2a3-03cc-5994-a280-677c942e1e0f'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-07-21','YILDIRAY BİLEN','Vahit bey nisan ayında ölmüş, tesis ile müdürleri ilgileniyor. İşleri yavaş olduğu için öğleye kadar çalışma yapıyorlar. Vahit bey sizinle olan tartışmasından bahsetmiş müdüre fakat biz de sık ziyaret etmemişiz. Tatko ile aktif devam ediyorlar. Bir kaç ziyaret daha yapıp kaplama ve tamirde girişi deneyeceğiz.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('26c953c3-1561-5e17-9c2c-d190438c5cc6','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='SİMGEMAT' AND il IS NOT DISTINCT FROM 'HEREKE' LIMIT 1),'2d42ea96-f48e-5bfc-a425-72ec3391fd00'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-07-21','YILDIRAY BİLEN','Bu tesise hizmet veriyoruz, Aytaç bey ile tanışmaya gittim hep telefonlaşıyorduk. Merkezdeki Caner bey ayrılmış yerine gelen kişinin bilgilerini aldım onu ziyaret edeceğim. Bu tesis ve Gebze ile aytaç bey ilgileniyor. Diğer tesisler için Bursa merkeze gideceğim.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('521fd1d5-7d3b-51ad-a619-97c300256287','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='AKBAY' AND il IS NOT DISTINCT FROM 'DEREKÖY' LIMIT 1),'20d416aa-d370-5847-9fd1-4ffe0a710764'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-07-22',NULL,'daha önceden takip ettiğim kaplamalar vardı, 3 loderi de ölçtüm toplamda 6 adet 29.5R25 kaplama tespit ettim, fiyat onayını aldım bu hafta içinde 2 tanesini hemen alıp kaplamalara başlayacağız.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('24026481-f0b5-540e-b6ca-fa99e7eea0e0','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='EMRAH SERİN' AND il IS NOT DISTINCT FROM 'DEREKÖY' LIMIT 1),'dea8b250-ff5d-5bf3-b4fb-391c138e64e5'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-07-22',NULL,'Serin beton kuruluşu taş ocağı Şirin şef ile görüştüm, loderlerin tamamı ile o ilgileniyor. Tatko ile çalışıyorlar, 1 loderi beraber ölçtük tatko kaplaması arıza yapmış tespit ettik. Çok vakit ayramadı arızaları vardı, takip edeceğim.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('a2e801e3-fe40-5fdd-9109-66e18a16486b','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='AR KA MADEN' AND il IS NOT DISTINCT FROM 'DEREKÖY' LIMIT 1),'84979df3-5be9-5891-b12d-fcf86bf123e0'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-07-22',NULL,'Dereköy taşıyıcılar kooperatifinin kurduğu taş ocağı. Mühendisleri Hakan bey ile görüştüm. 1 loderleri var tatko ile çalışıyorlar. Alımlara merkez ofisten Fevzi bey bakıyor.takip edeceğim.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('05f27955-f588-587c-b141-39f8c4494a72','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='BAKIRCILAR' AND il IS NOT DISTINCT FROM 'DEREKÖY' LIMIT 1),'2c11091a-6db4-520f-8479-7e5165fd74a5'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-07-22',NULL,'Cantaş betonun taş ocağı. İbrahim şef ile görüştüm. 6 lodeleri var. Tüm alımlara merkezde patron Ahmet bey bakıyor. Takip edeceğim.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('d8c047d7-40ef-5746-89ac-086d09565ceb','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='AYAZOĞLU MADEN' AND il IS NOT DISTINCT FROM 'DEREKÖY' LIMIT 1),'d0cbf5c8-b391-5e48-b24a-1f9bad61072c'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-07-22',NULL,'Rahmi Ayaz ile görüştüm, 2 loderleri var. Tatko ile çalışıyorlar. 1 loderin lastik durumu kötü ama işler yavaş diye onu çok kullanmadan idare edeceğiz dediler. Takip edeceğim.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('c9fbb825-5af3-57b0-9bef-17483ef9fbeb','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='MAKİŞ İNŞAAT' AND il IS NOT DISTINCT FROM 'ÇINARCIK' LIMIT 1),'71386f0e-2ca4-5462-9070-65c8a0bfa689'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-07-24',NULL,'Trabzon merkezli bir inşaat firması, hatayda da şantiyelerini ziyaret etmiştim. Yılmazlar ile çok aktif çalışıyorlar fakat bu lokasyonda otr kaplama metkaya vermiş yılmazlar. Viyadük ve tünel işleri var en az 3 yıl daha buradalar. 4 tane loder var kontrol ettik kaplanacak lasitk var. şefleri ile görüştük fakat satınalmada formenleri ne derse o olur dedi ve o kişi tüm şantiyeleri geziyormuş ona denk gelmeniz lazım dedi. iletişim bilgilerini vermedi.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('2f428069-525a-58ff-8bd0-c23859e502da','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='GÜRER MADEN' AND il IS NOT DISTINCT FROM 'İZNİK' LIMIT 1),'6fb8a65a-4cf2-5592-91af-798be7fc46a7'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-07-24',NULL,'İznikde taş ocakları var. 1 loderleri çalışıyor. Burada yetkili kimse olmuyormuş, taş köprüde ofisi ziyaret etmemizi istediler.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('af8cac38-8fdf-5708-a21e-42acd22b613b','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ASELMAS MADEN' AND il IS NOT DISTINCT FROM 'İZNİK' LIMIT 1),'5636e3a2-911d-5e66-97e0-60e26fece5c2'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-07-24',NULL,'taş ocaklarında 2 loderleri var. Firma eskiden bizi iyi biliyor, kaplanacak lastikleri vardı. Kaplama yaptırmıyorlarmıi yeniyi solaksubaşından alıyorlar ve karkaskarı onlara satıyorlarmı. Aldıkları lastik Galaxy markaydı, bizim kaplamaların bu lastikleriden çok çalışacağını söyledim. değerlendirecekler.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('41d7cc46-6d20-567a-8c13-24e472d8afaa','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ÇETİNKAYALAR' AND il IS NOT DISTINCT FROM 'ALTINOVA' LIMIT 1),'cf2c58d3-e29f-5f46-9e6a-4823e9cbf714'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-07-24',NULL,'Bursa beton altınova tesisine uğradık fakat makineleri çatinkayalar firmasından kiraliıkmış. Firma yetkilsine ulaştık, bizi olduğu yere çağırdı, 6 loderleri var toplamda hepsi bursa betonda kiralık. Aracı üzerinden ovakent ile çalışıyorlar. Kaplama ve hizmetlerimizi anlattık. mutlaka bizdedn hizmet alacakalarını söylediler.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('9291794b-3ab1-556c-8ef3-2f8d8f6bf8ec','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='TRAKTAŞ MADEN' AND il IS NOT DISTINCT FROM 'KIRKLARELİ' LIMIT 1),'5ea9cdec-118a-5751-b578-2bf291b5bd2a'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-08-19',NULL,'2 adet 26.5R25 alımları olacaktı, izindeyken fiyat vermiştim takibi için gittim. Bizim 125.000TL fiyata karşılık Atlı Bridgestone VJT yi 100.000TL ye teklif etmiş. O fiyata düşemeyeceğimizi söyledim. 110.000TL ye kadar hemen ödeme için revize ettik. hafta içi değerlendirecekler.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('35a2270c-b976-59bd-b29d-7449432dee53','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ÇALIŞKAN MADEN' AND il IS NOT DISTINCT FROM 'KIRKLARELİ' LIMIT 1),'4e8729e0-240e-5bb4-ace6-4861fc0d67d7'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-08-19',NULL,'Kaya bey ile görüştüm, müşteri çekleri çok fazla yazılmaya başladığı için tedarikçileri çek vermeyi durdumuşlar, çekleri tahsile kadar saklyırlarmış. Son dönemde 15K dan fazla yazılan çek olmuş. Bu sebeple alımlarıda yavaşlatmışlar. Yeni alımını takip ediyorum uzun süredir stoğa 2 adet L5 alacaklar fakat bu sebepten kalsın diyor. araç latı yaptım formen İlker ile 10 kamyon 2 26.5R25 kaplama tespit ettik. bunları planlayıp alacağız.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('5c5bb635-2dde-529d-9a8a-732f91a335dd','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ARNAVUTKÖY TAŞ OCAĞI' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'38820cf2-0978-5d18-877a-bbb71c41bd89'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-08-20',NULL,'5 Loderleri var, taş ocağı işletiyorlar. Bizim desene çok benzeyen ama logo olmayan bir kaplama gördüm, Atlı olabilir diye düşündüm. Bezli lastiği Radyal diye satmışlar ondan biraz üzgünlerdi. Bundan sonra bizden de fiyat alacaklarını söylediler. Akbaya giderken yol üzerinde bende daha sık uğrayacağım.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('bae4d931-52bc-5d1a-97a3-1f6e50a6b6aa','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ED MAKİNE' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'e146cc43-d04b-55d3-ad9e-26f1da535f25'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-08-20',NULL,'firma sahibi ile tanıştım, lastikli kiralama işinden lastik kısımını dahil edemediğimiz için vazgeçtik dedi. Bende marubeni vb firmalar lastik hariç kiralıyor dedim, müşteri kurumsaldan öyle kiralıyor bize gelince kabul etmiyor dedi. Ayrıca uzak bölgeye de kiralamayı işçilik maliyetinden dolayı bıraktım dedi. yine kaplama yada yeni lazım olursa haberleşelim dedi.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('947853a0-33fe-5a93-94dc-fd657c1c5e18','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='AKBAY' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'9c87bdcb-e0e2-5fa1-96f2-c52a122507ed'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-08-20',NULL,'Tahsilat için uğradım. İşleri onalarında sezonsal yavaşlamaya girmiş. Ayrıca bu tesisin izinleri için orman 40K ilave para istemiş bu parada anlaşamadıkları için tesisi açamıyorlar. Ferizilide çok pahalıya kaplama yaptığımızı diğer tesislerde bizden min %20 daha ucuza iş yaptırdıklarını söylediler fakat Ferizli bizle çalışmak istediği için sorun olmadığını söyledi. Kırklarelinde 2 adet 29.5R25 kaplama lastikleri var alacağız çekini yarlayınca haber verecekler. ayrıca bu tesiste de ölçüm yaptım 2 adet yeni 29.5R25 ihtiyaçları var değerlendirip haber verecekler.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('07b8853f-f3b0-513a-ad87-ee341f3ef29a','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='GÖKYAR MERMER' AND il IS NOT DISTINCT FROM 'BİLECİK' LIMIT 1),'b6013855-562f-5a1c-9a91-bf4c75cefb3e'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-08-25',NULL,'Tahsilat için merkezlerine uğradım, Osamn ve Fatih beyler ile görüştüm. fabrikaları olduğu için İç piyasaya verdikleri ebatlılar ve kurdukları mıcır ocağı satyesinde biraz hereket var. Mıcırı da piyasanın altına verip hareket sağlıyoruz dediler. Sonra ocağa geçtim, ADT kapladığımız lasitklerde koparak aşınmaları gözlemledim, mühendise bilgi verdim takip ediyorız dedim. son kapladıklarımızı henüz takmamışlardı.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('5d4f978f-1328-5470-84d3-b5c2a01f2790','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='GÖKSUTAŞ MERMER' AND il IS NOT DISTINCT FROM 'BİLECİK' LIMIT 1),'c27d7571-c0fd-5318-a1b3-c150286216c5'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-08-25',NULL,'Tek açık ocakları Söğütte burasıda hafif tempo çalışıyor. Formenleri Şakir usta en son bizim 29.5R25 teklifimiz sonrası yeni almaktan vazgeçip hurdalıktan çıkardığı 2 lastiği sovak kaplatmış. Lastik kötü güzüküyordu beraber inceledik. Bir daha sıcak kaplama yaptırmayacağını söyledi. lastiği sorduklarında ben izindeydim o sıra burada olsaydım ziayret edip yeniye ikna ederdim.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('011857c8-0358-5c29-9fd2-6430d4a7a071','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='AYNURLAR MERMER' AND il IS NOT DISTINCT FROM 'BİLECİK' LIMIT 1),'771a03bc-734c-5697-87d8-fea4da7431c6'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-08-25',NULL,'bu bölge mermerin hareketli olduğu dönemde çok popülerdi bir çok firma buradaydı fakat hepsi kapanmıştı. Gökar mühendisi aynurlar açmış dedi bunun üzerine hem bölgeyi taradım hemde aynurlara uğradım. Aynurlar ocağı taş ocağına çevirip bir firmaya satmış, henüz aktif değil sadece bekçi vardı. diğer tüm ocaklarda bekçi dahi yoktu hepsi kapalı.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('b65f3960-3828-5ba1-ab7f-8aca86c05aec','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ALTINSOY MERMER' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'48279c3d-5b5c-5a90-843d-3ad62cc13b5b'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-08-26',NULL,'Nurullah Altınsoy ile firma merkezinde görüştük. Yaklaşık 3 aydır takip ettiğim 2 adet 23.5R25 alımı var. Geçen hafta yine fiyat sormuştu. Yokohama ve maxam teklif ettim. Tatko GY fiyatı bizim Maxam dan ucuzdu bende diş derinliği farkı ve geçen hafta komşusu Erenler mermere verdiğimizi söyledim. biraz ilgisini çekti. Kütahya yolundaki ocağına 2 adet 26.5 var yeni onlara bak onları al bunları ver dedi. bende bakmadan birşey diyemem dedim. ocağa bakıp değerlendireceğim.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('2221fff1-af69-5edc-814a-66f9f423cb32','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='AKÇANSA' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'47733cbb-48c2-5e3a-8371-20cc9d447a74'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-08-26',NULL,'2 tane loderleri var 1 tanesini yatırıyorlar. Mühendisleri ile görüştüm, yatan makinenin lastik kaplama ihtiyacı var diğeri iyi durumda. Şuanda iş az diye yaptırmaycaklar. Taş ocaklarını Afay işletiyor bu hafta Afaya 2 yeni 2 kaplama yaptık aktif çalışıyoruz.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('95668d91-fb3e-594e-889e-ffa0d7023680','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='JEOPARK MERMER' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'e4eaca6e-d4fa-5d18-affc-82d8e954d2a4'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-08-26',NULL,'Kemal bey ile görüştüm, bende az önce kolpaş Mehmet Turantaş gelmiş.  Vadesi geçen vardı onu konuştuk faturayı gözden kaçırmışlar hemen ödeme planına aldılar. Şuan kaplama ihtiyaçları yok yedekleri de var. Sadece stoğa 2 adet 29.5R25 konusunu konuşuyoruz işler yavaş diye alttan alıyorlar.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('389349eb-d8d6-5c5d-9609-84c9c96f9f8c','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='AYKARDEŞLER MERMER' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'4f4cae56-961c-597a-bfb6-44a2cb255fb0'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-08-26',NULL,'10 yıldan uzun süredir çalışamadığımız eski müşterimiz, orhanelindeki tüm ocakları kapalıyıdı. Bölgeye her geldiğimde Nedim beyi arıyordum fabrikadayım iş yok diyordu. Eksi Aybur ismindeki ocaklarını taş ocağı için taşerone vermişler çıkan iyi taşıda stoğa çekip fanrikda işliyorlarmış. izin öncesi uğradığımda bekçi vardı, bu sefer Nedim beiyn babası Ali bey ile denk geldim. 23.5R25 için sen git Gemlik Avdandık ocağına bak bana haber ver dedi. fiyatları verdim. sıkı tatko müşterisi firma.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
