INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('a79ebce5-a1e5-543a-92cc-756a61bc73bc','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='GÖKSUTAŞ MERMER' AND il IS NOT DISTINCT FROM 'BİLECİK' LIMIT 1),'c27d7571-c0fd-5318-a1b3-c150286216c5'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-09-03',NULL,'23.5R525 karkaslı kaplama sormuşlardı geçen hafta talebi kaçırmamak için gittim. Formen Şakir usta ile uzun bir pazarlık ve ikna süreci sonrası 2 adet maxam E4 lastiği verdik. Ocağa yeni makine sipariş etmişler ocağı hareketlendirecekler. Yakında 29.5R25 yeni talepleride olacak.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('b009adc1-bfc5-54b8-9de9-165e950471bd','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='AYKARDEŞLER MERMER' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'4f4cae56-961c-597a-bfb6-44a2cb255fb0'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-09-04',NULL,'Avdancık ocaklarını ziyaret ettim, ocak kapalı taş ocağına taşerone agrega için vermişler. Ali beyin kontrol etmemi istediği kamyonu inceledim. 2 adet kaplama için lastiği aldık kaplanmazlarsa yerine yeni alacak. 1 tanesi sıkıntılı lastiğin. 10 yıl aradan sonra Tatkodan sonra ilk işimizi yapacağız. bölgede başka hiç ocak yok.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('b9038307-f63c-5fc0-bca6-2b77b6a8def8','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='İGA' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'14ea2641-9ef8-5e1d-aa89-2e370afe65ff'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-09-05',NULL,'Lastik konusundaki yetkilileri Hayrettin beyi ziyaret ettim. Geçen hafta kaplamaya aldığımız 2 adet 35/65R33 lastiği iade ettiğimizi açıkladım. Yeni talebine yanımda çıktılar bende Maxamları anlattım ve çok avantajlı vereceğimizi söyledim. Kataloğu inceledik, adam beyede anlatacağım ded. 1.000 adet yeni kamyon sipariş etmişler 300 adedi yakında teslim olacakmış bunların ebadı 13R22.5 istedik dedi. eldeki 325/95R24 leri satıyoruz dedi. ama az miktarda yine yeni alıyorum dedi. bende stoktaki Sailunları teklif ettim. inceledi hoşuna gitti talep açmadan bana at dedi. fiyatı GY altında olursa hepsini alacağım dedi. İGA ile buzları iyice eritiyorum, satınalmaya geçiyordum Atlı oradayış geçmedim. haftayda satınalma ile teklifleri takip edeceğim.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('a9c27f42-55b5-57de-99a9-08622ef8b282','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='AKBAY' AND il IS NOT DISTINCT FROM 'SAKARYA' LIMIT 1),'7853b190-84a8-5581-9fe4-4f23f96260fa'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-09-08',NULL,'Kamyon kaplama zam sonrası kamyon kaplamaları artık bize veremeyeceklerini söylediler, zaten %30 kadar pahalıydı son zam ile artık tercih edemeyeceğiz bir süre ara verelim sizinle dediler. Loderleri kontrol ettim, 2 kaplama, 2 yeni ve 4 tamir tespit ettim. yeni listeden onyladılar kaplamaları aldık, yeniler için değerlendirmelere devam ediyorlar.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('9acb632a-6f3d-5657-a8f2-5734d14180b7','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='İGA' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'14ea2641-9ef8-5e1d-aa89-2e370afe65ff'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-09-09',NULL,'Geçen hafta Atlı ile çakıştığımdan Yılmaz beye uğrayamamıştım, kademedeki Sailun 325/95R24 yönlendirmem sonrası 100 adetlik alımlarının 24 adedini (tüm stok bu kadardı) bizden yaptıklar, Yılmaz bey yanımda siparişi bize geçti. Aradan sonra buzları iyice eritmeye başladık. 35/65R33 maxam teklifimizi sordum, proje müdürü fiyattan dolayı büyük makineyi çalıştırmayın makineye ihtiyaç olursa alım yapın demiş. burada da MAxam için şansımız var. takip ediyorum','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
