INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('a6527905-e15d-54d9-8b8a-5c4eaa2a971f','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='MARMARA DOLOMİT' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'e85da4c2-2e58-52b8-8124-0f1a0017beff'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-09-12',NULL,'Sevan bey ile görüştüm, kaplamaları adadan onlar getirdi biz kaplayıp yine onlara teslim edeceğiz. Kamyonları haızr iş makineleri üretimde. Tüm lastileri için çeki aldım','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('81720ddf-ed19-5d84-b243-2fe1105bca1b','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='SİNTA BETON' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'82654da1-35a0-55f5-9b19-fac22056a66c'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-09-15',NULL,'Brisa filo bayisi firma daha önce kaplama yapmıştık. Ali bey beni tanımadı, işler çok yavaş bir talep yok diye geçiştirdi ama loderlerinin lastikleri aşınmıştı. Daha sonra tekrar uğramak gerekli.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('9a928ece-90dd-52cb-93ea-03b68a5d9479','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ALTINSOY MERMER' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'48279c3d-5b5c-5a90-843d-3ad62cc13b5b'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-09-15',NULL,'Şükriye ocaklarında çıkmış bir 23.5R25 lastik vardı onu inceledim, tamir için onayını alıp aldık. Tüm makineleri kontrol etmek istedim fakat öğlen arası gelmemi istedi şefleri. Sonra ölçüme gideceğim','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('d944df64-5824-503b-b13b-8fb3fa422321','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ALTINSOY MERMER' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'48279c3d-5b5c-5a90-843d-3ad62cc13b5b'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-09-15',NULL,'Serçeler ocaklarında ölüçüm yaptım. 2 adet 23.5R25 kaplama tespit ettim. Aslında 4 adet kaplama tespit ettim fakat Nurulah bey şimdilik acil olan 2 taneyi kaplamaya alın dedi.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('a275f5e3-34c4-5fb6-b89a-e5749740722d','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='BURSA BETON' AND il IS NOT DISTINCT FROM 'YALOVA' LIMIT 1),'d98c127c-69aa-549e-817c-d049d14fa67e'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-09-16',NULL,'Sipariş ettikleri sensör kılıflarını teslim ettim. Loderi kontrol ettim fakat loder kiralıkmış kiralama yapan firmayı tanıyorum ziyaret etmiştim. Servet beyi aradım firmanın yetkilisi bize sorduğu 23.5-25 lastik vardı hem onu sorum fakat henüz değerlendirememiş.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('94fa1a92-2533-5aa6-b90f-bd920fc8ad8d','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='MAKİŞ İNŞAAT' AND il IS NOT DISTINCT FROM 'YALOVA' LIMIT 1),'a21ef6d0-8818-5b3d-bb99-c56a62e01ee9'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-09-16',NULL,'buraya 2. gelişim tek yetkili formen Hlimi ustaya ulaşamıyorum. Fakat bu sefer iletişim bilgilerinni verdiler, genelde iznikteki şantiyede olurmuış aradım açmadı. Haftaya şantiyeye gidip bulacağım.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('62fb4720-f13f-50e1-b3ad-d7fa5fc94535','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='YAZICILAR MADEN' AND il IS NOT DISTINCT FROM 'YALOVA' LIMIT 1),'900fe9b4-f673-5844-8d44-82e62ccdc78b'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-09-16',NULL,'taş ocağı ve vinç kiralama işi yapıyorlar. Taş ocaklarını ziyaret ettim, tek yetkili Soner beymiş. Ocakta yokmuş, telefon ile görüştük firmamızı biliyor Yıldırayı tanıyor, geçen hafta gelseydin 2 adet 26.5R25 aldım ve 5 adet kaplamaya verdim dedi. Bize sordunuz mu peki dedim, hayır dedi nedenini sorduğumda çalışmadığıımız firmalara sormuyoruz dedi. tanışmak için randevu istedim bakarız dedi vermedi. takip edip yoklamak lazım.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('9857a6b8-1209-55d1-acec-387e729ac990','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ALTINSOY MERMER' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'48279c3d-5b5c-5a90-843d-3ad62cc13b5b'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-09-18',NULL,'Şükriye ocağına öğle arası ölçüme gittim, 4 loder 2 kaya kamyonu var. 1 tamir tespit ettim, Nurullah beye ölçümü attık lastiği alın dedi. Ayırca subaşı lokasyonunda 2 adet 29.525 var onlara da bak al kapla oluyorsa dedi, haftaya da oraya bakacağım. Bursada en aktif ocaklar Altonsoy firmasının, şuanda özel bir taşları çıkıyor siyah ve talebe yetişemiyorlar. Nurullah bey sürekli makine alıyor.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('b6b4d824-4247-500c-97db-87d0c426130e','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ÖZERLER MERMER' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'a25c2f1f-c636-5b59-9c2a-1815e12cfcc4'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-09-18',NULL,'Şükriyedeki ocaklarında ölçüm yaptım 3 loder ve 2 kaya kamyonu var. Burada da siyah değerli taş çıkıyor ama daha yavaş bir ocak. 2 adet 29.5R25 yokohama verdik, bunları takıp çıkanları tamire alacağız. Ayrıca kamyonda da 1 adet 29.5R25 tamir tespit ettim onuda alacağız.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('5b427453-5afc-5499-9d2a-21e63f07c37e','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='SEL MADEN' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'c6956321-e211-5258-9b8c-edb39a1becd9'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-09-18',NULL,'Afyon merkezli firma, daha önce bir kere uğramıştım o zaman ocağı yeni açıyorlardı. Ali bey ile görüştüm, müşterimiz jeopraktan 2.el almışlar makineleri 2 adet de yedek lastik vermiş orası bzim sattıklarımızdan. Çıkanları afyona gödnermişler Şeref abiden rica ettim benim için bakıp bilgi verecek.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('0d0abf04-2208-5148-8ea0-fe691ec98679','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='FEDERAL MERMER' AND il IS NOT DISTINCT FROM 'BİLECİK' LIMIT 1),'5aef9238-6308-5cb6-9856-94a5aacf7cc9'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-09-23',NULL,'29.5R25 yeni alımları gündemydi mühendisleri Selçuk bey beni satınalam Gökhan beye yönlendirmişti Gökhan bey beni davet etti. yokohama ve maxam olarak fiyatı verdik. Ürün sunumlarını yaptım. Conti E4 tatko fiyatını gördüm 170.000TL+KDV. Micehlin fiyatı gördüm 210.000TL+KDV. fiyatları topluyorlar. değerlendirecekler.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('8a556b98-08ce-5f4e-8b59-7c1b568cca60','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='GÖKYAR MERMER' AND il IS NOT DISTINCT FROM 'BİLECİK' LIMIT 1),'b6013855-562f-5a1c-9a91-bf4c75cefb3e'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-09-23',NULL,'tahsilat için merkezlerine gittim. Çeki aldım, kalanı havale yaptılar. Osman bey oradaydı ona uğradım. Şuan talep yok kontroleri de yapıyorum.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('3f264b39-302b-5047-9d4a-82849696b803','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='PRODEM MERMER' AND il IS NOT DISTINCT FROM 'BİLECİK' LIMIT 1),'4fc66b0c-e2b8-51c7-95d2-997acb32cf49'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-09-23',NULL,'mühendisleri Serkan bey ile ocaklarında görüştüm. Kaplama için olan taleplerini fiyat vermiştik fakat patronları fiyattan dolayı tatkoya vermiş kaplamaları. 2 loderleri var bu sezon artık bir talepleri olmaz. Yeni sezona takip edeceğim.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('4330f8c9-affd-5740-950d-a518b9ec1f9a','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='GEMPORT' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'af25b190-5cbd-5638-b7d1-25bf979e0e5b'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-09-24',NULL,'Eski kontağımız mühendisleri Sancar abi deveti üzerine gittim, hurdalık alanında detayl bir inceleme yaptık, 18.00-25 lerden ve terminal traktör lastiklerinden kurtarılabilecekleri seçtik. O sırada direktörleri Serdar bey geldi, eskiden onunla da Yılporttan tanışıyoruz. öğleden sonra için bana satınalmadan randecvu ayarlardılar. satınalmadan Mustafa bey ile görüştüm, kardeşler ayrılınca tüm satınalma ekibinide değiştirmiş, ekip yeniydi. kaplama ve tamir ve yeni ksımı ile ilgilediler. eski tedarikçiler ile tekrar görüşmek istediklerini tek yer subaşı ile gitmek istemediklerini yönetiminde bu şekilde istedğini söylediler. ebatlar için tamir ve kaplama fiyatları vererek başlayacağız.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('69065cd6-b318-5b03-bc18-435054e9e5d2','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='AKBAY' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'9c87bdcb-e0e2-5fa1-96f2-c52a122507ed'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-09-26',NULL,'satışının yeni tamamladığımız 29.5R25 L5 lerin çekini almaya gittim. İlk kez yokohama kullanacaklar, ferizli ocaklarına verdik lastiği. Trakya ve istanbul içinde yedek lastikleri yok fakat bütçeden dolayı zamana yayıp alacaklar, buralarada yokohama vermek için Savaş bey ile görüşüyoruz.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('48bc5593-1a1e-50a2-afd8-e1ef53b12be2','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ARNAVUTKÖY TAŞ OCAĞI' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'38820cf2-0978-5d18-877a-bbb71c41bd89'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-09-26',NULL,'formen seyfettin ile görüşebildim, Cuma saati olduğu için çok uzun görüşemedik. Kaplama konusund bizimle iletişime geçecek, arka lastiklerini takip ettiğim bir loder var birkaç aya kaplama için sökülmesi lazım.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('a1a02f92-5ece-5343-ae8b-cce5d9be1df1','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='MAKYOL' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'b540e6cd-c913-58ae-b0fb-d76d24b37afc'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-09-26',NULL,'Müjday bey seyahate gidityordu, kaplamaları hatırlarttım ben haber vereceğim henüz başlamadık dedi ama bence başladılar en son görüşmeden çok zaman geçti. Karasu şantiyesine uğrayıp fiziksel bakacağım.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('197bbb8f-0889-59b0-83a3-2bea8b0a0dc8','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='KALYON' AND il IS NOT DISTINCT FROM 'KOCAELİ' LIMIT 1),'1beaeb93-ff4c-53b5-a4c6-c228e48d4edb'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-09-26',NULL,'avrupa yakasındayken Ekrem beyi aradım kandıradım buraya gel dedi. Kandıra şantiyesine geçtim, genel sohbet ettik. En iş makinesi alımlaında  bizden tiron ve petlası onayaldığını söyledi. Kamyonu oradan çok ucuza alıyorum dedi. Oradaki iş bitmek üzere, kandıra ikmale kaldı sonu ne olur bilemiyorum dedi. bursa da artık üstyapıya geçildi lastik hareketi az olacak dedi. çok lastik işimiz 2026 da olacak gibi değil dedi. kars da cengiz üzerinden gidiyoruz lastiği onlar veriyor dedi. görüşmede ilk kontağımız rahmi de oradaydı, abi kademeye gidip lastiklere bakalım dedi. kademeye gittik, tatkonun yeni kaplama arızasını gördükmhrdaya atmışlardı, bunu garantiye yollayın dedim aytırdılar. 2 adedt 26.5R25 inceledil bunları abi siz alın kaplayın dedi, aracımız yakında kaplama için aldık.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('efbeec79-0652-55f5-9d45-a9bf9150045a','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ALTINSOY MERMER' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'48279c3d-5b5c-5a90-843d-3ad62cc13b5b'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-09-29',NULL,'Karacabey ocaklarına 2.el aldıları loderi kontrol etmemi istemişlerdi. Kontrol sonrası 2 lastik kaplanayamayacak durumda tespit ettim. Nurullah bey buraya depoesundaki yenileri takıp çıkanlarıda Orhaneline takmamızı oradan çıkanları da almamızı istedi. servisleri de ayrıcıa fatura etmemizi istedi. çıkan kaplamaları ve tamirleri tespit ettikçe alıyoruz, 2 yeni ihtayaçları olacak deposundaki lastikleri bitmek üzere.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('f44eea29-90db-5e79-95e7-1d3d785982d3','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='TEKNİK BETON' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'83e1c05a-4177-5a7e-8187-65c738f3150c'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-09-29',NULL,'Karacabeye gelmişken bölgeyi de tarafım, gördüğüm diğer mermer ocağına gittim fakat ocağı teknik beton mıcır tesisi olarak işletmiş şuanda da kapalıydı. Ayrıca civarda yine teknik betona ait başka bir beton tesisi vardı o da kapalıydı. Yi ni civarda büyük bir taş ocağı görüp gittim bursadı Özkar inşaata ait ve şuanda çalışmıyordu.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('46db0c6f-2832-5aaf-8738-bdd4f78bc256','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='DERYA TUĞLA' AND il IS NOT DISTINCT FROM 'TEKİRDAĞ' LIMIT 1),'f26a53b7-0aa6-5e02-81c4-4ef805b35574'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-09-30',NULL,'Bu yıl sattığımız 26.5R25 Bridgestone lastikeri kontrol ettim. Ayrıca diğer 3 loderide ölçtüm. 2 adet tamir tespit ettim. İşlerin yoğuluğundan sadece 1 taneyi şimdi alacağız durumu daha iyi olanı sezon bitimi alacağız. Pazartesi lastiği alacağız.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('73c3fb16-9c4b-57f4-bf43-7db21b66dd9a','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='EFOR BLOK TUĞLA' AND il IS NOT DISTINCT FROM 'TEKİRDAĞ' LIMIT 1),'5cf78981-f30e-5dd4-87c0-db3c29e6c706'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-09-30',NULL,'Loderleri ve forkliftleri kontrol ettim. 1 adet 26.5R25 tamir tespit ettim, Pazartesi gelip alacağız. Forklfifteri burada Tiron veriyorduk Nexen dolguya çevirmeye başladım. Onlarda bir sorun yoktu. Loderin arkaları daha önce kaplamıştık, artık kaplanamayacağı için 2 adet yeni konuştuk alımı planlayacaklar.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('7e8dad2d-2f97-510c-8a55-5b0bc11ff228','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='BEŞER TUĞLA' AND il IS NOT DISTINCT FROM 'TEKİRDAĞ' LIMIT 1),'fd190db9-2011-5f1a-910d-4e079a34f827'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-09-30',NULL,'2 loder ve forkliftler baktım. 2 adet tamir ve 1 kaplama tespit ettim. Bunları şuan hızlı bir işimiz var bitirince hemen yapalım dediler. 4 adet forkift lastiği ihtiyaçları vardı siparişini geçtiler.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('51d9031b-90b3-51a4-a564-da1ab28e5f38','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='MUTAŞ' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'4439c57d-53fb-5824-8167-aa23e6e529f8'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-10-01',NULL,'Ece hanım ile 3 hafatadır randevulaşmaya çalışıyordum, şirket yeni bir firma daha kurup mevcut rusatları ve yeni alınanları ayırmış son 2 faturayı bu sebepten yeni firmaya kestirmişlerdi Ece hanım bu sebeple yoğunmuş. Güncel kaplama fiyatlarımızı sundum burdaki fiyatlarımız iyiyid, genelde tamirde yüksek artış oldu. Oyak değişimi sebebiyle onlarda gözlemliyormış fakat bir sorunları olmadığını söyledi.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('0f859340-0d34-5420-a29c-6b77865031e7','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ÇAMSAN' AND il IS NOT DISTINCT FROM 'SAKARYA' LIMIT 1),'42b03df1-58e5-5f97-b641-9773a0c4dfae'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-10-03',NULL,'4 adet yeni 23.5R25 talepleri vardı, Cüneyt bey ile görüştüm, geçen ay 2 adet 23.5R25 kolpaş vermişti, alıma özellikle micehlin olarak çıkıyorlar bunu değiştirmek için birazda ziyaret ettim. Elimizde şuanda 23.5R25 de maxam olduğu için ona yönlendirdim diş derinliği avantajını anlattım. ayırca kaplamaları almak istediğimizi söyledim. genel olarak güzel bir görüşme geçti, Cüneyt bey genelde karşo tarafın fiyatlarını benimle paylaşıyor, bu sefer kaçırmamaya çalışacağım.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('21f1f898-59b2-521f-9da7-1c4f271ef332','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='DAŞDAN MADEN' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'351831ac-513b-57b0-ac63-d7017871426a'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-10-06',NULL,'Fırat bey şantiye etrafındaki çitleri yeniletiyordu ayaküsütü görüşebildik, haftaya geniş zamana gel dedi. Tüm makine parkı yatıyordu.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('a0824f06-4cc6-5073-844c-0ab700371b28','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ETİLER MADEN' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'896fbeef-abf2-5ddd-abdc-62bd783214e9'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-10-06',NULL,'Makineleri kontrol ettik, satınalma Hasan yoktu fakat patronun kuzeni işletme müdürü ile görüştük, greyderin lastik ihtiyacı vardı alımı albayraktan barter olarak yapmışlar betona kum veriyoruz karşılığında lastik alıyoruz dedi. En son loderleri maxam vermiştik, bölgeye gitikçe uğruyorum.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('bcafc636-410f-5451-bff6-e597e64ddf13','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ALBAYRAK BETON' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'c9302195-23fc-535c-b54d-c7ea4d97da94'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-10-06',NULL,'kaplama için fiyat vermiştik onayda vermişlerdi, ben araç gitmeden tesiste lastikleri görmek istedim, kaplatmak istedikleri lastikler kaplanamaz durumdaydı, yeni alıp önlere takıp önleri kaplayıp arkaya alalım dedim. Bunun üzerine aksiyon aldılar haftaya lastikleri kaplamaya alacağız.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('76e7dced-d85d-5124-bb43-0e0a0c3200a9','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='OMYA MADEN' AND il IS NOT DISTINCT FROM 'KOCAELİ' LIMIT 1),'149eaee4-2a75-5068-b811-8e3c8d7a213d'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-10-06',NULL,'mühendisleri Emre bey ile görüştük, 20.5R25 micehlin satmıştık, sadece micehlin alım yapıyorlar ve kaplama yaptırmıyorlar. L5 kullanmalarını önermdim, kaplamaya yönlendirdim. Micehlin harici yine iyi performans alacaklarını söyledim. Kaplama için ve L5 için bizden fiyat aldılar. teknik onayını alıp kaplamayı deneyecekler. balıkesir tesisini aradı Emre bey beni yönlendirmek için ordaki yetkili gerek yok ben sadece Tatko ile çalışıyorum sen bak bir kaç kere memnun kalırsak gelsinler dedi.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('f72d3bde-ba6b-5d53-b339-c9a3a3f38040','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='AKÇANSA' AND il IS NOT DISTINCT FROM 'YALOVA' LIMIT 1),'dd12a9dd-11e5-579c-992b-b0b72a987902'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-10-07',NULL,'buradaki makinin kontrolünü yaptım. Önler 1 tanesi kaplanabilir, arkalar bezli önler radyal. Tesis müdürüne bilgi verdim. Yeni lastik teklifi istediler. Sonrasında merkezden cahit bey yeni galaxy teklifimizi olumlu buduğunu bütçeye uydurup alım yapacağını söyledi. haftaya Cahit beyi genel tüm tesisler için ziyaret edip bu konuyuda bağlamaya çalışacağım.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('77e1b3cd-0277-5a26-8327-8b6e32236fae','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ÇETİNKAYALAR' AND il IS NOT DISTINCT FROM 'YALOVA' LIMIT 1),'0d8d5306-cea2-526e-a45c-a6233fa1f7bb'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-10-07',NULL,'Bursa beton ana taşeronlarından, 23.5R25 talepleri Servet bey ile görüşüyorum, makineye baktım henüz alımı yapmamışlar. Galaxyleri teklif ettim. Patronlarından değişim için onay alamamışlar 4 ader yeni alımları olacak takip ediyorum','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('8083f41a-c538-5dae-8cf1-be84b59175d5','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='DAĞİŞ MADEN' AND il IS NOT DISTINCT FROM 'BİLECİK' LIMIT 1),'5ef3ddc8-2a81-5222-9f0d-ba4ded91ca19'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-10-08',NULL,'yaptığımız kaplamaların çekini aldım. Satınalmadan Kerem bey ile görüştüm. 8 loderleri ve 1 greyder ve 1 silindirleri var. Bizim kaplamaları takıp çıkanları da yine verecekler fakat işlerin yavaşlamasını bekliyorlar. Tbr yeni de Günmarlas ile çalışıyorlar. ayrıca burda da taş ocakları var.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('77830c2b-bff3-597c-8856-25e2abbc48f3','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='AKDENİZ MANYEZİT' AND il IS NOT DISTINCT FROM 'ESKİŞEHİR' LIMIT 1),'02314292-b973-57f9-9e20-86d2d5886713'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-10-08',NULL,'Satınalmadan Cemal bey ile görüştüm, 8 loderleri var. Manyezit işindeler, işleri oldukça yavaşlamış. Kaplamada ovakent ile çalışıyorlar. Tbr 13R22.5 için fiyat verdim olumlu buldular alım olunca haber edecekler. Kaplamalar için formenleri karar veriyormuş aradım, haftaya gelmemi istedi ocağa yağıştan çıkamazsın dedi.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('ff76e681-f46b-5afa-812a-2c612553586f','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='KARÇET BETON' AND il IS NOT DISTINCT FROM 'BİLECİK' LIMIT 1),'2dcdc200-74eb-51af-825a-d324e746eb3e'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-10-08',NULL,'Osman abi ile görüştüm, yeni açmak üzere oldukları santrale uğradım. Sattığımız 23.5 ların çekini aldım. Oradaki loderi kontrol ettim lastik ihtiyacı vardı 20.5 2 adet son tironları verdik. Çekini haftaya alacağız.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('ad87f087-399e-5ca2-b962-de00ea3c26de','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='SİLTAŞ' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'6b1db3ed-4c45-564b-83b9-af14442e9678'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-10-09',NULL,'uzun süredir vedat bey ile görüşmiyorduk her seferinde yoktu, bugüne randevulaşmıştık. Ben asıl patronları Hüseyin beyi tanıyorum fakat ulaşamıyordum, bugün oda buradaydı. Beni tanıdı güzel bir görüşme geçti. 13 loderleri var 5 tanesini satıyorlar. Yağış çok olduğu için sahaya çıkamadık. haftaya 3 tesisinde de ölçüm yapıp kaplama ve tamirler için görüşeceğiz.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('c66ae632-f789-5f34-8122-a096f4ff951e','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='KASTAMONU ENTEGRE' AND il IS NOT DISTINCT FROM 'KOCAELİ' LIMIT 1),'8fa145e6-8626-581b-9173-e4389a7aced6'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-10-14',NULL,'Levent bey sürekli yurtıdışı yatırımlara baktığı için uzun süredir denk gelemiyorduk, bugün için randevulaşmıştık. İşleri çok yavaşlamış, kuzeydeki fabrikaları rusya ukrayna savaşından dolayı durmak üzereymiş. Yurt içindeki fabrikalarda satış çok düşük olduğu için stoğa üretim yapıyorlarmış. işten çıkarmalar başlamış ciddi sıkıntı var tüm fabrikalarda dedi. yeni lastiği uzun süredir portaldan sormuyorlar dedim, çünkü alım yapmıyoruz tesisler yatıyor dedi. tüm gidelerde frene bastık dedi. artık zaten lastik konusu bende değil ben yatırımlara bakıyorum dedi. ama senin için ben yine satınalma direktörlüğünü arayıp size öncelik vermelerini isteyceğim sende holdinge git Hasan beyi bir ziyaret et ben arayacağım dedi. kastamonu tesisindeki ciddi bir yolsuzluk sonrası merkezden her fabrkiya bir satınalmacı yollamışlar. bunlara benim ilerşim bilgilerimi iletecekler. gebze tesis müdürü Fatih beyde işten ayrışmış, yerine başlayan Özgen hanım hasta olduğu için görüşme kabul etmedi. sonrası için onunla da tanışmya gideceğim.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('ee829041-a7d9-5661-986d-c23260904e6d','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ALBAYRAK BETON' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'c9302195-23fc-535c-b54d-c7ea4d97da94'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-10-14',NULL,'Gamze hanıma 26.5r25 vjt sormuştum, iyi fiyat verdi, hatta stoğundaki diğer otr leri de fiyatlandırdı. Vadeli alabilirsiniz zaten kaplama yapıyorsunuz oradan da hesaplaşırız dedi. Beko loder için de fiyat istedim. Genel olarak işlerimiz yavaş dedi. Asıl ziyaret amacım bölgedeki kum firmaları ve beton firmaları ile bartır olarak çalıştıkları için oraların otr kaplamalarını onların üzerinden de alabilemek. bu çerçevede hizmet verebileceğimizi söyledim. satış ekibinie söyleyeceğim gittiğimiz yerlerde otr kaplama tamir talep gelirse direkt sizinle iletişime geçeriz dedi. tbr kaplama için çalıştıları yerden çok memnun olduklarını söylediler. kapıda lastiksan aracı vardı sanırım onlar ile çalışıyorlardı.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('a4cef7d9-7582-5523-946e-f2e79959a419','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ÖZTÜRK YAPI' AND il IS NOT DISTINCT FROM 'KIRKLARELİ' LIMIT 1),'d91b094a-4c5c-522b-8c59-414dd4b394ea'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-10-15',NULL,'Mustafa bey ile randevulaşmıştık fakat işi çıktığı için gelemedi. Telefonda görüştük. En son kaplamaları 2 hafta önce almıştık.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('7f289ed5-4201-549d-be3c-c60786f0737b','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ÖZBERCE MADEN' AND il IS NOT DISTINCT FROM 'KIRKLARELİ' LIMIT 1),'ee0c2882-ee38-514c-82e7-c3273ee6e8d3'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-10-15',NULL,'Pınarhisar çıkışında taş ocağı görüp uğradım. Satınalma ile ergin bey ilgileniyormuş bugün yokmuş. Sonraki hafta yine uğrayacağımı söyledim, mühendisleri ile görüşp bilgi verip ayrıldım.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('3da7ce81-3d31-5fd6-b6b5-c20161c6b8d5','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='KİMTAŞ KİREÇ' AND il IS NOT DISTINCT FROM 'KIRKLARELİ' LIMIT 1),'d1e9f281-7e6a-5d34-a981-6f2d1d26b55c'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-10-15',NULL,'Pınarhisar çıkışında büyük bir kireç fabrikası görüp uğradım. Tüm makine parkuru kamyonlar dahil Öztürk yapınınmış. Ben bilmiyordum, zaten orası ile çalıştığımızı söyledim, Öztürk yapı limak içinde vardı burda da varmış.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('c3bd950e-9113-5b25-ac59-08d5dee90e09','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ZOFUNLAR BETON' AND il IS NOT DISTINCT FROM 'KIRKLARELİ' LIMIT 1),'1f0dd0a1-5cbc-50d0-b4a0-8a4b92825632'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-10-15',NULL,'Pınarhisar beton santrallerini ziyaret ettim. Loderin lastikleri kaplama zamanı gelmişti yetkili kişi lastik konusuda direkt patron Hikmet bey karar veriyor ona gidin dedi. Santralden aradım, lüleburgaz merkez ofisteyim gel dedi.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('1005db6e-bc7e-567c-892a-b7bb533c3913','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ZOFUNLAR BETON' AND il IS NOT DISTINCT FROM 'KIRKLARELİ' LIMIT 1),'1f0dd0a1-5cbc-50d0-b4a0-8a4b92825632'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-10-15',NULL,'Hikmet bey randevulaşmamıza rağmen yoktu, ulaştım 1 saate yakın bekletti ve geldi. Kaplama kullanmıyorum ben dedi. Asla kullanmam dedi. Yaptıığım kontrolü gösterdim. Yeni için yokohama anlattım. 8 tesis ve 9 loderleri var. Yedek lastiği var mı diye birini aradı lastiğim varmış bir ihtiyacım olursa ararım dedi. çok ilgilenmedi.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('41731be0-475e-5632-a9c6-26d4de971e27','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='CANTAŞ BETON' AND il IS NOT DISTINCT FROM 'KIRKLARELİ' LIMIT 1),'5db4056e-5693-5b72-9d08-bae199325f2d'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-10-15',NULL,'Tesis müdürü ile görüştüm, lastik işine babeskide  Aydın bey bakıyor dedi. Aydın beyi aradım, iş makinesine Selim bey bakıyor o da edirne merkezde dedi. Sonrası için program yapacağım Selim beye','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('62768ceb-aee7-5603-8ff7-f2979963a449','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='MAY BEYON' AND il IS NOT DISTINCT FROM 'KIRKLARELİ' LIMIT 1),'4a72727c-0058-5fac-a5a9-cc69ef2fb8d3'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-10-15',NULL,'4 adet yeni 20.5-25 verdik, Turgay bugün montajını yapıyordu. Çıkanların 1 tanesi hariç çöptü onu da yedeğe ayırdık. Firma Atılım Danış beton ile ortaklık yapmış faturayı da bize oraya kestirdiler. Ömer beyden atılım danış yetkilisini aldım. Haftaya atılımıda yoklayacağım.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('5bf1b8b5-4ec4-5683-8b2c-a958332dde54','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='AKBAY' AND il IS NOT DISTINCT FROM 'SAKARYA' LIMIT 1),'7853b190-84a8-5581-9fe4-4f23f96260fa'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-10-16',NULL,'Cafer bey ile görüşmeye gittim fakat yoktu. Bende makineleri kontrol ettim. Tamire takında alamamız gerekenler var. Yokohama L5 ler gayet güzel görünüyordu. Haftaya cafer beyi yeniden ziyaret edeceğim. Kırklareli içinde 2 adet L5 alımı olacak burdaki Yokohama referans çok önemli. firmanın toplamda 4 adet daha L5 alması gerekli.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('7f658012-6042-5a73-a75f-cc3d26c7e0c6','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='OZAN BETON' AND il IS NOT DISTINCT FROM 'SAKARYA' LIMIT 1),'7112dbe7-5de2-5819-8f9e-c1a49b0ef30b'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-10-16',NULL,'beton santrallerini ziyaret ettim. Yetkilileri buraya yakın başka bir yerdeymiş. Tarif ettikleri yere gittim taradım fakat bulamadım ama oraya giderken başak bir taş ocağı buldum.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('2eb0495e-19f7-5d91-b186-47539f652fa5','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='FERİZLİ TAŞ OCAĞI' AND il IS NOT DISTINCT FROM 'SAKARYA' LIMIT 1),'1f346d96-b445-518b-8d5f-68bbf2a5adca'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-10-16',NULL,'Ozan betonu ararken buldum, firma sahibi ve şefleri ile görüştüm, çok eski ve hafif tempoda çalışan bir ocak. 2 loder var. Bir talep olursa haber verecekler. Arada bi uğramak lazım. Ozan betonu sordum burada yerleri yok dedi, ilk gittiğim yeri söyledi.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('8281b26d-ba82-5170-90aa-37134f4275fa','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='KASER MADENCİLİK' AND il IS NOT DISTINCT FROM 'SAKARYA' LIMIT 1),'b9b03ac0-ef9e-5536-bf26-267d1424ba33'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-10-16',NULL,'Satınalmadan Ali Kaya bey ile görüştüm. Taş ocağı ve beton satralleri var. BS kullanıcısı firma. 4 loderleri var. En son Bs almışlar. Ali bey çok uykuluydu ne yaptıysam esnemesini ve gerilmesini durduramadım, bende uyumamak için ziyareti sonlandırdım, birkaç hafta sonra yine uğrayacağım.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('07f70e3d-5cf1-54db-8c6f-0d47fe61f2a7','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='BİLEK TRANSPORT' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'f41aa512-45b9-5a8b-9756-9d683ff657eb'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-10-20',NULL,'Özdemir betona gelince karşılıklı oldukları için uğradım. Kasım abi ile görüştüm, kimse gelip gitmiyor sizden diye sitem etti. Sailun dorslerden çok memnun olduğunu varsa 12 adet daha almak istediğini söyledi. Vergiden dolayı getirmiyoruz dedim, sava fiyatı verdim. 315/60 30 adet çeker sordu kumho gelince fiyat vereceğimi söyledim.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
