INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('fd8b8e95-31ce-518b-b53c-430e03e8cfd3','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ALTINSOY MERMER' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'48279c3d-5b5c-5a90-843d-3ad62cc13b5b'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-10-20',NULL,'Erenler ocağında lastikleri kontrol ettim şefleri ile. 3 adet birkaç aya kaplamaya çıkacak lastik var. 2 adet yeni GY almışlar bizdende fiyat almışlardı onları takmışlar. Ellerinde yedek 23.5 da kalmamış Nurullah beye bilgi verdim.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
