INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('de6bc443-26c1-5a37-81e6-16847e12600c','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='SEVTAR' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'5f69cf77-b6a3-52e3-a8c6-23cc1b7beadb'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-10-20',NULL,'Özgür ile görüştüm, otr kaplamada çalışırız tatko burada bizim yenisini verdiğimiz yerlere giripyor dedi. BKT yerine bizden maxam almasını söyledim. Onun elindeki eski 26.5R25 lere fiyat vermesini istedim. Kaplama potansiyelleri var arada ziyaret edip diri tutmak lazım. Özgür sizinle sorun yaşamadan çalışırız dedi.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('71b66013-8fe5-5216-b4df-098a42d62a60','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='AKÇANSA' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'acde648f-42c4-54c0-b5f3-c1dcf4221b6a'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-10-21',NULL,'merkezlerinde makine ikmal müdürleri Cahit bey ile görüştüm. Bu hafta içinde loderleri bir personelini ezmiş ölümlü kazadan dolayı yenibosna tesisini kapatmışlar. Cahit beyin morali çok bozuktu. Sazlıbosnada kaplanacak lastikler vardı ama tesis şefi Rıdvan bey bütçeden dolayı onay vermiyordu, konuyu hatırlattım,yanımda aradı ben onay veriyorum lastikleri verin dedi. yalova tesisinin yeni lasitkleri de onay bekliyordu onuda onaylanması için hatırlatttım. genel sohbet ettik. işleri oldukça yavaşlamış.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('200d7f18-d976-5087-98a7-76c27b84e6b4','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='MARMARA LASTİK' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'6fe2d881-fb5c-5bdb-a569-c7d4371d11e8'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-10-22',NULL,'Aracımın lastiği patladı tamiri için yakın olduğundan marmara ya geçtim. Samet tatkocular ile görüşüyordu ona uğramadım. Amcam oradaydı. Sailun almaktan vazgeçmişler, tamer ön ödeme istemiş, türkiye stoğundaki mallar uymamış. Westlake aldık yerine ucuz dedi.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('dc4e97ec-1c9e-55be-ba70-c00fe9309302','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='MARMARA DOLOMİT' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'e85da4c2-2e58-52b8-8124-0f1a0017beff'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-10-22',NULL,'tahsilat için uğradım çeki aldım. Sevan  bey yerinde  yoktu.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('c9f02dd9-e9ce-5bcc-821f-691c6308a2cf','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='MARUBENİ DAĞITIM' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'2f2a5b8b-2c9a-562e-9f00-aeee24b4e6d6'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-10-23',NULL,'bugün aslında ataşehir ofislerinde satınalmalarıyla randevum vardı fakat cihan bey rahatsızlandığı için iptal etti, bende serdar abiyi ziyaret ettim. Kaplamalar ile ilgili henüz onay alamadığımızı söyledim, 12 adet olduğu için direktör onayında dedi, yakıdan size onayını geçerler ben takip ediyorum dedi.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('bf7ae60e-30e7-5c33-8870-d82f704927b0','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='PUSULA LASTİK' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'2da8a731-d70c-5d64-9f8c-3161957abd4c'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-10-23',NULL,'İsdemerin bizde kalan ihalesi için ödeme esnekliği istedim. 60 gün sonra %50 kart ve 90 gün sonra kalan olarak Halim abi ile de görüşerek anlaştık. Lastikeri yavuz abi isdemire sevk edecek. Gemi gelmek üzere.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('93cc2179-fc25-5249-8ec3-670ae0119342','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ASCENDUM' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'1898b44e-f927-5c8b-b2ea-d88113f8c643'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-10-23',NULL,'2.el ve kiralama müdürü Serdar bey ile görüştüm. Kendisi eski temsacı. Bir çok ortak tanıdığımız var genel sohbet ettik. Elindeki 29.5R25 BS lara eş için fiyat sormuştu bana, fiyat verdim. Kaplama işlerini tatko ile devam ediyorlar. Benim verdiğim 29.5R25 50mm kaplama fiyatından tatkonun 10k daha düşük olduğunu daha yeni kaplattığını söyledi. talep olunca haberleşeceğiz.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('9486a115-bd85-554e-8407-b2a61ca11afb','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ERKAY MADEN' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'bb02b48d-b869-523f-b6bf-145ec0769be3'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-10-27',NULL,'Denetlemeleri vardı çok uzun görüşemedik. Masada atlının fatuaları vardı, yakıtıda onlardan alıyoruz dediler. Krom halen zarırına satıldığı için ekipmanlara para haracamıyoruz dediler. Asıl parkur taşeronları ünaldı makinede.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('285176f1-402c-5fb2-9bdd-7fa2f2abf08a','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='CVK' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'22d42c06-9c34-5a62-9e3e-59978cf06e5f'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-10-27',NULL,'uzun süredir İlhan bey telefonlarımı açmıyordu, geçenlerde aradı ve 23.5R25 sordu. Bende yanına gelip konulaşalım demiştim, çavuşoğlundan elindeki eski malı teklif ettik. Aynı ürün için bir çok brisa bayisinden daha düşük aldığı fiyatları gösterdi, bizim çavuşoğlu alım fiyatımız ve bir tık altı fiyatlar vardı. kaplama için daha odaklı görüştüm, ilk 23.5 lara asılacağız.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('1c459ad8-dbbf-597d-95b7-0ff6849212e2','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='BAHADIR GRUP' AND il IS NOT DISTINCT FROM 'KÜTAHYA' LIMIT 1),'235e15b6-6637-518b-8ae3-2f18c527bb74'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-10-27',NULL,'Kereste ve taşeronluk yapıyorlar, 2 loderleri var. Firma sahipleri ile görüştüm, bir loderleri oradaydı lastik durumu iyiyidi. İletişim halinde olacağız.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('9232adf3-c564-5765-beb5-a15ed0cdea31','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ÜNALDI' AND il IS NOT DISTINCT FROM 'KÜTAHYA' LIMIT 1),'56400918-169e-5a15-807d-168bbf168599'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-10-27',NULL,'Erkay maden ana taşeronu 9 loderleri var, alımlarla patronları Mehmet bey ilgileniyor, o da bugün şansıma izmitteymiş. Bir sonraki tura uğrayacağım.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('cd9abd6b-e82b-56b1-9b9e-7d00f5be0232','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='TAVŞANLI KOOP' AND il IS NOT DISTINCT FROM 'KÜTAHYA' LIMIT 1),'45a7d6d7-1d91-5058-8072-d3d3aa75f172'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-10-27',NULL,'Başkan ile görüşmeyi başaramadım 3 loderleri var. Sonra tekrar deneceyeceğim.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('d661a43a-77ee-55e4-a23c-9669ff2d357d','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='BOZDAĞ' AND il IS NOT DISTINCT FROM 'KÜTAHYA' LIMIT 1),'da841e9f-5637-51ab-985a-cdda1ea1b377'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-10-27',NULL,'Satınalmadan Fatih bey ile görüştüm, yeni başlamışlar tki sahasında 5 loderleri var. Kaplama için fiyat verdim. Yeni lastik alımlarında da fiyat isteyecekler. Bir kaç hafta sonra yine uğrayacağım.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('2d144ca9-5e14-53ee-935a-074ad6665251','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ÖZDEMİR BETON' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'63253cb5-9e5d-506b-864f-28597394e9f6'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-10-28',NULL,'Zafer bey ile görümemiştim geçen hafta bugün için randevulaşmıştık. Beton işlerindeki santrallerinde 4 loderleri var. Ayrıca çorum hızlı tren projesinde taşeronluk yapıyorlar burda da 5 loderleri var. Toplamda 70 kamyonları var. Metkay ile aktif çalışıyorlar. bizden kaplamalar için fiyat istedi.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('edc7b954-a9fb-5c4f-98a6-5f68cc9306a8','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='MARUBENİ DAĞITIM' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'2f2a5b8b-2c9a-562e-9f00-aeee24b4e6d6'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-11-03',NULL,'merkez ofislerinde satınalmadan Cihan bey ve Berfu hanım ile görüştüm. Uzun süredir sadece mail ve telefon üzerinden görüşüyorduk. Berfu hanım biraz geç kaktıldı, Cihan bey elimden geldiğince işi size veriyorum Serdar bey sizden yana tercih kullanıyor dedi. 10 adet kaplamanın onayını verdiler. bir önceki bizde kalmayan kaplamalar içinde ben izindeydim Berfu Tatkoya vermiş ben olsam size verdirirdim ama raya gitti dedi. işleri genel olarak onlarında yavaşlamış fakat gebze ve adana fabrikalarını hendek yeni yerlerine taşıma işleri olduğu için biraz yoğunlarmış. tesisimize davet ettim.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('e4e3992d-e0cf-58c8-8258-1c318aedfe61','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ÖZTÜRK YAPI' AND il IS NOT DISTINCT FROM 'KIRKLARELİ' LIMIT 1),'d91b094a-4c5c-522b-8c59-414dd4b394ea'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-11-04',NULL,'Mustafa bey ile görüştük. İşleri yavaşlamış 3-4 loderi satıyorum dedi. Kamyon kaplamaları var alacağız. Limak içindeki taşeron için destek istedim bir yere yönlendirdi.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('cd86a11f-0271-5a7a-adae-6f8e86be5553','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ÖZDEMİRGİL' AND il IS NOT DISTINCT FROM 'KIRKLARELİ' LIMIT 1),'eaeca177-b768-525d-8698-70b8753ba4f0'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-11-04',NULL,'Limak çimentonun ana taşeronu firma, loderler onlara ait. Yetkilisi Erdinç beye ulaşamadım tesis dışındaymış ama iletişim bilgilerini aldım. Aradım açmadı. Sonraki sefere görüşeceğim.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('eb416ce0-38e5-5341-9f88-ec9f0b4fc985','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ÖZBERCE MADEN' AND il IS NOT DISTINCT FROM 'KIRKLARELİ' LIMIT 1),'ee0c2882-ee38-514c-82e7-c3273ee6e8d3'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-11-04',NULL,'bir önceki ziyaretimde Ergin bey yoktu, bu sefer görüştük. Tesis kapanmış fakat yeniden açıyorlar, 2 loderleri var, 1 tanesine yakın zamanda BKT almışlar, çıkanlara baktım yedek olacak durumdaydı. Kaplama yada tamir için iletişimde olacağız.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('8b1e498b-6120-510d-92f1-1c559305a87c','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='TRAÇİM ÇİMENTO' AND il IS NOT DISTINCT FROM 'KIRKLARELİ' LIMIT 1),'a7473d5c-7dcf-580c-b0f2-3933425d951b'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-11-04',NULL,'Çimento fabrikasını ziyaret ettim, fakat traçime adeti sadece forklift var loderler Çiftay a aitmiş. Orada hemen Çiftay merkez Sabahattin beyi aradım, düzenliservis verdiğimizi bu bölgeyede talip olduğumuzu söyledim. Tamam iyi oldu dedi, orada bir talep olunca haberleşeceğiz dedi.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('9315feac-84b2-59a0-9f4b-0aca3c3c83a8','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ÇALIŞKAN MADEN' AND il IS NOT DISTINCT FROM 'KIRKLARELİ' LIMIT 1),'4e8729e0-240e-5bb4-ace6-4861fc0d67d7'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-11-04',NULL,'Formenleri İlker ile görüştüm, kaplamaların hepsini takmamışlar takınca çıkanları alacağız. Loderleri kontrol ettik durumları iyi.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('9970c4f2-9ba5-5e1a-9a26-0944ec30258e','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='TRAKTAŞ MADEN' AND il IS NOT DISTINCT FROM 'KIRKLARELİ' LIMIT 1),'5ea9cdec-118a-5751-b578-2bf291b5bd2a'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-11-04',NULL,'Onur bey ile görüştüm, yokohamaları kontrol ettim önde çalışıyorlar, yedekleri yoktu ama diğer grup firmalarından fazla olan loder lastiği varmış onu getirmişler. Yakın zamanda talepleri olmayacak gibi.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('ce28ac3e-d3ae-551d-b11e-e246f6aa1e00','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='AKBAY' AND il IS NOT DISTINCT FROM 'SAKARYA' LIMIT 1),'7853b190-84a8-5581-9fe4-4f23f96260fa'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-11-05',NULL,'Şaban şef ile görüştüm, onunn tavsiyesi üzerine kırklareli tesiside L5 Yokohama aldı, teşekkür ettim desteği için. Kırklarerilinden çıkan kaplamaları al bana getir tak, benden 2 adet daha kaplama al dedi. Makineyi takip ediyorum 1 aya kaplamaya alacağız dedim.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('9b7e2b02-43bb-54a7-944e-8e2482c5d8dd','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='KASER MADENCİLİK' AND il IS NOT DISTINCT FROM 'SAKARYA' LIMIT 1),'b9b03ac0-ef9e-5536-bf26-267d1424ba33'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-11-05',NULL,'Ali bey ile görüştüm, işler var ama para dönmüyor dedi. Betondan 5.aya çek geliyor şimdiden dedi. Bu çekler ile alım yapıyoruz eğer kabul edersen lastikte başlayabiliriz dedi, bende o vadelerin çok uymadığını yine iletişimde kalmamızın iyi olacağını söyledim.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('1f27ffe9-5f43-5712-a485-7b8fc020cc54','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='OZAN BETON' AND il IS NOT DISTINCT FROM 'SAKARYA' LIMIT 1),'7112dbe7-5de2-5819-8f9e-c1a49b0ef30b'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-11-05',NULL,'Geçen sefer bulamadığım tesisi buldum bana yolu yanlış tarif etmişler. Faruk bey ile görüştüm, 3 loder ve 70 kamyonları var toplam 2 tesislerinde. Kaplamayı çağlayana batmana yolluyorum dedi, kamyonlarıda atmaca firmasına veriyorum dedi. Yakında 1 loderimde kaplama olacak haberleşelim dedi. arızalı yolda kalan bir aracı vardı çok telefon trafiği vardı ayrılmak zorunda kaldım.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('adea85f5-95d2-50ba-8d0e-538b497cc3aa','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='PAKSAN KİREÇ' AND il IS NOT DISTINCT FROM 'SAKARYA' LIMIT 1),'a13321e4-cf0c-51e7-9be3-f0b61636e3c9'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-11-05',NULL,'Kireç fabrikasını ziyaret ettim makinemiz yok sadece forklift var, taşeronda makineler dediler.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
