INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('bef66974-7cd7-5192-96dd-ba4e0d8bc890','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='AKÇANSA' AND il IS NOT DISTINCT FROM 'TEKİRDAĞ' LIMIT 1),'acbb04ab-2861-52de-a722-b9fe8234c04d'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-11-10',NULL,'tesis müdürü İbrahim bey ile yine denk gelemedik, loderin lastikleri iyi durumda ama hurdalıkta 4 adet 23.5 tespit etttim. İbrahim beyi arayıp bilgi verdim kaplanaması için, izindeymiş sonra gel konuşalım dedi.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('436c37c4-c8c9-5975-8b79-8af5991fe26e','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='İMPAZ MADEN' AND il IS NOT DISTINCT FROM 'TEKİRDAĞ' LIMIT 1),'19779e04-5d37-5d3f-b682-d686342771a5'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-11-10',NULL,'Mehmet formen ile görüştüm, hep telefonlaşıyorduk bugün tanıştık. Loderi kontrol ettik durumu iyi. İş az olduğu için çalışma yavaş. 3 tesislerini de takip ediyorum.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('1a959d85-4d2a-5879-bce0-c257aaa736eb','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='AKGÜN BETON' AND il IS NOT DISTINCT FROM 'TEKİRDAĞ' LIMIT 1),'291f3f81-4300-504f-8f99-18b0a3b47065'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-11-10',NULL,'atelye şefleri Turhan bey ile tanıştım. 2 tesisleri var 5 loderleri var. BKT alıyorkar otogar lastikten. Kaplama için ve yeni için artık bizimle de fiyat soraracaklar.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('a277b2ca-0ec5-5aa4-a608-3427fe848253','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ORBİTAL' AND il IS NOT DISTINCT FROM 'İZMİR' LIMIT 1),'f903398c-749d-5f60-a249-43956118257f'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-11-12',NULL,'Barış ile görüştüm, en son lastik devrilmesi sonrası madenden gelen tepki sonrası biraz soğumasını beklemiştim. Omuz profillerini düzelttiğimizi söyledim. O da madene o şekilde bilgi verdi. Yeniden tüm maden kaplamalarını bize verecek. 7 adet vardı bu hafta onları aldık. Gönlügür brisa baskısı ile tamamen Özcanlara dönmüş. çok ucuz kaplama talebi gelince batmanlılara veriyorum bende de dedi. bende bizim ucuz kauçuğun batmanlıların ürün ile denk olduğunu denemesini söyledim. madende hafif bir makinede test edecekler.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('7eb382e1-7aea-596e-9b3a-bf59566208c5','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='İGA' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'14ea2641-9ef8-5e1d-aa89-2e370afe65ff'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-11-13',NULL,'bakım ikmali ziyaret ettim Hayrettin  bey ile görüştüm. Son kaplama ve tamirlerin hepsini biz aldık. Hüseyin Torosun karkaslı stoğunu atmıştı bana oradaki 325/95R24 leri buraya teklif etmek için geldim. 32 adet var dedim. Geçen hafta yeni alımına çıktık keşke geçen hafta gelseydin yeni almaz bunlardan alırdık dedi, bu lastikleri satılan kamyonlara takıyorlar, yeni gelen kamyonlar 13R22.5 olarak geliyor. O sırada müdürleri Adem Karabudak geldi, ziyaretin amacı nedir benlik birşe var  mı dye sordu Hayrettin beye. masadaki getirdiğim pişmaniyeyi yedikten sonra, Hayrettin karkaslı varmış ama geçti artık dedi. Adem bey olur mu hemen satınalmaya mail at iptal etsinler bunların elinde olan adet kadarını kalanı yeni alsınlar dedi. banada sende satınalmaya git durumu anlat dedi.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('621f938b-4186-5c13-880b-460e894a2453','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='İGA' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'14ea2641-9ef8-5e1d-aa89-2e370afe65ff'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-11-13',NULL,'Zaten satınalmadan randevum vardı, kampüs ofislerine geçtim. Toros elindeki 32 lastiği 6.000TL den aldık, 10.000TL den igaya verdik.  Yılmaz bey ile revize işlerini hallettik ve sohbet ettik.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
