INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('93d18a95-8a9c-578b-a63c-888ee8061325','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ENTO MADEN' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'32c90717-85dd-572b-bfca-2687734a7782'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-11-17',NULL,'Danamandıra kum ocaklarına uğradım tesis müdürü ile görüştüm, tüm alımlar için kemerburgaz lütfi beye yönlendirdi. Her gittiğimde arıyorum fakat benimle görüşmüyor Lütfi bey sadece bir kere kamyon lastiği için mail attı. Takip ediyorum.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('17387a39-9a1e-5f55-8f03-88b57edea87f','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ADM BETON' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'756029da-a2db-53be-97d6-3110e891d275'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-11-17',NULL,'Danamandıra taş ocaklarını ziyaret ettim, Necmettin bey ile görüştüm, işleri yoğun oldukça. Kapladığmız lastikleri kontrol için uğradım. Kamyon fiyatı verdim, atlı ve albayrak fiyatına göre yüksek geldi. Tbr de petlasın filo bayisiyiz direkt alıyoruz dedi.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('50f176a2-ce4d-5f09-8cd6-4c8934528444','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='EBK HAZIR BETON' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'9c6f21ac-2701-505f-b321-662400669114'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-11-17',NULL,'Bayram şef ile görüştüm,2 loderleri var, petlas alıyorlar, kaplama yaptrımıyorlar. Kaplama deneyebileceklerini söyledilar. Petlas için de fiyat soracaklar.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('62ab2ad5-cd44-5efd-af3c-0efea0c7c583','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='GÜLERMAK' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'3a68b16d-1b01-5da5-b2d5-4bd82e850653'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-11-17',NULL,'Danamandıra beton tesislerine uğradım, 2 loderleri var, yetkileleri ana şantiyedeymiş 30 km ileride oraya geçtim. Makine ikmalde Kalyondan tanıdığımız Aytaç şef vardı. 67km hızlı tren projesi almışlar, Çelikler ile ortak ama makine işi bizde dedi, makineler yeni geliyor çok makine olacak dedi. kaplama için düzenli hizmet verebileceğimizi söyledim, olabilir sizie tanıyyoruz dedi. Aytaç bey ile eski firması ERG den de ortak tanıdklarımız çıktı. 2 hafta sonra tekrar gidip takip edeceğim.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('9f8806c7-a4c5-53a7-b4db-318964447c66','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ETİ BOR' AND il IS NOT DISTINCT FROM 'KÜTAHYA' LIMIT 1),'62b1eb4f-8594-5c16-810a-7d82bc40f5eb'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-11-18',NULL,'Kaplama ihalesini kazandık, lastikleri araç gelmeden önden seçmek ve oradaki yetkililer ile tanışmak için gittim Ramazan bey ile görüştüm. 10 adet 26.5R25, 5 adet 17.5R25 ve 1 adet 16.00R24 kaplama için ayırdım, diğerlerini hurda için ve tamir için çıkarttık.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('c2167101-7dba-5fd6-b886-18d1a22f9dc6','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='YILMAZLAR MADEN' AND il IS NOT DISTINCT FROM 'KÜTAHYA' LIMIT 1),'1bb4e198-d106-5b8c-99fd-f840a1c80a9a'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-11-18',NULL,'Fatih Yılmaz en son o bölgeye ziyaretimde benimle görüşmek istmememişti, lastikleri dar bulduğu için bana artık ticaretimiz olmayacak diye mesaj atmıştı. Kademesine uğrayıp ustalarada konuyu anlatmak için uğradım, doğangüye vermeye başlamışlar benden az önce gelmişti kaplamalar, aralarındaki genişlik farkınının ömre etkisi olmacayağını açıkladım. Ahmet ustaya anlattım biraz vakit geçirdim, bizde Fatih bey ile görüşürüz dediler.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('57d22243-5d54-52a4-a0c0-29e93706945f','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='NRC' AND il IS NOT DISTINCT FROM 'KOCAELİ' LIMIT 1),'bd71978a-040a-5ec2-98ed-5bc0c1dbbbd9'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-11-19',NULL,'İzaydaş sahasında çöp tesisinde verdiğimiz Yokohamaları kontrol ettim, yarı diş derinliğinde güzel aşınıyor. Diğer makinedeki kaplamalarımız bitmiş, yedeklerini takıp çıkanları 4 adet kaplamaya alacağız.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('4ce2e11a-85cc-528e-a0e2-79c72d379968','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='DANIŞ BETON' AND il IS NOT DISTINCT FROM 'KOCAELİ' LIMIT 1),'588534ea-b713-52ab-953a-9fffc9073a76'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-11-19',NULL,'4 adet kaplama yapmıştık, formenleri arayıp kaplanacak lastik var gelin bakın diye çağırdı. 5 loderleri var. 3 tanesini beraber kontrol ettik, koplas üzerinen doğangüye kaplattıkları lastikler için bizi çağırmışlar, doğangü lastikleri önde bizimkiler arkadaydı, fakat bizim lastikler bir makinede arkada olmasına rağmen çok kesikli aşınmıştı. kaplama için dedikleri lastikleri tamire aldık diş derinlikleri var henüz. salı günü alacağız.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('8f0c355c-6b24-5e08-b961-05b121e39d49','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='Emin Aygün' AND il IS NOT DISTINCT FROM 'BİLECİK' LIMIT 1),'7f8c105e-5b61-52d0-bb9c-9312a8e67610'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-11-20',NULL,'Daha önce verdiğimiz Yokohamaları kontrol etim. 3 loderleri var, 4 adet daha yeni lastiğe ihtiyaçları var, ya L4 verip yokohamaları arkaya alacağız yada arkalara galxy vereceğiz, müşteri fiyata göre karar verecek.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('e4c444fd-6f91-5946-a5af-4c83d776292f','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='DERYA TUĞLA' AND il IS NOT DISTINCT FROM 'TEKİRDAĞ' LIMIT 1),'f26a53b7-0aa6-5e02-81c4-4ef805b35574'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-11-24',NULL,'adetli forklift alımları vardı, preslemeden dolayı bizde kalmadı, Candanın işten ayrılan adamı mobil pres ile bölgede hizmete başlamış, alımı oradan yaptılar. Geçen sefer geldiğimde taşeronlarına kamyon kaplaması yapmıştık, şimdide başka taşeronları beko loder sordu, fiyaytta anlaştık ödemeyi ayarlayınca haber verecek','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('e4e200ce-8f3a-59da-a6ec-21a13fcf81c7','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='BEŞER TUĞLA' AND il IS NOT DISTINCT FROM 'TEKİRDAĞ' LIMIT 1),'fd190db9-2011-5f1a-910d-4e079a34f827'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-11-24',NULL,'En son ziyaretimde kaplama ve tamir tespit ettimiştim fakat işler yoğun diye sonra gelin demişlerdi. Tekrar kontrol ettim. 2 adet 26.5R25 kaplama ve 1 adet tamiri hafta içi alacağız, programı yaptık. İşleri çok yavaşlamış.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('faaf6b5e-4efc-5bfc-9da3-a7124189f16a','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='GÜRKAY OTO' AND il IS NOT DISTINCT FROM 'TEKİRDAĞ' LIMIT 1),'359d99c8-ac75-5661-8253-3bdc92f391fc'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-11-24',NULL,'En son kaplama için 2 adet almıştık, yine bize ver karşılığında zaten uyarsa mal alıyor Hüseyin senden diye sıkıştırdım, abi bizim müşteriye çökmeyin sonra ama senden öyle bir şey çıkmaz sen onları getirince takalım çıkanları alın dedi. Yeni için henüz tatko dışına çıkmıyor MAxam için zorluyorum.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('4661cdd1-9c26-5b25-be75-c277bb92f893','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='BAŞKAN NAKLİYAT' AND il IS NOT DISTINCT FROM 'TEKİRDAĞ' LIMIT 1),'266635fe-b198-59df-971d-7d197ff4a372'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-11-24',NULL,'Tahıl yüklüyorlar ambarda 2 adet loderleri var, bir ara biz kaplamıştık, en son tatkoya dönmşler. Loderlerin durumu iyiydi. Arada uğrayacağım.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('8234008c-5258-5bcd-9e7b-7f73c6ee634f','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ÖZEN MAKİNE' AND il IS NOT DISTINCT FROM 'TEKİRDAĞ' LIMIT 1),'390a4f05-ccc8-5de1-bc35-5411178f1d8e'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-11-24',NULL,'Marubeninin lastiklerini burada takacağız, makineye baktım, firma sahibi Yasin bey ile görüştüm, 2.el işine başlamışlar artık bizden de kaplama çıkacak dedi, özel fiyatlar ile yardımcı olacağımızı söyledim. Bölgede batan Kiremitçi kömürde 3 milyonları takılmış, tbr satan petlas bayisininde 2,5 milyonu takılmış. 2.el sebebi ile takip edeceğim.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('8668b42d-4443-5f8c-9d0a-0db6bdf7576e','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ADOÇİM' AND il IS NOT DISTINCT FROM 'TEKİRDAĞ' LIMIT 1),'e4c8c29b-d95b-5a16-8749-486c46b3005f'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-11-24',NULL,'Mesut bey ile görüştüm, makineyi kontrol ettik kaplama için artık zaman gelmiş durumda, merkeze bildirdi satınalma talebe çıktı fiyatımızı verdik. Kaplama için şartnameyi bizden destek alarak hazırladılar. Firmanın adı Yunan ortağı Titan grup olarak değişecekmiş. Traçim çimento fabrikasını da satınalmışlar.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('a0030899-4d41-5b52-ad61-e30e881065a0','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ÖZSOY MERMER' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'ae07897f-9e73-52b3-b06e-91fe4e622cd9'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-11-25',NULL,'Özerler mermer serdar abi dağın karşında yeni açılan ocak var diye söylemişti geçen sefer yolu bulamamıştım bu sefer buldum, fakat bu ocak kapanmış, oraya açılan Serdar abinin dediği İleri grup mermermiş.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
