INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('3d22b75c-38d7-5611-998e-1ad91b0f462f','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ÖZAY İNŞAAT' AND il IS NOT DISTINCT FROM 'SAKARYA' LIMIT 1),'5808de16-b27c-5a02-81ab-37c436da43e4'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-12-01',NULL,'Patronları ile denk geldik, 2 tane kireçte 1 tane hafriyatta loderleri var. Petrolas ile çalışıyorlar, 23.5 ihtiyaçları var fiyat verdim çek ayarlarsam haber edeyim dedi. Makineler çok eski durumdaydı.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('d04eb6d4-228f-5134-a554-55fa56782fee','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='AKBAY' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'9c87bdcb-e0e2-5fa1-96f2-c52a122507ed'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-12-02',NULL,'Geçen hafta Kırklareli bu haftada ferizlide kontroller yapmıştım, bugünde arnavutköyde kontrolleri yaptım. Savaş beye ve Emrullah beye notlarımı aktardım. Ferizliden aldığımız tamirleri kırklareline takıp oradan çıkanları tamire alıp, arkaya takıp sonra tamirler 30mm ortalamada 4 adet 29.5 lastiği kaplamaya alacağız. 3 tesistede hiç yedek olmadığını Yokohamaların fiyatının iyi olduğunu 4 adet stok almalarını tavsiye ettim. L5 lerden 2 adet ferizli ve 2 adet kırklareli için alımı onayladılar. toplmada 8 adet L5 yokohama aldılar 2 ay içinde.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('b8431616-04b2-5c65-81fa-d81cacc9f3b8','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ADNAN GÖKALP TAŞ OCAĞI' AND il IS NOT DISTINCT FROM 'SAKARYA' LIMIT 1),'b4e56bf0-7f86-5b51-bcec-828eb8989f5d'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-12-03',NULL,'İrfan bey ile yeni denek gelemedik ama bu sefer telefonda konuştuk, haftaya tekrar uğrayacağım.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('fbf1308e-e940-503c-abdf-49ba463a73e0','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='CİHAN SARAL KUM OCAĞI' AND il IS NOT DISTINCT FROM 'BİLECİK' LIMIT 1),'71f5fb7d-9a26-54ac-9276-f6c968a194ce'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-12-03',NULL,'2 loderleri var nehir kenarında kum çıkarıyorlar. Bezli kullanıyorlar. Firmanın aynı zamada ÖFS mermer isminde harmankayada ocağı varmış, ve lastik talepleri varmış, orayada gitmemi tavsiye ettiler.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('d4113f3f-aae8-5fc7-b3aa-932fe817f2a7','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ASGÖZDE MERMER' AND il IS NOT DISTINCT FROM 'BİLECİK' LIMIT 1),'925278bb-e530-5807-b464-563d338a308a'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-12-03',NULL,'Eski müşterimiz ocakları kapalı fabrikalarını ziyaret ettim, 1 loderleri var yüklemede kullanıyorlar onada masraf yapmak istemiyorlar. 1 kaplanacak lastikleri var onu belki kaplatırız dediler, takip edeceğim.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('145beb3b-42df-5dfd-9f96-8a605479afa6','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ÖFS MERMER' AND il IS NOT DISTINCT FROM 'BİLECİK' LIMIT 1),'a3b6ee5b-6b17-56cc-9b67-5dbfa59b4985'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-12-03',NULL,'eskiden çok aktif bir bölgeydi, bir çok firmanın kapanmış ocakları var, Aze çalışıyordu o da kapatmış, yeni kapanmış 3 ocağa uğradım. ÖFS mermer tek kalmış, şef Bülent ile görüştüm, 2 loder ve 2 kamyon var, firma eskiden Kutup mermerdi, o zaman çalışmıştık. alımı tatkodan yapmışlar bizden fiyat almamışlar Bülent bey satışlar düştü az toplayalaıp kaplamaları alarıız dedi. yine bahara uğrayıp takip etmek lazım kıştan kapatırlar yakında.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('133a530e-b43a-5823-b474-8977dc2e7508','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ÖRGÜN KALSİT' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'8b28f4b4-cabb-5774-9922-d3e9312522a7'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-12-04',NULL,'Yol üzerinde hep gördüğüm bir firmaydı, yetkilisi çalıştığımız yer var diye odasına almadı beni kartımı zorla verdim.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('f33a3b55-d2f6-5865-be5a-891770a3f02d','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='GEMPORT' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'af25b190-5cbd-5638-b7d1-25bf979e0e5b'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-12-04',NULL,'4 adet 14.00-24 Tiron vererek başladık, mühendisleri Sancar abi destek oldu marka tercihinde, kaplamalar için Tatko ve bizim aramızdalar, Tatko hem ucuz hemde min 4000 saat çalışma saat garantisi verdiği için önde. Ben saat garantisi vermedim ama tatkodan az çalışmaz dedim. satınalma bana diğer alımlarda da fiyat konusunda destek oluyor, tbr için markadan veremedik. sizde kalacak birkaç talep daha var onayda dediler. solventaş ve diğer liman yetkileri ile de görüştüm.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('44582d10-9fde-5ae7-b774-cad5ec53aa19','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ESEN MİKRONİZE MADEN' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'09afe52b-7c79-5f1c-8f13-cac403e1847d'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-12-05',NULL,'Irmak hanım ile görüştüm 1 loderleri var. Yerimizin onlara çok uzak olduğunu burada çalıştıkları lastikleri olduğunu söyledi.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('7aaf843c-97ad-5b6c-928a-a23531b6d19f','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='MARUBENİ DAĞITIM' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'2f2a5b8b-2c9a-562e-9f00-aeee24b4e6d6'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-12-05',NULL,'Serdar abi ile görüştüm, özen makinede 8 adet 23.5 var onlara bak işine yarayan olursa al bize bir teklif yap dedi. Emanetimiz azalmıştı 23.5 için iyi oldu. En son 23.5-25 bezli alımı da bizden yaptılar.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('46ae1c09-b111-5c5a-9ff5-6e696f89394e','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='SERKANLAR MADEN' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'d8224eb9-2af2-50d0-a284-e04347c390f7'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-12-08',NULL,'Sedat şef ile tanıştım, Ömer şef ayrılmış. Beni Tatko ile karıştırıp loderin kaplamaları kontrol etmeye yolladı sorun var geçende geldiniz diye. Tatkodaki serkan ile araçlarımız aynı oradan benzetmiş olabilir. Kaplamalarının 1 tanesi hızlı aşınmış garantiden kaplayacaklarmış. oradan ticari ödeme alın biz kaplayalım zaten sorun yaşamışsınız diye bastırdım topu patrona attı geçiştirdi.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('10d1cba4-c88a-5a92-8a50-d6b95bdc7e00','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='MAY YAPI İNŞAAT' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'2bb03f82-4b16-5ba3-b9f4-70965592bfdc'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-12-08',NULL,'Onur bey ile görüştüm, Olgun şefe yolaldı, halen stoklarındaki kaplamalar duruyor, Olgun şef ile görüştüm, ihtiyaç yok diye fazla görüşmedi.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('ca880e80-ef0e-536c-a87f-e855d86a5820','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='GÜLERMAK' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'3a68b16d-1b01-5da5-b2d5-4bd82e850653'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-12-08',NULL,'Ali Umran şef ile tanıştım, beni kademeye yönlendirdi lastikleri kontrol etmem için. 2 adet beton santrallerinde kaplama, 1 adet merkez atelyede kaplama ve 1 tamir 23.5 var. Fiyatı verdim mail olarak, size vermek için satınalmaya söyleyeceğim dedi.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('76380b4b-4345-5f1b-94a1-44835702c518','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='EKOLOJİK ENERJİ' AND il IS NOT DISTINCT FROM 'TEKİRDAĞ' LIMIT 1),'3158d2c6-a573-5bf8-92fa-1a3481d3349b'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-12-09',NULL,'Satınalma ile en sonunda görüşebildim. 1 loderleri var ama çöp içinde hızlı aşınıyor, kaplama için mutlaka çalışırız dedi. Sökme-takma sorun oluyor dedi. Yeni lastiği ankara merkezleri patronlarının arkdaşından alıyormuş, firma aynı zamanda marmara çimento ile aynı grup içinde. takip edeceğim','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('1453c445-e8b7-54ac-aeda-cdd83fe211dc','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='AKÇANSA' AND il IS NOT DISTINCT FROM 'TEKİRDAĞ' LIMIT 1),'acbb04ab-2861-52de-a722-b9fe8234c04d'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-12-09',NULL,'İbrahim şef ile görüştüm, çorlu ve silvir tesisine kendisi bakıyor. Silivrideki makine taşeronda, burada 2 adet kaplanacak lastik var teklif vereceğim yedek olarak tutacaklar.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('d4c04960-9184-59af-9fe4-77f487d6c130','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='AKGÜN BETON' AND il IS NOT DISTINCT FROM 'TEKİRDAĞ' LIMIT 1),'291f3f81-4300-504f-8f99-18b0a3b47065'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-12-09',NULL,'Turan bey beni kum ocaklarındaki makineyi de kontrol etmem için yönlendirdi, kum ocaklarına geçtim sonra yine beton santralinden görüştük. 4 adet 23.5 var burada kaplamasını takip ettiğim, birkaç aya çıkacaklar. Fiyatımızı verdim.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
