INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('7fbc9f0c-8252-595f-8af0-c11a9028d8f9','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='EYÜPOĞLU VİNÇ' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'11190c09-a47e-5636-acd2-aadc7e3ef141'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-12-11',NULL,'Ramazan bey ile görüştüm. Depolarında 4 adet 16.00R25 BS vardı atlıdan 2 yıl önce almışlar iş olmadığı için takmadık dedi. 2 adet petlas 50.000 dahilden vermiş ayrıca BS kadar çalışma garantisi ve arız yaparsa günlük yövmiyeyi ödemeyi yazılı garanti etmiş, lastikleri gayet güzel gözüküyordu. iş olmadıığı için parkur yatıyordu.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('d48149e3-5653-5b25-8af3-9badc46e97de','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='BİLEK TRANSPORT' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'f41aa512-45b9-5a8b-9756-9d683ff657eb'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-12-11',NULL,'Eyüpoğlu ile çok yakınlardaydılar, Kasım bey ile görüştüm. Pilot alacakmış kumholardan denemesi için 6 adet almaya ikna ettim, 6 adet daha bunları deneyince peşine alacak.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('2ce0313c-ccb9-586f-90d2-1e90a7332ee0','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='SİMGEMAT' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'587a81e8-ba6a-5627-b683-05b4301669b2'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-12-12',NULL,'Makine ikmal müdürleri Emrah bey ile merkez arge binalarında görüştük. 8 loder, 2 kaya kamyonu, 2 greyder var. Biz aktif olarak Hereke lokasyonlarına sadece kaplama yapıyoruz. diğer lokasyonlarda ve yeni taleplerinde yokuz. Emrah bey teknik lastik sunumu yaptım çok beğendi, alım yaparken dikkat edeceğim dedi. ocak ayında gelin tüm park beraber gezelim sizinle kontrol edelim dedi. yeni içinde fiyat soracaklar.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('f41fc7d8-f817-531a-af5c-2dd5ee6b69dd','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='YAPIRAY' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'f625624f-7511-55a1-bbd7-40255d9717b2'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-12-12',NULL,'Kalyonun hızlı tren projesinin betondan ray bloklarını üretiyorlar. Yapı merkezi holding firması tesis müdürü ile görüştüm. 2 loderleri var, 2sinde de kaplanacak lastikler var. Ferdi bey sahada sevkiyat olduğu için haftaya gelip kontrol edip çıkan rapora göre aksiyon alalım dedi.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('8ecfc638-7605-59d6-99f8-a17b85645f10','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='AKDENİZ MANYEZİT' AND il IS NOT DISTINCT FROM 'ESKİŞEHİR' LIMIT 1),'02314292-b973-57f9-9e20-86d2d5886713'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-12-15',NULL,'Hava şatlarından ocak kapanmış satınalma ve formenleri ile görüştüm. En son sordukları lastikleri almamışlar. Yeni sezon için mart gibi gelmemi istediler.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('acd1338f-fd65-5238-95f4-0ed3b3ffc1ff','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ÜNALDI' AND il IS NOT DISTINCT FROM 'KÜTAHYA' LIMIT 1),'56400918-169e-5a15-807d-168bbf168599'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-12-15',NULL,'Mehmet Ünaldı ile görüştüm. 15 loderleri var. Kümaştaki iş bitmiş makineleri çekmişler yatıyordu. Dirpa ile çalışıyorlarmış oradan ayrılan Serkan kendi dükkan açmış ona destek için iş veriyorum dedi. Otr leri alıp bir yerlere kaplatıyor dedi. 30.000TL ye 23.5R25 50mm lastik kaplattı geçen fiaytları da iyi dedi. kaplama için fiyat istedi verdim. bir sonraki kaplamada size de soracağım dedi.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('fe3c35aa-e112-5d7e-8338-13c14e4b1a30','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='YAPIRAY' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'f625624f-7511-55a1-bbd7-40255d9717b2'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-12-16',NULL,'Geçen hafta sözleştiğimiz üzere makineleir kontrol ettim. 4 kaplama ve 1 tamir 20.5R25 tespit ettim. Fiyatları verdim. Forkliftte 2 adet lastik tespit ettim onların siparişi geçtiler hemen. Loderler içinde sonra döneceğiz dediler.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('b5579c21-3d12-5660-8a5a-b806f40bb03a','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='CİHAN GRUP' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'b9536378-e658-5f57-b2b4-a29443342542'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-12-16',NULL,'Bilecikte taş ocakları vardı merkezleri Bursa. Satınalmadan Nisa hanım ile görüştüm bizim firmamızı hatırladı, Lassa tbr alımı oluyormuş eskiden. 15 loderleri var toplamda, kaplama için fiyat soracağız dediler. Ocakları ziyret etmemi istemediler karışıklık oluyor bizden talep gelirse gidin dediler. takip edeceğim','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('e8c8b8c2-6f8e-5712-b924-1fea922ba22c','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ENKA NAKLİYAT' AND il IS NOT DISTINCT FROM 'KOCAELİ' LIMIT 1),'b5a96d7b-2c60-5aa2-a01f-a1b4e91b1587'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-12-17',NULL,'4 adet 18.00-25 Tiron siparişi geçtiler. Cumartesi günü montajını yapacağız. Çeki yazdılar ankara merkezden kargı yapacaklar. 1 makineleri var.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('528978f1-83e2-5df0-b803-5d237b1a01e2','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='KASTAMONU ENTEGRE' AND il IS NOT DISTINCT FROM 'KOCAELİ' LIMIT 1),'8fa145e6-8626-581b-9173-e4389a7aced6'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-12-17',NULL,'Fatih bey ayrılmıştı yerine başlayan Özgen hanım ile tanışmaya gittim. Tesiste kapasite artuşı varmış ilave loder geliyormuş. 4 adet 23.5R25 kaplama işi bizde kaldı, ayrıca oradayeken 2 adet de tamir için anlaştık. Pazartesi günü Turgay alacak lastikleri. Tatko fiyatı referans gösterdiler 10K kadar geri gelmek durumunda kaldık tümünde toplam.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('7c5b6f9b-01de-5282-a7af-081ba481b705','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ÖZKUM MADENCİLİK' AND il IS NOT DISTINCT FROM 'KOCAELİ' LIMIT 1),'952f22f7-298d-5098-bdda-fb51de8a1499'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-12-17',NULL,'Sevan bey ile merkez atelyelerinde görüştüm. Çekimiz hazırdı onu aldım. Yeni aldıkları beton santralimi kontrol etmemi istedi. 2 adet 23.5R25 galaxy lastiğin sözlü onayını geçti, ocak ayında fatura et gönder dedi.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('bdf3bdcd-d218-5766-aa9a-178581bca493','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='SİLTAŞ' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'6b1db3ed-4c45-564b-83b9-af14442e9678'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-12-18',NULL,'2 loderi ölçtüm, 4 kaplama tespit ettim. Vedat beye bilgi verdim. Satınalmaya mail attım teklifi. Takip edeceğim.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('45733c98-ef6d-573d-9acc-94c807c4218a','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='YAZLAR MADEN' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'e5211c2d-765e-5197-bb34-a6f38095a73a'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-12-18',NULL,'Emre bey ile görüştüm. 3 loderleri var. 1 makineleri aşınmış durumda 2-3 aya kaplamaya çıkar onu takip ediyorum. Tatko ile çalışıyorlar.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('8ebc1473-35e4-5897-84aa-ef646b456a1c','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='YAFA İNŞAAT' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'8c43afaf-5ef4-58ce-b3f9-59126920505e'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-12-19',NULL,'Satınalmada yeni başlayan Ömer bey ile tanıştım. 10 loderleri var. Eskiden çalışmıştık. Bursa taş ocakarında kaplanacak 23.5 lar varmış onlar için fiyat verdim. Takip edeceğim.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('c5f8bd26-6b40-5254-b9b6-3f4235829cb2','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='MOLLAOĞLU' AND il IS NOT DISTINCT FROM 'KOCAELİ' LIMIT 1),'9beb5f14-83f2-5c1a-b59f-f09376a1ff56'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-12-22',NULL,'Sinan bey ile görüştüm, yıl sonu ihale yenilenecekmiş bu sebeple bira zişler yavaş dedi. Etis lojsitik çekilmiş onların yerine geçmişler ve onların makinelerinide almışlar. Toplamda 15 loderleri olmuş. Öğle arası makineleri kontrol edeceğim kaplama yada tamir varsa konuşacağız.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('f22a4a74-f740-5fd1-83af-bf8eba177689','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='KOÇER MADEN' AND il IS NOT DISTINCT FROM 'KIRKLARELİ' LIMIT 1),'06ca6e63-bfd5-5942-aab5-6e3c748c19fc'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-12-23',NULL,'3 makinelerini ölçtüm ve hurdalığı inceledim. 3 kaplama ve 2 yeni lastik ihtiyaçlarını tespit ettim. Aydın beye ve formenlerine bilgi verdim. Fiyat teklifimizi verdim.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('2e923144-a7dc-577e-8a9e-f7227d00315a','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='TRAKTAŞ MADEN' AND il IS NOT DISTINCT FROM 'KIRKLARELİ' LIMIT 1),'5ea9cdec-118a-5751-b578-2bf291b5bd2a'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-12-23',NULL,'OTR5 lerin sert olmasından dolayı yananları açmış arıza talebi için çağırdılar. Lastikler 18 ile 25mm arası önleri kaplamaya hemen arkaları sonra almak için konuştuk, fiyatta indirim yapacağım çatlamalar kaynaklı erken sökmemiz gerektiği için dedim. teklifi verdim. yokohama taktığımız makineyi takasa vermişler malesef lastikler gitti.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
