INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('92f59bbc-c189-5bbf-9cb5-55888f6a7e8b','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='DEMİRCAN MAKİNA' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'f77ca7ee-1a5f-505a-a005-608a1822a1e9'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-12-25',NULL,'Ümir Dermircan ile görüştüm, 3 loderleri var lastik durumları iyi. Stoklarında da 2 adet 23.5 kaplama var. Talep olursa haber verecekler.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('a13baf34-c765-5d1d-9866-956350365a8b','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='TEMEL MAKİNE' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'589c9388-0446-5c3c-bd59-84fdcc53beb7'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-12-25',NULL,'8 adet kaplama var takip ediyorum. Temmim bey yoktu telefon ile aradım hastayım sonra görüşelim dedi. Ayrıca 10.00-20 ler için de fiyat verdik.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('4fae1c92-0802-5bc0-9113-d401ead2e730','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='İGA' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'14ea2641-9ef8-5e1d-aa89-2e370afe65ff'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-12-26',NULL,'Kampüslerinde Yılmaz serdar bey ile görüştüm. TBR kaplama için tatkonun fiyatı verdi teklifte bunun altına gir ve bakım atelyeye git onlarada anlat dedi. Bobcat lastiği talepleri vardı fiyat verdim.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('77f71041-8182-59d8-bb24-369b4b5aeff6','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='İGA' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'14ea2641-9ef8-5e1d-aa89-2e370afe65ff'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2025-12-26',NULL,'Lastik formenleri Hayrettin bey ile görüştüm. Marka ve firma tercihinde tek yetkili kendisi. Kaplama için bakacağını söyledi. 35/65R33 taleplerii takip ediyorum Maxam vereceğiz onu anlattım tekrar. 29.5R25 kaplama 8 adet çıkacak talebi takip et dedi.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
