INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('f2ffb132-bfa4-5e2e-8b96-fffdc6258dcb','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='TAŞ YAPI' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'037e0d20-1c9a-5160-8fb2-20989fad43a1'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-01-27',NULL,'Makine ikmal müdürleri Fırat bey ilie görüştüm ve tanştım. Bursada 50 tbr ve 4 otr çorumda 45 tbr kaplama için pazarlığa gitmiştim. Masaya TBR üzeyir ve emre lastik herkül fiyatlarını koydu mecburen rakip fiyatına düşüp işleri aldım. Ayrıca satınalma ofislerine geçip Selma hanım ile de görüştüm yeni konusunda da bize soracaklar. Yokohama sunumu yaptım.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('d48c3945-91d2-51e0-9b72-f84a4ce290da','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='AKBAY' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'9c87bdcb-e0e2-5fa1-96f2-c52a122507ed'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-01-30',NULL,'çek için uğradım fakat gelen çeklerin vadesi uzun olduğu için bize vermek istemediklerini söylediler. Erhan bey hafaya fatrua vadesine uygun çek kesin ayarlaycağını söyledi. Ocak ayı kış sert geçtiği için istanbulda beton dökülmedi bizide etkiledi dedi. satınalma müdürleri Savaş beye uğradım, test kaplamasından bahsettiğim özellikle buradayı seçtiğimizi sattım. çok memnun kaldılar yaklaşımımızdan. tbr kaplama için tekrar girmek istediğimizi söyledim, tbr kaplama için yeniden fiyat atın bakalım elimizden geleni yapalım dediler.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
