INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('bc8c43ab-0c01-5caf-99a7-e52aa9916bfc','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='KİLSAN TUĞLA' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'210a8c6d-5c32-5f75-af69-be8c90eeb4d4'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-02-03',NULL,'Satınalma Murat bey  ile görüştüm, o sırada bakım müdürü ve iş makinelerine bakan formende geldi. 9 forkliftleri var Trelleborg Doğan direkt gelip satıyormuş. 3 lodeleri var. Bizden hiç teklif almadıklarını kibarca söyledim, ama aldıklarını iadda ettiler. iş makinelerinden sorumlu arkadaş yönetim kararı ile michelin harici alım yapmadıklarını ancak bedelsiz 29.5R25 lastik verirsem deneyeceklerini söylediler. Tatko eski personli Kürşat ile çalışmaya devam ettiklerini söylediler. takip edeceğim ama uzaktan.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
