INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('0920731f-655c-54b0-939d-3747200391e3','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='BETONSA' AND il IS NOT DISTINCT FROM 'KIRKLARELİ' LIMIT 1),'eebcf2f1-eb4f-5b30-9c0f-e62310d845c6'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-02-04',NULL,'Bu tesis beton santrali değil, agrega ocağı. Buradaki makinelerin hepsini kapladık durumları iyi. Semih beye uzun süredir uğramadığım için bir ziyaret yaptım. Tesis orman izini yenilenmesi sebebi ile yatıyordu, yakında yine harekete geçecekmiş. kamyonların lastiklerini o zamana kaplamaya planlayacağız.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
