INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('3e350ba8-e198-5b91-acca-d34de0c6cd05','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='MAKTAŞ' AND il IS NOT DISTINCT FROM 'KOCAELİ' LIMIT 1),'1b6504c7-d6cb-5e15-8d9d-1367bdefd8cb'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-02-16',NULL,'Stoktaki 14.00-24 Tironları konuşmak için Zafer beyi ziyarete gittim fakat ayrılmış, yerine bakan Feyzanur hanıma bilgi verdim, servis hizmeti için servis müdürleri ile konuştum. Sonrasında Serkan ile görüştüm konuyu biliyorsunuz, bence Serkanı sizin arayıp Kemal''e birşeyler demişsin gel konuşalım diye çağırmanız iyi olacaktır.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('2e5d0bc3-6922-586f-8ecb-1236d21bf7cc','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='İGA' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'14ea2641-9ef8-5e1d-aa89-2e370afe65ff'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-02-17',NULL,'satınalma Yılmaz bey ile görüştüm, kaplamalar için destek rica ettim ben atelye ile görüşeceğim sende buradan destek at dedim.  Genelde fiyatlarda destek oluyor.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('ac3d69f2-fca7-56bf-9480-c2060e8c7413','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='İGA' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'14ea2641-9ef8-5e1d-aa89-2e370afe65ff'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-02-17',NULL,'Merkez atelyelerine geçtim, Hayrettin bey ile görüştüm. Kaplama için desen gösterdim ve DG kauçuktan çok çalışma garantisi verdim. Yeni gelen kamyonların lastiklerini inceledik beraber OE BS gelmiş hepsi. 26.5R25 L5 alım için BS fiyatını 170K+KDV olarak söyledi.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('d42f92c9-d544-5f60-8bb8-6e24f6598c11','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='GÜLERMAK' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'3a68b16d-1b01-5da5-b2d5-4bd82e850653'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-02-17',NULL,'Ali Ümran bey ile görüştüm, artık yeni müdürü olduğunu onunla da tanışmamın doğru olacağını söyledi. Bünyamin bey ile tanıştım  NTF keşan şantiyesinde çalışmıştık son kötü dönemleri. Çok ortak tanıdık çıktı.  Kademeye gidip bakmamı istedi yanıma birini verdi. baktık %50 diş derinliğindeki lastikleri kaplama için söküp ayırmışlar, diş derinliği ölçümlerini aldım. Bünyamin beye ortada bir suistimal olduğunu kibarca anlattım ben seni anladım sen bunları satınalmaya söyleme dedi beni aldı satınalmaya geçtik, buradan fiyat alacaksınız diye söyledi. Halil bey daha önce çok umursamazken ilgilendi tekliflerine cevap vermediğimi söyledi, bende mailleri göstermesini istedim, karşdeler ulaşım ile bizi karıştırmış beni oranın çalışanı sanmış güya. neyse iletişim kazasını çözdük. takip edeceğim.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('b8eaebb7-cf3a-5f8f-a969-18ca9ce4e091','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ORBİTAL' AND il IS NOT DISTINCT FROM 'İZMİR' LIMIT 1),'f903398c-749d-5f60-a249-43956118257f'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-02-18',NULL,'Barışa yeni fiyatlara geçmem gerek sen şimdiden maden ile pazarlıklara başla diye gittim. Genelde de 2 ayda bir ziyaret etmeye çalışıyorum. 2 adet deneme için ako kaplamayacağız ve takip edeceğiz, olursa kademeli geçiş yapacağız. Diğer mermercilerde Şeref ile olan yerlerde Batman ve robin çetesi ile devam ediyoruz ve mutluyuz ne dersek yapıyorlar dedi.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
