INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('b585eb54-f709-5e9f-84f7-7a1fcf090df2','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa','6028c04f-1f20-4d70-bb91-53414f5ad69d'::uuid,'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-02-20',NULL,'Özakıncı madenin satınaldığı beton santralini ziyaret ettim, buraya gelecek olan makineleri sevindiklide duruyor, o makineyi kaplayıp ayağa kaldırmamızı istediler. Hafta içi müdehale edeceğiz. Tesis yenilendi ve ekipmanlarıda yeniliyorlar, bahar sezonu için beklentileri yüksek. buranın kamyon kaplamasınıda alacağız.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('6817e12d-b45d-5965-ba25-fccf35577e3b','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='KALYON' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'7fc96750-eddb-5840-b7e3-7393fe018052'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-02-25',NULL,'Kademeye gittim, kaplaama için ayrdıkları ve hurda için ayrıdıkları lastikleri seçtim, Volkan da geldi. 42 tbr 3 otr kaplama için seçip aldık.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('e6d95bd5-59f7-534a-8931-2f74e7e7978c','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='DAĞİŞ MADEN' AND il IS NOT DISTINCT FROM 'BİLECİK' LIMIT 1),'5ef3ddc8-2a81-5222-9f0d-ba4ded91ca19'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-02-26',NULL,'Aldığımız kaplamaları teslim etmeden çek talep etmek için uğradım. Genel olarak işleri yavaşlamış. Geçen ay 2 adet kaplamıştık bu ay 2 adet daha kapladık, bunları verince 2 adet daha çıkacak. Çek için muhasebelerinden talep ettiler. Takip edeceğim.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('cabc5f5d-f596-571a-8d96-7bc58be20ed9','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='GÖKYAR MERMER' AND il IS NOT DISTINCT FROM 'BİLECİK' LIMIT 1),'b6013855-562f-5a1c-9a91-bf4c75cefb3e'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-02-26',NULL,'ocağa ölçüm yapmaya öğlen arasında gittim, tüm kamyonları kontrol ettim. Son ömürlerinde olan ve kaplanabilecekler ve hurda lastikler var. Firma sahibi Fatih ve Osman beylere sunum yaptım. 6 adet 29.5R25 Maxam aldılar, bunları ortalara takıp çıkanları kapalayacağız. 450K lık fazladan çeki hemen verdiler. kaplamalar çıkacak nede olsa diye, kaplamalar bir kaç aya yayılacak diş derinliklerinden dolayı.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('2fd664d8-62d0-5b2d-85ce-ebcc8e687fa3','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='MAKİŞ İNŞAAT' AND il IS NOT DISTINCT FROM 'YALOVA' LIMIT 1),'a21ef6d0-8818-5b3d-bb99-c56a62e01ee9'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-02-27',NULL,'Hilmi şef ile randevualaştmıştık ama yine telefonlarımı açmadı ve gittiğimde de yerinde yoktu. Şantiyeden ayrıldım civarda gezerken gölet inşaatı yapan bir şantiyeye rastladım fakat ramazan sonrası açacaklarmış kimse yoktu. Artık razamazan sonrası tekrar deneyeceğim.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('63510b21-48b7-5f1f-b2e5-c44059f917f0','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='MOLLAOĞLU' AND il IS NOT DISTINCT FROM 'KOCAELİ' LIMIT 1),'9beb5f14-83f2-5c1a-b59f-f09376a1ff56'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-03-02',NULL,'Kademelerini gittim, Cuma günü sattığımız 23.5R25 lerin takıldığı makineye baktım. Diğer kademede olan makinelere baktım. Volvo da OE yokohamalar vardı kaplama zamanı gelmişti, formenlerini bilgi verdim, firma sahibi Sinan bey yerinde yoktu onada mesaj attım, yedek lastik ile kaplamaya almaya çalışacağım.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('9e7f4809-3096-5452-9bff-ffbe8ddc52d4','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='CFG' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'6f299b65-c728-5a3d-9194-9c40c6f17a01'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-03-02',NULL,'Çelikler Fernas ve Gültaş ortaklığı metro şantiyesi. Satınalma şefi Erkan beyi ziyaret ettim.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('2fd804bb-a1d5-5af5-989b-d277c7a28da8','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ALTINSOY MERMER' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'48279c3d-5b5c-5a90-843d-3ad62cc13b5b'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-03-03',NULL,'Nurullah Altonsoy ile merkez ofislerinde görüştüm. İşler çok yavaş diye alımları durdurdum dedi, petrol artışı sebebiyle yanımda arayıp yeni taş satmayın dedi fiyatı güncelleyeceğim dedi. Bursada o bölgede taş tutunca afyonlularda ocak açmaya başladı eskiden tek biz vardık şimdi 9 firma olduk rekabetten para kazanamıyoruz dedi. bahar gelip yine ocakları yoklayacağım.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('28d03a1a-e58b-5896-a08d-deb10453c482','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='MUTAŞ' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'4439c57d-53fb-5824-8167-aa23e6e529f8'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-03-03',NULL,'Ece hanım ile görüştüm, kümaşın 2 ocağını işletiyorlardı, birini ünaldı firması almış, tek noktada işleri yavaşlamış. Deneme kaplamalarını söyledim memnuniyetle karşıladılar. Balıkesir balya da kurşun madeni işine gireceklermiş burada yer altı küçük makineler olacak bizim kaplama hacmimize etkisi olmayacaktır. firma baba ve oğul olarak ayrılmış kütahyada krom işi yapıyormış ayrılan firma ama kapalı sistem küçük makine. buralara da denk getirip uğrayacağım.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('8434683f-cd76-5e09-a543-6d027af431c0','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='YAŞAR CİHAN BETON' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'10d74748-80d7-5da2-9338-bb01f9d7dcd3'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-03-03',NULL,'Nisa hanım işten ayrılmış yerine bakan Erkan bey ile görüştüm. Kaplama için fiyat verdim tatko fiyatı ile aynı dedi kontrol edip.  Vadeleri 120 gün Hüseyin çalıştığı dönemde de 120 günmüş Hüseyinden teyeit ettim.  İş makines kaplamada Tatko ile devam ediyorlar ama bize de vermeye başlayacaklar.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('3245c5e5-7413-59ff-819c-2a51df2bb6b9','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='YAPIRAY' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'f625624f-7511-55a1-bbd7-40255d9717b2'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-03-03',NULL,'Ferdi bey ile görüştüm, 4 kaplama ve 1 tamir hala bekliyor. Kalyon işin devamını para olmadığı için devam etmeyeceğinden dolayı tesisin yarısını kars projesine yarısını da afyon merkezlerine çekeceklermiş. Ama makineleri göndermeden kaplamaları yapacağız dediler. Onayını bekliyorum.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('24cc7ef6-7bc6-5d80-bec2-cfecbe9d9cd4','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa','65ff8425-ff58-4dd0-9719-2c6b9153929c'::uuid,'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-03-04',NULL,'2 loder vardı, lastik durumları iyiydi. Yetkili yoktu kart bıraktım.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
