INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('d4d67682-0fbd-5cd8-b704-4710775c49c3','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ERKAY MADEN' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'bb02b48d-b869-523f-b6bf-145ec0769be3'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-03-10',NULL,'yeni satınalmacı Emre ile tanıştım, sürekli fiyat soruyor eskileri sormuyordu. Yine atlıdan devam ediyorlar. Kaplamaları toplu biriktirip ihale yapıyorlar. Takip ediyorum.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('aa62332d-fc61-5af7-a25f-937000cda58e','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='AKK LOJİSTİK' AND il IS NOT DISTINCT FROM 'KOCAELİ' LIMIT 1),'cb782a80-9385-5699-88e5-4ab42142c62f'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-03-10',NULL,'yeni bir konteyner sahası yapıyorlar fakat saha çamur içinde makinenin lastikleri parçalanarak aşınıyor bazılarında darbe katlarına kadar yolunmuş durumdaydı. Firma yetkileleri sahanın 4 ay daha bu şekilde çamur ve toprak olacağını söyledi, çıkmış olan lastiklerini inceledim, bunları aldık, yerine iade olanlar için kendimizden karkas vererek 4 adet 18.00-25 kaplayacağız, bunları özel çekiş tipi bir desen yapacağız, 4 ay sonra saha düzelince 4 adet yeni vereceğiz beton zemin için.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('38f332f8-1f8c-5449-8776-ec01fd7dce97','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='BİLEK TRANSPORT' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'f41aa512-45b9-5a8b-9756-9d683ff657eb'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-03-10',NULL,'Kumhoları tedarik edemedik 55 leri başka yerden başka marka almış. Contilerin ödemesini yapınca parça parça çekeceğim sizden dedi. Hollanda tarafına çiçek taşıma işleri vardı yoğun savaş sebebiyle aksamış, çiceklerin çoğu arab yarımadasında geliyormuş yada gidiyormuş orasına tam anlamadım.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
