INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('d9e73778-80e7-574c-aea5-ede55e6eb27f','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ÇAMSAN' AND il IS NOT DISTINCT FROM 'SAKARYA' LIMIT 1),'42b03df1-58e5-5f97-b641-9773a0c4dfae'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-03-11',NULL,'Jant ve lastik siparişlerinde sorun vardı, hem onu konuşmak hemde kaplama ve yenideki sürekli michelin taleplerini konuşmak için toplatı yaptık. 3 mühendisde katıldı, Sevkan bey, Ali bey ve Hasan bey. Jant ve dolgu lastik konusunu çözdük siparişi geçmişlerdi zaten sevkini yapacağız. bizden benim bakmadığım dönem aldıkları maxamlardan performans alamadıklarını söylediler, ayrıca kaplama fiyatımızın da çok yüksek olduğunu söylediler (kaplama da da ben hiç teklif vermedim). yeni lastik michelinde 23.5R25 5 loderleri var, min. 9000 saat gördüklerini, tatko kaplamada da 7.000 saati gördüklerini söylediler. içeride BKT L5 deniyorlar ayrıca. L5  uygun olmadığını söyledim. ben Yokohama teklif edeceğimizi söyledim. OE bir makinede gelmiş ve memnun kalmışlar fakat en son XHA2 alım fiyatları 106.000TL+KDV bizim yokohama koşul 120+kdv. 10.00-20 tiron çok satıyorduk ama çok patladığı için artık almaycağız dediler. başka marka teklif etmemi istediler. onlar subaşından micehlin almaya başlamışlar. kaplama ve yeniler için fiyat teklifi istediler. güzel bir toplantı oldu, yokohama almaya sıcaklar, fakat kaplamada premium hamurda fiyat tutmuyor diğerinde o saat için bir kerelik deneyeceğim.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('d168bbb8-77df-5434-b897-095557869cc2','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ŞİLE MADEN' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'080c3745-36e5-5786-a9d9-61b33c072824'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-03-12',NULL,'Fatih bey ile görüştüm, burada işleri oldukça yavaş makineler yatıyordu, aldığı sailunlerden hiç memnun kalmamış, kelly ile devam ediyorum dedi. Beni eskişehirdeki diğer firmaları olan karakaya beton ve koçkaya madene yönlendirdi o tafa geç beni ara sana kontak vereceğim oaraya ben bakmıyorum dedi. takip edeceğim.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('7e04a5ce-5260-52a0-8abd-51cac2ec9382','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ÇELİKTAŞ' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'fb36c3b1-d182-51c5-af48-37b775ac2c3a'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-03-12',NULL,'Mühendisleri ile görüştük, satınalmanın fiyat sormadığını söyledik, Hülya hanımda bir pirellie takıntısı var gidiyor dedi. Ama otr hiç çıkmadı haber ederim size dedi. Hülya hanıma yine bizden her alımda teklif alması için hatırlatacak.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
