INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('9568d923-5776-5094-aa7c-6e2953c2d098','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='DEMİRKOÇ MADEN' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'80fb47f3-0f26-5139-bb22-baf931ef6ea4'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-03-12',NULL,'Kumsan taşeronu, işler yavaş olduğundan makineler yatıyordu. Sailun teklif ettik deseni beğendi az miktar alıp deneyceğim dedi, depoya gittik stoğu vardı. 26.5R25 alınacak ama kumsan üzerinden dedi bende Kerem bizden almıyor bize sormaz bile dedim, ben Kerem ile konucağım sizden teklif aldıracağım dedi. kaplamada da bize yokuş yaptığını söyledim, o risk alamıyor ben biliyorum konuyu konuşacağım sizin ile ilgili dedi.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('1f0fb8e4-58d6-50bd-8ce6-23063f78aab9','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='AKBAY' AND il IS NOT DISTINCT FROM 'SAKARYA' LIMIT 1),'7853b190-84a8-5581-9fe4-4f23f96260fa'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-03-16',NULL,'makineleri kontrol ettim 2 adet daha 29.5R25 kaplama tespit ettim. Bizdeki son 2 bedelsizleri takıp bunları alacağız, birkaç aya 2 tane daha var takip ettiğim. Şaban şef deneme kaplamalarını omuzlarını hiç beğenmediğini söyledi, bende denediğimizi ve takip ettiğimizi söyledim.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('7459a6a0-5b80-56b4-a316-33e0dd7f359d','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='KAPTAN DEMİR ÇELİK' AND il IS NOT DISTINCT FROM 'TEKİRDAĞ' LIMIT 1),'561a7a86-5b44-5862-b785-74ee3e72de92'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-03-17',NULL,'Ertan bey ile görüştüm, çıkmış iş makinelerini inceledik, hepsinde sayısız demir çelik hurdası kaynaklı batık var, kendileri kademelerinde soğuk yama atıp gümletene kadar devam ediyorlar, kaplama için ayırdıkları lastiklerin birinde üst üste 3 yama gördüm. 1 tanesini kaplama için alabiliriz. yeni lastikte BKT ve Petlasa dönmüşler tamamen. kamyonda goodyear ile devam ediyorlar. L5 kullanmalarının faydalarına olacağını söyledim. Ertan bey burada satınalmanın bir etkisi olmadığını söyledi, bende teknik kısıma gidip anlatayım dedim. bu seferde teknik kısımında yetkisi çok yok gibi konuştu.  genel olarak çok top çevirdi ve ne yapsan buraya giremezsin mesajın verdi. bayram sonrası için bana teknik kısımla bir görüşme ayarlayacağına söz verdi. takip edeceğim.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('73181033-c901-584f-82a8-1a6109c1a8ad','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='GÜLERMAK' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'3a68b16d-1b01-5da5-b2d5-4bd82e850653'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-03-17',NULL,'kaplamaları takmışlarsa çıkanları son teslimatta alalım diye uğradım ama kademeyi komple bayram tatiline göndermişler. Lastikleri de takmamışlar. Teslimatı 27 sinden sonrasına istediler. Müdürleri Bünyamin bey ile görüştüm, proje 4 yıl daha sürecekmiş.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
