INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('7454f9f2-cbd9-5d78-b12e-d8d5e5da0077','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='CFG' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'6f299b65-c728-5a3d-9194-9c40c6f17a01'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-03-26',NULL,'Erkan bey yine telefonlaşmamıza ve mesajlaşmamıza rağmen yoktu, bekle geliyorum dedik 2,5 saat sonra geldi, çok özür diledi, kaplama ihalesini yanımda makine müdürüne beni tanıştırıp imzalattı, burası çeliklerin bölgemizde kaplamasını aldığımız 2. şantiyesi oldu. 4 adet daha yeni istasyon işi almışlar 4 yıllık daha işimiz var dedi. beraber metro şantiyesine altunizadeye gittik lastikleri inceledik. çıkan tüm kaplamaları alacağız. bu firma için 3 ziyarette toplamda 6 saaten uzun süre ofislerinde bekleyerek mesleki bekleme rekorumu kırdım.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('a36b56d0-9d9d-542e-9d53-d76c7448f5e8','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='AKBAY' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'9c87bdcb-e0e2-5fa1-96f2-c52a122507ed'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-03-30',NULL,'Çekimizi almaya gittim, Tatko bu ay için de hiç gelmediği bu şantiyeye 3 kez farklı ekipleri ile gelmiş, kamyon ekibi ayrı iş makinesi ekibi ayrı gelmiş. Kaplamada en ucuz fiyatı vermişler, OTR de aramızda 20K da fazla fark var lastik başı biz buraya premium listeden esnemeden yapıyoruz. Fakat kayyum dönemi Tatkonun onlara mal vermemesinden dolayı asla çalışmayacaklarını söylüyorlar. TBR kaplama için uzun süredir baskı yapıyorum, Savaş bey kayyum dönemi ishakoğlu bize çok destek oldu şimdi onların zor zamanı biz onlara destek olacağız dedi. tüm iş makinelerinin kaplama ve yeni olarak yeniledeğimizi bu yıl pek hacmimizin olmayacağını söyledim, Savaş bey TBR yeni alır sizin ciroyu korurum sizinle çalışmak istiyoruz dedi.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('d4e257a4-b50b-50b3-8e7e-71873d5a16fe','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa','6028c04f-1f20-4d70-bb91-53414f5ad69d'::uuid,'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-03-30',NULL,'Marmara dolamit, öz akıncı ve akc beton olarak hepsi artık arnavutköye ofis olarak taşınmışlar.  Hayırlı olsunda gittim. Takip ettiğim 4 23.5 talepleri var onuda dürttüm ama muhammed bey şuan makine yatıyor çalıştırınca yapacağız diye yine erteledi. Atlı burada daha da yakından takip ediyor firmayı.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('7e7945d9-7303-5d7c-b69c-46578772ba2b','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='MOLLAOĞLU' AND il IS NOT DISTINCT FROM 'KOCAELİ' LIMIT 1),'9beb5f14-83f2-5c1a-b59f-f09376a1ff56'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-03-31',NULL,'takip ettiğim 4 adet 23.5R25 var, Sinan beyi onunla iligli sıkıştırıyorum. Fiyatı verdim bakarız dedi. Bir kaç kere daha sıkıştırmam lazım Sinan abi son ana kadar hep zorluyor. Diğer taşeron çıkmış limandan 15 loder ile tek yüklenici Sinan abiler kaldı. takip ediyorum.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('aeb6621e-c76f-53df-8e01-39857c445000','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='METGÜN' AND il IS NOT DISTINCT FROM 'KOCAELİ' LIMIT 1),'63306f31-0787-5e89-afb9-37adc7ac92f2'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-03-31','YILDIRAY BİLEN','23.5R25 talepleri için Yıldıray beraber gidelim demişti. Satınalmayı ziyaret ettik cahit beyi, ben sizi makine müdürümüz ile tanıştırayım o finalde karar veriyor dedi. Barış beyi davet etti. Barış bey beni tanıdı, Soner temel de beraber çalıştık kaplamaları bize veriyordu. güzel bir görüşme oldu. Barış bey çıkarken bana göz kırptı tamamdır dedi.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('363111ca-210b-54a9-b09a-659a8aabf0ea','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='GÜLERMAK' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'3a68b16d-1b01-5da5-b2d5-4bd82e850653'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-04-07',NULL,'Satınalma fatualarda yanlışlık var diye itiraz etmişti, Halil beyi ziyaret edip açıkladım sorun olmadığını gördü, bundan sonra net fiyat gösterin isk istemiyorum dedi. Ayrıca teknik kısım ok derse bundan sonra bana sormadan ne çıkarsa bu fiyatlardan alın kaplayın dedi. teknik kısıma uğradım Bünyamin müdür yoktu yardımcısı ile görüştüm, cuma günene araç organize ettik. 15 de bir araç sabit gelecek.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('60a4e024-f6a1-5a1b-a2de-5e669f767bee','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='İGA' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'14ea2641-9ef8-5e1d-aa89-2e370afe65ff'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-04-07',NULL,'Satınalmadan Yılmaz bey ile görüştüm, 26.5R25 L5 talepleri vardı, eski fiyattan aynı yerden bağladım dedi. Gürlastan aldığını söyledi, fiyatı kontrol ettim %2 marjla vermişler,bende revize teklif attım. Artık BS tarafında yeniden olduğumuzu söyledim.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('7b2ad0b7-8517-5c39-b9dc-2c0cf6810b93','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='İGA' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'14ea2641-9ef8-5e1d-aa89-2e370afe65ff'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-04-07',NULL,'mühendisleri Hayerettin bey ile görüştüm, kaplamalarımız sorun çıkarmadan çalışıyor. 26.5R25 L5 için bizimde fiyat verdiğimzii söyledim, en son alımını net fiyatını bana söyledi.%2 marja geliyor. Fakat kendi talebi VSDL iken Yılmaz bey VSDT almış bunu benimle sorgualrken fark etti ve çok bozuldu, benim dediğimi almamış bize kazık atmış diye söylendi. ilk zamanlar Yılmaz bize destek Hayrettin ve Adem köstek iken şimdi tam tersi oldu durum. Hayrettini daha sıkı takip edeceğim.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('c740e2b9-1f13-5948-9049-c31efcc7b57b','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='MADEN FUARI' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'734681fe-dfe9-52a4-9f7a-2c29b7aed915'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-04-08',NULL,'Tüyap maden fuarına gittim, Nuh stant açmıştı, Asten jant, Kolpaş ve Solaksubaşı vardır. Berk ve Mustafa abi stant açmıştı. Kontağım olanları ziyaret ettim.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('f6182d5b-a731-57fe-bdc4-a57ba8867c89','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='KALYON' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'7fc96750-eddb-5840-b7e3-7393fe018052'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-04-09',NULL,'Serkan abi ile görüştüm, hurda analizini sundum, genel sohbet ettik, BS konunusu söyledim, alımlarda destek istedim. Mühendisin periyodik olarak gelip ölçüm yapmasını ve kendisine raporlamasını istedi, bu ay başlayacağımızı söyledim.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('22dc91c2-56e3-5b87-9b64-915200d3d2f7','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='GEMPORT' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'af25b190-5cbd-5638-b7d1-25bf979e0e5b'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-04-09',NULL,'Halit bey ile görüştüm, uzun süredir görüşemiyorduk. BS konusunu söyledim, çoğunlukla GY alıyorlar subaşından. Talepleri vardı teklif verdim.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('5e4db6e4-d527-5969-ad56-b3958a85824b','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ÖZERLER MERMER' AND il IS NOT DISTINCT FROM 'BİLECİK' LIMIT 1),'eecd4c87-2af2-5112-8469-6ae92bc14e8c'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-04-10',NULL,'Serdar bey buradaki 2 lastiği incelememi istemişti, fakat gittiğimde lastikleri mermer ocaklarına sevk etmiş olduğunu öğrendim, ocakta lastikleri kontrol edeceğim.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('d1abb468-0a5c-57b3-a45f-07c9adc3ded3','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='DAĞİŞ MADEN' AND il IS NOT DISTINCT FROM 'BİLECİK' LIMIT 1),'5ef3ddc8-2a81-5222-9f0d-ba4ded91ca19'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-04-10',NULL,'Çeki talep ettim son kaplamaları teslim ettik. Kamyon kaplamasına da talip olduğumuzu söyledim. Günmarlas 4.500TL den kripto yapıyor. Sizde fiyat verin dedi. Kamyon yenisinden bu ay alıma çıkacaklar bizdende fiyat istiyecekler.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('af33dc13-7640-5bad-90fb-6f90b73de668','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='KASTAMONU ENTEGRE' AND il IS NOT DISTINCT FROM 'KOCAELİ' LIMIT 1),'8fa145e6-8626-581b-9173-e4389a7aced6'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-04-17',NULL,'Yeni mühendis Deniz bey ile tanıştım, kaplamalar için Tatko bizim ucuz fiyatında altına girip işi almış, en son biz almıştık, bu sefer fiyat önemli değil demişler. Ayrıca satınalma ile de konuştum, abi bu sefer çok ucuzdular mecbur oraya verdim, sonrakine söz sana vereceğim dedi. preslenecek lastikler vardı, onların işini aldık tesiste presleyip teslim ettik.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('64d6351e-e8bb-58e1-9efa-73c60b263685','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='SAFİ PORT' AND il IS NOT DISTINCT FROM 'KOCAELİ' LIMIT 1),'ba5f7956-d60c-5c8f-ac7c-0c25d7087e0a'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-04-17',NULL,'Buse hanım ve müdürleri İsmail bey ile görüştüm, İsmail bey kordsadan yeni gelmiş bizi çok iyi biliyor. Buse hanım satınalma olarak hiçbir yetkimiz yok tüm alımları toplayıp direkt olarak Hakan Safi beye sunuyoruz en küçük şeye bile o kendisi karar veriyor dedi. sizin içinde bizi aradı ve ilgilenmemizi istedi ama hep böyle şeyler oluyor ve en ucuz olmadıkça işi vermiyor dedi. bu ziyaret sonrası uzun telefon pazarlıkları sonrası kaplama işinin tamamını aldık.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('f701c138-b60b-5a02-979c-a629d05c9f5b','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ATLAS TERSANESİ' AND il IS NOT DISTINCT FROM 'KOCAELİ' LIMIT 1),'2bdc7e98-8a86-5d3f-acde-d0715e6a725c'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-04-20',NULL,'Yılport eski kontağım Alper bey burada ve işlerini yapıyoruz. 29.5-25 kullanann  mobil vinç için talep vardı. Sahada inceledim, 2 yeni ve 1 tamir olarak tespit ettim. Fiyatları mail olarak attım. Takip ediyorum.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('6bf3f793-b58d-54bf-af54-d520fa1bda89','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='MARMARA DOLOMİT' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'e85da4c2-2e58-52b8-8124-0f1a0017beff'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-04-21',NULL,'Sevan beyi ziyaret ettim, çekimizi aldım. Kamyon kaplamaları için fiyat verdim. Yakın zamanda loder lastiği talepleri olacak takip ediyorum. Sevan bey eskiden Koçer madende çalışmış benimle oraya giderek orası ile görüştürdü.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('05eca95a-324e-5866-98e7-b63bde5088b6','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='KOÇER MADEN' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'317f101f-eed0-5890-86c6-3ddec3348828'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-04-21',NULL,'Sevan bey ile kum ocaklarını ziyaret ettik. 2 loderi kontrol ettik, 2 adet .29.5R25 kaplaamyı aldık. Diğer loderin lastiklerini de takip edip alacağız. 2 adet de 29.5R25 yeni ihtyaçları olacak onlar içinde fiyat verdik.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('9c9b67b3-4d0a-507a-9df7-1b5c0c024de2','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='TAŞ YAPI' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'037e0d20-1c9a-5160-8fb2-20989fad43a1'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-04-22',NULL,'Sürekli telefonda görüştüğüm Özden hanım ile tanışmaya gittim, kıbrıs havalimanı, çorum, bursa ve konyada raylı sistem işleri var. Konya ve Kıbrıs ile Özlem hanım ilgileniyor, oraların kaplamaları için görüştük. Çorum için Selma hanım ile görüştüm, çıkmış kaplamalar vardı, onay için haber bekeleyin Fırat beye soralım dediler. ben Fırat beye de selam verdim, Çorumu aldın mı dedi onay verecekmişisiniz dedim al sen verdim dedi. yeni için bize sormuyorlar dedim talimat verdi bundan sonra soracaklar dedi, Kıbrıs kaplama ve yeni konusunu konuştuk, sen bir fiyat ver bende düşüneyim olabilir kaplama orada daha 2 yıl işimiz var dedi. tüm kaplamalar sende takip et dedi.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('ac5467ae-9f2f-5c0c-b54f-8ca9f2988e6b','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='MARUBENİ DAĞITIM' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'2f2a5b8b-2c9a-562e-9f00-aeee24b4e6d6'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-04-22',NULL,'Serdar abi ile görüştüm, 8 adet yeni taleb sormuşlardı gelişme var mı dedim, izmirin işi onu merkeze sor dedi. Merkezde kontağımız Cihan işten ayrılmış, Berfu devam ediyormuş, Berfu biraz ilgi istiyor cihan izindeyken bize iş vermemişti. Merkeze plan yapacağım. işleri genel olarak yavaşlamış, şuan bizlik bir talep yok','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('168f709c-06c5-58cf-bc4c-4ceebe5ffb60','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='EMAY ASFALT' AND il IS NOT DISTINCT FROM 'KOCAELİ' LIMIT 1),'669dc990-cb93-5edf-8dae-f7f040897a39'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-04-24','ADNAN KARAKAYA','Yunus formene uğradık, 20.5R25 kaplamaları takip ediyoruz fiyatımızı verdik.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
