INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('f3180afa-990a-5cda-901c-9c05a39f1f08','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='AKIŞIK ZAHİRE' AND il IS NOT DISTINCT FROM 'TEKİRDAĞ' LIMIT 1),'4efc1ab1-25d2-51d1-b336-63464058a2ec'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-05-06',NULL,'Akçasanın taşeronluğunu yapıyorlar, mikserleri satmışlar sadece loderleri kalmış. Loderlerini konrol ettim, daha öncede biz kaplamıştık. 2 adet kaplama için fiyat verdim. Değerlendirip bize dönecekler. Bölgedeki diğer firmalar hakkında iyi bir sohbet yaptık, bilemediklerimin iletişim bilgilerini aldım.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('481e3489-b23b-50b0-a547-b65a7ba24318','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='AKÇANSA' AND il IS NOT DISTINCT FROM 'TEKİRDAĞ' LIMIT 1),'acbb04ab-2861-52de-a722-b9fe8234c04d'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-05-06',NULL,'Alican bey yoktu formen Erdal ile görüştüm, Akışık mikserleri satınca 10 adet mikseri kendileri almışlar, bunların kaplaması ve yenisi için görüştük, şuan ekipmanlar yeni durumda. Takip edeceğim.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('685ccd68-1c5b-58a5-a3f7-b54b8fdb0a81','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='AKÇANSA' AND il IS NOT DISTINCT FROM 'YALOVA' LIMIT 1),'dd12a9dd-11e5-579c-992b-b0b72a987902'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-05-07',NULL,'Ege bey ile görüştüm, en son ziyaretimde işler çok kötü diyordu, şimdi yetiştiremiyorum ilave ekipman talep ettim o kadar çok işim oldu dedi. 2 adet 315/80R22.5 kumho ve 1 adet jant verdik, yedek tutacak. Faturalarını 20k altı onaya takılmadığı için 3 e böldük. loderin lastiklerini biz vermiştik şuan iyi durumda arkaları takip ediyorum vakti var yeni vereceğiz.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('ea30fdb1-5ec7-598d-95d0-7b9156bb88cc','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='NUH BETON' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'8506786f-8c17-5865-8cb0-1825d0274c34'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-05-07',NULL,'Ahmet formen ile tanıştım, 2 loderleri var, 1 tanesini Yalovaya yeni açacakları tesise göndereceklermiş ayırmışlar, bu makinenin arka 2 lastiği hurda durumda yeni almaları gerekiyor. Diğer makine OE yokohama 4k saate devam ediyor, az az hava kaçırıyor sağ ön dedi, kontrolde demir batık buldum, tamire alacağız. kamyonları da size veriyorduk ama bir sorun yaşanmış artık size vermemize söylediler en sonları başka yere verdim bilginiz olsun dedi. Yıldıraya bilgi verdim sorun yok dedi.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('861cdfd7-3a8e-52de-905f-1bff3b167faa','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='AKÇANSA' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'47733cbb-48c2-5e3a-8371-20cc9d447a74'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-05-07',NULL,'Merkezden Cahit bey kaplama için loderi kontrol etmemi istemişti, kontrol ettim. Kaplama zamanları yaklaşmış, burdaki formene bilgi verdim, teklifi atın bakalım dedi. Teklifi verip Cahit bey ile takip edeceğim.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('93b45fc2-6b65-5180-b58c-cdf899f2abd3','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='TEKNİK GRUP MAKİNA' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'d4e73838-74a2-55dd-8dc4-03a00775d391'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-05-07',NULL,'Marubeni bayisi eskiden çok iş yapırduk forklift olarak, Serdar abiden burası için kontak alıp gittim, müdürleri Talip bey ile tanıştım. Bizi hatırladı lastik işine girmiyorum artık dedi, bende teşvik edici yönde konuştum , otr de servise gelenlere teklif ver dedim. ilgileneceğim dedi. ben daha çok uğrayıp servise gelenlerin makinelerinde firma öğrenme niyetindeyim. gelip gittikçe bilgi alacağım.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('31084535-ad71-5145-9915-74e490c9cf22','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='SİMGEMAT' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'587a81e8-ba6a-5627-b683-05b4301669b2'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-05-07',NULL,'Makine müdürleri Emrah bey ile görüştüm, nakliye kısmından çıkmışlar kamyon sayıları azalmış bayağı, 30 altına düşmüş totalde, burda 10 tane var. Loderleri 5 tane ve aktif. Lassa tbr teklif almalarını rica ettim, satınalmayada bilgi verin dedi. Mustafa beyi arayıp bilgi verdim randevu istedim merkez ofiste olduğu için görüşemedik haftaya bakacağız. en son 26.5R25 yokohama alımında satınalmanın biraz almak istemediğini kendisinin baskı ve onayı ile aldırdığını söyledi. avrasya tünelinin asflat yenileme işini almışlar ona hazırlanıyorlar.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('f3d6f166-6f78-5b63-bc2e-21a7c1a46eca','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='OSMAN DEMİR' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'04c8103b-6b4d-5531-b8a5-2c4e6f31d982'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-05-07',NULL,'Buraya her geldiğimde görüyordum bugün uğradım, loderleri yok sadece 32 kamyonları  var agregayı simgemat tan alıp satıyor ve taşıyorlar. Günmarlas ile aktif çalışıyorlar, kaplama kullanmıyorlar. Süleyman bey iletişim bilgilerimi aldı, lastik talebi olunca soracak.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('c00fe743-2fa9-50c5-9cbd-d7638c61769d','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='CANTÜRK' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'3637bb44-0194-5504-9fd1-1381b4b2a71b'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-05-07',NULL,'Başköydeki diğer sahayı işleten firmar, toplamda 6 loder ve 25 kamyon var, firma sahibi Servet bey ile görüştüm. Günmarlas ile aktif çalışıyorlar.ekipmanları çok eski durumdayı sadece 2 loderleri aktifti. Genel izlenip çok olumlu değil gibi fakat saha aktif satış yapıyor. kaplama için fiyat vermemi istediler oğluna mail atacağım.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('441a089c-5557-5762-b1e4-73aab52bd08b','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='BİLİM MAKİNA' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'8cc76682-4b6b-547e-a1f1-179f9ecf9f3a'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-05-07',NULL,'ihsan Bilim ile görüştüm, vezir çimento içinde kamyon ve lodeleri var. Bizi hatırladı, güncel bir kaplama ve binek talebi varmış mail attı. Sorduğum soruların çoğuna cevap vermedi, yoğundu ekrandan bana bakmadı. Takip edeceğim, potansiyeli olan büyük firma.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('a8bc7308-6433-5e65-890b-97a9b026ac7d','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='MOLLAOĞLU' AND il IS NOT DISTINCT FROM 'KOCAELİ' LIMIT 1),'9beb5f14-83f2-5c1a-b59f-f09376a1ff56'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-05-08',NULL,'Makineler işe çıkmadan 6 tanesini yakaladım , 2 adet daha kaplama tespit ettim. Sinan abi yoktu, hafta içi uğrayıp diğer 4 ve bu 2 için tekrar konuşacağım.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('23337829-bb7e-5251-8349-6b282d333138','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa','8b1ab4be-de03-4a62-a51b-249550f385e3'::uuid,'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-05-08',NULL,'Satınalma uzmanı Murat Meriç ve müdürü Murat Sağır ile görüştüm. Müdür biraz tavırlıydı ilk başlarda, kısa bir özet yaptım bizim hakkımızda, sizi iyi biliyorum fakat siz bize kaplama teklifi vermiyorsunuz dedi. Bende bilgisayarımı açıp gösterdim, Murat Meriç 2026 yılında hiç sormadı, 2025 de de şartnamedeki bilgileri vermedi dedim, mailleri gösterdim. Meriç ağladı, kekeledi, ben istedim teknik kısım vermedi dedi, müdür sizin teknik kısım ile iyi görüşemeniz gerekli dedi. bende orası ile hep görüştüğümüzü tek yetkili sizin olduğunuz için birşey yapamayacaklarını söylediklerini söyledim. biz burası için çok mücadele verdik diye bedelsiz 29.5 konusunu söyledim, benim haberim yok, teknik kısım alıp bize söylememiştir dedi, bende satınalmanın haberi vardı ürünleri zaten sözleşme ile verdik dedim, 26 yıldır buradayım olsa benim haberim olur dedi, bende 17 yıldır nuh ile ilgileniyorum o zamanki satınalmadaki tüm muhataplarımıza söyledik, onlar size akatarmamışsa buna birşey diyemeyiz dedim, bunun üzerine ajandasına not aldı ve yutkundu. ayağa kalkıp hemen kemal beyden kaplama için fiyat alıyorsun, diğer tüm birimlere de veriyorsun numarasını dedi, beni kaydedip çaldırdı, bundan sonra ben sizi bilirim, en ufak şeyde ararım dedi. Beton içinde oranın yetkililerine telefon açıp bilgi vereceğim herşeyi soracaklar dedi.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('230b9180-88c4-5f1f-8dc4-6b425cdf2a26','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='CLOVER DEPOLAMA' AND il IS NOT DISTINCT FROM 'KOCAELİ' LIMIT 1),'82ebe3c6-95c2-557d-b680-c2710da1d6a6'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-05-08',NULL,'Adnan''ın eski kontağı olan Aziz bey burada ortak olarak işe başlamış, 4 tane stacker var bunların durumlarını kontrol etmiş Adnan daha önce fakat saha şartlar öneri için benimde gelmemi istedi. Derincedeki 2 makinenin birinin 4 kaplamaya ihtiyacı var, diğerinin 2 kaplamaya ihtiyacı var, lastiksan üzerinden ovakente kaplama yaptırmışlar lastikler dökülmüş pullanarak 15 günde bitmiş 2 lastik. yerine karkaslı kaplama almışlar onlarında durumu benzerdi, hurdalıktaki 3 lastiği inceledik 1 tanesini kaplama için ayırdık. lastik havaları çok düşüktü. ovakentin kapladığı desende makine için hiç uygun değildi. Yetkili Aziz bey burada yokmuş bilgi vermek için aradık, bizi gebze lokasyonlarına çağırdı.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('461e232e-b213-5a94-bf81-6c35757530e0','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='CLOVER DEPOLAMA' AND il IS NOT DISTINCT FROM 'KOCAELİ' LIMIT 1),'82ebe3c6-95c2-557d-b680-c2710da1d6a6'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-05-08',NULL,'burada da 2 makineleri var, 1 tanesi iyi durumda, diğerine 2 adet yeni ve 2 kaplama lazım. Aziz bey bu firmanın ortağıtmış, Fevzi Kocaman ile ortak kurmuşlar firmayı, Fevzi Kocaman bu işlerde bilenen biri. Gemport içinde de 2 makineleri varmış. Aziz beye durumu aktardım, lastiksan ile arızalar yüzünden tartışıyoruz olumlu bir geri dönüş alamadım, lasitkleri söküp kapılarına atacağım en sonunda dedi. lastiksanın kendisinin kaplamadığını ovakente kaplattığını söyledim. 4 yeni alıp derincedeki makineye takıp oradan çıkanlar ile kaplama döngüsünü başlatmalarını tavsiye ettim. Aziz bey bizi iyice dinledi, makinelere çok para harcadım durumumu toplayayım dediğiniz gibi yapalım dedi, lastiksandan garantiden lastik alırsamda çıkanları yine siz alın kaplayın dedi.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('4109fb41-266c-5248-a358-9bf7f300e4f3','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='NRC' AND il IS NOT DISTINCT FROM 'KOCAELİ' LIMIT 1),'bd71978a-040a-5ec2-98ed-5bc0c1dbbbd9'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-05-11',NULL,'Kapladığımız lastik omuzdan 30cm kadar açma yapmış, çöp içinde sürekli malzeme girmesi sonucu büyümeye başlamış. Yedek lastik takıp sökecekler, dolgu tamiri ile kurtaraibliriz, diş derinlik seviyes %50 üzerinde. Diğer Yokohama L5 olan makinenin lastiklerini kaplamaya almışız çok yakında ben kontrolde farkettim, makine yeni geldiğinde 300 saat civarı iken biz L3 leri söküp takmıştık, formunu ofiste olduğu için bulamadım. 3.750 saat civarı çalışmış ve kaplamaay almışız, kaplarken bilgim olmamış zincir altına çekiş tipi boş desen kaplamışız, müşteri zincir ortası dolu kapladıklarımızda tutunmadığı lasitk içinde döndüğü için istemiş, ortası dolu fakat çentikler geniş olarak bundan sorna yapacağımızı söyledim, Adnan abidende bu şekilde devam etmemizi rica ettim. Adnan L5 lastiğin L3 ten 3 kat fazla çalıştığını anlatacak, yedekleri yok yeni olarak L5 alımları olması olası. 4 adet de 2. el aldıkları makine üzerinden çıkan lastiği inceledik, fazla batık olduğu için tesiste inceleme sonrası raspa iade şartı ile bakılacağını söyledik, lastikleri aldıracak Adnan abi.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('a1c0fea7-ab45-5121-8d4a-aff4c969ec5a','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ÇALIŞKAN MADEN' AND il IS NOT DISTINCT FROM 'KIRKLARELİ' LIMIT 1),'4e8729e0-240e-5bb4-ace6-4861fc0d67d7'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-05-12',NULL,'Kaya abi ile geçen hafta Çorlu ocaklarının ölçümü sonrası bu hafta buluşalım diye konuşmuştuk, çorluya 2 adet 26.5R25 lazım. Burada da saha çalışması yaptım, 2 adet yeni 26.5R25, 2 adet kaplama ve 2 adet tamir tespit ettim. Ayrıca kamyonları da ölçütüm onlarda da yaklaşık 45 güne kaplamaya çıkacak 315/80R22.5 ları tespit ettim. hepsini Kaya beye ve formenleri Ramazan beye aktardım, hatta ölçümün bir kısmını Ramazan bey ile beraber yaptık. Kaya abi 4 adet 26.5R26 L5 Yokohama için 1K lık bir çek var patronda onu alayım sana haber edeyim gönder lastikleri dedi. ama süreç bayramı geçebilir dedi. sonrasında kaplamalara başlarız dedi. sözlü olarak 4 adet için anlaştık fakat son final onayını patronlarından alacak.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('290915da-cfd0-5978-8197-2893290a3380','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='KALE MADEN' AND il IS NOT DISTINCT FROM 'EDİRNE' LIMIT 1),'a9a81c65-5312-54fb-ba65-0ecdddb0a6fc'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-05-12',NULL,'Aslında pınarhisar, vize tarafında takılacaktım ama Orhan bey beni arayıp çağırınca Edirneye geçtim. Eski Brisa bayisi, kömür madenleri, tuğla fabrikaları, un fabrikaları ve petrol istasyonları var. Ben en son bayilikleri varken uğramıştım ve lodelerini kaplamştık. Lastik işini ve kömür madenini kapatmışlar. 2 loderi kontrol ettim, bir tanesi bizim kaplama çok memnunlar. diğer loder 15K saate kaplama zamanı gelmiş. fiyatı verdim yarın sana dönüş sağlayacağız dediler. 4 adet 23.5R25 takip ediyorum.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('9a2c1558-4397-54ca-a948-485d4cf96605','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='TRAKYA TUĞLA' AND il IS NOT DISTINCT FROM 'EDİRNE' LIMIT 1),'0e86432c-9c56-5eaf-8e3d-e1e0a95eca54'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-05-12',NULL,'Yol üzerinde görüp uğradım, 3 lodeleri var, 2 si eski 1 tanesi yeni. Yeni makineyi kullanıyorlar. Eski makineleri sıfırlamışlar yatırıyorlar. Tüm makinelerin lastik durumu iyi. Kendi nakliyelerini yapıyorlar 20 tırları var. Tır lastiği alımı içinde fiyat soracaklar. arada geçerken uğrayıp takip edeceğim.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('a501ddf2-614c-56e4-8763-5736524225e6','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='SERİN BETON' AND il IS NOT DISTINCT FROM 'EDİRNE' LIMIT 1),'fed03cda-c88f-5e6c-9473-e8f045df6f11'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-05-12',NULL,'Kırklarerlindeki kademe çavuşları Şirin usta ile her gittiğimde görüşüyordum ama yol alamıyordum, ana merkezlerine uğradım. Halit bey ile tanıştım, tüm tesislerin ve ekipmanların bakım ve satınalmalarından sorumlu kişi. 6 tesisleri var toplamda, 10 loder ve 100 e yakım kamyon, mikser grubu var. OTR yenide Tatkodan BKT ve Gy alıyorlar, otr kaplamları en son atlı almış, ama genelde tatkoya veriyorlar sahada gördüğüm. TBR yenide Gürkay ve atlıdan alımları var. Lassa da kullanıyorlar. TBR kaplama yerel bir firmaya burada michelin kaplama yaptırıyorum dedi. Halit bey ile iletşim bilgilerimizi aldık ben tesislere uğradıkça arayıp kendimi hatırlatacağım.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('8fc9eb92-7df8-53b3-82aa-2cb3a176b745','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='BÜLENT OTO LASTİK' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'c2140cb3-46cb-57b7-b7d3-b6514ad63667'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-05-13',NULL,'Haftalık toplantıda 295/60 konusu olunca burası aklıma geldi, bizden uğrayan olmamış benden sonra, B2B kurulumu yaptım, ekranda sorunlar vardı Eftal''e bildirdim. Bülent abinin ilgilendikleri oldu. Ben oradayken atlıdan Levent bey geldi, eskiden ishakoğlundaydı, oğlu da atlıda çalışıyor. yanımda nuh beton kaplamaların teslimatı için nuh beton deniz bey ile konuştu. 315/60 lar için bülente özle fiyat verdik.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('eea51d32-9e25-5341-8c6e-d95bdceca1f1','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='TEMEL MAKİNE' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'589c9388-0446-5c3c-bd59-84fdcc53beb7'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-05-13',NULL,'Tahsilat için uğradım fakat muhasebecileri sağlık sorunu sebebiyle hastaneymiş, Temmin amca yarın arasınlar beni kart için dedi. Kaplamaları konuşalım dedim, yoğunda sonra konuşalım dedi.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('0e08256e-ec7d-51dc-b8d8-419800e64376','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='DP WORLD' AND il IS NOT DISTINCT FROM 'KOCAELİ' LIMIT 1),'133723f9-2725-509a-9e20-939851832f91'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-05-13',NULL,'Satınalmadan Şüheda hanım ile ve Sercan bey ile görüştük. Evyap limanı ile birleşmişlerdi, satınalmanın başına Brisadan Hüseyin Kahraman gelmiş. Bizim Bridgestone süreci başladı bilgisi verdim, memnun oldular artık her alımda yine sorarız dediler. Teknik kısım 18.00-25 lerde contiden dönmüyor onlar marka belirtince bizim tercih şansımız olmuyor dedi. Micehlin 6 adet 18.00R25 deneme lastiğini toplamda 1.000€ bedel ile vermiş normal fiyatımız 2.500€ demiş. toplantıya teknik kısımdan Özerk bey de davetliydi ama katılmadı. Özerk bey marka tercihinde ikna edilmeden çok yol alınamaz, ÖZerk beyin müdürü Ayhan beyi de tanıyorum, kademeli olarak teknik tarafı sıkıştıracağım. en son 310/80r22.5 vermiştik Brisa grubu az da olsa alıyorlardı. Şüheda hanımda teknik tarafa biraz yönelin biz buradan destek olaacağız dedi. verimli ve çok güzel bir görüşme oldu.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('b170f57a-79e7-566c-8f94-964064ff123f','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='GEMPORT' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'af25b190-5cbd-5638-b7d1-25bf979e0e5b'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-05-14',NULL,'Teknik müdürlükten Sancar abi ile randevumuz vardı, 18.00-25 için hem reach stacker hemde rtg lerde kullanabilecekleri Bridgestone ELS2 için sunum yaptım. Solaksubaşından aldıklaro GY ELV-4B ile teknik karşılaştırma tablosunu gösterdim. Bridgestone diş derinliği avantajını bunun ortalama 1000+ saat ömür sağlayacağını söyledim. öğle arasında sahayı gezerken daha önce bizim sattığımız ELS2 leri gördük halen çalıştıklarını ona da gösterdim. Ben teknik olarak tamamım konu satınalmadan gelince BS konusunda alım yapılması yönünde görüş bildireceğim dedi. Terminal traktörlerde 11R22.5 dan 295/80R22.5 kullanmaya geçmişler. Terminal traktörler için doğru ürünün endüstriyel olan 310/80R22.5 Bridgestone VPCT olduğunu söyledim. DP world de bu denmeyi yaptığımızı sonra memnun kalıp devam ettiklerini söyledim. BS burada MI ve CT ya göre fiyat avantajı var. Bir terminal traktörde 6 lastik set deneme için maliyetine fiyat vereceğimizi söyledim, bunu bana mail at projelendireyim onayını alayım deneyelim dedi. Yine terminal traktörlerde kaplama kullanmadıklarını bunları kaplayabileceğimizi söyledim, çok önceden denedik sorun yaşadık dedi. 4 adet bedelsiz yada 8 adet yarı bedelli kaplama yapıp takip edip çalıştığını gösterebileceğimi söyledim. 70 adet terminal traktörleri var. bunuda bana mail at projenlendireyim ve onayını alayım dedi. Lastik takip için daha önce bahsettiğim programın artık çok iyi düzeyde olduğunu söyledim, ekipman ve lastikleri kayıt altına alıp takip edebileceğimizi söyledim, aslında elimde bir mühendisim var bu işi ona yaptırabilirim dedi, not aldı, bunu projelendirmem lazım olabilir dedi. hava kontrolleri için bir alan oluşturup dijital saat koyup uzatma ile operatörlerin havaları tamamlayabilecekleri bir alan için konuştuk, bunu kaplama sözleşmesi olursa bizimde yapabileceğimizi söyledim. 18.00-25 kaplama geçen tespit ettiklerimizi fiyattan dolayı tatkoya vermiş satınalma bizim ucuzdan da ucuz bir fiyat vardı, yine çıkanlar vardı onlar için satınalma yeniden soracak. liebher vinç için 40 adet 285/70R19.5 talebim olacak sanada sorarlar dedi.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('bee42678-0610-5800-aff0-02b3ddb89283','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='GEMPORT' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'af25b190-5cbd-5638-b7d1-25bf979e0e5b'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-05-14',NULL,'sonrasında benim satınalma ile toplantım vardı, Sancar abi BS konusuna onayım olduğunu ve konuştuğumuz projeleri onlarada anlat dedi. Selinay hanım ve diğer arkadaşlar ile ana bina da görüştük, tüm konuları anlattım notlarını aldılar. 18.00-25 alımında rakam büyük olduğu için onay süreçleri uzun sürer ayrıca teknik kısımın önce yönetim onayını alması gerekiyor henüz bize gelmedi dedi. genel olarak güzel ve verimli bir görüşme oldu, takipteyim. Yıldırımlar bildiğiniz üzere ayrılmıştı burası Ali Rıza Yıldırım da kalan taraf, Eti krom,gemlik gübre, eti lojistik, tekfenin %30 hissesi ve belkçida bir liman var.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('ba6f94e7-b68d-5dce-8383-f3b139f01806','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='CİHAN GRUP' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'b9536378-e658-5f57-b2b4-a29443342542'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-05-14',NULL,'Satınalma müdürü ayrılmış, yerine satınalmadan hayrettin bey terfi etmiş. Yeni loder alımları olmuş 20 lodere çıkmışlar, 70 mikser, 15 silobaş ve sayısını bilmediği taş ocaklarından çalışan hafriyat kamyonları var. Toplamda paletli makineler ile dahil 400 plakam var dedi ama bir listesi yok sayıyı abartmış olabilir. Yaşar Cihan Brisacı binek arabalara kadar Lassa alıyoruz dedi, kaplamada günmarlas ile çalışıyorlar ( tarif ettiği yer buraa uyuyordu firma adı vermedi) otr kaplamada tatko ile devam ediyorlar. eskiden çalıştığımızı bir süre ara verdiğimizi söyledim, iyi oldu geldiniz artık toplu alıma çıkacağız dedi. çeker, düz ve pilot için teklif istedi. otr için ocak ve tesislere uğrayın tespitiniz olursa bakalım dedi. güzel bir görüşme oldu.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('0df5ccd3-dddb-5c61-921d-d25d3b62ef7f','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='YAFA İNŞAAT' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'8c43afaf-5ef4-58ce-b3f9-59126920505e'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-05-14',NULL,'Satınalmadan Ömer bey ile görüştüm, 26.5R25 yeni talebi varmış onu fiyat verdim, kaplama için tesisler genel olarak kendi bağımsız gidiyor dedi, şuan Bilecik ve kayseri aktifmiş. Kamyon kaplama için de sizden müdürüm fiyat almamı istedi  dedi. Bizi tanıyormu dedim sanırım dedi. çıktıktan 1 saat sonra Yıldıray bey beni aradı buradaki eski kontağımız ayrılmıştı satınalma müdürü olarak geri dönmüş, 26.5 lazım fiyat ver dedi, bende 1 saat önce uğradım dedim haberi yokmuş, haftaya ayrıca Yıldıray beyi ziyret edeceğim. güzel bir görüşme oldu takip edeceğim.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('e3d44ad6-4689-5fb3-9a9a-7b7b22be3a10','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='İGA' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'14ea2641-9ef8-5e1d-aa89-2e370afe65ff'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-05-15',NULL,'Satınalma Yılmaz serdar ile görüştüm, 2 gün önce 100 civarı kamyon kaplama, 2 iş makinesi kaplama ve yeni sordu. Teklifin üzerine gelmek istedim hemen. Kaplamalarda ucuz olmamıza rağmen kaliteli olduğumuzu reçetemizi kendimiz hazırltattığımızı anlattım. öğleden sonra teknik kısım ile randevum var önce sana geldim onlara da anlatacağım dedim. 23.5-25 yeni petlas almışlar en son silindire biz tiron teklif ettik, fiyatta uçurum olmazda teknik de evet derse alırız dedi. ofislerini terminal bina içine taşıyorlarmış artık daha zor görüşürüz gelmen için yolcu gibi giriş yapacakasın dedi. müdürü Hakan beye selam verdim, müsait olduğunuzda patronu getireceğim dedim, bayram sonrası haberleşelim otel yapıyoruz terminal içine onunla yoğun ilgileniyorum dedi. İsmail abiyi kaçırıp getireceğim Hakan beyde kalyon kadrosundan.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('8466eced-e93b-5623-8580-2305ac065164','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='MAKYOL' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'b540e6cd-c913-58ae-b0fb-d76d24b37afc'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-05-15',NULL,'Müjdat uzun süredi aradığımda yerimde yokum yada müsait değilim diyordu bugün kabul etti, buraya her geldiğimde arıyorum mutlaka. Romanya aktifmiş ama alımı yerelden oradan yapıyoruz dedi. Sakarya açılmak üzere dedi. Antalyada kalyon ile ortak yol aldık ama başlamadık dedi. bir de çatalcada taş ocakları var. ben parton savaş bey ile görüşüyor banada soruyor almıyorlarmı diye dedim. görüyorsun yatıyor her yer talep yok dedi. abi 1 yılda 1 tane bile mi lastik almadınız yada kaplatmadınız dedim, taş ocağı hep aktif hiç mi ihtiyaç olmadı dedim. olmadı dedi. masasında  tatkonun teklifini gördüm. kaplama için peki dedim neden sormuyorsun yok ki talep dedi, ben sakarya açılacaksa gidip bakacağım kaplama çıkar belki dedim mutlaka git bana da haber ver dedi, pazartesi uğrayacağım dedim. yeni de lassa başladı dedim bu süper olmuş dedi hemen bana teklif ver elimin altında olsun dedi. verdim mail olarak eh işte fiyatlarınız ama idare eder dedi. talep netleşince haber edeceğim dedi. bence burayı savaş bey aramadı çünkü daha önce bir kere aradığında beni çağırıp alım yapmışlardı. bu arada müjdatda bizden kasıtlı teklif almıyor sakaryadaki kaplamalar için bence masadaki teklifi o almış tatkodan. İsmail abiye detaylı aktaracağım.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('5eb0e017-caf1-5f8f-bf71-7dc3824a92b2','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='İGA' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'14ea2641-9ef8-5e1d-aa89-2e370afe65ff'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-05-15',NULL,'Teknik müdürlükten Hayrettin bey ile öğleden sonra görüştüm, yeni pist kademenin olduğu yere akdar uzanacağı için kademeyi taşımaya başlamışlar ufaktan. 40 dakika kadar harita üzerinde havalimanının en ince ayrıntısına kadar öğrendikten sonra lastik konusuna gelebildik. hayrettin ben her seferinde projeyi baştan anlatıyor. kaplama için hamurunu kendi bildiğimiz özel sırtımızı teklif ettiğimizi söyledim, sen yine alternatifli ver atlı aradı 3 çeşit verecek dedi. silindir lasitği için tironu teklif ettiğimizi söyledim ve anlattım. şantiye içinde asflat çıkmayanlara önleri de kaplayabilriz dedim, çok ilgisini çekti not aldı, benden desen istedi, bir kaç arabada deneyeceğim dedi. satınalmanın sorduklarını konuşurken yine bana sormadığı 2 kalem ürün tespit ettik, neyseki küçük forkift ebatlarıydı. Yılmaz bey kasıtlı yada kasıtsız sormadığı oluyor. loder kaplama içinde yine bizim ürünü ve hamuru anlattım. fiyatta çok fark olmazda tercih edecekler.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('8e0bfa2c-c83e-5aea-b9ff-83f8db21f3e4','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='MAKYOL' AND il IS NOT DISTINCT FROM 'SAKARYA' LIMIT 1),'f06a0361-58df-51f2-b94e-ba457ddcf07f'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-05-18',NULL,'Cuma günü Müjdat ile görüşmemde burayı sorduğumda açtık bir uğra kaplanacak lastikler var demişti. Şantiye burada yukarıda yapılan barajdan dolayı su altında kalacak olan yolları yukarı alma projesi, ödeneksizliklten uzun süredir kapalıymış Nisan ayında açmışlar. 1 yıllık daha işleri kalmış fakat işin kalanını almak istiyorlarmış. şuan burada 4 loder, 1 greyder ve 13 kamyon çalışıyor. çıkmış olan lastikleri kontrol ettim ve listesini çıkarttım. Müjdat a telefonda bilgi verdim, mail olarak teklif atacağım. şantiyenin 12 çeker 4 düz kamyon lastiği talebi olmuş, ilave de olacakmış. henüz lastikler gelmedi dedi. Müjdata sordum alımı sonuçlandırmadım dedi. araçların altında atlının kaplamaları vardı.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('5b9a29fb-a1c7-5a58-9625-9c369fbb8847','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='MARDAŞ' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'a03df5cb-84f1-55a2-8212-c39754b457b3'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-05-20',NULL,'Satınalmaları Fevzi bey bazen telefonlarımı açıyor ve asla görüşme için randevu vermiyor. Bende teknik müdürleri Kemal beyden randevu almayı başardım. Kemal bey benim lastik konusunda hiçbir etkim yok, inanın alınan markaları bilmiyorum formen talebi açıyor Fevzi bey fiyat alıp yönetimin onayladığı markaları alıyor hatta bazen yönetim illa bu markayı alın diyor dedi. Benim tedarikçiler ile görüşmeme hoş göz ile de bakmıyorlar ben sizi kırmak istemedim dedi. satınalmaya tepkili olduğu belliydi, bende Fevzi bey randevu vermiyor dedim, benim yapacak birşeyim yok bununla ilgili dedi. 81 terminal traktör, 100 treyler, 15 dolu 4 boş konteyner taşıyıcıları var. burası yukarıdan kanal bulmadan yol alınayacak durumda, son 3 yıldır Fevzi bey bir kere bile lastik sormadı.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('90cafd71-31bd-59c5-8e91-0de674dcee9f','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ŞEN LOJİSİTİK' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'08e2f0e5-6b06-5381-86a2-ab12313f81b3'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-05-20',NULL,'Ambarlı liman sahasında toprak sahada şartları oldukça kötü bir firma. Daha öncede birkaç kez uğramıştım. 2 dolu makineleri var. Üzerlerinde  BS ve CT vardı. Alımları ömerlideki uzun kardeşler hakandan yapıyoruz o ne satarsa onu alırız dediler. Daha önce uğradığımda atlıdan lassa almışlarda ama memnun değillerdi. biraz daha kapı aşındırmak lazım diyaloğa kapalılar, hakan ile özel ilişkileri ( akrabalık yada heşerilik gibi) olduğu belli. fakat firma profili hiç düzgün değil, arada uğrayıp geçilecek kategoride.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('dad193e4-6448-53f1-92a3-f8915552257d','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='KUMPORT' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'43bf164b-9159-5f31-9083-1ee9d7afcf01'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-05-20',NULL,'Satınalma müdürleri Onur bey ve yardımcısı Duygu hanım ile görüştüm. Beni hatırladılar, tekrar BS sürecini anlattım bu sebeple biraz az ziyaret etmiştim dedim. Anlayışla karşıladılar. Mart ayında yıllık ihale usulu ilerliyoruz dolu ve boş makineleri BS ve CT alıyoruz, dorselere dolgu alıyoruz dediler. Dolguda solaksubaşı ve lastiksan solideal olarak ilerliyoruz ama Daronu severiz A tire getirmiş deneme 16 adet aldık dediler. bizde Yokohama sürecini anlattım, dolguda Trelelborg söyledim 16 adet deneme için fiyat verin deneyelim uyarsa ihaleye kadar dediler. Fakat sahada presli hizmet alıyorlar. bunu çözebilememiz lazım. Yoko içinde fiyat verin bakalı m dediler. terminal traktör kaplama için çok gelen oldu biz teli çıkana kadar kullanıyoruz olmaz dediler boşuna dediler. bende 4 bedelsiz yada 8 yarı bedelli ile deneme önerdim o zaman teknik kısımı teste ikna edebiliriz dediler. 18 dolu, 12 boş makinesi, 40 RTG ve 64 terminal traktör var. ciddi 18.00-25 ve 10.00-20 dolgu pazarı var. firma %65 çin ve %35 umman ortaklı. buradaki yöneticiler Çinli. bana ekipman listesi atacaklar denemeler için fiyatları vereceğim.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('9fa61364-0724-55a3-93fc-2d78125fa798','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='KOCAMAN DENİZCİLİK' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'3930a867-e838-5090-929d-410f76574b12'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-05-20',NULL,'Aşkın bey bize conti forklift arızasından dolayı ödeme yapılmadığından ve contideb giden Baranın ukala tavrlarından dolayı çok tepkiliydi, hatta o zaman şirket içinde KRB den bir daha mal alınmaycak diye mail bile atmıştı. En son ziyaretimde bunları bana kuşmuştu belki öfkesi geçmiştir diye ziyaret ettim ama geçmemiş güvenlikte uzun beklemem sonrası içeri aldırmadı beni müsait değilim diye. birde yasemin hanım var onuda denedim o yokmuş, sonra tekrar deneyceğim. tatko bkt ile iyi yol alıyor burada. Akçansa tarafının limanda ana taşeronu firma.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('47e4180e-402d-56a9-a50a-4cb81c522b3e','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='HÜRSAN' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'7d55607a-37a9-53f0-b24c-1253cf02705d'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-05-20',NULL,'2 dolu makineleri var, Tatko ile çalışıyorlar, 13 terminal traktörleri var. Şefleri ile görüştüm. Numaramı kaydetti mutlaka fiyat alırım dedi. Ekipman altında kaplama ve BKT ler vardı. Takip edilecek firma.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('99da1fc2-c0c6-5594-af55-6994ff873d34','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ALTINSOY MERMER' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'48279c3d-5b5c-5a90-843d-3ad62cc13b5b'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-05-21',NULL,'6 adet binek lastik almıştı Nurullah bey onları kendi aracım ile depolarına bıraktım.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('8e502592-6848-5e6f-a925-5047030caae8','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='KALYON' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'7fc96750-eddb-5840-b7e3-7393fe018052'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-05-21',NULL,'Abdülkari Serkan abi ve diğer ekip ile tanıştırdım. Yaptığımız hurda analizinin üzerinden geçtik, sebepleri marka dağılımlarını konuştuk, önerin ne marka ile devam diye sordu Lassa dedim. Notlatrını aldı. Yahya abi özel hamur demişti halen ortada yok dedi, bende avon+ tarafında da tavsiylerimiz oluyor hepsini takip ediyoruz dedim ama çok kabul görmedi. Abdülkadire sen mühendismisin diye sordu, Yayha abi mühendis sözü vermişti, ölçümleri bana mail olarak da at. rakipler her gün gelip ölçüm yapıp sunum yapıyor dedi. bende lastikçi gökhana verdiğim eğitimleri anlattım, ona verdiğimiz sök-tak desteğini söyledim. Gökhanı kazandık artık habvalar daha düzgün, hurdalar az dedim, Gökhanın sağlayacağı yarar en show ölçümlerinden daha değerli dedim. haklısın doğrusu bu dedi. Ağustos sonu yeniden ihaleye çıkacağım kaplama için dedi. şuan iş azaldı ama 2 tarafta devamını alırsak hızlanırız dedi. 2 yıl önce prag gezisine yollamıştık bu yıl yine yurt dışı bekliyorum senden haberin olsun dedi. bende planlama olunca benim adayım sensin dedim. Kars ığdır projedeki müdürü aradı, bizi önerdi, Ergün bey önce kibarca teşekkür etti, Serkan abi zorlayınca Asım Cengiz direkt kaviye işi ver yada yılmazlara ver dedi başka yer olmaz diye talimat verdi ikisine böldüm dedi. Bülent çamı aradık eskiden sohbet ettik biraz. genel gazını aldım, 1 ay sonra yine ölçüm sunumu için gideceğim.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('473dc575-f2c2-5516-b3f4-f331139b9a1b','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='KALYON' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'7fc96750-eddb-5840-b7e3-7393fe018052'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-05-21',NULL,'Ana merkez şantiyelerini çeki almak için uğradım. Tahsilatımızı yaptım. Artık çekleri sadece şantiyeden vereceklermiş.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('16fcf92c-ca0d-59ab-b67a-33f95e461885','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='DENİZ GRANİT' AND il IS NOT DISTINCT FROM 'BİLECİK' LIMIT 1),'bb3545b0-5f64-5ed2-988a-5ce4495c80f6'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-06-01',NULL,'Göksutaş sahasındaki rödavanscı firma, kendi ve göksutaş makinelerini ortak kullanıyor. Burada 2 loder 1 kaya kamyonu var. Geçenlerde lastik sattığımız kamyonu satmışlar, makineleri kontrol ettim. Kamyona ihtiyaç var ama az kullandıkları için patlayana kadar gideceğiz dediler. kamyonun 1 kaplaması bizde onu bırakacağız. 17-20 si afyonda mermer fuarı varmış izmirden hareketli olmasını bekliyorlar, geçen sene gitmiştik izmire katılmayanlar gelecekmiş 1 günlük uğrayacağım.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
