INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('219e8485-b5dc-5934-bb1c-ab7279b91fa1','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='DAĞİŞ MADEN' AND il IS NOT DISTINCT FROM 'BİLECİK' LIMIT 1),'5ef3ddc8-2a81-5222-9f0d-ba4ded91ca19'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-06-01',NULL,'2 adet 26.5 kaplamalarını yarın teslim edeceğiz onları takınca yerine 2 adedt daha verecekler. Toplamda 10 loderleri 125 kamyon ve mikserleri var. 1 ay önce 315/80 grubu karışık Bayraktardan 102 lastik almışlar 330S fiyatını gösterdi %38 iskonto. 100 gün vade çek ile alıyorlar. Normalde Günmarlas aktfiti ama son alımda fiyatları ciddi olarak yüksek gelmiş 102 lastikte kdv dahil 400k daha pahalıydı dedi. bende vermek istememiştir dedim aksine burada yatıyor adamlar bizde anlamadık patron ara sor fiyatları yanlış mı demiş aramışlar 40K daha düşmüşler. binek aldık toplu günmarlas verdi dediler. bundan sonrası için bizede soracaklar tbr grubunu.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('9fe1399d-77a6-5264-bb32-0fbce2cbc83e','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='DİLER HOLDİNG' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'285f80d9-3e06-5dd6-bf7d-e125bf19c17d'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-06-02',NULL,'Satınalma müdürleri Erdal Şen ile görüştüm. Gelmeden bizim cariye bakmış biz çok az miktar resa tarafında çalışmışız sizinle dedi, evet orada çok şans bulamadık brisa ve gy filo bayiliği vardı dedim. Artık kalmadı Resa tarafını sattık dedi, Gürkan nakliyat firmasına verdik 1 yıl olmadı dedi. şuanda 15 kamyon kaldı dedi. diğer parkuru sordum bilgim yok dedi. Dİlovası ve İskenderun demir çelik fabrikası devam ediyor. tüm satınalma ekibine sizin bilgileri ilettim her talep için mutlaka fiyat soracağız dedi. ben teknik kısımın etkisini sordum marka tercihinde, iyi sordunuz onlar hangi marka derse mecbur onu alıyoruz dedi. teknik taraf içinde destek talep ettim, bana tüm ilgililerin iletişim bilgilerini verdi. Dilovasından randevu alarak başlayacağım teknik kısımları ziyaretleri. Dolgu grubu ağırlıklı alıyoruz dedi ama ebat ve makine bilgisi veremedi. takip edeceğim.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('b0bdd718-7501-50f7-9a41-fa43353f992d','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='METGÜN' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'6bd25b4b-9067-5d16-9098-4a05aa20399e'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-06-02',NULL,'Melik bey ile bugün 15:00 için randevulaşmıştık, güvenlik aradı benim geldiğimi söyledi önce tanımadığını söyledi, sonra kendimi tanıtınca yok diyin dedi, kadın sıkılarak yokmuş pardon dedi, önce ofiste demişti. Sizi Atilla beye yönlendirdi dedi, Atilla beyi aradı, konuyu anlattı o da şantiyeymiş malesef dedi. sizi Yunus beye yönlendirdiler dedi. 15 dakikalık yönlendirmeler sonrası Yunus bey ile satınalma ofisinde görüştüm, şantiyede olduğunu söyleyen Atilla bey de oradaydı. Önce beni çok sıcak karşıladı Yunus bey, kardeşler ulaşım ile karıştırmış, sizden Rasim var sürekli görüşüyoruz dedi. sonra binek için bir lastik firması gelecekti orası sandım sizi dedi. kendimizi tanıtınca sizin patron daha öncede aradı ama continental çok pahalı diye sizden alım yapamadık dedi, bende brisa tarafı var artık diyince çok iyi o zaman çalışabiliriz zaten alıyorum dedi, masasında atlı ve kardeşler ulaşım faturaları vardı. bende kaplama tarafını söyledim, eskiden conti diye yenide çalışamadık ama kaplamada da şans vermediniz dedim. şantiye bizim hiçbir yetkimiz yok merkez direkt tatkoya veriyor dedi bana diye söyledim. doğru dedi, kaplamalar için fiyat sormuyoruz sbait fiyat tatkoya veriyoruz dedi. sizin gibi bir çok gelen zaten üstten aratarak geldiği için böyle gidiyor dedi. şuanda bir talebimiz yok ama siz kaplama için fiyat verin 29.5R25 için dedi bende sizde 29.5R25 yok dedim evet haklısınız dedi. laf olsun diye sorduğu çok belliydi, Atilla bey müdürü geldi sonra yanımızı kartını verdi, mutlaka sorarız ve alırız teklif dedi. bende patronlarımız görüşüyor zaten bana sürekli neden buraya mal veremiyorsun diye soruyorlar dedim. şuan 9 loder 90 kamyonları var, ağırlıklı işleri kocaeli civarında, kredi işimiz var onaylanırsa 400 kamyon alımı planımız var dedi. lokasyonlarda satınalma var siz buradasınız biz hepsine nasıl dahil olalım dedim, hepsi buraya geliyor bende ilave teklifler alıp bağlıyorum dedi. takip edeceğim.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('c6199c7d-040c-5573-acc5-e8739f3bd5ba','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='JEOPARK' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'df6b9425-125d-5c2e-92df-b65702146cb1'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-06-03',NULL,'Kemal bey ile görüştüm, işleri yavaş devam ediyor hala. Cat 750 yi satıp Volvo A40 almışlar, Cat 988 in lastiklerinde hava kaçağı vardı, köpük testi yapıp bana haber verecekler. Diğer ekipmanlarda sorun yoktu. Yedeklerin 6 adet lastik var ihtiyaçları yok.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('7c041f19-6cf6-58fc-b2b2-1fcebac67b39','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ALTINSOY MERMER' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'48279c3d-5b5c-5a90-843d-3ad62cc13b5b'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-06-03',NULL,'Erenler ocağındaki kamyonu ölçtüm, 2 adet yeni alması gerekiyor, 2 adet de kaplama olacak var. Nurullah beye bilgi verdim.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('fa67b8e5-98e8-507b-a900-8c65420f5e2f','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ERENLER MERMER' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'179f5ac5-09a9-5dc8-b6db-d87c3c4f6426'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-06-03',NULL,'Çoğu makine yatıyordu, birkaç tanesi çalışıyordu. Kapladıklarımızdan takmadıkları var henüz. Osman bey birkaç aya hepsini çalıştıracağım şimdilik iş az yatıyorum dedi. Lastik ihtiyaçları yok. Hepsi çalışınca çıkacak lastikler var.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('9d2d348d-8781-5f21-8cb1-f33d67635fce','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='BURÇ MERMER' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'03841b24-f9c7-591f-9113-41afa038bda9'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-06-03',NULL,'Takip ettiğim kamyondaki 2 lastiği kışın Şerefe vermişler, buranın merkezi Burdur olduğu için oradan iletişime geçmişler. Fakat lastikler Batmana gitmiş ve bizim VLTS desen açamışlar 1 aydan uzun sürmüş gelmesi ciddi sıkıntı yaşamışlar. Cem bey ödemelerinide yapmıyormuş. sen takip et ben ilk başta boş bulundum sizden ayrıldığını anlayamadım dedi. şuan talepleri yok,takip ediyorum.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('3e776adb-0e27-5547-99c6-e9588a78d00a','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='AFAY' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'074da1a4-d59b-5193-aa23-684456803014'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-06-03',NULL,'loderi kontrol ettim, 4 adet lastiğinde kaplanması gerekiyor fakat Yıldıray bey şimdilik 2 adedi kapla sonra bakalım diğer 2 adede dedi. Cur cure olarak haftaya alacağız lastikleri.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('0eafa938-7d7c-5af5-b120-817c954fdfc6','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='AKÇANSA' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'47733cbb-48c2-5e3a-8371-20cc9d447a74'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-06-03',NULL,'Yunus beye uğradım. Saraydaki makineyi buraya getirmişler, lastik durumu iyiyidi. Sadece sol arka sezonu çıkarmaz onu takip edeceğimi söyledim. 2 adet de kiralık makine gelecekmiş 3 ay sonra onları da takip edeceğim','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('12a5b781-8477-5dc1-bc01-04a284297c38','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ALTINSOY MERMER' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'48279c3d-5b5c-5a90-843d-3ad62cc13b5b'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-06-03',NULL,'Subaşı ocaklarındaki kamyonu ölçtüm, 1 kaplama tepsit ettim aracımız alacak, 2 adet 26.5R25 çıkma vardı, Nurullah bey al bak iyi değilse emanete senin olsun dedi. Onları da alacağız. Kamyona 2 yeni lastik lazım, diğer ocağada 2 yeni lazım, Temmuzda bakalım gel yanıma ödemesine bakayım dedi. takip ediyorum','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('b1ec599e-068d-5c22-a8cd-97bf4e83b7c1','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ŞİLE İNŞAAT' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'1843f090-238e-555e-b78f-e3bf6eb540a4'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-06-04',NULL,'4 adet competus at almışlardı fakat sap da sipariş takılınca mal satılmış yerine stoktan yokohama götürdüm, teknik müdürleri ismail bey lastiği övüp kabul ettirdim. Yeni lastikleri takmışlar, çıkanların kaplaması için asıldım ama kötü durumda oldukları için hurdaladık dediler. kamyon takviyesi olacakmış yine onlara da lastik lazım olacak, yeni yeni tam çalışmaya başlıyorlar. Kalyon ile ortak trabzonda iş aldık bilgin olsun dedi. romanya konusu açınca sen müjdatın müdürü var Peyami bey ona git o bakıyor o tarafa asıl dedi. loderi kontrol ettim durumu iyiydi, bir ara ön arka yapacağız. yukarı şantiyeye geçip satınalma müdürleri Ayhan beye uğradım. lastik fiyatlarında bana atlama merkezden fiyat karşılaştırması yapıyorlar sonra bana laf gelmesin dedi, bende açıkladım. şuanda yeni kamyonlar gelene kadar lastik talepleri olacak gibi değil. Ayhan ve ismail beyler ile frekansım tuttu, Ayhan bey ile balığa gideceğiz teknesi var. 45 günde bir takip edeceğim, sezonda tüketim olacak lokasyon.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('6e774a56-fe43-555b-bdb0-8fd5937a457b','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='KOMATEK' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'b1d57c14-e27f-5971-bde5-ce8d2e83f41f'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-06-04',NULL,'bu fuara biz katıldığımız yıldan beri geliyorum sadece pazarlama dönemi 2-3 fuara gelemedim, hepsi çok kötü ve sönüktü fakat bu o katıldığımız yıldakine çok benzer kalabaktaydı. Özellikle çinli makine üreticilerinin etkisi vardı. Eski çalışanımız Cüneyt de zoomlion da oradaydı, paletli makinede hidromeki geçtik, elektirklide zaten en büyüğüz dedi. gerçekten kamyonlarda özellikle iyi satıyorlar. Borusan Cat Kemal Tabur ve 2.el Özgür bey ile görüştüm, fuar sonrası yine ziyaret edeceğim, kaplama ve tamir için. marubenide çok yoğunda, cevo istanbul 2.el i kapatmış hendek fabrikaya taşımış. Pusulu lastik forklift yedek parça ve az miktar lastik ile katılmıştı. Berk abi GRI ekibi ile oradaydı ayak üstü sohbet ettik. Tatko ekbibi Bestami, Eray ve hintli BKT cilerle geziyordu. son dönemde ülkemizde gördüğüm en hareketli fuardı.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('d29946a6-8d4a-5525-b47a-b26d92716623','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='LİMAK HOLDİNG' AND il IS NOT DISTINCT FROM 'ANKARA' LIMIT 1),'9222cd6e-5d08-5db1-afd5-3f59a460f7dd'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-06-08',NULL,'Satınalma grup müdürü yada direktörü (kayarken kartını isteyemedim) Erhan Erken bey ile Ostim limak makine ikmal müdürlüğünde görüştüm. Kaplamadan sorumlu mühendisleri Ahmet Salgıntaş beyi çağırdı, Ahmet beyi siirt almkumru ve kiralık baraj şantiyelerinden tanıyorum o da beni tanıyor. Erhan bey Ebru hanımı nereden tanıyorsunuz diye sordu, patronumuz tanıyor dedim, kim diye sordu ismini verdim not aldı. Ben Ahmet bey ile tanıştığımızı siirte 2  barajda, kuzey marmarada ve çanakkale köprüsünde Yılmazlar üzerinden hizmet verdiğimizi söyledim. sizi biliyorum bana kendinizi anlatmanıza gerek yok, Ebru hanum KRB dedi eğer kardeşler dese zaten tanıyorum derdim. ayrıca siz buraya direkt gelebilecekken neden Ebru hanımı arıyorsunuz diye ilk kayışı attı. ikinci bir aramada ticaretmizi biter. bizim kapımız herkese açık yıllar 20 yıldan sonra ilk kez kaplama yılmazlardan başkasına gitti, yenide artık en çok alım yaptığımız yer atlı, sonra doğangü sonra özcanlar eskiden tek özcanlardı dedi. bende brisa sürecine ara vermeden önce merkezi faturalama ve özcanlar ile olan tek tedarikçi konusundan çok direkt sizinle görüşemedik dedim. yine başa sardı, o kadar kaydı ki randevu için attığım ve cevap vermedikleri maili bulamadım aslında iyiki bulamamışım orada göstersem belki daha da üstüme gelecekti. tüm ekibi ile tanıştırdı. tüm satınalma benden geçer dedi, sadecec çimento fabrikaları bana bağlı değil dedi. limanda ona bağlıymış. herkese mailimi verdi.benimde almamı sağladı. kaplama yıllık atlı ile sözlü sözleşme üzerinden gidiyor başka yere veremem yoksa verdikleri özel fiyat geçerli olmaz diye kaplamanın önünü kesti, seneye yenilenirken görüşürüz dedi. yeni lastikte sorarız ama asla pazarlık için dönmeyiz fiyat konuşur dedi. vademiz 60 gündür ona göre fiyat verin dedi. kaplama ihalesini doğangü almıştı ama brisa baskısından patronları beni aradı ve özür diledi geri çekildi dedi. yenide yakın bayiden çalışmayı tervcih ederim dedi. istanbudlaki projeye adanadan almam dedi. bende malkatra yolu bize çok yakın diye aradan söyledim ama cevap vermedi. kaplama için eski kontağım Ahmet bey yeni lastikte Yunus Emre bey ile tanıştım. tüm taleplerde fiyat alacaklarını söylediler. en son beni aracıma kadar uğurlamak kisvesi ila aşağı gelip 20dk kadar bireysel kaydı.  ben sorun etmedim ama başkası takılır patronun aramasına dedi. şuurum yerine geldikten sonra limaktan ayrıldım.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('6635ad88-8b91-55b1-993f-87f705a537c4','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='BAHAR MADENCİLİK' AND il IS NOT DISTINCT FROM 'ANKARA' LIMIT 1),'a75442c9-b0ca-50bc-bef3-e4a58bc196a8'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-06-08',NULL,'Ahmet bey ve Mustafa bey ile görüştüm, beni hatırladılar. Sivas koyulhisar altın madeni, ordu altın madeni ve istanbul cebeci taş ocakları var. 60 kamyon ve 20 loderleri var. Bandag fiyatı sordular verdim. Yeni tarafında artık Lassa olduğunu söyledim, teklif alacaklarını söylediler. Patronları Ramazan bey İstanbuldaymış onu yakalamayı planlıyorum.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('f1dae058-9850-5586-846e-3a9729cd3e1f','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ÇİFTAY İNŞAAT' AND il IS NOT DISTINCT FROM 'ANKARA' LIMIT 1),'c929611c-4936-5bcd-93e5-31fe4772c7ad'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-06-08',NULL,'Satınalma müdürleri Sabahattin bey ile görüştüm, vadesi geçen için planımda bu hafta bekliyorum onu söyleyelim dedi. Brisa tarafını söyledim haberim yoktu dedi yeni lastik teklifi toplayan Aytaç beyi çağırdı bizi tanıştırdı fiyat sormasını istedi. Atlı çok agresif buralarda dedi, konu karlılığa gelince emin ol ana markalar destekledikleri yere sonradan fark prim vb kesip omuz atıyor kimse zarar etmiyor dedi. Sivas divriiğinden Er maden taşeronu, Kayseri develi de öksüt altın taşeronu, erzuru iliç de altın taşeronu (burayı cengiz aldı ne olacak belirsiz duruyoruz dedi) . izmir batı çimento ortaklık, şile çöp tesisi, ege ve ankara biogaz işleri var. Doğangü ile çok üst düzey bir ilişkimiz var bozulmaz dedi. ama fiyat sorarız her zaman dedi.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('3a2e767a-4e56-5036-9f4e-44adc1ee43d9','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='YDA İNŞAAT' AND il IS NOT DISTINCT FROM 'ANKARA' LIMIT 1),'c61cc7b2-868c-5e67-bef1-065779fd0b4f'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-06-08',NULL,'Orhan bey ile tanıştım, sorduğum 23.5 ları petlas aldım L3 70K+KDV L4 80K+KDV dedi. Biz filo bayisiyiz başka bir marka almıyoruz dedi. 315 ler için 11.000TL+KDV den alıyorum dedi, bu paralar olunca gerisi anlamsız oluyor dedi. Geçen yıl 17.000.000TL lastik ciromuz oldu dedi. ama eskiden pirelli alırdık yarın ne alırz belli olmaz ben her alımda sana sorarım dedi.hatay, trabzon, Denizli ve urfa işlerimiz var dedi. 150 kamyon 15 loderleri var.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('e301575b-9ee0-5bde-bf02-6c5f92fa4230','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='SEZA İNŞAAT' AND il IS NOT DISTINCT FROM 'ANKARA' LIMIT 1),'b7ec08e6-4631-523f-bcb4-fb268351a59b'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-06-08',NULL,'Hacı abi ile görüştüm, çok yoğundu erp kullanmaya başlamışlar talepler oradan geliyor teklifleri oraya yüklüyor ve faturaları işliyorlarmış gerçekten yüzüme bakamayacak kadar bilgisardan talep basıyor ve işliyordu. Daha o lastikleri alamadım yenilerini talep ettiler şantiyeden dedi ama ade büyük konu patrona çıktı artık o da yok gelecek dedi. haber veririm alımı yapmadık dedi.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('09e6bf9b-5854-553f-a4e5-276bfd8b8511','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ÇETİN İŞLETMELERİ' AND il IS NOT DISTINCT FROM 'ANKARA' LIMIT 1),'5ef5043b-63c3-58e3-a319-0abcf83aa22d'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-06-08',NULL,'Satınalmadan Caner bey ile görüştüm beni hatırladı. Brisa tarafını söyledim zaten o grup alıyoruz iyi olur dedi. Yoğun olarak ukraynada ve moldova tarafındayız dedi. Tüm yurtdışı şantiyelere tır bazlı buradan alıyoruz dedi. Arabistan, Sivas ve Osmaniye ve Ankara civarı yol işlerimiz var dedi. 102 loder ve 1000+ kamyonumuz var dedi. en son siz conti verdiniz yüksek olduğu için sormadık dedi. bende artık rekabetçi olacağımızı söyledim.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('bcf0da44-fd5b-5a50-a20e-4a66dc235245','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='BAYBURT GRUP' AND il IS NOT DISTINCT FROM 'ANKARA' LIMIT 1),'06fb320a-a960-5765-9444-47611a6cf8f0'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-06-09',NULL,'Satınalmasan Erkan bey ile görüştüm, halen en son Rasimin alıp geç teslim ettiği kaplamaların siteminde, bende artık sorun olmayacağını benim sıkı takip edip artık sorun olmayacağını söyledim. Kaplama içinde söz artık size de soracağım dedi. Yeni konusunda brisa tarafının başladığını söyledim, sadece teklif isteme noktasın desteğini rica ediyorum dedim. söz her lastiği soracağım artık dedii, biliyorsun patronlar tanışıyor bana geçenlerde de sordu var mı hareket diye bende daha sıkı takip edeceğim dedim. sorun yok ben destek vereceğim dedi. şuanda Antalya, burdur,zonguldak, çankırı, kayseri, rize,sivas,bayburt ve ankara da yol şantiyeleri var. manisa ve uşak hızlı tren şantiyeleri var. hepsi aktif durumda. kamyon sayıları 1000 üzerine çıkmış loder 50 adet üzerinde.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('dcf5cd2a-2146-50d8-a8a3-cf40c3791475','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='MV İNŞAAAT' AND il IS NOT DISTINCT FROM 'ANKARA' LIMIT 1),'b12b4108-0c68-58ad-8951-e0e365873272'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-06-09',NULL,'Fernasın sahiplerinin kurduğu diğer firması, Satınalmalarının başında Aydenizden tandığım Kemal abi var. 200 kamyon ve 10 loderleri var. Diyarbakır, maraş, batman, antep ve çorumda yol şantiyeleri var. Kemal abi çok ilgilendi. Fernasın satınalmasının başındaki Süleyman beyi benim için aradı ve 16:00 için bana randevu aldı. tüm alımlarda fiyat alacaklar.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('3db2d194-9a28-5675-bf4f-895dd5c6ba71','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='SARGIN İNŞAAT' AND il IS NOT DISTINCT FROM 'ANKARA' LIMIT 1),'f86d7ba0-6619-511e-931c-4daab74101b8'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-06-09',NULL,'Eskiden beri bildiğim Tünel taşeronu bir firma. Esan, Cengiz gibi çok firmanın madenlerindeki tünelleri açan firma. En son hatay tünellerinde görüşmüştük. Şuanda ellerinde sadece hatay kalmış ve bitmek üzereymiş. Müdürleri Süleyman bey ile makine ikmal müdürlüklerinde görüştüm. 15 loder 30 kamyonları var. yakında sonuçlanacak 2 maden ihalemiz var onlara hazırlanıoyoruz dedi. biri altın diğeri bize ait bir maden dedi. Tatko ile çalışıyorlar yenide michelin ve bridgestone alıyorlar. takip edeceğim. her geldiğimde yokluyordum bugüne yakaladım.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('0bcaa03e-6a9c-5e8f-a7cd-377b32023c50','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='KLV İNŞAAT' AND il IS NOT DISTINCT FROM 'ANKARA' LIMIT 1),'1fe55a6f-fc7c-54e1-9434-c406409d0fcf'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-06-09',NULL,'Talip bey ile görüştüm, abi ben hep iş makinesi diye sormuorum diğerleri artık soracağım dedi. Yılbaşında pirelli paket 2.300 tbr almışlar, parça parça çekiyoruz dedi. Çanakkalede Limak taşeronu olacağız dedi, Kıbrıs,Ordu, Elazığ, Malatya ve Adanada aktif şantiyeleri var. kamyon sayıları 400 civarında.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('4e37cf0e-c30e-53eb-af63-24e9f46cd230','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ÖZALTIN İNŞAAT' AND il IS NOT DISTINCT FROM 'ANKARA' LIMIT 1),'d4358e8a-e1e1-54ce-99be-6ed81bf4c855'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-06-09',NULL,'Erkan abi ile görüştüm, zenit ile ortak altın işindeler, ayrıca kendileri maden grubu kurmuşlar sondajlara başlamışlar artık aktif madencilik yapacağız dedi. Mersin, aydın ve romanya aktif devam ediyor. Artık romanyaya da buradan alacağım lastiği dedi. brisa konusunu söyledim, rekabetin soruşturmasından ankara bayilerinin kurduğu whatsupp grubundan haberi var. benim için hiç birinin önemi yok en uygun verenden alır geçerin bana dayatamazlar dedi. artık bizede tbrleri sormaya başlayacağını söyledi.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('0cce598b-f806-5625-bf2a-581fc85e2662','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='FERNAS' AND il IS NOT DISTINCT FROM 'ANKARA' LIMIT 1),'e9229993-a140-5b6b-bc46-3c353128bc0a'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-06-09',NULL,'Süleyman bey ile telefonlaşıp merkezde buluşup görüşmek için sözleşmiştik, merkeze gitim biraz bekledim. Aradım açmadı geri de dönmedi. Ofiste değilmiş güvenlik dışarı çıkardı beni.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('3e1c0c02-ff15-5d33-8b3b-a4ec492e6e36','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ÜMİT MERMER' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'4bce4773-2d3b-5588-8a8a-7d42c3822ea2'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-06-10',NULL,'Belenoluk ocaklarını ziyaret ettim, Afyon merkezli firma buraya mart ayında geldiler. 2 adet 29.5R25 yokohama verdik dün takıldı, çıkanklara baktım biri maxam topuk hasarlı diğeri gümlemişti. Bu ocakta 1 loderleri var sadece. Metehan beye bilgi verdim.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('d0b11a7d-ef47-5308-b328-4506f0850285','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ALTINSOY MERMER' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'48279c3d-5b5c-5a90-843d-3ad62cc13b5b'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-06-10',NULL,'Şükriye ocaklarını ziyaret ettim, burayı her zaman öğlen arası ziyaret edip ölçüm yapıyorum, tüm ekipmanı kontrol ettim. Şef yoktu aradım beni bekle dedi, tespitlerimi ona aktardım beraberde gezelim dedi 2.kez tüm ekipmanı gezdik beraber. 1 ader bizim kaplama omuz açması var garantiden alacağız. 1 adet 29.5 tamir, 2 adet 23.5 kaplama tespit ettik. ayırıca 1 aya 2 adet 29.5 kaplama zamanı gelecek var onu takip edeceğim. Beytullah şef not aldı hepsini sen kendinde Nurullah beye bilgi ver dedi. Nurullah amcayı aradım  bilgi verdim, tamamdır ne gerekiyorsa plana al yap dedi. en kısa zamanda kaplamaları alacağız.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('7a4ac0ab-f58a-57b8-963a-d89a2f6f342a','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ÜMİT MERMER' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'4bce4773-2d3b-5588-8a8a-7d42c3822ea2'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-06-10',NULL,'Şükriye ocaklarını ziyaret ettim, buradaki taşları çok iyi çıkmış, altınsoy ile özerler arasında, yolu çok kötüydü zor ulaştım. 1 kamyon ve 1 loder var. Kamyona 4 adet 29.5r25 yeni gerekli Metehan beye bilgi verdim. Fiyat teklifi istedi gönderdim. haftaya afyonda fuarda buluşacağız o zamana yüz yüze bitirmeyi planlıyorum.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('dc4890ee-7f05-5679-87d6-30b184288a89','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ÖZERLER MERMER' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'a25c2f1f-c636-5b59-9c2a-1815e12cfcc4'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-06-10',NULL,'Bölgenin en popüler ocağı, Serda abi yine müşterilere sıra yazıyordu. Tüm ekipmanı kontrol ettim hepsi iyi durumda. Bizde parasını ödediği duran 2 adet 29.5 yokohaması var onları bu ay içinde revizyona soktuğu lodere takacağız. Eskişehir ve bilecik ocakalarını tekrar açma kararı almış paletlilerle çalışmaya başlamış taş tutarsa ilave makine alacağım dedi. eski lodere yenileri takınca yedeği kalmayacak o zaman 2 adet için bastıracağım.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('ab703557-f84b-5489-a856-de372dcd15c2','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='AKBAY' AND il IS NOT DISTINCT FROM 'SAKARYA' LIMIT 1),'7853b190-84a8-5581-9fe4-4f23f96260fa'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-06-12',NULL,'Saha çalışması yaptım, 2 kaplama tespit ettim, haftaya kaplamaya alacağız. Yokohama L5 leri kontrol ettim durumları iyiydi birinde bir büyük taş batığı vardı kademeye bilgi verdim çıkaracaklar. 1 adet de 23.5 çıkma buldum alıp tamir edip istanbul ocaklarına teslim edeceğiz. Elek altındaki makinenin lasitkleri son ömründe sezon sonu gelmeden 2 adet 29.5 L5 alım yapmaları gerekecek bu tesis için yedek lastikleri yok. bir kaç hafta içinde merkezlerini sonrada kırklareli ocaklarınnı da ziyaret edeceğim.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('f8ec14ea-f84b-50f4-a188-304f0d78e322','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='MOLLAOĞLU' AND il IS NOT DISTINCT FROM 'KOCAELİ' LIMIT 1),'9beb5f14-83f2-5c1a-b59f-f09376a1ff56'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-06-15',NULL,'Sinan abi yokohama OE volvo lastiklerinin onyayını vermişti, organize etmek için ve diğer makinelere bakmak için kademelerine gittim. Murat şef Sinan abi ile konuşayım sana haber vereyim kaplamaya alalım lastikleri dedi. Diğer makinelerden de 4 adet 20.5-25 kaplama tespit ettim onları bunlardan sonrası için Sinan abi ile konuşacağım.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('2a8ea398-4523-5d57-8834-b264ea1d009a','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='PEHLİVANOĞLU BETON' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'d0821613-73a6-5387-a352-3613665e84bb'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-06-16',NULL,'Silivir kum ocaklarını ziyaret etttim. Formenleri Necmettin beni çağırmıştı. Loderi kontrol ettim, kaplamalarımız açmış ama ömrünüde tamamlamış, karkasların durumu ço iyi değildi, 2 tanesi iyiydi.  Teklifi verdim, habe r verecekelr. Tbr kaplama için asıldım, 4 adet denemeye verecekler Atlı özka kaplıyor, 4.500TL+KDV''den yapıyormuş. yeni 5.000 yapmış. aynı fiyattan alacağız.12 çekici 12 dorse 2 loder ve 3 kamyon var ayrıca 3 den fazla beton santrali var ama santrallere başka kişiler bakıyor onlarıda arada yokluyorum. takip edeceğim.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('7a7c4e6a-020b-56dd-94ef-d0e6aafc177b','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='HAZNEDAR REFRAKTER' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'ef9ff1cb-4cb6-53d0-963b-8e428594dbed'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-06-16',NULL,'Satınalma Osman bey ile görüştüm 1 lodeleri var, 2 de forklift fakat çanakkale ve eskişehirde bentonit madenleri var orada da loderleri varmış. Hepsine buradan bakıyorlar.kümaşı refarans verdim ilgilerini çekti. Loderi incelememe izin vermediler. Takip edeceğim.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('12f26b62-bbc2-5a0b-9022-e5aa4f7888b4','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='GÜLERMAK' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'3a68b16d-1b01-5da5-b2d5-4bd82e850653'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-06-16',NULL,'Kademe de şef ile görüştüm önce genek bilgi verdim, sonrasında lastikçileri Süleyman ile görüştüm, talepsiz kaplama veriyorum diye bana bazen kzııyorlar talep açınca da neden açtın gerek yok diyorlar dedi. Bende satınalma ve müdürün haberi var sen araç geldiğinde ver ben bilgi veriyorum dedim, araç yolda sen biraz lastik sök dedim. iadelerin fazla olmasından şikayet etti, bizde gereksiz risk almadığımızı söyledim. sonrasınde müdür Bünyamin beye gittim, genel bilgi verdim, iade konusunu konuştuk, ona bir iade raporu çıkaracağım. sen risk alma olanı kapla devam et dedi.talep konusunu söyledim ben açtırırım sen ne buluyorsan al kapla dedi. sonrasın da satınalma Halil beye gittim, iade konusunu onada söyledim, geçen sefer 17.5 bezlileri yenisi ile aynı para diye kaplamamıştın biz senden gördük bunu sorun yok sana güveniyoruz ne varsa al kapla olanı dedi. ödeme için ciddi sıkışıtırdım, cumaya kadar için merkezden bizim adımıza söz aldığını söyledi. takip edeceğim dedi. sen lastikleri yolla dedi bende hazırlıyorum diye geçiştirdim.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('20a6504d-c07c-5411-90f8-927a229eedec','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='AKIŞIK ZAHİRE' AND il IS NOT DISTINCT FROM 'TEKİRDAĞ' LIMIT 1),'4efc1ab1-25d2-51d1-b336-63464058a2ec'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-06-17',NULL,'loderin lastiklerini kaplamatmak istiyorlardı depoalarındaki lastikler iade oldu, yerine gelip buradan makine ve depodan lastik bak diye çağırdılar, Betonsa Muratlı tesisinin işletmesini yapıyor firma. 2 adet yeni ve kaplama fiyatı verdim, loderin arkası kaplanabilir durumda değerlendirip haber verecekler. 12 adet de 315/70 karkas seçtim onlarıda kaplamaay alacağız loder lastikleri ile.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('42ffc473-6dd4-5b1b-824c-fa241e331c2d','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='GÜRKAY OTO' AND il IS NOT DISTINCT FROM 'TEKİRDAĞ' LIMIT 1),'359d99c8-ac75-5661-8253-3bdc92f391fc'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-06-17',NULL,'525.000TL çek tahsilatımızı yaptım. Gürkay sizinle görüşmek istediğini söyledi, bende arayıp randevu almasını tavsiye ettim. Mal almak isteği var sizinle iletişime geçecek.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('c91cebbd-6fac-5267-b8dd-e31728d5a253','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='AYYILDIZ BETON' AND il IS NOT DISTINCT FROM 'TEKİRDAĞ' LIMIT 1),'eb74bdaf-312a-5b14-8911-9d830ca2b19d'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-06-17',NULL,'Çanakkale-kuzey marmara otoyulu için limak taşeronu olarak yolun 110km lik kısmını almışlar ana şantiylerine gittim, yeni kurulyordu, 3km kadar toprak yol açarak işe başlamışlar. Firma aslında beton firması fakat daha öncede limak taşeronluğıu yapmışlar makine müdürleri Cemil bey ile tantıştım bu firmada yeni başlamış işleyişi çok bilmiyorum düzenimi kurmaya çalışıyorum dedi. beni satınalmaya yönlendirdi,pazartesi için ranedevu aldım. sadece bu şantiyede 100 damperli kamyon çalışacakmış bir kısmı sıfır araç olarak gelmişti. firma atlının kalesi konumunda uzun vade ile çalışıyorlar. limak makine koymayacakmış kalan işi KLV almış  ankarada geçen hafta ziyaret etmiştim aktiviteme de yazmıştım, KLV henüz şantiye kurmamış.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('8a222861-0132-5468-b5fc-46324cd19042','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='EFOR BLOK TUĞLA' AND il IS NOT DISTINCT FROM 'TEKİRDAĞ' LIMIT 1),'5cf78981-f30e-5dd4-87c0-db3c29e6c706'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-06-17',NULL,'fabrikayı işleten firmaya taşere etmişler, ldoeri takip ediyordum 2 aya kaplaması gelir durumuna baktım. 4 adet forklift lastiği sipariş ettiler. 2 ay sonra geleceğim tekrar.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('07e2630a-0bb7-5229-a966-c581c8ff531f','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ÖZEN MAKİNE' AND il IS NOT DISTINCT FROM 'TEKİRDAĞ' LIMIT 1),'390a4f05-ccc8-5de1-bc35-5411178f1d8e'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-06-17',NULL,'Yasin bey ile görüştüm, işleri yoğun ama tahsilattan sıkıntılı durumdalar, şuan lastik ile iligli bir talepleri yok, buraya her geldiğimde servise gelen müşterilere bakıyorum, kayda değer bir yer yoktu. Kömürcüde batırdığı parayaı kurtaramamış morali bozuktu','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('7c254e02-2615-5126-a26b-eb8967ef8616','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ADOÇİM' AND il IS NOT DISTINCT FROM 'TEKİRDAĞ' LIMIT 1),'e4c8c29b-d95b-5a16-8749-486c46b3005f'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-06-17',NULL,'Mesut bey ile görüştüm, firma artık tamamen yunanlıların Titan grubuna ait ayrıca traçim i de satın aldılar. Bilecikte hammade ocakları vardı ama taşerondaydı oraya kendileri geçmiş ve loder alımı planlıyorlarmış şuan paletli makine var orada. Makineyi çağırdık kontrol ettim, ön yokohama L5 ler ciddi kesikler almış, işleri sakinleyince yada sakinlemesede takip edip tamire alacağız. Eko hamur kaplamamız gayet güzel aşımıyor ciddi kesik alan sahada yolunarak veya hızlı aşınması yok aldığı kesikler var ama görüntüsü beni mutlu etti.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('a4dfcc1a-cb5f-5187-9cfa-6d9e6cc152d6','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='BLOK MERMER FUARI' AND il IS NOT DISTINCT FROM 'AFYON' LIMIT 1),'07c1519e-cbdb-5883-bdf3-47c8aa2cdce4'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-06-18',NULL,'bu yıl ikincisi düzenlenen fuarı ziyaret ettim, Özcanlar stant açmıştı. Makinecilerde katılım vardı. Blok alıp içi piyasa yada ihracahata fabrikasında kesip satacak yerli ve yabancı alıcılar vardı. Genel olarak hareket vardı. ben erken gitmiştim öğlen gibi Murat Yener ile bulıştuk beraber gezdik. Şeref Bektaş ile de 1 saat denek geldik. Ümit mermer, Noche mermer, Demmer, Asonur, Gökyar mermer, Serkan mermer, Özerler mermer, Öfs merner gibi müşterilerimle görüştüm.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('bc4f0819-ea71-5ed6-88f0-a460e583420d','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='CFG' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'6f299b65-c728-5a3d-9194-9c40c6f17a01'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-06-19',NULL,'Erkan beyi ziyaret ettim, bu aylarda yeni tünele başlayacaklardı. Henüz kendi iş işleyişlerinden dolayı yeni tünellere başlayamamışlar temmuz ayın sanırım başlarız dedi. Erkan bey çelikler kadrosunda gülermak ortaklığındaki ödeme konusunu onu da açtım bizimkiler hep böyle pra olmadığından değil ama işte inatla geç ödüyorlar sapık bir bürokrasileri var dedi. bana destek ol kime çökeyim dedim, sen çökemezsin dedi kendisi merkezden birilerini aradı bizim cariyi buldurdu ödeme durumunu sordurdu 620.000TL yazılmış ödememiz varmış bugün yarın ödenir dedi. sen bizde 15 gün önceden başla para talep etmeye dedi,biz zaten hep 90 fiyatına 60 gün kesiyoruz faturları durumu bildiğimiz için. tünelleri takip edeceğim.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('68e70693-b51b-5161-b5f4-573db52acf40','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa','8b1ab4be-de03-4a62-a51b-249550f385e3'::uuid,'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-06-19',NULL,'Yusuf Menteş ile görüştüm, bugün gelen 18.00R25 talepleri vardı fiyat verdin mi dedi yok seni bekledim dedim. Aradı satınalmayı teklifler gelince bana dönün dedi, en son ne aldık dedi BKT aldık dediler, hatta acildi tatko lastiği taktı talebi peşinden açtık dedi Murat Meriç, fiyatı sordu 2.000€ ya aldık dedi, sen 2.050€ ver şimdilik ben Bridgestone alın diyeceğim dedi yanımda da aradı öyle dedi. ben diğer işler için hep dışardayım bana sormadan alıyorlar birde tatkonun adamı burada çalışıyor o ayarlıyor herşeyi dedi. ben basıtıracağım ama senin adam koymam gerekecek dedi, koyarız abi dedim, tatkonun kaç para fatura ettiğini öğren bana dedim adamı not aldı döneceğim dedi. kaplama içind verdiğim fiyatları sordu tek tek not aldı ben soracağım şimdi onlar ibneliğine yüksek çekerlerse senin fiyata bileyim pazarlık konu olursa da ararım seni dedi .ben oradayken vestel elektikli şarj ekibi geldi, ben çok yoğunum açmıyorum diye küsme yaz okurum mutlaka dönerim dedi. yoğun diye çok konuşamadık ben hafyaya teklifler için arayacağım.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('8837f7b7-070a-5863-9713-7b43c1519c73','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='NRC' AND il IS NOT DISTINCT FROM 'KOCAELİ' LIMIT 1),'bd71978a-040a-5ec2-98ed-5bc0c1dbbbd9'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-06-19','ADNAN KARAKAYA','Adnan abi NRC 23.5 sordu L3 istiyorlar bu sefer seninle gidip  konuşalım dedi. Emrah  bey ile görüştük, verdiğimiz yokhama L5 in kaç saat çalıştığını kaç kere kaplandığını söyledim. Küçük bir L3 L5 farkı eğitimi verdim. Desen konusunda bizdekine yönlendirdim. en son aldığım fiyata %15 ekliyorum gönderin dedi kurtarmayacağını söyledik. son 4 kaplamamız sırt atmış resimlerini gösterdi bende sökün garantiden bakalım diye mayıs ayında saha görüp söyledim dedim. pazarlık sürdü bir süre daha Adnan esnemedi, konu ortada kaldı, siz başka yerden fiyat alın bizim fiyaatı görünce geleceksiniz dedi. takip edeceğim.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('6d0539e2-e2ad-5a61-a4c4-80f6a2112261','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='AYYILDIZ BETON' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'a164d04d-a1de-52e2-9b11-3506cc0fe02c'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-06-22',NULL,'Satınalma sorumluları Salih bey ile Silivri merkez binalarında görüştüm.Aktif olarak 400 kamyon mikser ve 15 loderleri var. Atlı, Lastik burada, Günmarlas ve Petlas direkt müşteri olarak çalışıyorlar. Kaplamaları Lastik buradaya Avon olarak yaptırıyorlarmış, bizim avon fiyatımızı çok yükse buldular, hatta lastik burada zam yapmak isteyince Atlıya özka kauçuğa döndük dedi. orası içinde fiyat verdim. yenide Lassa ve Petlas karışık alıyoruz dedi. Petlas direkt fabrikadan alıyoruz, 3 kere kaplıyoruz çok memnunuz 15 bandına alıyoruz dedi. Lassa grubuda alımımız oluyor. geldiğiniz iyi oldu bana alternatif firma lazımdı dedi. her alımı mutlaka sorarım dedi. 45 günde bi yoklama listeme aldım.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('d37555d4-2ae9-5618-bffe-8fc9a5090b9c','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='SEREN ASFALT' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'ab816af9-133f-5db1-945d-b51348652f50'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-06-22',NULL,'ATİS adi ortaklığının asfalt yüklenicisi firma. Silivri şantiyelerine uğradım. Satınalmadan İlyas bey ile görüştüm, alımları merkez başakşehir Serkan Baran yapıyormuş, iletişim bilgilerini aldım. İstanbuldaki tüm AK partili belediyelerin asfalt işinde varız hepsinde şantiyemiz var dedi. merkezlerini ziyaret edeceğim buradan yol almak mümkün değil.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('9a4fc969-0690-57df-9613-ea49993bba8f','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ADM BETON' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'756029da-a2db-53be-97d6-3110e891d275'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-06-22',NULL,'Necmettin beyi Silivri merkez ofis ve beton santrallerinde ziyaret ettim, öğlen arası makineleri kontrol ettim, 8 adet 23.5R25 kaplanacak lastik var, lastikleri kantara sürtmekten yanak kısmından kötü yaralamışlar. Fiyatı verdim, pazarlık edeceğim o paraya olmaz diye itiraz etti, planlamanı yap lastikleri de parça parça alalım dedi. 315/80 için Atlı ucuz kalıyor orası içinde fiyat verdim. deneyeceğim dedi. fiyatları tekrar yazacağım ona not aldı ama atmamı istedi. üretim ve sök-tak bu hafta dolu diye haftaya planlamaya çalışağım. yeni tarafınıda söyledim Lassa oalrak sormaya başlayacak.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('c8de12ba-01b3-5d7b-a969-c5850e80db88','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='SONER TEMEL' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'2c0dedcb-a35a-5f2d-905e-65056bf5dc05'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-06-22',NULL,'Satınalma Yunus bey ile görüştüm, buraya periyodik 45 de bir planım var, işler açılmaya iyice kendimi belletmem gerekiyor, eskiden çalıştığım yüksek potansiyelli firma. Sakarya ve taşyapı ile ortak niğde hariç çalışmıyorlar. Takip ediyorum.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('f70a6deb-254f-57a4-addd-6ba0a449ef11','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='PEHLİVANOĞLU BETON' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'d0821613-73a6-5387-a352-3613665e84bb'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-06-22',NULL,'Silivrideki 2 tesisine de uğradım ama yetkileri ile yüz yüze görüşemedim, bu hafta silivri kum ocaklarından 4 adet 23.5 kaplama ve 4 adet 315/80 alacağız. Beton tarafı ile kumun yetkilileri farklı hepsi ile telefonlaştım takip ediyorum.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('565a63ea-4554-5583-b710-d43b0ed58083','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='BAYBURT GRUP' AND il IS NOT DISTINCT FROM 'TEKİRDAĞ' LIMIT 1),'dd27b7a8-4fa5-57f6-a7c1-f65232d7dc03'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-06-22',NULL,'yol şantiyesini açmışlar, ankara Erkan beyi aradım buranın kaplamalarını ver abi bize diye olur aslında bak dedi. Sen gir içeri mehmet beyi bul dedi ama yoktu telefon ile görüştüm yoğunum diye görüşmedi. Haftaya ankarada Erkan beyi sıkıştıracağım.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('7fcf7f85-8a62-5057-baf2-33f5891a3904','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='EKOLOJİK ENERJİ' AND il IS NOT DISTINCT FROM 'TEKİRDAĞ' LIMIT 1),'3158d2c6-a573-5bf8-92fa-1a3481d3349b'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-06-22',NULL,'20.5R25 kaplamalar vardı karkasları inceledim kaplama olur, fiyat teklifimiz verdim. 315/80 yanlış kaplananları haftaya alıp yerine karkaslı kaplama doğru deseni vereceğiz. Çıkan tnr kaplamalarıda yine alacağız. Buradaki çöp yetmediği için şileden buraya çöp çekmeye başlamışlar yoğunlukları artmış. tesis çöpten elektrik üretiyor.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('c902d69b-0e77-5d96-b8f0-1a15ab3873c3','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ÜSTÜNOL NAKİYAT' AND il IS NOT DISTINCT FROM 'KIRKLARELİ' LIMIT 1),'4e3cbfb3-8673-5c30-a814-f8890da464ed'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-06-23',NULL,'Muhammed bey ile görüştüm, conti kampanyalı fiyatlarımızı paylaştım, artık conti pahalı diye almıyoruz ucuz gruba yöneldik dedi. Kumho fiyatı verdim görseli gösterdim beğendi ama 24 kat olmadığı için değerlendirmek istemediğini söyledi. Yanında 7 arabası olan başka arkadaşı vardı onada fiayat verdim ama ilgilerini çekmedi. 315/70 Brdgestone fiyatı sordu düz ve çeker onlarıda vereceğim.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('06a69099-4267-5147-8283-5c4174a49048','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ÖZTÜRK YAPI' AND il IS NOT DISTINCT FROM 'KIRKLARELİ' LIMIT 1),'d91b094a-4c5c-522b-8c59-414dd4b394ea'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-06-23',NULL,'Musatafa bey ile ofiste buluştuk, sonra kademeye geçip loderin lastikeri inceledim, 2 kaplama 2 yeni ihtiyacı var. Ayırca tbr kaplamaları kontrol ettim 2 hurda lastiği attık. 3 adet 26.5-25 bize kaplatıp kullanmadığı lastiğe baktım teklif edeceğim başka yerlere. sonra ofise geçtik kaplamalardan olan 212.000TL nin tahsilatı yaptım. 2 adet yokohama ve 2 kaplama için fiyat verdim, bu hafta içi haber verecek.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('518105c5-381e-5044-8b40-4a2e3fcd9fd6','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ÖZBERCE MADEN' AND il IS NOT DISTINCT FROM 'KIRKLARELİ' LIMIT 1),'ee0c2882-ee38-514c-82e7-c3273ee6e8d3'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-06-23',NULL,'Saha halen çok aktif değildi, Ergin beye baktım ama yoktu. Durumlarını halen toplamış gibi değiller. 3-4 ay sonra yine uğrarım.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('f8359f0a-0814-558a-b797-b1c199993adc','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='TRAKTAŞ MADEN' AND il IS NOT DISTINCT FROM 'KIRKLARELİ' LIMIT 1),'5ea9cdec-118a-5751-b578-2bf291b5bd2a'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-06-23',NULL,'İşleri halen ortalamada devam ediyor, çok istedikleri gibi değil, mühendisleri izindeydi, müdürleri ile görüştüm. Vadesi dolan için ödeme talep ettim cumaya kadar ödetirim dedi. Şuanda bir talepleri yok, 2 ay sonra loderli ölçümeye geleceğim.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('97936efb-3b58-5916-b4ed-fb4594c2d422','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='AKÇANSA' AND il IS NOT DISTINCT FROM 'KIRKLARELİ' LIMIT 1),'a51822a6-ed73-5cc2-9609-4cbad5720cbe'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-06-23',NULL,'Buradaki tüm makine ve kamyonları diğer tesislere dağıtmışlar loderi geçen hafta bursada görmüştüm tesiste. Buraya akçansa taşerono Selim Usta firması gelmiş. Yetkilisi ile görüştüm. Yeni lastiklte direkt olarak Petlas ile çalışıyorum, kaplamaları atlı ve tatko ile çalışıyorum dedi. bizdende fiyat almasını talep ettim, çalıştığım yerler ile sorun yaşamıyorum macera peşinde koşamam dedi. sonrasında akçansa genel tesisler makine müdürü Cahit abiden aramasını rica edeceğim.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('6b2811e8-21fd-5528-ba0d-7a82c35ba559','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='KALYON' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'3c8c41e1-a531-5fee-b022-b8fd6835a540'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-06-25',NULL,'Ekrem bey ile makine ikmal ofislerinde görüştüm, geldiğin iyi oldu bir konum vardı dedi, Iğdır kaplama işini çözmem gerekiyor, Tatko, Kavi, Yılmazlar ve Akdeniz kaplama fiyat vermiş. Asım Cengiz Kavi ve Yılmazlar diye baskı yapıyor dedi. Bende telefonda bize de benzer söylendiği için çok asılmadığımızı söyledim. akdeniz kim diye sordu bildiğim kadarı ile açıkladım. Saat garantisi konusu nedir dedi Ccengiz istiyor dedi bende kandırmacadan ibaret çünkü her sahanın gerçekleri farklı bu operatöre göre bile aynı saha içine farklılık gösterebilen bir durum dedim. nasıl garanti veriyorlar peki dedi çünkü kimse takip etmiyor dedim, çok doğru diyorsun dedi. ben bu kaplama işini çözeceğim orada dedi. bursa da verdiğimiz raporlama ve diğer hizmetleri anlattım biliyorum sizin tarzını çok sağolun dedi. oraya gidip bakamamı isterseniz bakabilirim dedim, hiç gerek yok gideceksin oraya sonra işi başkasına verecekler olmaz dedi. Zaten cengizin lastik satan adamı sürekli görüşmek istiyor randevu vermiyorum dedi. Sizin brisa işin çözmeniz gerekiyor dedi, çözüldüğünü söyledim sevindi. Iğdırın yeni lastiğine neden teklif vermedin dedi sormadılar dedim, bunun üzerine 15 dakika kadar bilgisayarına gömülüp bir şeyler aradı söylenip. sen ne fiyat verirdin diyei söyledi 13R22.5 7500 için bende ihale fiyatını söyledim, Cengiz fiyatı 16.300TL+KDV dedi. Bziden teklif almaları için arayayım mı dedim sen birşey yapma gerekli şeyi yapacağım dedi. Bursa ihale için destek istedim bakacağım önüme gelmedi daha dedi. genel olarak güzel ve verimli geçti.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('a2b78348-efbb-5a6f-a69a-8c461d91547e','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ÖZGÜN BETON' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'f843ee92-71d0-5e29-8131-3ed816c4a93d'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-06-25',NULL,'Satınalmaya Okan bey bakıyor. Edirnekapı ve Cenderede 2 tesisleri var. 30 kamyon ve 2 loderleri var. Dışarıdan iyi bir görüntüleri yoktu, yanımda telefonda arkadaşı aradı görüştüğüm kişiyi firma adı  konusu oldu yeni değişti sürekli isim değişiyoruz dedi. çok uzatmadım sonra yine arada takip edeceğim.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('7072aae1-7172-57de-8761-2b3b8efcf77f','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='GÜMÜŞTAŞ BETON' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'f4550397-67e0-5f37-81f6-d4e42ef89d97'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-06-25',NULL,'Cendere tesislerini ziyaret ettim, ofiste beni karşılayan kişi lastikçi olduğumu söyleyince biz tatko ile çalışıyoruz dedi ve arkasını dönüp gitmeye başladı bende biliyorum ben tanışmak ve görüşmek istemiştim dedim. Gerek yok dedi döndü gitti. En azında güvenlikten siktir yemedim diye teselli olup ayrıldım.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('1ac6b1e4-7e5a-5022-b1b1-08254bf91bdd','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='AKDAĞLAR GRUP' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'7ca7b93d-066b-5fcf-b913-e45da6d1fb4a'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-06-25',NULL,'Her geldiğimde satınalma değişmiş oluyor yine değişmiş. Kadir bey bakıyormuş. Fakat yine patron lastkaptan kendi alım yapmaya devam ediyormuş bizim bir yetkimiz yok fiyat alıp onu söylüyoruz o da hep laskaptan alıyor dedi. Bendende fiyat almalarını istedim ve ayrıldım.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('718884b9-975e-59ed-80d4-f4e945a67173','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='BAHAR MADENCİLİK' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'59303ce3-3fb5-56f9-be9e-b89a25ec5247'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-06-25',NULL,'Ankara merkezli Ordu ve Sivasta altın madeni olan fimanın taş ocağı burada patronları Ramazan beyde burada duruyor. Tanıştım beraber çıkmı 2 loder lastiğini inceledik çöptü. 29.5R25 kullanan loderin arka lastikleri kaplama zamanı gelmişti ankara satınalmaya ilet senden fiyat alsınalar dedi. ilettim aradım açmadılar yarın ulaşarım takip edeceğim. burada 2 loderleri var.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('59c7bece-e28d-5f34-a9c8-11b2d0aebf86','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='İSLAMOĞLU MADEN' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'4f7339db-5180-5568-8ed4-e958b1c93205'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-06-25',NULL,'sahayı Boğaziçi betona kiraya vermişler kendilerinin hiçbir ekipmanı yoktu sadece ofisleri vardı.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
