INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('3d9a034a-f3e3-58fb-b7c5-c69b500793e0','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='OYAK BETON' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'271f4ddb-caf5-5702-bddc-6cec55073e68'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-06-25',NULL,'Cendere taş ocaklarını ziyaret ettim tüm satınalma işimizi kurtköy tesisimizden yapıyoruz burada yetkili yok dediler. Haftaya planlayacağım.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('6770f504-c3f9-5f60-a64f-bef847ce554b','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='BOĞAZİÇİ BETON' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'11951ff9-4ab1-549e-98e2-a44939d38e1a'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-06-25',NULL,'Hakan bey yine yoktu fakat busefer diğer genç arkadaşlar benimle görüştü. Pirelli ile kontrat imzalamışlar, tüm işi tatko yapıyormuş. Kaplama promotec. Yeni lastikte sabit fiyat alıyorlarmış hatta bir süredir zam talebi varmış pirellinin kabu etmiyorlarmış. otr kaplama geçen yapıtırdık siz yine fiyat atın sunarız dediler. 600 kamyon 32 loder çalışıyor. Finalde Hakan bey karar verici fakat randevu taleplerimize dönmüyor sadece bir kere görüştük önceden hedef fiyat verdi düştüm ama işi yine vermedi.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('cf657e41-e2f5-5e75-b25d-5d85b67b81a1','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='TAŞ YAPI' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'037e0d20-1c9a-5160-8fb2-20989fad43a1'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-06-29',NULL,'Fırat bey ile görüşmem vardı, güvenlik haber verince geliyor bekleyin dedi odasına almadığı için şaşırdım lobide görüşmeden yollayacak heralde dedim. Gelince bana çok değişmişsin dedi, bende sadece traş oldum diye geçiştirdim, bana ev anahtarı verdi al bakalım dedi, baktım Fırat beyin hatlar gitmiş (yaşı oldukça var) kendimi tanıttım daha da karıştırdı, müsait değilseniz ben gideyim dedim o sırada normale döndü odasına geçtik, evini satılığa çıkarmış emlakçıyı bekliyormuş anahtarı geri verdim. 2. şok dalgası Ali Kazemi odasındaydı aynı yaşta daha laf anlamaz yardımcısı ile ilk kez yüz yüze tanıştık onuda emlakçı olmadığıma ikna ettikten sonra o da benim çok değiştimi söyledi 3 kere felan ilk kez görüşüyoruz yüz yüze dememe cevap vermeden tanıyamadım seni çok değişmişsin dedi. görüşmenin 30 dakikası tandığım bu yaşlı şeker adamlara kendimi hatırlatmak ile geçti. sonra Fırat bey sen gidebilirsin dedi bende lastikleri almazsan gitmem dedim, aldığı teklif tablosunu açtı baktı indrim için brisayı aramamı istedi. sizi aradım ilk açmadınız, memduhu aradım, ilave 1 verdi 6 daen 7 ye. oraya sonra senle gidelim dedi. Fırat beye fiyatta indirim yapamayacağımızı söyledim. ben seni arayacağım yeni lastikler ile ilgili dedi. geçen aldıkları izmirin lastiklerini sivasa gönderttiler bana yanımda izmir şantiyesi lastikleri sordu onayladık ama nerede takıldı dedi Ali bey. Hatlar odada çok karışınca kaplama için alınan 6 adet 17.5R25 ve 4 adet 26.5R25 leri söyledim indirim için seni arayacağım sen işleme başla dediler bende daha fazla yanmadan çıktım. arada emlakçıda geldi onuda yaktılar. yan ofise Özden hanıma uğradım satınalma sorumlusu kendisi fakat anlamsız bakıyordu çok yoğunum lütfen onlar birşey için size onay verirse siz söyleyin bana diye rica etti. konuyu anladığımı kibarca ifade edip güncel taleplerin olduğu konuları ve teslim edilenleri aktardım ve müsade istedim.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('aa335b78-7b03-5826-9a6c-7a6ab829b1a2','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='BRİSA' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'deef21e3-461c-544b-b94a-65c4c0f073cc'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-06-29',NULL,'Engin ile dışarıda bir kafede buluştuk, genel sohbet sonrası tabloyu açtım tüm fiyatların üzerinden tek tek geçtik. Hepsii katıldığını söyledi ve tablo için çok teşekkür etti. japonların zam için geldiğini bu fiyatları kullanıp zammı püskürtmeyi düşündüklerini söyledi. saha verisi alamadıklarını artık işin ayağa düştüğünü söyledi. ortalama %5 zama bezli limana %15 gibi bir zam olacak istersen biraz stok al dedi. bezli ors için 300 adet ve üzerine ilave vereceğiz yıl sonu %3 Fatih beye söylersin alım düşünürse dedi. OTR PD işini aktif etsek sağlıklı veri alırmıyız sahadan dedi bende alamayız kimse sadece OTR için adam koymaz yan dal olarak sana sabunlama veri akar dedim. bana az da gelse yeter şuan hiçbir şey gelmiyor dedi. bende OTR odaklının bir şekilde ayrılması gerektiğini söyledim, İGA daki 26.5 için Gürlas örneğini verdim adam sevkli senden 2 puan ile mal gönderiyor ben iga da 10 yıldır sahadayım burada rekabet şansımız yok maliyetlerimi farklı dedim. haklısın sahada olanı %7 gibi bir isk ile korumak gerek yoksa çalışmaz dedi. benimle saha ziyareti yapmak istediğni söyledi haftaya 1 gün dedi, haftaya izinliyim sonraki hafta için yapalım dedim, nuh çimentoya gidelim dedi olur dedim. izmir için buldukları adam olmamış halen pozisyon açık dedi, bildiğin otr satış tecrübesi olan ingilizcesi olan biri var ise bize söyle dedi. aklımda biri yok Fatih beyede söylerim onunda aklına biri gelir belki dedim yok ona deme lütfen adam arıyorlar konusu olmasın dedi. adam konusunu uzattı bana mı iş koydu tam anlamadım üstünde durmadım. sen git abi izmir evin orada dedim benim beklentim var olmazsa farklı şekilde kesin döneceğim zaten dedi. pandeminden sonra OTR pazarının büyüdüğünü söyledi bende aksine büyümediğini düşündüğümü söyledim, küçüldüğünü söyledim. özetle fiyatlarda benimle hem fikirdi. ana rakip bizim için Gy dedi.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('3c522fe9-9f54-5357-9bee-97e681bd47c2','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='KALYON' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'7fc96750-eddb-5840-b7e3-7393fe018052'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-06-30',NULL,'Bursa hızlı tren şantiyesinin ana yerleşkesine satınalma ve finanstaki görüşmelerim için gittim. Satınalmadan Bilal bey ile tanılştım hep telefonlaşıyorduk ilk kez yüz yüze görüştük, bir kez de telefonda biraz gerilim olmuştu önceden bu sebeple özellikle onu arayıp gittim. beni sıcak karşıladı genel sohbet ettik. kamyon alımında en son indirimi yapmadan herkesin fiyatı aynıydı ondan senden indirim istedim dedi. 40 ile fiyat vermiştik 41 yapınca bizde kalmıştı. sonrasında diğer firmaları arayıp bir daha indirim istemedim sende kalsın diye dedi. 315/60 düzz talebi için gelen markaları okudu yorumlarımı istedi. Makine müdürü Serkan abiye karacabeye geçecektim o da toplantı için oradaymış toplantısı bitince o da katıldı bize, düz tipler için Petlas varsa al dedi bende hemen petlas teklif ettim. Serkan abi ile görüştük, kaplama zammı diye gelme sakın çok taciz ediyorlar iş karışır gidebildiğin kadar git dedi. ölçüm ve raporlar üzerine biraz konuştuk. sonrasında finanslarını Ersin beye gittim. son kesilen yeni lastik faturasını da dahil ettirip tutar için çek talep ettim. temmuz içinde çekin hazır olacağını söyledi. genel olarak tren şantiyesindeki kontaklarımla görüşmelerimi yaptım.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('aafc4f1c-7f7b-5690-82fb-7033ab217c82','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='MUTAŞ' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'4439c57d-53fb-5824-8167-aa23e6e529f8'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-06-30',NULL,'Ece hanım ile görüştüm, Kümaştaki işleri bitmişti ama bu hafta bize kaplamaya lastik verince çalıştıklarını anladım, sordum. Normalde sözleşmemiz bitti, yeni ihaleyide maraşlı tekno diye bir firma aldı o da Mehmet Ünaldı ya taşere etti, bizim bir işimiz yoktu ama ihaleyi alan firma ben maliyetimi yanlış hesapladım zarar ediyorum diye oyak tarafına itiraz edince bizden 2 ay daha çalışmamızı istediler onu çalıştık ama biraz daha devam ediyoruz. Oyak biz kendimiz makine koyacağız dedi onu bekliyor ve çalışıyoruz fakat oyak tarafının ne yaptığı belli değil devam de etmek niyetinde değiliz dedi. yeni kapalı maden işleri henüz netleşmemiş şimdilik ellerinde yeni işleri yok. takip edeceğim.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('e75deff4-0716-5fd2-9b4b-3b78375a8d45','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='YAFA İNŞAAT' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'8c43afaf-5ef4-58ce-b3f9-59126920505e'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-06-30',NULL,'yeni lastik talepleri sonrası satınalmayı ziyaret ettim, henüz değerlendiriyoruz dediler. Asıl kontağım müdürleri Yıldıray bey yoktu adıyaman şantiyesine gittmiş ziyarete, 2 hafta sonra onu ziyaret edeceğim.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('d9962321-3211-58b9-833e-6026c50cc4b8','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='SEVTAR' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'5f69cf77-b6a3-52e3-a8c6-23cc1b7beadb'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-06-30',NULL,'Özgür ile görüştüm, yanımda telefonda petlas tbr siparişi geçiyordu, kapatınca kimden alıyorsun dedim, bayiliği var bizde direkt alıyoruz dedi. İşleri yavaşlamış oldukça. Atlı bölgede her yerde 35 üstü iskonto ile bunların tüm düzenini bozmuş sürekli şikayet ediyoruz ama sonuç yok dedi. bizden ayrılan çocuk bursalı zaten o geziyor. bir de yakıt satıyorlar burada onda da millet bezdi çok agresifler buradaki yerellerden ucuza veriyorlar dedi. sizin yoklukta birde batmanlılar dadandı biraz buraya iyici bozuldu bizim huzurumuz dedi. bende genelde tbr için değil otr odaklı yine buralardayız dedim. konu cihan gruba geldi, günmarlas vermiyormuş artık en son vade ile ilgili ciddi sorun yaşamışlar, firmanın ödeme ahlakı ciddi bozulmuş. biz ve atlı kapışıyoruz ama aradan goodyear sıyrıldı en son partiyi onlar verdi de. bir firma eskisi gibi değil lastikte çizik görse söküp getirip alın bunu garantiye diye olay çıkarıyor dedi. ellerinde 4 adet 23.5 vjt varmış 45 isk ile teklif ederim satılırsa alırım senden dedim tamam dedi. kaplama işini bıraktık artık hiç peşinden koşmuyoruz dedi.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('8b00ad98-3cc1-5583-9586-b1f1885b208f','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='OYAK BETON' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'271f4ddb-caf5-5702-bddc-6cec55073e68'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-07-01','ADNAN KARAKAYA','Anadaolu yakası müdürlüğününde içinde olduğu kurtköy tesisini ziyaret ettim. Anadolu bölgeye bakan Ahmet bey ile görüştük. Adnan abi daha önce kendisine birkaç kez ulaşmış ama sonra telefon ve mesajlarını geri dönmemiş. Ahmet bey anadolu bölgesindeki 9 tesis ve taş ocağının teknik sorumlusu. Avrupa yakası bölge sorumlusu Enes bey Cebecide duruyormuş ,geçen hafta uğramıştım ama görüşememiştim. ayrıca 3 bölge daha varmış. kaplama için tüm tesisler dilerler ise bağımsız dilerler ise bölge sorumlularından destek isteyerek hareket edebiliyormuş. fakat yeni lastik için merkezde Sinan bey pratis portal üzerinden alıma çıkıyormuş ve Petlas ile direkt çalışıyorlarmış. Akçansadaki durumda tamamen böyle. Adananın en son verdiği teklifi yüksek bulduklarını söylediler ve indirim talep ettiler bende ürünlerimizi ve hizmetlerimizi görmeleri için özel bir fiyatlama yapacağımızı söyledim. Tesislerin lokasyon bilgilerini aldık Adnan abi hepsini ziyaret edip bir tespiti olursa Ahmet beye bilgi verecek, bende denk gelenleri ve Avrupa bölgeyi takip edeceğim ayrıca 2 hafta sonra ankara programımda Sinan beyi ziyaret edeceğim.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('9e9bdd17-9a4f-50b4-9e2b-7189ea1f9938','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='HİLAL TRANS' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'2449cb85-e6e3-5a71-9c28-77299390544d'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-07-01','ADNAN KARAKAYA','Naci beyi orhanlıda ziyaret ettik, araç sayılarının 1.600 e kadar yükseldiğini söyledi. Girişte GY basınç okuyucu duruyordu bizim arabanın basıncınıda 36Psi olarak ölçtü. Bayiliği aldığınızı duydum hayırlısı olsun dedi. Çavuşoğlu gitmiş buradan dedi, Naci bey lastikçiler ile sıkı diyaloğa devam ediyor halen belli. 385/55R19.5 Sailun konusunu açtık, devamının olmadığını eldiklere özel bir fiyat ile değerlendimelerini söyledik. önce sıcak bakmadı sonra ilgisini çekti. bana bir fiyat diyin bende bakayım dedi. sizinle konuşup fiyatı verdim sana döneceğim dedi. çıktıktan 2 saat sonra beni arayıp lastiklerin görsel ve teknik verilerini istedi gönderdim. yarın yine arayı p takip edeceğim','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('8becf248-5f18-525a-a551-50c2e50caf45','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='BİLEK TRANSPORT' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'f41aa512-45b9-5a8b-9756-9d683ff657eb'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-07-01','ADNAN KARAKAYA','Conti arızadan 1 adet 315/60 ecoplus için zorla kasım abinin scanina baskısı ile ödeme çıktı. Kasım abide lastiği yollayın 3 adet var takımı yapayım takayım dedi fakat conti ecoplus üretimi durdurmuş Kasım abide ödemeyi kabul etmiyorum bana ya 1 lastik verecekler yada kalan 3 adedi geri alacaklar dedi. kendisi Scania üzerinden Conti ile mücadele ediyor. son 2 yılda 20 ye yakın scaina aldığı için orada sözü geçiyor. 385/55R19.5 için ondan da destek istedim. bize 2 kontak verdi bunlara selam söyleyin onlarada var dedi. Adnan abiye iletttim numaraları. 1 adet 385/55R22.5 OE çıkması lastik almışltık 2 hafta önce onu antalyada birini bizim adımıza vermiş adam seni araycak dedi. 55 serisi Kumholar çalışıyor sorun yok. Sailun 55 serileri çalışıyor ve çok memnun. Conti 55 ona özel getirdiğimiz ecopluslarda çalışıyor.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('ea259453-aeaa-5366-96be-6b88835e2412','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ABS LOJİSTİK' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'e5138eb9-79c2-5d1e-8058-53405fa0a1e4'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-07-01','ADNAN KARAKAYA','Ben Adnan abiye devrettikten sonra ödeme sorunu yaşamışız ve ilişikileirmizde kopmuş. Eski kontağımız Selçuk ve Murtaza ayrılmış Adnan abiye de patronlar yurtıdşında diye kontak vermemişler. Patronları yerleşik ingilterede yaşıyor Abdullah bey. Fakat burada ortağı olan amcası Emrah amca var onu aradım yurtdışındayım aradağın iyi oldu işim var seninle haftaya dönünce arayacağım seni dedi. garajdaki diğer kişilere uğrayıp ayrıldık.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
