INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('ae76e74f-5548-5a12-b031-a59fb24f1661','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ERTA GERİ DÖNÜŞÜM' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'7823eea1-6d88-5f60-8a44-ac8892838f06'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-07-01','ADNAN KARAKAYA','2 loderde yatıyordu, tırlara tesisi söküp yüklüyorlardı. Çok zarar etttik bu işten kapattık aksaraya geri dönüyoruz dediler.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('27c612aa-ccab-5298-b390-75d74b0f8090','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='BAŞKA İNŞAAT' AND il IS NOT DISTINCT FROM 'KOCAELİ' LIMIT 1),'3e7b0f32-07b3-52eb-b012-3a5b801829f9'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-07-01','ADNAN KARAKAYA','Kademeye uğradık 2 adet yeni bezli galaxy almışlar. Bizdende fiyat sormuşlar ama Adnan abi sadece radyal teklif etmiş daha doğrusu adamlar bezli diye sormamış bizim fiyat yüksek olunca bezli almışlar. Loderin arkalarının kaplanmaya ihtiyacı vardı, Adnan abi fiyat vermişti bir daha dürttük, onayı geldi lastikleri kaplamaya alacağız.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('6dc18f0f-4e8c-568a-867d-6c992c3ecb4a','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='AKÇANSA' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'acde648f-42c4-54c0-b5f3-c1dcf4221b6a'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-07-02',NULL,'Tüm tesislerin teknik müdürü olan Cahit bey ile arge merkezlerinde görüştüm, şantiyeden tespitimde sorun yaşarsam hemen destek oluyor bazende kendisi direkt yönlendiriyor. 4 yada bir uğruyorum arada da telefon yapıyorum. Yeni ekipman pompa alımları vardı yoğunda. almanların satınalma işlemi tamamen bitmiş eskiden gmy olan birini tekrar çağırıp ceo olarak atamış almanlar onun dışında hiç bir değişiklik yapmamış. artık sabancı bayi kalmadığı için yeni lastikte alımlarda destek istedim, beni merkezde yasemin hanıma yönlendirdi. sen yine tesisleri gez lastik ile ilgili konuları yaz bana dedi.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('2ab72524-694e-5cba-a998-e11d86920a0d','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='GÜLERMAK' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'3a68b16d-1b01-5da5-b2d5-4bd82e850653'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-07-02',NULL,'Kademeye gittim 30 kadar kaplama lastik vardı, bizdeki kaplamaları bekliyorlar. Kakdeme mühendisi ile görüştüm. Kaplamaları haftaya yollarım ama yeni lastikleri ödeme almam lazım sende lastik kalmadı diye satınalmaya baskı yap dedim. Ödeme odaklı herkesi bilgilendirdim. takip ediyorum.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('d16b0243-0274-57de-98d2-09a8071e55d8','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='AKÇANSA' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'acde648f-42c4-54c0-b5f3-c1dcf4221b6a'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-07-02',NULL,'ilk zamanlarından beri çalıştığımız tesis, biz 15 yıla yakındır çalışıyoruz burayla, halen müdür Sedat bey formen Cüneyt bey var. Test kaplamalarını ölçtüm, 36-38 ve 40mm bandındalar aşınmalarında sorun yok, takılış formuna bakınca ayrı mailde çalışma saatine paylaşacağım. diğer loderin arka lastikleri kaplama zamanı gelmişti. Sedat beye bilgi verdim, program yap al ne zaman dersen dedi. elimizde yedek boşta yok 2 haftamız dolu olduğu için 15 güne planlarım acil değil dedim kabul etti. Tesis çok yoğundu Akçansanın en yoğun tesisi burasıymış.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('11400f50-c6ff-55c4-aa86-206034e72057','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='OYAK BETON' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'271f4ddb-caf5-5702-bddc-6cec55073e68'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-07-02',NULL,'Loderin lastikleri kaplama zamanı gelmişti fakat yetkili kimse yoktu görüşemedim, burası için avrupa bölge müdürü Enes bey cebecide ilgileniyor onu ziyaret edeceğim sonra.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('0e6c463f-05d1-5186-9f9c-eae8bab4a9f9','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa','6028c04f-1f20-4d70-bb91-53414f5ad69d'::uuid,'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-07-02',NULL,'Sevan abi Atlı bartu ile hurda aküden dolayı tartışmıştı iyice ayar olmuş artık lastik ticaretimi kestim patronlada konuştum dedi. Bana onlardan aldığım ucuz leoa karşılığı ürün bul dedi. Bende biraz daha pahalı ama kaliteli kumho önerdim olur alırız kumhoyu adadaki kamyonlarda ucuz ürün alıyorum dedi. fiyatları atacağım. kaplama için marangoni karşılık bandag olabilir dedim ama 8.750TL+KDV ye kaplatıyorum dedi, veloxia yada avon+ olarak teklif atacağım. Beton işleri tutmuş ve çok yoğun. 10 mikser, 3 pompa ve 2 loder beton işlerinde. 12 tır ve 12 treyler hammadde sevkatında. 15 kamyon ve 3 loder ada da dolamit ocağında aktif çalışıyor. Yakıt işinde en ucuz Atlı orada alternatif bulamıyorum dedi, bursa bölge ziyaretimde de aynı şeyi duymuştum adamların ucuzu motto edinmiş ne satarlarsa ucuza satıyorlar. Koplastaki Latif ayrılmış ve kendi adına iş yapacakmış ziyaret etmiş. kaplamaları bizim için sevindikliye getirmeye çalışacak.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('392cf075-5df9-56a9-9925-d90ae6881df3','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa','8b1ab4be-de03-4a62-a51b-249550f385e3'::uuid,'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-07-03',NULL,'Çimnak müdür yardımcısı olan ve lastik işi ile ilgilenen Yusuf Menteş bey terfi etmiş liman müdürü olmuş. Limanda hayırlı olsun ziyareti yapmış oldum. Eski işime geri döndüm çanakkle içdaş limandaydım ben büyükler burada diye gelmiştim zaten bu tarafa geçmek istiyordum dedi. içdaş içinde tatko tekeli var orada iyi kontaklarım var sana omuz atarım dedi. 18.00 lerin siparişi gelmedi mi hala dedi hayır diyinvce yanımda murat meriçi aradı o da evet kardeşlerde kaldı ama imzada olduğu için geçemiyorum siparişi dedi. Daron geldi GY teklif etti dedi. şimdilik çimnak tarafı bende sen benim yardımcım safa ya da git dedi. artık safayı daha merkeze alacağım ziyaretlerde. kaplama için ona dönmemişler not aldı sana haber vereceğim yüz yüze görüşmem gereken bir konu bu satınalma ile dedi. 315/70 leri sordum bilmiyorum amaöğrenrim talep bana ait değil di acaba nereye aldılar dedi. 26.5 ları petlas aldık çok ucuza geldi dedi. çok yoğundu sonra yine ziyaret edeceğim. fakat Safaya daha fazla odaklanmam gerekecek.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('5cefa147-7c0e-59cc-a494-3915bd1f3b6e','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='BAYBURT GRUP' AND il IS NOT DISTINCT FROM 'TEKİRDAĞ' LIMIT 1),'dd27b7a8-4fa5-57f6-a7c1-f65232d7dc03'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-07-13',NULL,'Ömer bey ile görüştüm, bu şanityede değilmiş artık, buradaki işimiz bitti, ben bakırköy şantiyeye geçtim dedi. Kaplama için olan lastikleri de merkeze kaplama için gönderdim dedi. Erkan bey beni Ömer beye yönlendirmişti Ömer beyde yine Erkan beye yönlendirdi. ilk ankara ziyaretimde Erkan bey ile kaplama işini çözmek üzere görüşeceğim. biraz beni salladığını hissediyorum.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('e4235846-b170-586c-b5af-179883c3e98b','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ÇALIŞKAN MADEN' AND il IS NOT DISTINCT FROM 'TEKİRDAĞ' LIMIT 1),'89b6d9e1-d861-550c-a3e2-9b484a774f8b'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-07-13',NULL,'Merkezlerine tahsilat için uğradım 960.000TL çek aldım.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('08213f39-1179-5819-976a-5b957323cdb3','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='İMPAZ MADEN' AND il IS NOT DISTINCT FROM 'TEKİRDAĞ' LIMIT 1),'19779e04-5d37-5d3f-b682-d686342771a5'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-07-13',NULL,'Mehmet bey ile görüştüm, contileri takmışlar. Kum işi oldukça zayıfladı buradaki ocağı kapadık diğer ocak açık dedi. Şimdi tahıl zamanı araçlar tahıl nakliyesine koşuyor onun hareketi var ama genel olarak keyifsiz dedi. 2 ay  içinde 315/80 conti talebim olacak şuan stok var dedi. talebi öne çekm eyei çalıştım ama en erken 1 ay sontra görüşelim dedi. takip edeceğim.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('75b9b74d-8312-504d-ae5c-d2c34d1480d3','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='MERT KUM' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'64a32528-46f9-5b73-9b02-3f819422719b'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-07-13',NULL,'Aşağı ocaklarına uğadım, burada izin sebebi ile kum işini durdurmuşlar, beton mikserlerinin de  çoğu yatıyordu. Lastik için Yasin formene diğer ocağa bak dediler. Yasin normalde burada duruyordu.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('c074953a-ac45-5768-9e77-f01055c15e9a','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='BEYKUM' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'e7ca8ed7-87a5-535a-8a6f-6dc8b7d63b13'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-07-13',NULL,'Mühendisleri Gökhan bey ie görüştüm, halen Tatkodan alınan yüklü stok bitmemiş, Mehmet Turantaş ayrılmadan buraya toplu bir mal vermişti, 1 yıldır hiç lastik almadık dedi. İşleri var ama çok istedikleri formda değilmiş. 3-4 ay sonra yine yoklayacağım.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('df0218ce-e835-5644-9106-ea1ec44b42f6','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='AYDINOĞLU MADEN' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'72ed3d59-a774-54fd-ac0f-2692f2d44333'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-07-13',NULL,'En son uğradımda ara verdikten sonra açmaya çalışıyorlardı, tamamen açılmışlar ocak aktifti. Loderin 1 tanesi iş az diye yatıyordu. Diğer makinede takip ettiğim kaplamaya çıkacak lastikler var halen durumu iyi. Ömer bey ilgileniyor patron. 2-3 ay sonra yine uğrayacağım.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('d8d87a96-7860-52df-a5c2-b0901e9e0d67','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='MERT KUM' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'64a32528-46f9-5b73-9b02-3f819422719b'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-07-13',NULL,'Sinekli ocaklarına uğradım, Yasin formen buradaydı, diğer ocak izindedn dolayı yatıyor burası çok aktif dedi. 315/80 ön ve çeker fiyatı sordu. Aynı teklifi beton santraline de ilet onlarda alım yapacak dedi. Loderlerin durumu iyiydi.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('af19581a-dd35-52c3-9606-9ac2ba6abb62','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ÖZKUM' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'0c186150-1f24-5036-bd6c-ad825adf64df'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-07-13',NULL,'3 loderi de sıfırlamışlar, hepsinin lastik durumu iyi. Ahmet şef ile görüştüm. Bölgedeki en büyük ocak olmuşlar. Kaplama işi sende ama makineler sıfırlandı dedi. Sezon sonunda doğru ilk gelen komatsudan iş çıkabilir 2-3 ay sonra uğrayacağım.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('5382d354-9290-5fae-94ed-beb57c05117b','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='KALAYCI KUM' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'1feb2c7e-0e14-5ba5-a731-92f04b3d720c'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-07-13',NULL,'Alımlara Yüksel kalaycı bakıyor yoktu fakat oğlu oradaydı. İletişim bilgilerimi aldı. Babamla görüşüp ileteceğim dedi. Yüksel beye denk gelemiyorum her geldiğimde uğruyorum. Ocakta iş kazası olduğu için bölgedeki tüm ocakları incelemeye almışlar biraz tedirginlerdi.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('0182f387-fbde-5a16-a633-79912c76d33e','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='SAFİ PORT' AND il IS NOT DISTINCT FROM 'KOCAELİ' LIMIT 1),'ba5f7956-d60c-5c8f-ac7c-0c25d7087e0a'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-07-14',NULL,'En son 3 ay önce ziyaret etmiştim, genel tüm kadroları ziyaret ettim. Satınalma Buse hanım doğum iznine ayrıldı dün yerine bakan Nur hanım ile toplantımız vardı. Kendimizi ve süreçlerimizi anlattım, Korda geçmişi olduğu için bizi biliyor ayrıca Hakan Safi nin oğlu Arif Safi bizim ile ilgili hassiyeti iletmiş her teklifi mutlaka onlara sorun demiş. Fakat marka için hep en ucuz neyse onu alma eğilimdeyiz patron böyle ilerliyor dedi. 22 tbr kaplama ve 2 otr kaplama vardı onların onayını aldık. Sonrasında müdürü İsmail Arpa beye uğradım, genel sohbet ettik, Brisa tarafı başladı dedim haberim oldu hayırlı olsun dedi. sonrasında kademeye lastikçi Cemile ustaya uğradım eskiden Fatih usta vardı o da ayrılmış, Cemil usta ile biraz vakit geçirdim, kaplama ve lastikler hakkında görüştük, iletişimde olacağız. sonrasında teknik direktörleri eski kontağımız Barış abiye uğradım. genel sohbet ettik, limandaki inşaat 1 yıla bitecekmiş ve alan olarak en büyük olacağız dedi. ilk durumun 3 katına denizi doldurup çıkıyorlar inşaatı da kendileri yapıyor. Barış abiye Hakan safi ile olan durumu anlattım iyi yapmışsın dedi, şimdi o işi oğlu Arif e bıraktı Arifte kendini kanıtlamak için en ucuz neyse onu alarak kar edeceğini sanıyor neler yaşıyoruz bilemezsin dedi. vinçler için kimsenin almadığı yerden halat aldık başımıza gelemeyen kalmadı. terminal traktörleri çin malı alıyorlar. herşey için tek mottoları var en ucuz neyse o biz işi biliriz kafasındalar dedi. teknik olarak tüm lastik alımları benim onayıma geliyor ama finalde Arif karar verici ben ne desem boş dinlemiyor dedi. ama sen yinede sıkıştığın her yerde ara beni konuşurum anlatırım dedi. sonrasında beni alıp bakım müdürü Göktuğ beye götürdü, eski dostumdur her konuda teknik oluru vereceksiniz dedi. Göktuğ bey kaplamalar için olur verdik zaten dedi. bir sürede orada süreçler hakkında sohbet ettik. genel olarak hakan ve arif safi hariç her kontak ile görüştüm, uzun ama verimli bir görüşme sinsilesi oldu. buradaki amacım marka algılarını yavaş yavaş yükseltip bizim ürünleri daha çok satabilmek','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('0a5057bb-1af9-5d7b-9ca7-ce85666f1390','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='EGE ALİAĞA' AND il IS NOT DISTINCT FROM 'KOCAELİ' LIMIT 1),'174c7dfc-f5c5-5277-8c39-f930cfa0324d'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-07-14','ADNAN KARAKAYA','Adnan abinin sahaya gitmem talep ve baskısı sonucu gittim. Harso Tosyalı tesisindeki taşeron firma, curuf yüklemesi yapıyor loderler. Makinenin 4 lastiği kaplama zamanında Adnan abi anlaşmayı sağlamış. Karkaslar petlas marka ama kaplama olur durumda. perşembe günü turgay arka 2 lastiği alacak sonrasında kaplamaları öne takıp arkalara takacak emanetleri koruyacağız. Tatko müşterisi firma. desen konusunu görüştük anlaştık.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('87b6be1f-e53f-5ea4-ac59-037bee09ada6','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='BAYBURT GRUP' AND il IS NOT DISTINCT FROM 'ANKARA' LIMIT 1),'06fb320a-a960-5765-9444-47611a6cf8f0'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-07-16',NULL,'Erkan bey ile görüştük, beni uzun süredir Mehmet Ali diye anıyor öncelikle kimliğimi ibraz ederek Ali Kemal olarak tescil oldum. Kayseri şantiyesine 19.5 jantları onaylamıştı dün. Bugünde 40 adet tbr yi onayladığını imzaya çıkardığını imza sonrası maili atacağını söyledi. diğer teklifleri sonuçlandırmadım dedi. bu sefer fiyatların çalışıyor çalışınca bende sana destek olacağım dedi. Çorluyu pazartesi ziyaret ettiğimi yönlendirdiği ömer beyin kaplamaları buraya gönderdiğini söyledim. almadım lastikleri buraya sabah başkasına verdim kaplamaları ama hepsini seçmeden alıp hurdaları atar kalanı buraya getirirsen işi al dedi. bende önce hurdalar için yokuş yaptım sonra kabul ettim. 70 kadar lastik varmış karşı tarafa iş iptal dedi. lastikleri yarın alacağız. velexia ve herkül için fiyatları verdim, karkasların marka ve durumlarına göre haber vereceğim. Erkan bey daha önceden aldığınız gibi 2 ay sürmesin abi bu seferki gerilimi yönetemem dedi. bende takibim altında olduğunu önceki konunun detayını bilmediğimi ama artık yaşanmacağının garantisini verdim. otr kaplamalar içinde asıldım çıkarsa söz dedi. Erkan bey takip edilmesi gerekyor, kaplamaları söz vermesine rağmen şans eseri denk gelerek aldım.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('d873af53-8ab3-5df7-b240-ca1c052e0022','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='BAHAR MADENCİLİK' AND il IS NOT DISTINCT FROM 'ANKARA' LIMIT 1),'a75442c9-b0ca-50bc-bef3-e4a58bc196a8'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-07-16',NULL,'ilk kaplamalarımızı aldık ve lassa ors satışımızı yaptık. Memduh burası için hiçbir firmaya vermedği tepkiyi verdi yazışmayı atmıştım size. Başka yer vereyims sana burası gerçekten çok sıkıntı lütfen dedi. Sorukları tbr leri petlas olarak 13.300TL+KDV den almışlar. istanbuldaki taş ocakları için. genelde petlas almıyoruz taş ocağına bir parti almıştık memnun kaldık yine aldık dedi. altın madenleri için ordu ve sivasta, lassa alıyoruz dedi. hatta 600D üretimi bitmek üzereymiş bu ay onun yerine bize bridgetone teklif ettiler dedi. bende benim bilgim yok diyince ara sor dedi, memduhu aradım 510D geliştiriliyor ama yıl sonu belki satışa çıkar dedi Ahmet bey duydu. bunun üzerine elindeki stoğu bize vermek için sallamışlar demekki dedi neyse anladık dedi. senden 500 lastik alsam parasını nakit ödesem parça parça çeksem olur mu dedi. olur tabiki dedim. 1-2 aya 500 adet alım olacak altın madenleri için mutlaka fiyat alacağız dedi. kaplamaları içinde LGT fiyatı verdim, lastikleri sevk eder kaplamaları alırsın kaplama fiyatı özcanlar ile aynı çıktı. daha doğrusu 1.500Tl destek düşünce. her ziyaretimde iletişimimiz güçleniyor. eskiden petlas filo bayisiydik ama şimdi alım az diye bayiye yönlendiriyorlar dedi.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('850bffba-c25c-59e9-be10-ea91f2f4e6f4','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='SEZA İNŞAAT' AND il IS NOT DISTINCT FROM 'ANKARA' LIMIT 1),'b7ec08e6-4631-523f-bcb4-fb268351a59b'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-07-16',NULL,'Hacı abi en son görüştüğümüzde beri telefonlarımı açmıyor ve geri dönmüyordu  çat kapı gittim. Abi küstük mü açmıyorsun dedim. Kemal portala yüklediler her şeyi 2 kişi tüm grubu çevirmeye çalışıyoruz çok yoğun dönemiyorum dedi. Öyle şey olur mu her zaman gel ara dedi. lastikleri 15.000TL KDV dahildin petlas olarak aldık dedi, abi siz lassa alırdınız dedim evet öyleydi ama 20K ya lassa alacağımıza petlasa döndük 1 yıldır da alıyoruz sorun yok dedi. sırp malı lastikde aldık ucuz mal teklif et dedi kumho söyledim olur bak iyi marka dedi, 19k dahil fiyat  verdim çok yüksek almayız bizim çizgi petlas ayaraı dedi. otr de dynamax almışlar yurdusevenden. marka algıları değişmiş ve çok yükselecek gibi durmuyor. yine takip edeceğim.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('afb52fc6-028e-51bb-8325-cd483580a67c','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ÖZALTIN İNŞAAT' AND il IS NOT DISTINCT FROM 'ANKARA' LIMIT 1),'d4358e8a-e1e1-54ce-99be-6ed81bf4c855'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-07-16',NULL,'Erkan bey ile görüştük, genel sohbet sonrası konuya girdim abi ne yaptın alımı dedim, adık dedi ama brisa direkt fatura edecek dedi, sonra konuşmanun ilerisinde brisa faturada etmeyebilir siz devreye girince biz ayarlayacağız demiş brisa. Ben kardeşlerin kendisinin fiyatları onlara söylediğini bizim teklifi servis ettiğini söylediğini verdiğimiz rakamı bildiklerini söyledim. olamaz ben demedim dedi, bilgisayarınıza sızmadılarsa boş atıp dolu mu tutmuşlar acaba sizi 17 yıldır tanırım böyle bir şey yapacak insan değilsiniz dedim. ben asla kimseye fiyat vermem dedi, kameralarımı izliyorlar bizim geldiğimizi nereden biliyor bunlar dedim. çok bozuldu, lütfen bu konuyu kapatalım ben onlara yapacağımı biliyorum dedi. bir süre daha dürütlükten dem vurup onlara yapacağımı biliyorum dedi. bizim mesajı net aldı, takip edeceğim.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('68fa5d08-1421-5751-98bd-69d9e0273a2a','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ÇETİN İŞLETMELERİ' AND il IS NOT DISTINCT FROM 'ANKARA' LIMIT 1),'5ef5043b-63c3-58e3-a319-0abcf83aa22d'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-07-16',NULL,'Caner beyi ziyaret ettim, 1 aya 315/80 asfalt ve hafriyat alımı olacak sen önden fiyat ver bana elimde dursun ama sonra resmi teklif isteyeceğim dedi. Marka genel tercihiz ne oluyor dedim, lassa da alıyoruz petlas da hatta kaplamaya lastik çıkmayan hatay şantiyemizde sadece petlas alıyoruz dedi. burada da ilişkimizi geliştiriyoruz. markalarımız ve bizi artık tanıyorlar.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('18a0091e-fd85-5843-9ac2-3e47a82825a2','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='MV İNŞAAAT' AND il IS NOT DISTINCT FROM 'ANKARA' LIMIT 1),'b12b4108-0c68-58ad-8951-e0e365873272'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-07-17',NULL,'Kemal abi ile Ostimde görüştüm, Fernasın firması burası. Kemal abi Fernastan süleyman beye yönlendirmişti geçen ziyaretimde randevu vermesine rağmen benimle görüşmemişti. Bu sefer salıdan aradım gel dedi, 2 gündür telefonlarımı açmıyor dedim, onun tarzı malesef öyle tüm esnaf şikayetçi ondan, ben doğru bulmuyorum uyardım ama öyle yapıyor, çoğu insan benden destek istiyor ona ulaşmak için dedi. ben sana oranın satınalmaya kayıt için destek olacağım onunla çözülmeyecek o iş belli sen benden haber bekle dedi. en son alımı petlas yaptık otr dedi sizin fiyatı kıyaslamuoyrum yokohama premium tabi dedi. ama premiumda deneriz mutlaka dedi. tbr için lassa tercih ediyoruz talep olunca soracağım dedi.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('eae61263-0cbb-59dd-b2d0-849003db865a','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='BETAMER' AND il IS NOT DISTINCT FROM 'ANKARA' LIMIT 1),'e6d070fa-a6b0-5790-9571-c84a4baaf195'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-07-17',NULL,'Faruk bey ile fabrikalarında görüştüm. Yokohama ile ilgili endişeleri vardı telefonda bunlara dile getirmişti, biz lastikleri tarkarkende formeni lastiklerin üzerinde E4 yazıyor L4 olması lazım yanlış diye gaza getirmişti. Tüm endişelerini gidermek için kısa bir sunum yaptım, almak istediği VSNT ninde üzerinde E4 yazdığını gösterdim. kaygıları yok oldu, ve memnun oldu yaklaşımımızdan. ayrıca gitmişken tahsilatımızı yaptım. eskişehir ocaklarında 5 loder 2 belden kırmalı var. karaman ocaklarında 1 loder var. Eskişehir ocaklarını ilk fırsatta ziyaret edeceğim.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('3cf61e7c-5281-53f9-8287-8975269418df','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='OYAK BETON' AND il IS NOT DISTINCT FROM 'ANKARA' LIMIT 1),'fcba7b0d-5214-5313-8ecf-65915ce6a768'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-07-17',NULL,'tüm tesislerin satınalmasını yöneten merkezlerini ziyaret ettim. 5 kişlik bir ekipleri var. Lastik grubu ile Sinan bey ilgileniyor. 56 beton santrali, 9 taş ocağı ve çimento fabrikaları var. 600 kamyon 30+ loderleri var öz mal olarak. Petlas filo bayilikleri var, ve çok memnunlar. otr de kaplama için teklif istedi 2 lastik var dedi eko hamur fiyatı verdim ako fiyatı çok daha uygun dedi. loder yenide yokohama deneyebiliriz dedi. tbr kaplama için de fiyat alacağım sizden dedi. ben lassa grubu teklif edebileceğimizi söyledim, Brisa bizi burada bir bayiye yönlendirdi ama alım yapmadık dedi. yeni lastik alımları e tadarik portalları üzerinden oluyor oraya kaydımızı yaptık. çimento fabrikaları eskiden taşerondu şimdi öz mala dönmeye başlamış oralar pratisin farklı bir e tedarik portalını kullanıyor ve her tesis kendi yönetiyor dedi. bana aslan çimentodan kontak verdi oradan başlayın portala kaydınızı yapınca tüm tesisler düşer dedi. genel olara çok olumlu ve sıcak bi görüşme oldu teknik olarak sorular sordular. fakat günün sonunda Petlas taradından çok memnunlar ve algı değişmeden yeni tarafında şansımız zor. takip edeceğim.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('676b6ef3-5e80-5d6e-9b8e-f2803025a4ef','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='AFAY' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'074da1a4-d59b-5193-aa23-684456803014'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-07-21',NULL,'Kaplamalarımızın hızlı aşınma şikayeti ve arka 2 lastiğide kaplamaya almamız için davet etmişlerde. 6. ayda kapladığımız cut cure yoğun kesik almış ve diş diplerinden açmaya başlamış, karışısında daha önce kaplayıp depolarında beklettikleri şimdi cut cure ile takılan rekor otr5 vardı onun durumu dahada kötüydü. detaylı incelememde makinenin kovadan taşan malzemeye yoğun girdiğini ve diğer makineler gibi elek altında değil direkt sökümde taşa girdiğini tespit ettin. kesiklerin sebebi buydu fakat yinede 1 ayda otr5 neredeyse tamamen bitmişti. sonrasında firmanın yetkilisi hasan beye bilgi verdim, o da 5 yıldır makinenin aynı sahada olduğunu hiç 6 aydan önce lastik bitmediğini söyledi. bende diş dipleri için bizim bakmamız gereken bir durum olduğunu kabul ettiğimi fakat derin kesiklerin özellikle kaplama alanı dışında da ciddi hasar verdiğini video ile gösterdim. arkaları kaplamaya alınca önleri yine incelemeye alacağımızı söyledim. tesiste inceleyeceğiz lastikleri,','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('827b799b-a51e-5cb9-b09e-0b297093f149','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='YAFA İNŞAAT' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'8c43afaf-5ef4-58ce-b3f9-59126920505e'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-07-21',NULL,'Satınalma müdürleri  Yıldıray bey ile görüştüm. En son alımı GY olarak yaptık ama sana sorduğumuz alımı henüz bekletiyoruz neticelendirmedik ama GY eğilimindeyiz dedi. Fiyat olarak avantajı var dedi, bu aralar her markayı denedik, ling long, petlas ne varsa aldık ama GY devam eğilimindeyiz dedi. kaplamalar için satınalmadan ömer beyin biz şantiyelere karışmayız isteyen istediği yere verir dediğini bu konuda destek istediğimi söyledim. olur mu öyle şey ben varım artık (ara vermişti geri geldi) hepsi tekelden gidecek senden fiyat alacağım her kaplama için dedi.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('535b08c5-7369-5871-81bc-88cc4aa3a9c3','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='AKÇANSA' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'47733cbb-48c2-5e3a-8371-20cc9d447a74'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-07-21',NULL,'Yunus bey ile görüştüm, kendi makinelerini merkeze gönderip taşerona dönmüşler, taşeron için iletişim bilgilerimi bıraktım ama ulaşamadım yine geçen seferde uğramıştım.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('57ea589d-1f5a-5b70-862e-15d8b36e0ca6','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='CİHAN GRUP' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'b9536378-e658-5f57-b2b4-a29443342542'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-07-21',NULL,'merkezin yönlendirmesi üzerine tesislerini ziyaret ettim. Kaplama için bakmamı istedikleri 26.5R25 henüz diş derinliği var diye arkaya alıp devam edelim dedi. 20.5 kullanan makinenin arkaları bezli ve kötü durumdaydı kaplamaya gelmez yeni alın dedim. teknik sorumluları Şenol bey yeni fiyatını merkeze iletmemi istedi.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('637ae541-90e0-5308-b959-d39866093dec','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='CİHAN GRUP' AND il IS NOT DISTINCT FROM 'BURSA' LIMIT 1),'b9536378-e658-5f57-b2b4-a29443342542'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-07-21',NULL,'Hayrettin ve Onur bey ile görüştüm, mekeceden aldığımız kaplamayı durumu kötü ve diş derinliği iyi diye tamire çevirdiğimizi söyledim. Nilüfer tesistede 3 kaplamayı 2 yani 2 rotasyon önerdiğimizi söyledim. Yaklaşımımızdan çok memnun olduğunu söyledi, burada 3 lastik var gel bakalım olanları al dedi. beraber inceledik 2 23.5 kaplanabilir gibi duruyor alacağız. yeni için günmarlas ile ciddi gerilmişler bunların muhasebelerini çok ağır konuşmuş günmarlas. zaten en son GY aldık şuanda GY ile devam kararındayız dedi. kaplama avon+ yaptırıyorum dedi. fiyatımızı veridm 6.000TL+kdv benim fiyatım dedi, çok makas var dedi. şimdilik otr de kaplamada başladık, tbr yeni ve kaplama içinde takip ediyorum.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('c9833efe-7399-55ae-b184-f4b8c64ae4c3','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='TAŞ YAPI' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'037e0d20-1c9a-5160-8fb2-20989fad43a1'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-07-22',NULL,'Fırat bey ile telefonlaşmıştım fakat beni gittiğimde lobide 1 saat bekletti kimse ulaşamadı. Görüştüğümüzde telefonu şarjda unutup üst kata çıkmışım kusura bakma dedi. En son teklif veridğimiz iki talebi sordum hemen masasında kağıtarı gösterdi hala bekletiyoruz dedi bakamadım henüz dedi. sonra tüm dosylara benimle beraber baktık. coşlaş fiyatları bizden 250 ile 500TL arası pahalıydı. bizim fiyatımız %41 isk. koplas Fulda için 14.800TL vermiş. anteo için 16.000TL fiyat almışlar. Hankook için 17.500TL fiyat almışlar. bu durumda biz Fulda alacağız öyle gözüküyor dedi. bende lassa kaplanabilirlik bahsettim, fulda da kaplanıyor alıp sen kaplıyorsun hatta dedi. zaten hepsi şantiyede kesilip hurda oluyor dedi. bende fuldanın kesilipi hurda olduğu yerde lassa tamir oluyor işe devam ediyor, fulda 1 kaplanıyor lassa 2 diye açıklama yaptım. açıklamalar sonra doğru diyorsun dedi. zaten lassa da en düşük benim fiyatım var zam geldi ama siz eski fiyattan vermeye devam ediyoruz dedim. tamam ben bunların onayı alırsam sana döneceğim dedi. zaten emrullah beyden dolayı patron buraya özel fiyat yapıyor hiçbir yere yapmıyoruz bu fiyatları dedim. emrullah ile ne işleri var dedi bilmem abi ben orasını ama diylogları var dedim. konuşma sonuna aldığım elektrik olumluydu takip edeceğim.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('9bbd514b-d48e-5986-b438-0a473ab9bdb8','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='TÜRK ALTIN' AND il IS NOT DISTINCT FROM 'ANKARA' LIMIT 1),'ca6a4c93-4b23-55b9-8607-30ca96a7033a'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-07-22','TELEFON GÖRÜŞMESİ','Türk altın satınalma müdürü aradı, beni tanışmak için dave etti haftaya plan yapacağımı söyledim. 30 yıldır gönlügür ile çalışoıyoruz dedi, bende yokohama ve bridgestone olarak yardımcı olabileciğmizi zaten gönlügür üzerinden lasitklerini bir dönem kapladığımızı hatta tüprag da halen devam ettiğimizi söyledim. siz gelin mutlaka bir iş çıkar ortak dedi. yokohama için beni jendry ve spin global firması anıl aksoy ziyaret etti dedi. uçak lastiği getireceklermiş otr de çalışırmı diye sordular dedi bende bizm tek otr getiren firmayız dedim. orada sorun yok biz sizinle çalışırız dedi.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('dcc572b7-c34e-5b4d-a090-68b47ee2efc2','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='İGA' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'14ea2641-9ef8-5e1d-aa89-2e370afe65ff'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-07-22','TELEFON GÖRÜŞMESİ','İGA bugün 315/70 50 adet lastik sordu, aprondaki asflatda giden ekipmalar için muhtemelen, meduha isk sorduğumda atlı çok aktif burada dedi. Bende değil emin olabilirsin dedim. Burası brisa filo bayi ayrıca %50 hisse sahbibi Cengizin hem filo hemde fiziksel baiyliği var. Brisa grubu bineği bilemem ama hiç bir alımları yok otr de michelin, tbr de GY alıyorlar. zaten tbr ebatları brisa da yok 324/95R24. Atlı buradaki takipsizliği kullanıp maks isk alıp muhtemelen pompa yeri olarak aktif kullanmış.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('930ba453-d85b-5193-886c-cb07eca6115b','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='İGA' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'14ea2641-9ef8-5e1d-aa89-2e370afe65ff'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-07-23',NULL,'Satınalma ofisleri kampüsten ana terminal binasına tanımış, son 2 alımda bzie fiyatı Yılmaz Serdar yerine Serkan bey sordu. Hem yeni yerlerine hayırlı olsun demeye hemde serkan bey ile tanışmaya gittim. Organizasyonda değişiklik olmuş artık Serkan bey bakacakmış lastik alımlarına, her gittiğimde merhabalaştığım birisiydi beni anımsadı. Kaplama işi sende ama Hayrettin teknik onay vermedi bilgin olsun git konuş ok derse siparişi geçeceğim dedi. yeni ofislerine girmek için normal yolcu girişi yapıp içeride ayrı bir güvenlikten daha geçiyorsun, artık tedarikçi gelmiyor buraya girmek zor dediler. 50 adet tbr teklifimziin durumunu sordum petlas bile teklif eden oldu hayrettine attım hangi marka isterse onu alacağım dedi. bende buradan atlı konusunu açtım sizin isk sorarken yoğun tbr alımınız olduğunu söyledi ama hiç bize sormadınız dedim. bu yıl hiç alım yapmadık dediler, ama geöen yıl alım oldu atlıdan 200 civarı dediler. Serkan bey eski personel fakat lastiğe yabancı, takip edeceğim.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('56361b46-b527-5dd5-8fb3-f7e390fda791','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='İGA' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'14ea2641-9ef8-5e1d-aa89-2e370afe65ff'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-07-23',NULL,'liman tarafına makine ikmale hayrettin beylere gittim, aynı sahdalar ama araç ile iki yer arası 20dk dan uzun sürüyor. Önce depoya geçtik şikayete konuları vardı bizden, son kapladığımız 45mm 26.5R25 ile tatko kapladığı 55mm arasında ciddi çap farkı var diye şikayetleri vardı. bizim kaplamamız 45mm tatko 55mm dedim. ayrıca bizim karkas L5 tatko karkası L3 çap farkı çoğu uradan geliyor diye anlattım. önce çok anlamadılar sonra L3 l5 farkı teknik olarak daha detaylı bir kaç kez anlattım, depodaki ustalar tatmin olmadı ama hayrettin bey tatmin oldu açıklamadan. isterseniz tatko lastiğini verin bizim lastiğin çapa kadar raspa yapalım yada bir sonraki vereceğinizde bunları ölçüp üretimde denk ayarlamaya çalışalım dedim. sonra diğer omuzların daraltılması şikayetlerini dinledim, ömüre etkisi yok dedim omızdaki yükü azaltıyor dedim. makine yüke girince sizin lastiğin omuzları olmadığı için yanaklar daha çok hasar alıyor biz bu şekilde istemiyoruz dediler. bir miktar iyileştirebilriiz ama tam geniş olmaz dedim. eğer açma yada az çalışma olursa garantimiz altındadır hemen gelir ben incelerim dedim bu biraz rahatlattı onları. 315/70 için bir marka tercihiniz var mı biz BS teklif ettik dedim. tercihim yok BS olaiblir önüme gelsin bakayım dedi. kaplama için işin bizde olduğunu ama onay vermediği için bize vermediklerini söyledim, 35/65 için sen yeni teklifi at yeni alacağım ki kaplamaya lastik çıksın dedi. 26.5R25 L5 ler için Yokohamayı denemeleri için özel fiyat verdiğimizi söyledim. hepsi gelince bakacağım dedi. kaplamadaki sorun çözüldü gibi. yeniler için takipteyim. ayırıca depoların 150 kadar 600D 80 kadar 520s vardı bunları ne zaman aldığınız dedim, yakın zamana değil 6 aydan eskidir dediler. burasıda bu yıl alım olmadığını teyit etti.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('c54d2fc0-dcc8-5072-93d1-64c02843f114','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='BAHAR MADENCİLİK' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'59303ce3-3fb5-56f9-be9e-b89a25ec5247'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-07-23',NULL,'Firma sahibi Ramazan bey ile görüştüm, kaplamaları yarın teslim edeceğimizi söyledim. Alımlarda final kararı ramazan bey verdiği için ilişkimi geliştirmeye çalışıyorum. Yakında sivastaki altın madeni için toplu tbr alımları olacak. Sen o gün gelip bakmasaydın ben hala kullanırdım 29.5 ları dedi bende kullasaydınız çöp olurdu dedim. genel sohbet ettik.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('e2518b89-b3f4-5f11-a3cd-ac9c0d0cc462','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ENTO MADEN' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'32c90717-85dd-572b-bfca-2687734a7782'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-07-23',NULL,'En sonunda Bedri bey (sabah gıyabında ettiğim küfürler işe yaramış olacak ki) aramamı açtı ve gel bekliyorum dedi. 1 yıldan uzun süredir sadece 1 kere telefon açtı ve 1 kere lastik sordu. Yanına gidince 1 yıldan uzun süredie size ulaşamıyorum diye sitem ettim biraz mahçup oldu ama yeterince değil. sizden tek isteğim bize teklif sormanı ötesinde hiç talebim yok dedim, abi sorsam ne olacak atlı var diye fiyat veremeceksiniz burda kimse atlıyı yıkamaz dedi. yoksa ben çok tedarikçi isterim ama yok dedi. kimse şeref atlı ile mücadele edemyior dedi.bende eskiden rusyada ve bollucada iş yaparlarken fiayt verdiğimizi iletişimiz olduğunu ama sonra onların iletişimi kestiğini söyledim. amacınız mal almaksa ve tedarikçi çeşitlendirmekse ben fiyat veririm ama fiyatı şerefe e oğluna servis edip ortalığı durduk yere karıştırmaksa hiç vakit çalmayalım dedim. ciddiyetimi alayınca ben asla kimsenin fiyatını kimseye söylemem bende kalır dedi sen lütfen 600 d fiyatı ver dedi. talep olunca sorun o zaman çalışayım dedim, yok ver bak sana fiyat 22.250TL den aldım en son yakında dedi ver bu fiyatı dedi. %38 isk geliyor fiyat. bende gerçekten bir alım talebiniz olur ve fiyatımı servis etmezseniz size gerçekten iyi bir fiyat veririm bu fiyatıda veririm dedim. sonra konu otr ye geldi orada da Tatko ile rekabet edemezsin dedi, tatko iyi bir rakibimizdir her koşulda en az onlar kadar iyi hizmet veririz dedim. 55m kaplama 40+kdv yapıyorlar dedi. bu fiyat eko da nakit fiyatımıza denk geliyor. kaplamada da gerekirse bu fiyata düşeriz ama bir talep olunca bakalım dedi. 26.5 yeni GY gp4d 156+kdv alıyorum dedi düş fiyata alayım senden dedi tamam dedim o paraya sana yokohama vereyim hemen dedim. sonra o markayı bilmiyorum be bilsem denerim dedi. GY satınaldı dedim biliyorum dedi. şuan en ucuz koplas veriyor gy dedim ben oradan almıyorum ama ora parasına alıyorum dedi, kürşat kendi satıyor muhtemelen. 20 loder ve 50 kamyonları var bölgedeki en büyük ocaklarından.çıkarken artık sen direkt aramadan gel dedi. özetle artık kilidi açtım bedrinin gazına gelmeden iş çıkarabiliriz.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('d0d963ab-63e8-55d3-8ee6-53e1887fb594','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='MAKYOL' AND il IS NOT DISTINCT FROM 'İSTANBUL' LIMIT 1),'b540e6cd-c913-58ae-b0fb-d76d24b37afc'::uuid),'ab23df67-75c8-40ff-bac9-2de66c6a76b6','Ali Kemal Pıçakcı','TICARI','TAMAMLANDI','2026-07-24',NULL,'Savaş Çebi ve müdürleri Oktay bey ile görüştüm. Bizim kontoğımız Müjdatın sadce ihsaniye talepleri ile ilgilendiğini diğer taraflara karışmadığını söyledi. Kemerburgaz tarafındaki ocaklarının yetkililerine bilgi vereceklerini oraya hizmet verebileceğimiz söylediler. romanya için ne olduğunu bilmediklerini söyleyip not aldılar, ilgili arkadaşlar ile görüşeyim sonra sizlik bir şey olursa döneriz dediler. kaplama ve buradan lastik tedariğini vurguladım. Oktay bey lastik ile ilgili teknik bilgiler sordu genel bir 10 dak lastik sohbeti oldu. güzel ve verimli geçti. pazartesi günü kemerburgaz lokasonlarına gideceğim.','{}'::jsonb,'EXCEL_MIGRASYON','ab23df67-75c8-40ff-bac9-2de66c6a76b6') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('95fd477f-9315-507a-8a20-95738568b79c','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='KÜÇÜKLER TAŞM.AKAR.VE MADENİ.YAĞ.TİC.LTD.ŞTİ.' AND il IS NOT DISTINCT FROM 'KOCAELİ' LIMIT 1),'d80652d2-43a6-5466-a221-6a04e46c08ab'::uuid),'79d8adeb-c58f-4564-b625-a023e141e14b','Yıldıray Bilen','TICARI','TAMAMLANDI','2026-04-17',NULL,'FİRMA SAHİBİ OLAN ŞUAYİP BEY İLE GMRÜŞEM YAPILDI TALEP ETMİŞ OLDUĞU 12 ADET LASTİKL ALIMI SONUCU SORULDU ALIMI DAHA YAPMADIĞINI BAŞKA YERDEN DE DAHA FİYAT ALMADIĞINI SÖYLEDİ KONSİNDE OLAN LASTİKLER İÇİN MUTABAKAT YAPILDI 2 ADET SAİLUN PİLOT FİRMA TUTMUŞ OLDUĞU  SİSTEMİNE İŞLMEDİĞİ TESPİT EDİLDİ TESLİM FORMU GÖSTERİLEREK MUTABIK OLUNDU','{}'::jsonb,'EXCEL_MIGRASYON','79d8adeb-c58f-4564-b625-a023e141e14b') ON CONFLICT (id) DO NOTHING;
