INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('fbb55bf6-264c-58fa-8fae-22d2d861214d','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ÇAYCUMA NAK. KOP GARAJ' AND il IS NOT DISTINCT FROM 'ZONGULDAK' LIMIT 1),'fed4da0f-5f1d-5d21-83e0-ccf4607e25d6'::uuid),'0c5e2e6e-64a8-4c9b-9c45-81060ce6b042','Önder Yılmaz','TICARI','TAMAMLANDI','2026-04-17',NULL,'Kooperatif üyeleri ile yapılan görüşmede, genel iç piyasa, nakliyat ve akaryakıt fiyatlarındaki belirsizlikten ve piyasanın daralmasından memnun olmadıkları belirtilmiştir.
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('c3bc06cf-6708-5924-acc3-8ae51f1c94e2','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='EROĞLU ENERJİ TARIM NAK' AND il IS NOT DISTINCT FROM 'BARTIN' LIMIT 1),'3fd64550-f47a-5b75-b0fc-b9854ae12b99'::uuid),'0c5e2e6e-64a8-4c9b-9c45-81060ce6b042','Önder Yılmaz','TICARI','TAMAMLANDI','2026-04-17',NULL,'Fatih Bey ile yapılan görüşmede, en son alımlarını Prometeon Tyre Group ürünlerinden ön ve çeker lastik olarak gerçekleştirdikleri öğrenildi. Dorsede ise ithal ürün kullandıklarını, ancak fiyat ve firma bilgisini paylaşmadıklarını belirtti.
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('fe97e8a2-a5bc-5c2f-b159-7078a5c6f3e2','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='MUSTAFA YILMAZ MADENCİLİK' AND il IS NOT DISTINCT FROM 'BARTIN' LIMIT 1),'cfc41b47-40c7-5ff7-939c-fa1c87c8e132'::uuid),'0c5e2e6e-64a8-4c9b-9c45-81060ce6b042','Önder Yılmaz','TICARI','TAMAMLANDI','2026-04-17',NULL,'Yeni müşteri Murat Bey ziyaret edildi. Firmada toplam 12 adet araç ve 2 adet iş makinası bulunduğu, tonajlı çalıştıkları öğrenildi. Lastik alımlarını ağırlıklı olarak Başoğlu Lastik Kaplama’dan yaptıklarını, ancak fiyatlar nedeniyle Mustafa Bey’in artık eskisi gibi tek bayi ile çalışmayacaklarını ifade ettiği belirtildi. Bundan sonra fiyat-performans açısından hangi bayi daha avantajlı olursa o şekilde alım yapacaklarını iletti. Ayrıca yıl sonuna doğru adetli lastik alımları gerçekleştirdiklerini belirtti.','{}'::jsonb,'EXCEL_MIGRASYON','0c5e2e6e-64a8-4c9b-9c45-81060ce6b042') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('9e95d260-40f8-5668-92ae-0bd6928150f7','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa','ce290249-a64d-4ab8-92a4-60ad1db1d4cb'::uuid,'0c5e2e6e-64a8-4c9b-9c45-81060ce6b042','Önder Yılmaz','TICARI','TAMAMLANDI','2026-04-17',NULL,'Metin Bey ziyaret edildi. Kendisi toplantıya gireceğini belirterek daha sonra tekrar gelmemi rica etti. Bunun üzerine kademeye inerek araç ve lastik durumlarını inceledim.','{}'::jsonb,'EXCEL_MIGRASYON','0c5e2e6e-64a8-4c9b-9c45-81060ce6b042') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('892da1d6-8b5d-52a8-b855-e166a8779d2b','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='UYGAN HAFRİYAT' AND il IS NOT DISTINCT FROM 'BARTIN' LIMIT 1),'0b1a487d-2f17-5f25-83a1-d731fa548d47'::uuid),'0c5e2e6e-64a8-4c9b-9c45-81060ce6b042','Önder Yılmaz','TICARI','TAMAMLANDI','2026-04-17',NULL,'Uygan Hafriyat kademesine kaplama indirildi. İki aracın lastik kaplama performans takibi için araç altı analizleri yapıldı. Kaplamaya gidecek lastikler jantlı olduğu için alınamadı; ayrıca lastikçinin işlerinin yoğun olması ve jant ihtiyacı bulunması nedeniyle süreç ertelendi','{}'::jsonb,'EXCEL_MIGRASYON','0c5e2e6e-64a8-4c9b-9c45-81060ce6b042') ON CONFLICT (id) DO NOTHING;
