INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('3c66cd25-f5b8-564d-9ec5-ec6ba8b82df4','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ABANT GLOBAL' AND il IS NOT DISTINCT FROM 'BOLU' LIMIT 1),'ad86fef0-9eef-5735-b048-b020f832afef'::uuid),'0c5e2e6e-64a8-4c9b-9c45-81060ce6b042','Önder Yılmaz','TICARI','TAMAMLANDI','2026-05-07',NULL,'Rıdvan Bey ve Cemil Bey ile yapılan görüşmede, Brisa marka 385/55R22.5 lastiklerin gövde çatlağı nedeniyle garantiye gönderildiği ancak red geldiği, sonrasında lastiklerin tamir edilerek kullanılmaya devam edildiği ve Brisa alımlarına sıcak bakılmadığı belirtilmiştir.Sailun marka  315/60R22.5 çekici lastik bu kullanım döneminde yaklaşık 75.000 km yol yapmıştır. Başlangıç: 03/02/2025 → 737.000 km
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('ec63699a-16fe-56a1-80e2-6c171f5eeb87','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='RAHMİ EREN' AND il IS NOT DISTINCT FROM 'KARABÜK' LIMIT 1),'01633bca-9b5c-5f12-8557-8fc4cd2d15e0'::uuid),'0c5e2e6e-64a8-4c9b-9c45-81060ce6b042','Önder Yılmaz','TICARI','TAMAMLANDI','2026-05-08',NULL,'“Rahmi Bey ziyaret edildi. Havaların düzelmesiyle birlikte orman kesim işlerinin başladığı, ancak Orman İşletmesi’nin barkod sistemine geçiş süreci nedeniyle istihkakların alınamadığı belirtildi. Bu nedenle işleyişin tam olarak sağlanamadığı ve buna bağlı olarak ödeme ile alacak süreçlerinde aksaklık yaşandığı ifade edildi. İhtiyaç durumunda kendisinin iletişime geçtiğini bildirdi.”','{}'::jsonb,'EXCEL_MIGRASYON','0c5e2e6e-64a8-4c9b-9c45-81060ce6b042') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('4e5c4aed-cba5-5ef2-8853-b977da80742d','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='HORYAN MADENCİLİK' AND il IS NOT DISTINCT FROM 'KARABÜK' LIMIT 1),'3c77353f-ccbf-596f-91ee-5e8e4739ef47'::uuid),'0c5e2e6e-64a8-4c9b-9c45-81060ce6b042','Önder Yılmaz','TICARI','TAMAMLANDI','2026-05-08',NULL,'“Maden ocağına kaplama lastikler bırakıldı. İki farklı iş makinesine ait 23.5R25 ölçüsündeki lastiklerin incelemesi gerçekleştirildi. Toplam 6 adet lastiğin kaplama zamanının geldiği, daha önce kaplama yapılan lastiklerde ise yanak bölgelerinde açılmalar başladığı tespit edilerek detaylı şekilde fotoğraflandı. Ayrıca 2 adet lastiğin diş derinlik ölçümü yapılarak yaklaşık 2 ay daha kullanılabileceği değerlendirildi.
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('ed4895ae-2b18-5722-8b05-e1054d939351','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='HELKA BETON' AND il IS NOT DISTINCT FROM 'KARABÜK' LIMIT 1),'3c75e9f7-174a-5f14-9f61-d405ab49eb2f'::uuid),'0c5e2e6e-64a8-4c9b-9c45-81060ce6b042','Önder Yılmaz','TICARI','TAMAMLANDI','2026-05-08',NULL,'“Yeni müşteri kapsamında daha önce ziyaret edilmiş olan Mehmet Bey, kademede tekrar ziyaret edildi. Gerçekleştirilen görüşme olumlu geçti. Önümüzdeki hafta lastik sökümü yapılacağını, kaplama ve tamir konusunda tarafımıza lastik vermeye başlayabileceğini belirtti.”','{}'::jsonb,'EXCEL_MIGRASYON','0c5e2e6e-64a8-4c9b-9c45-81060ce6b042') ON CONFLICT (id) DO NOTHING;
