INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('0fa9b3f5-f6f7-5fc8-811c-0c85918448fd','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='DÜZCE CAM' AND il IS NOT DISTINCT FROM 'DÜZCE' LIMIT 1),'f71e6fac-13f3-5119-9e8a-6260e4aa1ec3'::uuid),'0c5e2e6e-64a8-4c9b-9c45-81060ce6b042','Önder Yılmaz','TICARI','TAMAMLANDI','2026-05-11',NULL,'Özkan Bey ile telefonda görüşme yapıldı. Kendilerini ziyaret için aradığımda yerinde olmadığını belirtti. Bugün yine kaplama lastiğin sırt attığını, lastiğe ait görselleri paylaştı. Aracın akaryakıt depo çamurluğunun zarar gördüğünü iletti. Bu süreçte lastiklerle ilgili sıkıntı yaşandığını, kaplama lastik verilmediğini ve şu an beklemede olduklarını belirtti.','{}'::jsonb,'EXCEL_MIGRASYON','0c5e2e6e-64a8-4c9b-9c45-81060ce6b042') ON CONFLICT (id) DO NOTHING;
