INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('ca658502-d24a-5e0b-aab5-4c57d6cce9ec','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='SALTAN ULUS' AND il IS NOT DISTINCT FROM 'BOLU' LIMIT 1),'7a3cfdef-decf-5235-8592-8f03ffe31a12'::uuid),'0c5e2e6e-64a8-4c9b-9c45-81060ce6b042','Önder Yılmaz','TICARI','TAMAMLANDI','2026-05-11',NULL,'Oğuz Bey ile tahsilat hakkında görüşme yapıldı. Ödeme vadesinin geldiği bilgisi verildi. Metin Bey, ödemenin öğleden sonra yapılacağını belirtti. Öğleden sonra telefon ile tekrar görüşme yapıldı, tahsilat gerçekleştirildi. Ayrıca yeni lastik siparişi alındı.','{}'::jsonb,'EXCEL_MIGRASYON','0c5e2e6e-64a8-4c9b-9c45-81060ce6b042') ON CONFLICT (id) DO NOTHING;
