INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('667e86c6-090c-539a-aa54-20e2b2b2599d','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ALLAR BETON' AND il IS NOT DISTINCT FROM 'BOLU' LIMIT 1),'949dc91d-c68a-5692-b5c9-fffc79c8997e'::uuid),'0c5e2e6e-64a8-4c9b-9c45-81060ce6b042','Önder Yılmaz','TICARI','TAMAMLANDI','2026-05-12',NULL,'Muhasebe tarafında Nihat Bey ziyaret edildi. Satın alma süreçleriyle Mevlüt Bey’in ilgilendiği bilgisi alındı. Firma hakkında yapılan görüşmede, işletmede 13 adet araç ve 1 adet iş makinesi bulunduğu öğrenildi.
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('e18e1875-860e-549d-bf89-240acf262971','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='TAŞ YAPI' AND il IS NOT DISTINCT FROM 'ÇORUM' LIMIT 1),'297a8c26-72e9-5f7e-a960-15245287f7b3'::uuid),'0c5e2e6e-64a8-4c9b-9c45-81060ce6b042','Önder Yılmaz','TICARI','TAMAMLANDI','2026-05-12',NULL,'Mustafa Bey ile görüşme yapıldı. Araçlarının Sivas ve Amasya bölgesine gönderildiği bilgisi tarafımla paylaşıldı.
