INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('1fdb683e-77dc-54b7-ba71-b50f1fd3eb69','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='EKŞİOĞLU MADENCİLİK' AND il IS NOT DISTINCT FROM 'ZONGULDAK' LIMIT 1),'ca92f93e-9728-5041-8c3d-695798e6b5a5'::uuid),'0c5e2e6e-64a8-4c9b-9c45-81060ce6b042','Önder Yılmaz','TICARI','TAMAMLANDI','2026-05-13',NULL,'“Firma sahibi Uğur Bey ile görüşme yapıldı. En son lastik alımını Fahrettin Başoğlu’ndan yaptığını belirtti. Son kullanıcı olarak tercih ettiği lastik markasının Goodyear olduğu öğrenildi. Yeni lastik fiyat teklifleri ile ilgili olarak Necla Hanım’a iletişim bilgileri paylaşıldı. Daha sonra, daha önce kaplamasını yaptığımız lastiklerin takılıp takılmadığı bilgisi için kademeye uğrandı.”','{}'::jsonb,'EXCEL_MIGRASYON','0c5e2e6e-64a8-4c9b-9c45-81060ce6b042') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('b1e52acf-6eba-5e3c-a9fd-67c34ab7c7ca','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='YIL NAK' AND il IS NOT DISTINCT FROM 'ZONGULDAK' LIMIT 1),'a5a082e6-bb9e-52cb-9946-8bfd4be3d090'::uuid),'0c5e2e6e-64a8-4c9b-9c45-81060ce6b042','Önder Yılmaz','TICARI','TAMAMLANDI','2026-05-13',NULL,'“Mustafa Bey ziyaret edildi, firma tanıtımı yapıldı. Daha önce Uğur Yıldız ile görüştüklerini belirtti. Ağırlıklı olarak silobas araçlarının Gebze hattında çalıştığı ve toplam 25 adet araçlarının bulunduğu bilgisi alındı. Yol yardım desteği verebileceğimiz belirtildi. Kaplama konusunda Başoğlu Lastik ile çalıştıklarını ifade etti. İhtiyaç durumunda iletişime geçeceğimiz belirtildi.”','{}'::jsonb,'EXCEL_MIGRASYON','0c5e2e6e-64a8-4c9b-9c45-81060ce6b042') ON CONFLICT (id) DO NOTHING;
