INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('44f2c44d-c759-5438-998e-c648464296c3','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='TUNCAYLAR MADENCİLİK' AND il IS NOT DISTINCT FROM 'BOLU' LIMIT 1),'62d9ca92-2f81-58a7-a6a2-e600289eedeb'::uuid),'0c5e2e6e-64a8-4c9b-9c45-81060ce6b042','Önder Yılmaz','TICARI','TAMAMLANDI','2026-05-18',NULL,'Depoya lastikler teslim edildi. Orada 315/70R22.5 çeker Sailun marka lastikler görüldü. Daha sonra ofise ziyaret gerçekleştirilerek Birol Bey ile görüşme yapıldı. Kendisi, 12 adet lastik alımı yaptığını ve toplam 14.500 TL ödemenin kredi kartına taksitli şekilde gerçekleştirildiğini belirtti.','{}'::jsonb,'EXCEL_MIGRASYON','0c5e2e6e-64a8-4c9b-9c45-81060ce6b042') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('9ba6cc40-c67a-5edb-81fd-7a5325d69b33','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='DEREBEY LOJİSTİK' AND il IS NOT DISTINCT FROM 'BOLU' LIMIT 1),'80dc3e63-ea07-5555-b9f9-0cca8d3ea7b0'::uuid),'0c5e2e6e-64a8-4c9b-9c45-81060ce6b042','Önder Yılmaz','TICARI','TAMAMLANDI','2026-05-18',NULL,'Tahsilat için ziyaret edildi ancak araçlarından birinin kaza yapması nedeniyle Cemalettin Bey yoğundu. Bu sebeple ödeme konusunda görüşme gerçekleştirilemedi. Abisi Cemali Bey ile stokları paylaştı. Şu an için ihtiyacı olmadığını, ayrıca artık ithal marka kullanmayacağını ifade etti.','{}'::jsonb,'EXCEL_MIGRASYON','0c5e2e6e-64a8-4c9b-9c45-81060ce6b042') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('d9482572-45a2-5432-9417-44afd08a2122','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ATABEY ULUS.' AND il IS NOT DISTINCT FROM 'BOLU' LIMIT 1),'04815c5f-df87-561f-88f3-ce616272a028'::uuid),'0c5e2e6e-64a8-4c9b-9c45-81060ce6b042','Önder Yılmaz','TICARI','TAMAMLANDI','2026-05-18',NULL,'Firma ziyaret edildi. Daha önce 12 aracı bulunduğu ancak bir kısmının satıldığı ve araç sayısının yaklaşık 7 adede düştüğü görüldü. Aktif olarak 5 adet aracın çalıştığı belirtildi. Firmanın küçülmeye gittiği anlaşıldı. (emanetteki lastiklerini istedi)Geçen hafta cuma günü BaşoğluLastik Kaplama firmasının satış danışmanı ve müdürü ile de ziyaret gerçekleştirildiği, firmanın piyasadaki daralma nedeniyle Ankara’daki ofis ve dairelerini sattığı ifade etmiş. Piyasada genel bir daralma olduğu belirtmiş','{}'::jsonb,'EXCEL_MIGRASYON','0c5e2e6e-64a8-4c9b-9c45-81060ce6b042') ON CONFLICT (id) DO NOTHING;
