INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('9afa34d3-169d-5e3a-a76b-6bfdbce4a865','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='EKŞİOĞLU HAFRİYAT' AND il IS NOT DISTINCT FROM 'ZONGULDAK' LIMIT 1),'7d1ad7bc-ec7e-55d2-8499-fa11cb825e2e'::uuid),'0c5e2e6e-64a8-4c9b-9c45-81060ce6b042','Önder Yılmaz','TICARI','TAMAMLANDI','2026-05-19',NULL,'Kademeye ziyaret gerçekleştirildi. Tamir edilen lastikler teslim edildi. Kaplama yapılacak lastikler teslim alındı.','{}'::jsonb,'EXCEL_MIGRASYON','0c5e2e6e-64a8-4c9b-9c45-81060ce6b042') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('9f4e365b-72a9-5449-8d89-19bd23f83aa2','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='SÖNMEZLER MADENCİLİK' AND il IS NOT DISTINCT FROM 'ZONGULDAK' LIMIT 1),'81b51ab4-d492-56cb-95a8-7b3a87d90564'::uuid),'0c5e2e6e-64a8-4c9b-9c45-81060ce6b042','Önder Yılmaz','TICARI','TAMAMLANDI','2026-05-19',NULL,'Geçen haftaki karabük sönzmerler madencilik kademe ziyaretimde, Zonguldak Çatalağzı’nda bulunan Eren Enerji’de çalışan iş makinelerinin lastik incelemesi için program yapılmıştı. Program kapsamında 3 adet iş makinesinin lastik incelemesi gerçekleştirildi, görsel fotoğraflar çekildi ve Kemal Bey’den destek alındı.Yapılan incelemelerde, 2 ayrı aracın topuk kaynaklı problem yaşadığı tespit edildi. Lastiklerin Goodyear marka olması nedeniyle durumun kronik bir arıza olduğu değerlendirildi.Diğer bir aracın lastiğinde ise darbe kaynaklı kesik olduğu ve lastiğin tamire alınması gerektiği belirlendi. Ayrıca 2 aracın lastiklerinin yaklaşık 1,5 ay sonra kaplama süresine ulaşacağı tespit edildi. Rapor hazırlanıp firmaya mail olarak gönderildi.','{}'::jsonb,'EXCEL_MIGRASYON','0c5e2e6e-64a8-4c9b-9c45-81060ce6b042') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('f243c526-1b5d-5827-8262-024c7543ab73','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='SAYILI BETON' AND il IS NOT DISTINCT FROM 'ZONGULDAK' LIMIT 1),'55b20c2b-1c28-59e1-a1e7-193ccd6d961a'::uuid),'0c5e2e6e-64a8-4c9b-9c45-81060ce6b042','Önder Yılmaz','TICARI','TAMAMLANDI','2026-05-19',NULL,'Osmay Bey ile görüşme yapıldı. Firmada yaklaşık 100 plaka bulunduğu bilgisini paylaştı.
