INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('0c5042cf-6f0e-5bba-ad47-9ce094fd2eb4','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ER PİLİÇ' AND il IS NOT DISTINCT FROM 'BOLU' LIMIT 1),'a408b02a-8cd5-510f-9349-d97b758550d7'::uuid),'0c5e2e6e-64a8-4c9b-9c45-81060ce6b042','Önder Yılmaz','TICARI','TAMAMLANDI','2026-06-01',NULL,'Selami buluşma gerçekleştirilmiştir. Göynük Kademe’ye sevk edilecek lastikler teslim alınmıştır. Daha önce merkeze teslim edilen ve kaplama işlemi tamamlanan, Göynük’e gönderilecek lastikler araca yüklenmiştir.Batı Karadeniz bölgesine sevk edilecek lastikler ise ER Piliç Kademe’ye teslim edilmiş, Göynük dönüşünde ilgili lastikler araca yüklenerek sevkiyata hazır hale getirilmiştir."**','{}'::jsonb,'EXCEL_MIGRASYON','0c5e2e6e-64a8-4c9b-9c45-81060ce6b042') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('198c026e-5eef-5eb5-99ba-c21bac0a84a8','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ÜNSALLAR NAK' AND il IS NOT DISTINCT FROM 'BOLU' LIMIT 1),'2a2c68cb-cc9a-51ec-b75e-187c2165edae'::uuid),'0c5e2e6e-64a8-4c9b-9c45-81060ce6b042','Önder Yılmaz','TICARI','TAMAMLANDI','2026-06-01',NULL,'"İbrahim Bey’e yönelik ofis ziyareti gerçekleştirilmiştir. Ancak kendisi ziyaret sırasında yerinde bulunmamaktadır. Ardından kademe birimine uğranmış ve İlhami Bey ile görüşülmüştür. Yapılan görüşmede, mevcut durumda herhangi bir ihtiyaçlarının bulunmadığı bilgisi alınmıştır.','{}'::jsonb,'EXCEL_MIGRASYON','0c5e2e6e-64a8-4c9b-9c45-81060ce6b042') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('386bbdd4-8708-5b49-8d29-df97f8e28bbe','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ER PİLİÇ' AND il IS NOT DISTINCT FROM 'BOLU' LIMIT 1),'a408b02a-8cd5-510f-9349-d97b758550d7'::uuid),'0c5e2e6e-64a8-4c9b-9c45-81060ce6b042','Önder Yılmaz','TICARI','TAMAMLANDI','2026-06-01',NULL,'Halit Bey’e ofis ziyareti gerçekleştirilmiştir, ancak kendisi ziyaret esnasında yerinde bulunmamaktadır. Ardından kademe birimine geçilerek 26 adet lastiğin teslimatı yapılmıştır.Lastikçi Ayhan Bey ile birlikte kaplama   lastikler incelenmiş, yapılan değerlendirme sonucunda üretim tarihlerinden kaynaklı olarak lastiklerin kaplama işlemine uygun olmadığı tespit edilmiş ve gerekli bilgilendirme yapılmıştır. Ayrıca tamir işlemi uygulanabilecek lastikler teslim alınmıştır.','{}'::jsonb,'EXCEL_MIGRASYON','0c5e2e6e-64a8-4c9b-9c45-81060ce6b042') ON CONFLICT (id) DO NOTHING;
