INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('a6db5bd2-241f-506b-a64d-10d2c8e6e275','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='KUMSAN NAKLİYAT' AND il IS NOT DISTINCT FROM 'BOLU' LIMIT 1),'c694f930-91b7-5d6a-93a7-c78750af901a'::uuid),'0c5e2e6e-64a8-4c9b-9c45-81060ce6b042','Önder Yılmaz','TICARI','TAMAMLANDI','2026-06-11',NULL,'Servet Bey ile yapılan telefon görüşmesinde, kademede 1 adet lastiğin söküldüğü bilgisi alınmıştır. Bunun üzerine kademe ziyareti gerçekleştirilerek sökülen lastik incelenmiştir. Yapılan kontrolde lastiğin omuz bölgesinde batık ve küçük bir yama işlemi bulunduğu, ayrıca gövde kısmında balon oluştuğu tespit edilmiştir. Lastiğin mevcut durumu nedeniyle teslim alınmamıştır. Yapılan inceleme sonucunda lastiğin durumu hakkında Servet Bey’e gerekli bilgilendirme yapılmıştır.','{}'::jsonb,'EXCEL_MIGRASYON','0c5e2e6e-64a8-4c9b-9c45-81060ce6b042') ON CONFLICT (id) DO NOTHING;
