INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('2fa62ac7-a58a-55e0-8d49-7888556c1965','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ÖZOFLU KARDEŞLER' AND il IS NOT DISTINCT FROM 'BOLU' LIMIT 1),'914c624c-1d21-543a-bcfd-ef762b27589d'::uuid),'0c5e2e6e-64a8-4c9b-9c45-81060ce6b042','Önder Yılmaz','TICARI','TAMAMLANDI','2026-06-11',NULL,'Halil Bey ziyaret edildi. Yapılan görüşmede, depolarında halen eski tarihli kullanılabilir lastiklerin bulunduğunu ve öncelikli olarak bu lastikleri değerlendireceklerini ifade etti. Bu nedenle mevcut durumda yeni lastik ihtiyaçlarının bulunmadığını belirtti. Genel piyasa koşulları ve ürünler hakkında kısa bir görüş alışverişi yapılarak ziyaret tamamlandı.','{}'::jsonb,'EXCEL_MIGRASYON','0c5e2e6e-64a8-4c9b-9c45-81060ce6b042') ON CONFLICT (id) DO NOTHING;
