INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('1b868350-381a-51f9-b309-5020de9631b2','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='KARTAL PETROL' AND il IS NOT DISTINCT FROM 'BARTIN' LIMIT 1),'46dbdf12-4c06-59f9-8de2-a151c35939e2'::uuid),'0c5e2e6e-64a8-4c9b-9c45-81060ce6b042','Önder Yılmaz','TICARI','TAMAMLANDI','2026-02-12',NULL,'Yaşar Bey ziyaret edildi. Genel piyasa ve iş durumu hakkında görüş alışverişinde bulunuldu. Firmanın kereste işi yaptığını ancak şu anda üretim faaliyetlerinin olmadığını, çalışanların mevcut işlerle ilgilendiğini belirtti. Akaryakıt tarafındaki işlerin ise kereste işine kıyasla daha iyi durumda olduğunu ifade etti.
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('fbd2eca1-e9f2-5483-bb79-eb0aa0f79412','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='BARTIN NAK KOP GARAJ' AND il IS NOT DISTINCT FROM 'BARTIN' LIMIT 1),'82ec0019-216a-5487-94e9-8c58a5b42c33'::uuid),'0c5e2e6e-64a8-4c9b-9c45-81060ce6b042','Önder Yılmaz','TICARI','TAMAMLANDI','2026-02-12',NULL,'Üyeler ile görüşmeler gerçekleştirildi. Görüşmeler sırasında yeni lastik fiyatları hakkında . Özellikle Michelin, Hankook ve Pirelli markalarına yönelik fiyat soruları yöneltildi tarafıma. Talepte bulunan üyelere Brisa ve Continental markalarına ait güncel fiyat bilgileri paylaşıldı.
