INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('fb360363-b04f-5bf2-b63c-652e095d241f','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='AKAY KARDEŞLER' AND il IS NOT DISTINCT FROM 'BOLU' LIMIT 1),'788bf2ec-9d9b-5d12-a211-cd7e049f3091'::uuid),'0c5e2e6e-64a8-4c9b-9c45-81060ce6b042','Önder Yılmaz','TICARI','TAMAMLANDI','2026-06-15',NULL,'Aydın Bey ziyaret edilerek yeni lastik ve kaplama ürünleri hakkında görüşme gerçekleştirildi. Yapılan görüşmede, 2022 yılında Tatko firmasından adetli olarak satın alınan Michelin marka lastiklerden halen yaklaşık 315/70r22.5 ve 385.65r22.5  85 adet stoklarında bulunduğu bilgisi paylaştı
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('342fa8af-8628-5e68-a214-c6e947c1db72','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='TUNCAYLAR MADENCİLİK' AND il IS NOT DISTINCT FROM 'BOLU' LIMIT 1),'62d9ca92-2f81-58a7-a6a2-e600289eedeb'::uuid),'0c5e2e6e-64a8-4c9b-9c45-81060ce6b042','Önder Yılmaz','TICARI','TAMAMLANDI','2026-06-15',NULL,'Fadıl Bey ziyaret edilerek vadesi gelen bakiye hakkında görüşme gerçekleştirildi. Ödemenin alınabilmesi için uygun kredi kartı talebinde bulunuldu. Yapılan görüşmenin ardından Özden Hanım ile iletişime geçilerek ödeme gün içerisindeki ödeme planına dahil edildi. Günün ilerleyen saatlerinde takip sağlanmış olup, ilgili tahsilat başarıyla gerçekleştirilmiştir.','{}'::jsonb,'EXCEL_MIGRASYON','0c5e2e6e-64a8-4c9b-9c45-81060ce6b042') ON CONFLICT (id) DO NOTHING;
