INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('1eebb9a3-1ff6-5c23-b95a-4ac9c333dd62','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='EREĞLİ BETON -TEKAY İNŞ' AND il IS NOT DISTINCT FROM 'ZONGULDAK' LIMIT 1),'2b0da68f-71b2-58dd-9609-3fc417314f91'::uuid),'0c5e2e6e-64a8-4c9b-9c45-81060ce6b042','Önder Yılmaz','TICARI','TAMAMLANDI','2026-06-16',NULL,'Yeni müşteri çalışması kapsamında Ceyhun Bey (Satın Alma Sorumlusu) ile tanışma ve firma tanıtım görüşmesi gerçekleştirilmiştir. Görüşmede firma hakkında genel bilgiler alınmış olup, filolarında yaklaşık 60 adet plakanın bulunduğu ve ayrıca 4 adet iş makinesi ile faaliyet gösterdikleri öğrenilmiştir.Ödeme koşulları hakkında bilgi alınmış, alımlarını 90 gün vade ile gerçekleştirdikleri belirtilmiştir. Mevcut durumda Frenpar ile çalıştıklarını ifade eden Ceyhun Bey, güncel kaplama fiyat teklifinin hazırlanarak e-posta yoluyla kendisine iletilmesini talep etmiştir.
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('55d4c941-5700-500b-8cdb-adb852214416','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='ÇAYCUMA NAK. KOP GARAJ' AND il IS NOT DISTINCT FROM 'ZONGULDAK' LIMIT 1),'fed4da0f-5f1d-5d21-83e0-ccf4607e25d6'::uuid),'0c5e2e6e-64a8-4c9b-9c45-81060ce6b042','Önder Yılmaz','TICARI','TAMAMLANDI','2026-06-17',NULL,'Rutin ziyaret gerçekleştirildi. Yapılan görüşede üyeler tarafından lastik talebi veya fiyat teklifi isteği bile soran olmadı. İç piyasadaki durgunluğun devam ettiği, buna bağlı olarak lastik alımlarında ve fiyat araştırmalarında belirgin bir yavaşlama olduğu gözlemlenmiştir.','{}'::jsonb,'EXCEL_MIGRASYON','0c5e2e6e-64a8-4c9b-9c45-81060ce6b042') ON CONFLICT (id) DO NOTHING;
