INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('d2ac4722-5476-5b8c-95fc-a1d85ec6867e','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa','2668487d-5055-402a-af86-16f7b14370ae'::uuid,'0c5e2e6e-64a8-4c9b-9c45-81060ce6b042','Önder Yılmaz','TICARI','TAMAMLANDI','2026-07-08',NULL,'Hüseyin Abi ile birlikte firma ziyaret edildi. Anca firma sahibi umrede olmasında dolayı görüşme sağlanamadı daha sonra kademe tarafında mehmet  abi ile görüşme yapıldı stoklarında lastiklerini kalmadığını  kenan bey önümüdeki hafta geleceğini bellirit  lastik talebinde olacağını  haftaya tekrar gelmemizi talep etti','{}'::jsonb,'EXCEL_MIGRASYON','0c5e2e6e-64a8-4c9b-9c45-81060ce6b042') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('09dad32e-c18e-5594-bd6e-b051b0e95f24','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='DÜZ NAK' AND il IS NOT DISTINCT FROM 'ZONGULDAK' LIMIT 1),'fe53e139-51da-5cdf-a302-a68be65f9e2d'::uuid),'0c5e2e6e-64a8-4c9b-9c45-81060ce6b042','Önder Yılmaz','TICARI','TAMAMLANDI','2026-07-08',NULL,'Hüseyin Abi ile birlikte firma ziyaret edildi. Ahmet abi  görüşme sağlandı.  Yarın için cemil beyin düzce garajda olduğunu  oraya ziyaret ederek  lastik ihtiyaçlarının  durumunun kontrol edilmesini talep etti','{}'::jsonb,'EXCEL_MIGRASYON','0c5e2e6e-64a8-4c9b-9c45-81060ce6b042') ON CONFLICT (id) DO NOTHING;
INSERT INTO saha_ziyaret (id,tenant_id,musteri_id,rep_id,rep_adi,tip,durum,ziyaret_tarihi,katilimci,notlar,detay,kaynak,created_by) VALUES ('5c0c4fbf-754d-5822-99fa-0d150d8b0b9e','f8a5d20f-ecf8-4ce2-a492-69268fbb03fa',COALESCE((SELECT id FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND firma='BNB İNŞ' AND il IS NOT DISTINCT FROM 'ZONGULDAK' LIMIT 1),'5b44213f-42ce-5324-835d-9efc54289981'::uuid),'0c5e2e6e-64a8-4c9b-9c45-81060ce6b042','Önder Yılmaz','TICARI','TAMAMLANDI','2026-07-08',NULL,'Hüseyin Abi ile birlikte firma ziyaret edildi.Mehmet bey ile görüşme yapıldı firmanın 115 adet plakası bulunmaktadır merkezi ankara  ağırlıklı olarak  devlet  işlerinde çalışmakta batıkaradenizin dere ıslah çalışmalarını yapmakta.  Yeni lastik alımlarında goodyear ve promeion  kullanmakta orjinal  ekipman çıkan araçların altında gelen lassa marka lastiklerde memnun olduğunu  bellirti  bölgede çalıştığımız referans müşteri sordu ve kendisini  çalışmakta olduğumuz firmalar paylaşıldı 315/80r22.5 ve 13r22.5   ön ve çeker hafriyat madeni   yeni lastik ve lastik yenileme fiyat teklifi istedi .  fiyat teklifi verilecek.','{}'::jsonb,'EXCEL_MIGRASYON','0c5e2e6e-64a8-4c9b-9c45-81060ce6b042') ON CONFLICT (id) DO NOTHING;
